window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["25806793"]={"book":{"id":25806793,"title":"提问的艺术","author":"安德鲁.索贝尔（Andrew Sobel）","translator":"陈艳","publisher":"中国人民大学出版社","pubdate":"2014-1-1","isbn":"9787300183268","tags":["沟通","思维","提问","批判性思维","职场","心理学","个人管理","商业"],"memCount":42},"np":1,"pb":[51],"idx":[{"i":18977,"t":"如何利用高效提问的方式，让沟通更加顺畅。","l":"TF2-2","c":"毛晴（晴晴）","g":1,"p":1},{"i":18840,"t":"如何在回答对方问题时，避免滔滔不绝，且关注到对方感受","l":"TF3-1","c":"马子喻","g":1,"p":1},{"i":17635,"t":"如何通过五个为什么实现清晰认知","l":"TF2-2","c":"马子喻","g":1,"p":1},{"i":15629,"t":"苏格拉底三步法，让交流无障碍","l":"TF3-2","c":"李婷","g":1,"p":1},{"i":14879,"t":"提问的艺术","l":"TF2-2","c":"青橙","g":1,"p":1},{"i":12775,"t":"“三分心注定”提问法","l":"TF2-2","c":"周凡","g":1,"p":1},{"i":11570,"t":"找到“我”该过怎样的人生","l":"TF1-1","c":"兔小灰","g":1,"p":1},{"i":11196,"t":"“你怎么想？”--通过提问可与他人增加链接","l":"TF1-1","c":"朱娣娣","g":1,"p":1},{"i":9141,"t":"答得好不如问的好","l":"TF1-1","c":"车车","g":1,"p":1},{"i":6444,"t":"通过五个问题来挖掘真实需求","l":"TF2-2","c":"马子喻","g":1,"p":1},{"i":6044,"t":"直击问题核心的方法","l":"TF2-3","c":"范范姐","g":1,"p":1},{"i":5864,"t":"如何运用圣人思维来解决问题","l":"TF3-2","c":"丹丁先生","g":1,"p":1},{"i":5764,"t":"避免谈话中漫无目的的迂回","l":"TF2-2","c":"锦莉","g":1,"p":1},{"i":5477,"t":"像苏格拉底一样思考1","l":"TF2-1","c":"罗巧琴","g":1,"p":1},{"i":5278,"t":"如何做出更好的选择？","l":"TF2-3","c":"程婷婷","g":1,"p":1},{"i":5086,"t":"如何帮助他人做出个人选择","l":"TF2-2","c":"素语","g":1,"p":1},{"i":4781,"t":"沟 通 02","l":"TF2-1","c":"行知行晓","g":1,"p":1},{"i":4733,"t":"沟 通 01","l":"TF1-2","c":"行知行晓","g":1,"p":1},{"i":4714,"t":"用加减法帮助对方做出选择","l":"TF1-1","c":"刘志学","g":1,"p":1},{"i":4679,"t":"如何更好地通过提问来引导对方积极思考","l":"TF3-2","c":"什刹海","g":1,"p":1},{"i":4606,"t":"如何利用一个好问题治疗一个坏情绪","l":"TF2-1","c":"丹丁先生","g":1,"p":1},{"i":4337,"t":"用提问的方式引导他人参与思考","l":"TF1-2","c":"李明轩","g":1,"p":1},{"i":4191,"t":"不要滔滔不绝，忘了对方的感受","l":"TF2-3","c":"倩倩老师","g":1,"p":1},{"i":3818,"t":"学会提问哟","l":"TF2-1","c":"鸳鸯","g":1,"p":1},{"i":3692,"t":" 如何做出更好的选择？","l":"TF2-3","c":"程婷婷","g":1,"p":1},{"i":3664,"t":"如果通过简单的提问把主动权交给对方从而建立良好的沟通关系","l":"TF2-2","c":"豆小燃","g":1,"p":1},{"i":3331,"t":"提问的艺术—像苏格拉底一样思考","l":"TF3-2","c":"勍勍","g":1,"p":1},{"i":3330,"t":"不要滔滔不绝，却忘了客户的感受","l":"TF3-1","c":"勍勍","g":1,"p":1},{"i":3015,"t":"《提问的艺术》勍勍TF3-3过级","l":"TF2-4","c":"勍勍","g":1,"p":1},{"i":3014,"t":"《提问的艺术》像苏格拉底一样思考-TF3-2过级","l":"TF2-4","c":"勍勍","g":1,"p":1},{"i":2253,"t":"提问开场技巧","l":"TF2-4","c":"勍勍","g":1,"p":1},{"i":1487,"t":"如何通过提问找到对方的关注度","l":"TF3-1","c":"金家东","g":1,"p":1},{"i":1327,"t":"《提问的艺术》","l":"TF1-1","c":"宋懿玲","g":1,"p":1},{"i":1222,"t":"如何提问让别人接受我们的产品或建议","l":"TF2-2","c":"金家东","g":1,"p":1},{"i":1207,"t":"如何问“五个为什么”","l":"TF2-2","c":"刘云汉","g":1,"p":1},{"i":1206,"t":"如何提出封闭式问题避免兜圈子","l":"TF2-1","c":"刘云汉","g":1,"p":1},{"i":1203,"t":"了解为什么你该这样问","l":"TF2-1","c":"金家东","g":1,"p":1},{"i":655,"t":"要去解决问题，而不是去消除批评？","l":"TF1-2","c":"刘红艳","g":1,"p":1},{"i":508,"t":"如何通过提问让别人接受我们的方案","l":"TF2-2","c":"金家东","g":1,"p":1},{"i":500,"t":"五个为什么","l":"TF2-2","c":"刘云汉","g":1,"p":1},{"i":456,"t":"为什么你该这样提问","l":"TF2-1","c":"金家东","g":1,"p":1},{"i":424,"t":"如何用封闭式问题提问避免兜圈子","l":"TF2-1","c":"刘云汉","g":1,"p":1},{"i":423,"t":"如何通过提问了解对方的需求","l":"TF1-2","c":"金家东","g":1,"p":1},{"i":387,"t":"为什么你该这样问","l":"TF1-1","c":"金家东","g":1,"p":1},{"i":373,"t":"追溯根源的问题往往更有力 ","l":"TF1-2","c":"刘红艳","g":1,"p":1},{"i":349,"t":"如何围绕决策提问来解决会议拖延症","l":"TF1-2","c":"刘云汉","g":1,"p":1},{"i":333,"t":"如何开启沟通的阀门","l":"TF1-1","c":"刘云汉","g":1,"p":1},{"i":160,"t":"如何探索对方真实需求","l":"TF3-2","c":"西里孟钢","g":0,"p":1},{"i":158,"t":"如何针对客户利益和价值提问","l":"TF3-2","c":"西里孟钢","g":1,"p":1},{"i":155,"t":"如何针对客户利益提问","l":"TF3-3","c":"西里孟钢","g":1,"p":1},{"i":82,"t":"使用提问开始会议","l":"TF3-2","c":"海边渔民","g":0,"p":1}],"ms":[{"id":18977,"topic":"如何利用高效提问的方式，让沟通更加顺畅。","learn_goal":"","remark":"这本书是由美国商业战略家安德鲁.索贝尔与世界顶级慈善咨询师杰罗德.帕纳斯联手创作，专业背书扎实。全书以“商业+人际+人生”三大篇章为脉络，精心归纳327个实用问题，覆盖商务洽谈、客户沟通、亲友互动等多元场景，系统传授高效提问方法。","level":"TF2-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"毛晴（晴晴）","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>各位小伙伴，各位老师晚上好！首先感谢大家百忙之中牺牲周末陪伴家人的时间，来给我和汝禾老师的过级赋能，我是来自深圳桃李分舵的晴晴，今天要拆书过级的级别是tTF2-2，话不多说，先用三个标签来介绍我自己。一、国学老师。二、旅游及文学爱好者。三、读书会创始人。在这里我要着重介绍一下我的第三个标签，因为我第三个标签是通过我加入拆书帮以后衍生出来的，要感谢拆书帮这个平台，让我有机会系统地学习拆书的技能，我深知教是最好的学习方法，所以在我前脚加入了拆书帮，我后脚利用我的资源组建了一个读书社群，把我在拆书帮学到的技能应用到读书会中，以上就是关于我的三个标签介绍，接下来我给大家介绍一下今天的学习目标。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>通过本次的学习，帮助学习者学会在与别人沟通时，能够通过简单的提问（如“你能多讲讲吗?”），引导对方多表达，达到与对方进行深度对话，从而建立信任关系。\u003c/p>\u003cp>\u003cstrong>我今天带领大家拆解的片段来自《提问的艺术》这本书，现在我用FAB法介绍此书。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F：\u003c/strong> 由美国商业战略家安德鲁·索贝尔与世界顶级慈善咨询师杰罗德·帕纳斯联手创作，专业背书扎实。全书以“商业+人际+人生”三大篇章为脉络，精心归纳327个实用问题，覆盖商务洽谈、客户沟通、亲友互动等多元场景，系统传授高效提问方法。\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong> 在全美引发广泛关注，收获众多读者好评。同时获得《一分钟经理人》作者肯·布兰佳等行业大咖推荐。书中通过大量真实案例，将抽象技巧转化为易懂易用的实践指南。\u003c/p>\u003cp>\u003cstrong>B1\u003c/strong>：职场中能精准把握客户需求，提升会议效率，加速职业进阶； \u003c/p>\u003cp>\u003cstrong>B2\u003c/strong> 生活里可让对话更有深度，增强情感联结，还能从中获得人生思考，实现自我成长。\u003c/p>","ratings_count":1,"texts":[{"id":23312,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>\u003cstrong>接下来，请大家花1-2分钟时间来阅读一下我挑选的这个片段。阅读完的伙伴\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请抬头示意我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R原文片段\u003c/strong>\u003c/p>\u003cp>\u003cstrong>主题：如何用提问的方式让沟通更顺畅\u003c/strong>\u003c/p>\u003cp>当你让谈话都在围绕着自己时，别人也许会认为你很聪明，但这并不能在你们之间建立起信任，也就无从了解对方。同时，也失去了一次建立深厚友谊的机会。因此，若要推销自己，可以尽力表现自己的聪明。如果想建立良好的关系，那么就应该将表演的机会让给别人。想要赢得他人的心，就要多向他人提问，以表达你的兴趣和鼓励他人进行深度对话或多说一些话，是每个优秀提问者的任务。\u003c/p>\u003cp>你可以先这样问：“关于这件事，你能再多说一点吗？”接下来再这样问：“什么时候？发生了什么事？后来怎么样了？为什么呢？”弄清楚对方的情况和需求后，你才会知道该怎么去做，而对方也会从你的问题中体会到你对他的关心和重视。“你能多跟我讲讲吗？”是一个简单而有效的问题，不妨经常这样问别人，以开启更为流畅的交谈。\u003c/p>\u003cp>当对方回答时，你可以进一步问对方：“能跟我多讲讲吗？”这样会让你们之间的对话和交流更加畅通。不要小看这样一个简单的问话，它可以用在任何场合使用，将对方迅速带入到互动的对话中。“你能多跟我说说吗？”是一个随时都能用上的有效问题，甚至每天都可以用。\u003c/p>","explains":"\u003cp> \u003cstrong>What：\u003c/strong>在人际交往中，过度自我中心的表达无法建立信任，想要与他人建立良好关系，需要通过提问引导对方表达，展现对对方的关注。\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>单方面展示自我，会让对话变成“独角戏”，对方难以参与，关系也停留在表面；而提问能让对方感受到被重视，愿意分享更多信息，从而加深彼此了解与信任。例如，在朋友聚会中一直讲述自己工作中的成就，其他人可能只是礼貌回应，但若问朋友“最近你在工作上有没有遇到特别有挑战的事？”，朋友就会打开话匣子，交流也更深入。\u003c/p>\u003cp>\u003cstrong>Where：\u003c/strong>该方法适用于各种人际交往场景，无论是日常聊天、商务洽谈，还是家庭沟通，都能帮助建立良好关系。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>1. 开启话题：用开放式提问，如“关于这件事，你能再多说一点吗？”鼓励对方开口。\u003c/p>\u003cp>例子：同事说“最近项目压力好大”，可回应：“听起来确实不容易，具体是哪部分让你觉得压力最大呢？”  \u003c/p>\u003cp>1. 深入追问：通过“5W1H”（何时、何事、何人、何因、何地、如何）进一步挖掘。\u003c/p>\u003cp>例子：朋友说“我和家人吵架了”，可依次问：“是最近发生的吗？”→“当时因为什么事情？”→“现在关系缓和了吗？”→“你觉得这次矛盾的根本原因是什么？\u003c/p>\u003cp>2. 持续引导：对方回答后，重复使用“能多跟我讲讲吗？”延续话题。\u003c/p>\u003cp>例子：客户提到“这个方案不太合适”，可追问：“您能多讲讲具体哪部分不符合需求吗？这对我们调整方向很重要。”  \u003c/p>\u003cp>\u003cstrong>可能的异议及预防：\u003c/strong>\u003c/p>\u003cp> \u003cstrong>异议：一直提问会不会让对方觉得被审问？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>预防：提问时语气要真诚自然，结合对方的回答适时给予回应，如点头、关切的眼神，共情表达（“听起来真不容易”），避免机械提问。同时，注意提问节奏，不要一股脑抛出多个问题，而是循序渐进。若对方犹豫，可穿插自我暴露（如“我之前也遇到过类似情况……”）降低压迫感。  \u003c/strong>\u003c/p>","interaction":"\u003cp>\u003cstrong>分组：接下来进入讨论分享环节，请会议主持人根据人数线上平均分成2组。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化1：\u003c/strong>以下哪种场景你会遇到？给客户推销产品时，你一直滔滔不绝说产品如何好，而对方只说，“嗯，好，我知道了。”，却没有给你什么反馈；和闺蜜聚会，你不停分享你家淘气孩子的日常趣事和糗事，而对方却似听非听，一边刷手机一边应和，“哇！小家伙可真淘”。\u003c/p>\u003cp>想象一下未来一周可能遇到的情景有哪些？2分钟时间，请大家将类似的一个场景写在便签上，等下请一位小伙伴分享。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者susan分享：\u003c/strong>兴高采烈地约朋友逛商场，试完新衣服后忍不住分享购物心得：“这件针织衫版型超显瘦！而且面料软软的，贴身穿完全不扎。还有这个品牌新出的联名款包包，配色特别适合秋冬，背出去绝对不撞款！对了，他们家最近还有满减活动，算下来性价比超高。我打算再买双靴子搭配，你看官网这双马丁靴，侧边拉链设计特别酷……”朋友靠在休息椅上刷短视频，时不时“嗯”“啊”应两声。我拿起手机展示商品页面：“你觉得黑色百搭还是棕色更有质感？我拿不定主意。”朋友头也不抬：“都还行，你喜欢就好。”我还想听听搭配建议，对方却突然说：“我有点累了，要不早点回家？”话题瞬间冷场，我只能匆匆结束购物。\u003c/p>\u003cp>\u003cstrong>分步催化2：\u003c/strong>那么接下来，面对刚才可能遇到的场景，你决定尝试一下用提问的方式将谈话的主动权交给对方，希望对方更多的表达，接下来你怎么做呢？\u003c/p>\u003cp>2分钟时间，请大家写到便签上，然后讨论一下，每个小伙伴都尽量表达一下自己的观点。等一下我们请几位小伙伴来进行分享。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者susan分享;\u003c/strong>\u003c/p>\u003cp>我兴高采烈地约朋友逛商场，试完新衣服后，拿着针织衫走到朋友面前问道：“这件针织衫版型超显瘦！而且面料软软的，贴身穿完全不扎。你之前买过这种软糯面料的衣服吗？会不会起球呀？”\u003c/p>\u003cp>朋友放下手机，凑过来说：“我买过类似的，选含羊毛比例高的就不容易起球。你挑的这个颜色很显白，准备搭配牛仔裤还是裙子？”\u003c/p>\u003cp>我兴奋地说：“还没想好呢！你觉得配我那条黑色半身裙，还是浅色直筒牛仔裤更好看？对了，这个品牌新出的联名款包包，配色特别适合秋冬，背出去绝对不撞款！要是买包的话，搭哪个颜色的衣服更出彩？”\u003c/p>\u003cp>朋友站起身，仔细端详衣服和手机上的包包图片：“包包的焦糖色和这件针织衫很搭，配黑色半裙更有氛围感。而且他们家最近还有满减活动，算下来性价比超高，要不凑单再买双靴子？你更倾向长靴还是短靴？”\u003c/p>\u003cp>我立刻来了兴致：“短靴！我打算买双马丁靴，官网有黑色和棕色两款，侧边拉链设计特别酷。你觉得哪个颜色更百搭？会不会和包包颜色重复？”\u003c/p>\u003cp>朋友认真分析道：“棕色靴子和焦糖包同色系会更和谐，但黑色更经典。不过咱们可以再逛逛实体店，试试上脚效果，说不定还能发现更惊喜的搭配！”\u003c/p>\u003cp>我开心地挽住朋友胳膊：“走！有你帮我参谋，今天肯定能满载而归！”两人笑着继续穿梭在店铺中，热烈讨论着接下来的购物计划 。\u003c/p>\u003cp>接下来我们总结一下：今天我们学习了如何用有效的提问，鼓励对方表达，赢得信任，最终建立良好的关系。一个好的提问是用主动积极的方式，去打动对方的心，看似简单的几句话，却充满了力量。想要沟通的更顺畅，更有效，就好好琢磨一下，自己该如何提问吧！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1749030313000,"updated_at":1749542185000,"ria":true},{"id":18840,"topic":"如何在回答对方问题时，避免滔滔不绝，且关注到对方感受","learn_goal":"","remark":"在面对别人给我们提出一个问题后，我们总是急于给出答案，而《提问的艺术》这本书告诉我们“答的好不如问的好”，在人际交往中，好的问题远比问题的答案更有力量。这本书是两位来自美国的著名商业战略家和咨询家对他们商业与人生提问的精华总结，书中通过一个个有力的提问再现对话的场景，涉及商业领域、人际交往等多种场合，通过这些有效的提问，可以帮助我们实现高效对话","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位小伙伴，大家晚上好！\u003c/p>\u003cp>我是马子喻，简单的做下自我介绍，我是一名有11年经验的国际教育咨询老师，目前还是头马社群V中区的俱乐部发展总监；另外我是一名传统文化爱好者，非常高兴大家支持和喜欢拆书帮的活动；除了本职工作和拆书，我还喜欢读书和喝茶，希望能和大家成为好朋友。\u003c/p>\u003cp>今天非常感谢大家参加我TF3-1的拆书分享。\u003c/p>\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，我们就能学会在回答对方问题时，避免滔滔不绝，真实的关注到对方感受，让对话更加高效。\u003c/p>\u003cp>【分组】现在我们先按照座位，两人一组。\u003c/p>\u003cp>【学习者场景法介绍图书】\u003c/p>\u003cp>【事件场景】今年上半年，我因为没有把握好谈话重点丧失掉了一个大客户。这个客户是找到我们机构做长达三年的企业英语培训项目。如果真的签约的话，毫不夸张，我们整个公司躺平一年绝对没问题。我认真的准备了方案，画了极其精致的妆容，开心的到了客户公司。坐在正中位置的一看就是公司老大，他说“先介绍下你们公司吧”，于是我把提前精心准备好的PPT展示，然后用心的介绍，从使命愿景价值观一直讲到课程类别。但是我注意到，我讲的激情澎湃、唾沫横飞，客户却有点不耐烦。我立马感觉不对劲，于是我本能的加快了语速匆匆结束介绍。虽然之后我们也闲聊了一些，但是显然第一印象没把握好，最后这个客户没和我们公司签约。\u003c/p>\u003cp>【影响】如果你也有过类似的情况，你一定也会像我一样纳闷，为什么我们自认为表达十分全面和详细的介绍但是对方并不买单呢。事实上，仔细想想就知道，滔滔不绝的回答对方的问题是十分不明智的。不但对方的感受不好，同时还没回答到对方真正关注的点子上。这带来的影响可十分严重，不单单是丢失一个客户，也可能是在一场重要面试中失败失去了宝贵的工作机会，还可能是第一次约会的不成功让你的男神女神给你减分。\u003c/p>\u003cp>【提问】那遇到对方提问，尤其是类似于我的客户一样，对方问了一个宽泛性问题，我们该如何应对才能把握住沟通的关键点呢？如何才能让对方感受良好？给对方留下更好的印象？\u003c/p>\u003cp>【解决】《提问的艺术》这本书告诉我们“答的好不如问的好”，好的问题远比问题的答案更有力量。在关键对话的时候，遇到对方问了宽泛性问题，这本书就给了很好的提问方法来把问题具体化，然后使得关键对话更加高效，避免了滔滔不绝带来的不好印象。\u003c/p>","ratings_count":2,"texts":[{"id":23170,"quote":"\u003cp>巧的是，一年后的今天，我和我的高级合伙人德威特（Dewt）先生出席了一次似曾相识的销售会议。他是经历过数百场会议的资深人士，可以说是一位智者。我们的客户也提出了相同的问题：“你们何不先介绍一下你们的公司来开始我们今天的会议呢？” 德威特若有所思地停顿了片刻，然后抬起头问客户：“那您具体需要了解些什么呢？” 对方陷入了沉默中。\u003c/p>\u003cp>通常，问了一个问题后，如果对方沉默，我们就会换个说法再问一遍这个问题。我们是不会允许会议陷入沉默的，但德威特是一个例外，他习惯于保持沉默。很久以前他曾告诉过我：“一旦说完你想要说的，或问完问题，就闭嘴吧！”过了一会儿，客户具体地说道：“好吧，我们当然已经很了解你们是做什么的了。我们只是特别想知道你们在亚洲的运营能力如何以及你们内部是如何一起工作的。”这无疑将会议带入了一个互动的交流氛围中了。“我很好奇，你能具体描述一下你想了解的‘内部一起工作’的意思吗？是什么促使你提出了这个问题？”\u003c/p>\u003cp>接下来，他又问了一些引人深思的问题，并与客户一起分享了最近遇到的一些案例，大多都是我们如何帮助老客户的有趣故事。通过德威特的提问，我们了解到这家公司与其他咨询公司曾经有过不愉快的合作经历。这家公司曾在广告中号称自己是客户的感受一家全球性的公司，然而公司内部的各个部门却从来没有齐心协力地一起合作过。我们还了解到了这家公司的亚洲扩展计划，也弄清了他们寻找外援的真正原因。德威特还做了一些让我至今难忘的事。他当着客户的面夸赞我。\u003c/p>\u003cp>为什么他不夸夸自己呢？他没有在客户面前炫耀自己从业 25 年的丰富经验，也没有吹嘘他那杰出的专业知识，而只是跟客户说他为自己的团队有我这样的合作伙伴而感到幸运，还说我是他们前途无量的年轻合伙人之一，也是他们当中工作最努力的一个。这次讨论与众不同，绝对比上一次我和电信公司的会谈精彩得多，这才是建立新关系的一次良好的开始。一周之后，那家公司再次打电话给德威特，邀请我们去做进一步的探讨，之后又制定了方案。德威特一直和他们合作到八年之后他退休的那一天。如今，他们成了我的终身客户。自从那次会议之后，我非常乐意跟随德威特并向他学习。\u003c/p>","explains":"\u003cp>好的，大家已经阅读完了原文的片段，片段里的这个案例无疑是一个成功的商业案例。相信大家也看出了其中成功的奥秘，我们看到，当案例中的客户提出一个宽泛的问题时，德威特没有立刻给出答案。反倒是反问了细节让问题具体化了。\u003c/p>\u003cp>在客户做了回答之后，德威特又问了一个让问题更加清晰的问题。正是通过这两个问题，德威特慢慢问出了客户的真实需求，才打开了和客户长达8年的合作的大门。\u003c/p>\u003cp>【强化讲解概念】\u003c/p>\u003cp>那我们现在知道，在遇到对方问宽泛性问题的时候,为了避免我们的回答滔滔不绝,我们可以不要着急给出答案，而是用提问的方式让对方把问题具体化。\u003c/p>\u003cp>那什么是宽泛性问题？什么是具体化问题呢？这点非常好理解，宽泛性问题首先是开放式的，而且很难用几句话介绍清楚，涵盖的范围很广；而具体化的问题，往往包含一个或者两个明确的范围，它可能也是开放式的问题，但很容易提取出关键词来进行回答。\u003c/p>\u003cp>我们举几个例子：比如能介绍一下你们的公司吗？这是宽泛的问题还是具体的问题？（宽泛）\u003c/p>\u003cp>比如：能介绍一下你们公司的XX产品吗？这是宽泛的问题还是具体的问题？（具体）\u003c/p>\u003cp>比如：能不能介绍一下拆书帮？这是宽泛的问题还是具体的问题？（宽泛）\u003c/p>\u003cp>比如：针对亲子沟通的问题，有哪些书籍推荐呢？这是宽泛的问题还是具体的问题？（具体）\u003c/p>\u003cp>好的，非常好感谢大家的配合。\u003c/p>\u003cp>【适用场景】\u003c/p>\u003cp>当你被问到一个宽泛性问题，我们就可以用“D-M-C”这样的三步提问法来把宽泛的问题具体化，使得关键对话顺畅进行。\u003c/p>\u003cp>那这三步法是什么呢？\u003c/p>\u003cp>1.询问细节（Detail）。首先用缩小范围的提问来确认细节，比如我的客户让我介绍公司，那我可以问 “你想具体了解我们公司哪方面的情况呢？”。\u003c/p>\u003cp>2.了解动因（Motivation）。为了更加具体化问题，我们还需要继续提问来确认对方问题的底层原因，这样方便我们把问题更加具体化，比如还是我的那个客户，他可能会说“介绍一下你们公司的企业英语培训课程”那这时候我就可以提问“什么类型的企业英语培训课程是您期待的呢？”\u003c/p>\u003cp>3.适时确认（Confirmation）。比如我根据客户的需求，介绍了我们公司的企业英语培训课程，回答完他的问题后，我就可以说“我的回答有解答您的问题吗？”\u003c/p>\u003cp>这样沟通下来以后，通过这样的三步提问，询问细节，了解动因，适时确认，可能让我们不盲目作答，节省了双方的时间。也会让这次关键对话顺畅进行，而且给客户留下很好的印象，同时还能推动这次谈话的目标达成。大家一定还记得我开场提到的丢掉的客户那个案例，过去的半年，我不断维持跟客户的互动和沟通，虽然那一单客户没找我们，但是他们最近又需要一个销售团队短期集训的项目。前几天我刚刚去做了方案汇报，这次我没有急着讲自己的PPT，而是在客户提出第一个问题问到我“这个课程能不能保证效果的时候”，我立马询问了细节”您提到的效果是希望销售团队和国外客户无障碍的介绍产品以及开商务会议吗？“，然后了解到客户的动因是他们很希望和英国的一家公司达成长期合作，最后我逐步确认了他们的这个目标，然后给予了具体且可执行的方案，客户十分满意，已经约好下周商讨合同签约的时间了。可见，拆书可以帮助我们提升工作能力啊！\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这里需要注意的是，以上的提问技巧特别适合于一些正式的或者商务的场合，比如给客户介绍方案时，给陌生的朋友推荐产品，或者初次见面的伙伴介绍拆书帮等等。在平常朋友闲聊等等就不太合适追问过多的细节了。\u003c/p>","interaction":"\u003cp>那么，接下来，我想让大家练习一个具体应用的场景。\u003c/p>\u003cp>小伙伴们想象一下，未来的一个月内，你可能遇到一个新盆友，对方想了解你公司的产品或者服务，或者是想让你给他介绍一下拆书帮。对方首先提出的问题就是一个相对宽泛的问题，请每个人构想一下这样未来会发生的场景，然后编写一个小剧本，运用今天的提问三步法询问细节，了解动因，适时确认，将这个剧本写出来，有【地点、人物、情节变化和当时双方的对话】等。\u003c/p>\u003cp>给大家5分钟的时间，可以把剧本摘要写在一张纸上，各自完成以后可以再小组内相互分享，5分钟后我们请一位伙伴来讲讲他的剧本。\u003c/p>\u003cp>【分享者：兜爸】：我正好认识了一个新盆友，他是做企业管理的，我用了刚刚的三个步骤进行了互动：\u003c/p>\u003cp>我首先问：“你做企业管理的话，能不能介给我介绍一下关于企业管理方面的内容？”\u003c/p>\u003cp>然后他说：“你想要了解关于企业管理方面的什么内容呢？”\u003c/p>\u003cp>然后我说：“嗯，我是想知道这个，你是特定行业的企业管理，比如说有些是电器业的，有的是银行业的？还是说是普遍的一种企业管理？\u003c/p>\u003cp>他继续问我说：”为什么希望知道这两者的区别呢？“\u003c/p>\u003cp>然后我就说：”因为我可能今年要做一个公益的组织，然后不管是行业管理啊，还是企业管理，还是组织管理，我觉得它都是有相通之处的，那我提这个问题就想知道您所从事的这部分。和我这个未来可能要建的这个组织之间，有没有相似相通的地方。“\u003c/p>\u003cp>然后他说：”哦，原来是这样啊：“\u003c/p>\u003cp>他最后他确认了一下说到：”那你就是想知道一下，我们现在这个所做的这个事情，和你未来要做的这个组织之间是不是有共通的地方是吗？“\u003c/p>\u003cp>我说：”是的“\u003c/p>\u003cp>这样，我们就通过提问完成了三个步骤。\u003c/p>\u003cp>好的，那再次感谢这位伙伴的分享，我们今天学习了回答大而全问题的提问技巧，总结一下就是三步提问法：1、询问细节，2、了解动因，3、适时确认，通过这三个步骤明确对方具体想知道什么，可以让谈话更有效率，以上就是我TF3-1的拆书分享，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1745636982000,"updated_at":1747579448000,"ria":true},{"id":17635,"topic":"如何通过五个为什么实现清晰认知","learn_goal":"","remark":"这本书的作者是来自美国著名商业战略家、\n《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、\n以及世界顶级慈善事业咨询师杰罗德.帕纳斯。\n这是一本风靡全美、影响无数人的神奇提问书。\n这本书揭示了320个强大问题背后的商业与人生精髓。\n截止到2016年8月，这本书已经是第10次印刷了。\n也一直在亚马逊商业类图书TOP100的榜单上。\n乔布斯用激动人心的简单问题引领苹果电脑取得了突破性成就，\n德鲁克以其五大经典管理问题影响了一代又一代的企业家。\n同样，这本书也可以帮助我们可以在事业、生活的各种场合，\n随时展开富有成效的对话、迅速解决沟通问题，\n轻松实现自我认知，并帮助别人实现自我认知。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>各位小伙伴，大家晚上好！我是马子喻。非常高兴大家参加我今天TF2-2的拆书分享。在跟随我完成本次RIA现场学习后，我们就能学会通过问五个问题的方式，帮助自己和他人挖掘真实需求。我们先按照座位，两人一组。\u003cbr>\u003cbr>今天我拆的书是《提问的艺术·为什么你该这样问》，\u003c/p>\u003cp>【F】这本书的作者是来自美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯。这是一本风靡全美、影响无数人的神奇提问书。\u003c/p>\u003cp>【A】 这本书揭示了320个强大问题背后的商业与人生精髓。截止到2016年8月，这本书已经\u003c/p>\u003cp>是第10次印刷了。也一直在亚马逊商业类图书TOP100的榜单上。\u003c/p>\u003cp>【B】 乔布斯用激动人心的简单问题引领苹果电脑取得了突破性成就，德鲁克以其五大经典管理\u003c/p>\u003cp>问题影响了一代又一代的企业家。同样，这本书也可以帮助我们可以在事业、生活的各种场合，随时展开富有成效的对话、迅速解决沟通问题，轻松实现帮助自身以及帮助别人挖掘真实需求。\u003c/p>","ratings_count":1,"texts":[{"id":21834,"quote":"\u003cp>提问的艺术P56-P58\u003c/p>\u003cp>“有时候培训并不是最好的开始”，我补充道，“以我的经验来看，那只不过是最后的选择。”直觉告诉我，他并不喜欢我的回答，他最想要的销售培训，但是他还需要什么吗？\u003c/p>\u003cp>五天之后我来到了道森的办公室，小口面这一家有着20年历史的咖啡店烧的咖啡。他向我描述了他的公司、产品以及增长势头强劲的销售队伍。\u003c/p>\u003cp>“我们如今已经是市场的领先者了。我们有用最高的商业品质，就连我们的销售人员也成了竞争对手争相抢夺的炙手可热的商品了。”\u003c/p>\u003cp>这听上去好得有些让人难以置信。我开始了我的第一个“为什么”的问题。我靠在椅子里问道：“那为什么你还需要销售培训呢？”\u003c/p>\u003cp>“哦，这是一万我们需要继续不断提高销售人员的能力。”\u003c/p>\u003cp>我接着问了第二个为什么：“为什么你需要提高你的销售人员的技巧呢？听起来他们应该是行业的佼佼者了。”\u003c/p>\u003cp>“我坚信如果我们能提高他们的销售技巧的话，他们将在新客户开发方面更有效率。”\u003c/p>\u003cp>我接着问了第三个为什么：“那为什么你们需要增加新客户的开发呢？”\u003c/p>\u003cp>他看着我，好像我在问他为什么需要呼吸才能活着一样。\u003c/p>\u003cp>“现有的客户不足以支撑我们的增长目标，因此我们需要开发更多的客户。”我们越来越接近问题的核心了。\u003c/p>\u003cp>于是我又向道森抛出了第四个为什么：“为什么你们不能让现有的客户增长得更快些呢？”\u003c/p>\u003cp>随后我们陷入了长时间的沉默中。他不停地发出哼哼哈哈的声音。我没有再说什么，也没有去打破这一富有成效的沉默，而是等着他回答。\u003c/p>\u003cp>“嗯，我们每年都会有20%的客户流失。”\u003c/p>\u003cp>我几乎能听到每一部恐怖片的恐怖场景出现时伴随的从低音炮传出的低沉而隆隆作响的刺耳的乐声，它往往预示着某种不好的事情即将发生。就像格伦·克洛斯（Glenn Close）在电影《致命的诱惑》中刚从浴缸中跳出来时的场景一样。\u003c/p>\u003cp>“20%。”我随意地重复着这个统计数字，从我的声音中听不出任何判断来。\u003c/p>\u003cp>最后，我问了我的第五个为什么：“我不得不问一下，为什么你们每年会失去20%的客户？”\u003c/p>\u003cp>“我们遇到了许多竞争对手，他们总是以低于成本的价格与我们竞争。但这一定不会持久，他们无法长期维持这样的低价。”\u003c/p>\u003cp>“你怎么知道的？”我决定再给他施加一些压力。\u003c/p>\u003cp>“我们向销售人员调查过，也从一些客户那里听说了这件事。”我已经挖掘够深入的了。\u003c/p>\u003cp>我劝他先将培训的想法搁置一边，对自己的运营先做一次细致的检查。\u003c/p>\u003cp>之后，我访问了公司的销售人员，也拜访了他们流失的客户。真正的问题很快就浮出水面了。道森公司便没有受到低价竞争的冲击，而是产品的质量和物流配送出了问题。由此我更加肯定了自己最初的想法。我告诉我的客户，如果他们不首先解决产品质量和物流配送的问题，即使培训也无济于事。\u003c/p>\u003cp>正因为有了我问客户的这五个为什么，我们在一起合作的项目才更加广泛了，这远比销售培训的影响力更为深远。我帮助道森彻底检查了公司的整个运营环节，从生产到销售，从而使公司走上了可持续发展的正轨。\u003c/p>\u003cp>当有人说“我想要这样”的时候，你需要去发现他们真正需要的是什么。你可以通过问“为什么”去做到这一点。你可以问五遍这个问题。从“你为什么想这样做”或者“为什么会发生”开始问起。\u003c/p>","explains":"\u003cp>好，大家都看好了，故事非常简单，作者通过对当事人道森提问，而且连续提问五次这样的方式，帮助道森意识到，他的真实的需要不是销售培训，而是需要在公司的运营上面做一些调整。当有人或者我们自己说“我想要怎样”的时候，我们需要知道也许这并不是对方或自己真正的需求，这时候我们可以通过问问题，连续问五个问题，来帮助自己或者他人挖掘出真实的需求。\u003c/p>\u003cp>【预防异议】那可能有的伙伴会说：连续问五个问题这种方式“太麻烦了”。“有些时候根本不需要”，五个问题这种方式用于工作分析尚且可以，但是用于谈话的话，这样连续问别人，不会显得“咄咄逼人”吗？即使是问自己，就问几个问题就能实现“自我认知”了，做不到的吧？\u003c/p>\u003cp>不试试看怎么知道呢？生活中，我们经常忽略提问的力量。正如书的名字一样，提问是一种艺术，问题能够让被问的人更加深入的思考他们正在做的事，提问是能够让我们停下来反思的，如果我们学会在适当的时候，敢于提问，这将是个帮助自身或者帮助他人挖掘真实需求的好的做法。那提问可以问什么，可以问为什么，可以问怎么，也可以问是什么。\u003c/p>\u003cp>【举例】举一个例子，大家就能更好的理解啦。前些天，我就用了五个问题的方式来帮朋友理清楚了一件事。她说她最近一直想买个跑步机，还在犹豫中，我问她为什么会想买跑步机，她说因为她这个月突然变胖了，于是我继续问她，为什么会突然变胖呢？因为我记得她一直有跑步的好习惯。她说她把跑步的习惯丢掉了，我很纳闷的问了她第三个问题，为什么会把跑步的习惯丢掉呢？她说因为自己平时是早上起来跑步，最近早上起不来。我继续追问，为什么最近早上起不来呢？她说因为晚上睡的太晚，我又问了她第五个问题，为什么晚上不早些睡呢？她的回答是因为熬夜追剧。问完这五个问题，朋友立马清晰的意识到，她需要的不是一台跑步机，而是要早点睡。那我就是通过连续问朋友五个问题这样的方式，帮助她发现了自己潜在的真实需求不是买跑步机，而这也是她犹豫的真正原因。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】：\u003c/p>\u003cp>下面请大家设想一下：自己或者身边的人，是否有一直想要做但还在犹豫的事情，而且很可能未来一周还不会去行动的事情，比如你的客户说想要签约，可是迟迟没有下订单？比如你看到邻居家小孩的兴趣班老师不错，也想给自己的孩子报名一个，却一直没去咨询？比如你一直想要拆书升级，却始终都是有想法没行动？再比如你在工作上一直想找领导沟通新的季度计划，却一直在逃避？\u003c/p>\u003cp>请把这样正在发生以及未来可能发生的场景写在纸上，2分钟，写好的请举手示意。\u003c/p>\u003cp>【学习者案例记录】 \u003c/p>\u003cp>张军老师：我是做翻译工作的，国内的客户给的价格比较低，一直想去找国外的客户，因为国外的客户给的回报高一些。但是接待国外客户的应聘流程很复杂，一直想做但没行动\u003c/p>\u003cp>【拆书家提问设计】：\u003c/p>\u003cp>好，那未来的一周，大家遇到了自己所写的场景，你想起今天的拆书，你决定通过问自己或者问别人五个问题来帮助自己或者他人来找到真实需求，这五个问题可以问为什么，可以问怎么，可以问什么，那你决定怎样做来实现这个结果。给大家5分钟时间，写完后请在小组内部分享一下你们的案例。\u003c/p>\u003cp>【学习者案例记录】 \u003c/p>\u003cp>李老师：刚刚张老师说要去找一些国外的客户开展翻译工作，为什么要找国外的客户呢？\u003c/p>\u003cp>张军老师：因为他们单价高一点\u003c/p>\u003cp>李老师：为什么想找单价高一点的客户呢？\u003c/p>\u003cp>张军老师：这样我的单位时间收入就高一点，假设每天工作8小时，那收入就更高。\u003c/p>\u003cp>李老师：为什么想要收入更高一点呢?\u003c/p>\u003cp>张军老师：因为我的收入更高的话，我保证基本生活之后，我就有更多的空闲时间。我并不想收入有太高，只希望达到基本生活需要，我就有更多空闲时间做别的事儿了。\u003c/p>\u003cp>李老师：为什么想要有更多空闲时间呢？有了更多空闲时间你准备做什么呢？\u003c/p>\u003cp>张军老师：希望有更多的空闲时间，是因为小孩需要辅导，我自己也想有学习有进步，我想有时间做这些事。\u003c/p>\u003cp>好的，更这组伙伴掌声，李老师通过问张老师问题，挖掘出来，他想去挖掘国外客户的根本原因和真是需求是“在保证现有收入的情况下，有更多空余时间来陪伴孩子和自我提升”，所以，反过来说，为了达到这个目标，拿那不一定通过挖掘国外的客户，肯定还有其他的方式。\u003c/p>\u003cp>好，谢谢各组的分享！通过问五个问题，我们了解发掘到我们各自内心的真实需求。在合适的时机，通过合理的问为什么、问什么以及问怎么，可以帮助我们挖掘到自己或者他人一直说想要但是迟迟还在犹豫的事情背后的真实需求。希望大家都过上随心所欲的生活。\u003c/p>\u003cp>今天我的TF2-2拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1716285061000,"updated_at":1716604073000,"ria":true},{"id":15629,"topic":"苏格拉底三步法，让交流无障碍","learn_goal":"","remark":"宣传语：当你下班回到家，看到小孩并没有像你期待的那样正在做作业，而是正坐在电视机前看电视，你会立马关掉电视？还是把他臭骂一顿？\n\n除了这种暴力的方式，还有没有更好的方式去处理这种情况呢？","level":"TF3-2","duration":30,"status":29,"type":0,"chaishujia":{"username":"李婷","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cstrong>【自我介绍\u003c/strong> \u003cstrong>】\u003c/strong>\u003c/p>\u003cp>大家好，我是李婷，用3个标签介绍我自己\u003c/p>\u003cp>第一个标签，人资机构打工人，我现在就职于人力资源事业单位，主要负责对接企业的政府申报工作。\u003c/p>\u003cp>第二个标签，《30天挑战》者，用30天挑战一件自己想做的事，截止到现在我已经完成5个挑战，历史5个月，150天。3月正在进行第6个挑战，如果你也想用30天改变自己，欢迎你的加入。\u003c/p>\u003cp>第三个标签，批发商，我在3C和IT行业终端零售干了10年，副业做手机，平板，生活电器的批发业务。\u003c/p>\u003cp>今天要拆的级别是3-2，为了让大家在学习的过程中，更好的交流与讨论，我们现在分组。\u003c/p>\u003cp>\u003cstrong>【用学习者场景介绍图书】\u003c/strong>\u003c/p>\u003cp>事件场景：假设你现在正在参加一场面试，当面试官问：“你会如何平衡家庭与事业？”这样的问题时，你会如何作答？\u003c/p>\u003cp>提问：面对这样的问题，你是会针对“如何平衡家庭与事业”这个话题展开一翻自己的见解与分析，还是确认清楚面试官问题背后的真实用意后，再作答？哪种方式会更容易说到对方心坎里呢？\u003c/p>\u003cp>影响:答案很显然，后者的方式会更好。这里并不是说前者的方式不好，只是前者很容易造成你说了一大堆，但没有一句话是对方想听的尴尬局面。\u003c/p>\u003cp>解决：那么，当我们与他人交流时，如何确保对方说的和我们想的是一回事呢？如何将对方的问题细化、聚焦呢？这里将圣人苏格拉底的思考法分享给大家，运用“苏格拉底法”让交流信息更对称，更准确的理解他人。\u003c/p>\u003cp>\u003cstrong>[学习目标]\u003c/strong>\u003c/p>\u003cp>完成本次拆页学习后，当学员面对他人的倾述、抱怨和交流时，能够运用“苏格拉底法”挖掘对方的所思所想，并让对方具体的表达出来，更深入的理解或帮助他人。\u003c/p>\u003cp>\u003cstrong>【自测题】\u003c/strong>\u003c/p>\u003cp>在开始阅读拆页之前，请大家利用3分钟的时间完成以下测试，完成以后请把分数发到留言区。\u003c/p>","ratings_count":1,"texts":[{"id":19692,"quote":"\u003cp>\u003cstrong>A1自测量表\u003c/strong>\u003c/p>\u003cp>请仔细阅读下面表格中的五个题目，根据自己的实际情况为自己打分（1代表完全不符合，6代表非常符合）。\u003c/p>\u003cp>\u003cstrong>I解释自测题\u003c/strong>\u003c/p>\u003cp>分数的高低不代表好坏，目的是看看大家是否拥有像苏格拉底一样思考的思维。\u003c/p>\u003cp>分数越高，代表你与他人交流时，会更多的关注到对方，引导对方去思考和表达自己。反之，我们要有意识的培养自己多提问少表达的习惯。\u003c/p>\u003cp>大家一定很纳闷吧，为什么要像苏格拉底一样思考呢？接下来，请大家带着这份好奇心，阅读原文拆页，给大家2分钟的时间，读完的小伙伴请在留言区回复“1”。\u003c/p>\u003cp>\u003cstrong>R原文片段（不带HOW的片段）\u003c/strong>\u003c/p>\u003cp>苏格拉底生活在古希腊，他是一位杰出的、善于提具有影响力的问题的大师。他在教授学生时，并没有采取演讲的方式，而是传授给学生一系列发人深省的问题。通过这些问题，他鼓励学生在学习中提升自己的思维。他总是能揭示出这些问题的本质。尽管只是慢慢地一点点渗透，但却总能直达事物的核心。\u003c/p>\u003cp>苏格拉底总是以“什么是美德”或“什么是美好”这些我们随时都在用的词语开始他的课程。我们真地清楚它们意味着什么吗？今天，世界上的许多大学都在他们的教学中采用了“苏格拉底法”，其中最有名的便是哈佛大学商学院。\u003c/p>\u003cp>苏格拉底将这一方法总结得很透彻。他说：“人类最高级的智慧就是向自己或向别人提问。”\u003c/p>\u003cp>l 不要说：“我们需要改进客服质量！”而试着问：“你今天如何评价我们的客服水平？”或者“我们的服务将会如何影响客户的保有量？”\u003c/p>\u003cp>l 不要说：“我受够你的坏脾气了！”而试着问：“你生气时是否想过，这会影响你和身边最亲近的人的关系？”\u003c/p>\u003cp>l 在工作中，有人会说：“我们需要更多的创新。”这时你应该问：“你眼中的创新是什么样子？”\u003c/p>\u003cp>l 当听到一个需要更多团队合作的提议时，你可以这样问：“当你提到‘团队’一词时，你的意思是什么？”\u003c/p>\u003cp>l 有人会说：“我不信任他。”这时你可以这样回应：“为什么？在这种情形中，对你来说信任是什么？”\u003c/p>\u003cp>诸如此类的问题能够引导对话双方进入更深层次的探讨中，并让对方参与进来，引起他们的思考。你也会因此赢得智慧导师的声誉——引导别人步入正确的方向，而不是将自己的观点强加于人。\u003c/p>","explains":"\u003cp>\u003cstrong>I折书讲解\u003c/strong>\u003c/p>\u003cp>【What】这一段介绍了“苏格拉底法”的核心内容就是向自己和别人提问，通过提问的方式，引导对话双方进入更深层次的探讨中，并让对方参与进来，引起他们的思考，加深双方对彼此的理解。\u003c/p>\u003cp>\u003cstrong>【简短互动】\u003c/strong>\u003c/p>\u003cp>请大家和我一起思考一个问题，为什么苏格拉底总是以“什么是美德”或“什么是美好”这些简单的问题开始课程？\u003c/p>\u003cp>学员：我认为他是想把大家往正向的方向去引导。\u003c/p>\u003cp>我：好的，谢谢你的回答，我想问一下你，对你来说，什么事情是美好的？（通过提问来引导到我希望他回答的方向）\u003c/p>\u003cp>学员：每个人对美好的定义不一样，可能有些人着力点在自己的家庭，有的人在事业上，对于我来说，一家人开开心心，收入够用，是件很美好的事情。\u003c/p>\u003cp>恩，是的，对我来说，我认为的美好，是在一个春暖花开的时候，小树叶在风中摆动着。我们每个人对美好的定义是不一样的，我之所以提这个问题，是为了让大家思考，当我们对同一件事情有不同理解的时候，要如何让彼此之间达成共识，也就是我们说的是同一件事情。\u003c/p>\u003cp>其实刚刚我也运用了提问的方式，让大家思考这个片段，我的目的一方面是为了确保我传达的内容和大家的理解是一致的，另一方面，也想引发大家对于提问这个方式的深层思考。为什么提问的效果比我们直接告诉他们效果更好？有句老话说，提一个好问题，胜过千言万语。那么，我们如何正确使用“苏格拉底法”去引导对方说出我们想得到的信息呢？\u003c/p>\u003cp> \u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>我按照原文脉络，细化了行动步骤：\u003c/p>\u003cp>首先，克制表达，不直接给建议和评价。\u003c/p>\u003cp>其次，有针对性的提问：\u003c/p>\u003cp>(1) 用为什么……？提问对方的动机；\u003c/p>\u003cp>(2) 用如何……？提问对方的行动计划；\u003c/p>\u003cp>(3) 用是否想过……？提问对方的感受;\u003c/p>\u003cp>(4) 用是什么......？提问对方的观点和看法;\u003c/p>\u003cp>最后，认真倾听,根据对方的回答，决定是否继续使用步骤二，深入探讨。\u003c/p>\u003cp> \u003cstrong>【预防疑议】\u003c/strong>\u003c/p>\u003cp>这三个步骤，相对比较好操作的是第一步和第三步，只要我们控制好自己就行。最有难度的是第二步，需要我们及时去发现对方说话的信息，并正确选择用哪一种方式去提问，引导对方说出我们想知道的内容，要达到灵活运用，需要在平时不断的练习和实践。\u003c/p>\u003cp>其实更好的方式应该用4个例子让大家去感受一下这个用法，不过由于时间原因我以最后一个问话方式来举例，大家可以感受一下。\u003c/p>\u003cp>【A1】\u003c/p>\u003cp>记得前天，我去参加头马的一个活动，当天入会以后，我把这个消息告诉了我的师傅七七。我告诉她，头马的会员是全国通用的，每个分支俱乐部都可以参加。七七疑惑的问我，通用吗？好像不通用吧。她说她记得上次去另一个俱乐部好像说也是要交钱的。于是，我俩就通不通用，展开了一翻激烈的“辩论”，其实我俩对于“通用”的理解是不一样的。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>运用苏格拉底法，回到这个对话,当她说：“通用吗？好像不通用吧，记得上次去另一个俱乐部好像说也是要交钱的这话以后，首先，我就应该停下来克制表达（第一步），接着，我会问她：“那你说的通用指的是什么意思？”（第4个提问方式，提问对方的观点和看法）。最后，听她说完她的理解以及她了解的信息（第三步）。\u003c/p>\u003cp>回忆这个案例时，给我的触动是非常大的。在向她提问以后，发现我俩对于“通用”的理解是完全不一样的。\u003c/p>\u003cp>我理解的通用是只要交了会费，就可以不受限制的在头马任何一家俱乐部进行培养，只是去到不同的俱乐部参加活动的“茶位费”不一样，但是七七理解的是无论去哪一家分支俱乐部，除了茶位费应该免费，还有练级通用才是真的“通用”。\u003c/p>\u003cp>\u003cstrong>【试用边界】\u003c/strong>\u003c/p>\u003cp>提问不仅可以用于确认对方的想法，还可以通过向对方提问，激发他们自己思考问题，找出答案。但要注意的是，提问的内容和语气不要让对方感受到被挑衅，这样会让对方反感，不太愿意继续聊下去。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3角色扮演与互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>案例一：\u003c/strong>小王是东区某市销售经理，本季度所带领的团队完成率排东区最后一名。在季度会议结束后，小王找到东区的区域负责人张总汇报情况以及寻求帮助，小王说：“张总，完成率低的主要原因是现在人手不够，大家各搞各的。张总沉思了一会儿......接下来，请一人扮演小王，一人扮演张总，办演张总的伙伴在整个沟通过程中，需要大家运用到“苏格拉底法”的三个步骤，帮助小王探寻大家各搞各的原因以及如何处理人手不够的问题。\u003c/p>\u003cp>学员一：小王\u003c/p>\u003cp>学员二：张总\u003c/p>\u003cp>学员一：张总，这次我这个销售排名不好，这个真的不怪我，我们是有原因的，第一，我没有人，没人给我干活，第二，剩下这些人自己干自己的，我根本就没有办法带这个团队，不是我的错，都是他们的错。\u003c/p>\u003cp>学员二：小王，那你是否有分析过，大家不配合你，是为什么吗？（引导对方思考，想动机和原因）\u003c/p>\u003cp>学员一：他们就是不想干活，就是糊弄人\u003c/p>\u003cp>学员二：那你得出他们糊弄人的依据是什么呢？（提问对方的观点和看法）\u003c/p>\u003cp>学员一：他们拜访的数量不够，他们拜访的时间太但是没有成交\u003c/p>\u003cp>学员二：好的，我了解了，那你作为团队的领导人，针对以上的问题，你有做哪些解决方案？你会怎么处理这个问题？（询问引导行动计划）\u003c/p>\u003cp>学员一：制定正向和负向激励制度，不让大家吃大锅饭，做得好的拿更多的钱，其次，做得不好的，需要复盘一小时。\u003c/p>\u003cp>学员二：那你这样做，就人手不够的问题，我可以给你配置二个名额，你下个季度计划达到什么结果呢？\u003c/p>\u003cp>学员一：下个季度的业绩计划同比上个季度提高10%。\u003c/p>\u003cp>好的，感谢两位精彩的演绎，整个过程中，张总做的非常好的一点是保持克制，没有评价和表达自己的意见，一直在用问题引导小王。我想问一下小王，张总在向你提问的时候，你是什么样的感受？\u003c/p>\u003cp>学员一：我觉得挺好的，本来我想扮演一个刺头，但是不断的问我以后，我刺头不起来。哈哈哈哈\u003c/p>\u003cp>张总没有告诉你要怎么做,而是一直在引导你自己思考，要如何做？最后你们达成了共识，你需要的是增加二个人手，让团队自然淘汰，那你觉得张总解决了你的问题了吗？\u003c/p>\u003cp>学员一：是的，解决了。\u003c/p>\u003cp>\u003cstrong>【A2】课后练习\u003c/strong>\u003c/p>\u003cp>请大家在今明二天去试着用苏格拉底法和身边人交流，过程中尽量克制去表达自己的想法和观点，多用提问的方式，挖掘对方的想法。请留意当时对方是怎么说的，你是怎么回复的，将你们的对话记录下来，发在群里和我们分享。\u003c/p>\u003cp>学员作业反馈：\u003c/p>\u003cp>背景：儿子作业不会做，找到我帮他完成作业\u003c/p>\u003cp>儿子：妈妈，这个题目你帮我看看，怎么做\u003c/p>\u003cp>妈妈：换以前我肯定是直接告诉他，题目要怎么做，我这次想到这个方法，我向他提问了。这个题目对你的难点在哪里？\u003c/p>\u003cp>儿子：这个数学题我做是做了，但是不确定做得对不对，你帮我看看。\u003c/p>\u003cp>妈妈：你做这个题目的思路是什么？可以说给说说吗？\u003c/p>\u003cp>儿子：他BALABALA说了一通，最后说，我不确定最后是先减再乘，还是先乘在减。\u003c/p>\u003cp>妈妈：你在学这个知识点的时候，老师是怎么说的？\u003c/p>\u003cp>儿子：老师说先乘除，再加减\u003c/p>\u003cp>妈妈：那你有答案了吗？\u003c/p>\u003cp>儿子：那我就是对的，好了，我知道了。\u003c/p>\u003cp>【END】\u003c/p>\u003cp>我们每个人内心都有一扇别人打不开的门，唯一能改变我们的，只有我们自己。\u003c/p>\u003cp>把这句话送给大家的目的是，希望我们每个人都能做一个启发他人去改变的人，而不是告诉别人要怎么改变的人。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1681808447000,"updated_at":1682666279000,"ria":true},{"id":14879,"topic":"提问的艺术","learn_goal":"","remark":"提问的艺术","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"青橙","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>hello，大家好，我是今天的晋级者杨桂兰，我今天晋级的关卡是TF2-2。\u003c/p>\u003cp>我用3个数字标签介绍一下自己。第一个数字是1，我来蜀汉分舵已经1年了；第二个数字是2，我正在晋级的关卡是2级；第三个数字是3，大家也看到了，我晋级的关卡并不高，才2-2.我来蜀汉分舵已经一年了，晋级始终触足不前。我也曾问自己，成为3级拆书家了之后，你会成为一个培训师吗，我不会，那我为什么还有坚持晋级。后来我想，既然我来了，那我就需要成为3级拆书家，去看看成为3级之后的风景，至于其他的，以后再说。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>通过本次拆页的现场学习，学习者能想到一个带有批评，抱怨，挑剔等负面情绪的沟通场景，并通过今天拆页学习的方法，写出一个以后可以如何做的具体计划。\u003c/p>","ratings_count":1,"texts":[{"id":18893,"quote":"\u003cp>\u003cstrong>图书介绍；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>（F特征）\u003c/em>\u003c/strong>《提问的艺术》是一本教你如何通过富有技巧性的提问，来提高沟通效率，并提升自身影响力的书。被誉为“风靡全美，影响无数人的神奇提问书”。\u003c/p>\u003cp>\u003cstrong>\u003cem>（A优势）\u003c/em>\u003c/strong>人们普遍认为，我们之所以赢得生意是因为自己的聪明和勤奋，以及说对的事，然而本书打破常规，强调巧妙提问远比给出答案更为重要。对我们而言，无论想快速获得生意，立即获得潜在客户的尊重与信任，让会与不偏离主题，还是想让交谈对象感到备受关注，保持良好人际关系，获得更多人生启示……无疑都得学会聪明地提问。\u003c/p>\u003cp>\u003cstrong>\u003cem>（B利益）\u003c/em>\u003c/strong>本书用具体的问题，真实的案例，为读者打造了一个提升提问技巧的使用宝典。本拆页，通过具体的沟通场景，让学习者面对负面情绪沟通时，能多一种应对方法。\u003c/p>\u003cp>\u003cstrong>阅读原文：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>《提问的艺术：为什么你该这样问》\u003c/strong>  P53--54\u003c/p>\u003cp>\u003cstrong>你希望他们应该多做些什么？\u003c/strong>\u003c/p>\u003cp> “他们必须做出改变！”这是一种普遍存在的批评之声。批评是会传染的。如果你能让别人聚焦在自己所希望看到的行为上，你就能够建立起强有力的直接对话，也能够将抱怨和批评之声转化为关于如何继续前行的建设性对话，并帮助他人重塑对于问题的理解。\u003c/p>\u003cp>不要去消除批评，而要去解决问题。\u003c/p>\u003cp>\u003cstrong>什么时候问最合适\u003c/strong>\u003c/p>\u003cp>·当别人抱怨工作时。\u003c/p>\u003cp>·当某人遭到别人的挑剔和批评时。\u003c/p>\u003cp>\u003cstrong>你还可以这样问\u003c/strong>\u003c/p>\u003cp>·如果你能让别人做出意见完全不同的事——采取能对行为产生巨大影响的行动的话，你希望那将是什么？\u003c/p>\u003cp>·你希望他们做出什么样的改变？\u003c/p>\u003cp>\u003cstrong>接下来这样问\u003c/strong>\u003c/p>\u003cp>·你为什么认为他们没有在做那些事？\u003c/p>\u003cp>·他们之所以做错是因为他们缺乏常识和技能，还是他们的企业要求他们那么做，或是因为他们根本没有能力做到？\u003c/p>\u003cp>请大家花2分钟时间，阅读刚刚发下去的拆页，看完后举请手示意一下，谢谢。\u003c/p>","explains":"\u003cp>好，我看到大家已经看完拆页了。\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>这个拆页片段，介绍了一种面对批评、指责场景的有效沟通的方法。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>在交谈中，交谈对象一直在对着我们宣泄负面能量：批评、抱怨、挑剔，让我们眼睁睁的看着事情远离我们想要的轨道，而且不经意间，我们的思绪被带偏。这时，面对对方的不满，我们的第一反应是解释，亦或是爆发自己的情绪。不论哪种，事情都没往我们预想的方向发展。这时，我们该怎么做，才能让我们的沟通更高效，让谈话回到真题，对我们有利的方向上？\u003c/p>\u003cp>那该怎么做呢？今天拆页提供的方法，让我们应对这种场景，多了一种应对方法。\u003c/p>\u003cp>\u003cstrong>【HOW】那具体怎么做呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、\u003c/strong>\u003cstrong>放下情绪\u003c/strong>；在面对谈话者的批评、抱怨、挑剔等情绪时，我们可以愤怒，但我们一定要清楚，爆发情绪并不能拿到我们想要的结果。所以这时，在心理给自己设置一个开关。一遇到交谈，变成指责、批评、挑剔时，就告诉自己，“按一下开关”。让心绪回归冷静。\u003c/p>\u003cp>比如：\u003c/p>\u003cp> 小A是瑜伽馆的店长，他想让会员小B买一些提升课。\u003c/p>\u003cp>小A：“最近练习怎么样啊？”\u003c/p>\u003cp>小B：“就那样吧！我练了一年了，这一年我跑的这么勤，几乎每天都来了。你看我想要改善的富贵包，圆肩驼背还是这个样子，一点都没改善。而且，你们这里明明是社区馆，老师的流动量还那么大？以前一起练习的老会员，越来越少……”小B的抱怨像是洪水决堤一样袭来。 \u003c/p>\u003cp>这时候，就处于一种批评的情绪当中。告诉自己“按一下开关”，这个提示就告诉自己，我想要得到这一单生意，就不让情绪遮挡了我内心的渴望。\u003c/p>\u003cp>\u003cstrong>1、\u003c/strong>\u003cstrong>拉回正题\u003c/strong>：你可以这样说，将对方拉回正题。句式：（批评/抱怨/挑剔的）这体事+你希望应该是什么样的？\u003c/p>\u003cp> 回到上面的例子上，面对小B的抱怨，成单的可能性似乎越来越渺茫。小A 可以这样问，将话题拉回正轨：你体态的改善，你希望改善到什么样子呢？一下子拉回到用户最关心的问题上了。\u003c/p>\u003cp>\u003cstrong>2、\u003c/strong>\u003cstrong>挖掘信息\u003c/strong>：尽量用提问，来挖掘出对方心理潜在的答案。一步一步让交谈对象，说出自己真正的顾虑，引发进一步的思考。比如可以这样问：你认为应该怎么做？或者没有做到哪些呢？……\u003c/p>\u003cp> 回到上面的案例：将会员拉回正题之后，多给她解决一点实际的问题之后，再问：你希望上些什么类型的课程啊？进一步挖掘她的信息。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>在面对客户/同事/家人批评、抱怨、挑剔等负面情景时运用。\u003c/p>\u003cp>\u003cstrong>【预防性讲解】\u003c/strong>\u003c/p>\u003cp>有没有人觉得这个方法太难了，一遇到批评、指责、挑剔自己就炸了，根本控制不住情绪，也就没有了后续的提问。学了那么多情绪控制方法，到用时还是想不起来。\u003c/p>\u003cp>那你就是小看了开关的作用，就像，望梅止渴，你一看到有关酸梅的图片，词，你的嘴巴就会分泌唾液。\u003c/p>\u003cp>所以，多练习几次，就能轻松掌控，不被情绪带着走了。\u003c/p>\u003cp>还有人问，我去跟他摆事实讲道理不好吗？为什么一定要去想个问题来问对方，比摆事实更好呢？\u003c/p>\u003cp>会有这些疑问的伙伴，可都是爱思考的人啊！试想一下，听别人讲，能引发你多少思考？如果是问你一个互动的问题，又能引发你多少思考，而且，别人问你问题，你需要做出及时反馈，还是不是能让你印象更深刻一些呢？答案不言而喻了吧！\u003c/p>","interaction":"\u003cp>\u003cstrong>分布催化1：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（激活学习者想出具体的应用场景）：\u003c/strong>\u003c/p>\u003cp>那，回到现实生活中，大家预想一下，在面对同事，客户时，你们正在谈一件事，对方确在不停的对着你批评，抱怨，挑剔，话题越走越偏，就是不回归到，你们正在谈的这件事的情况呢？\u003c/p>\u003cp>大家预想一个沟通场景。\u003c/p>\u003cp>联想一下自己的生活经历，未来在怎样的场景下来应用我们刚刚学到的方法。\u003c/p>\u003cp>比如：在和妻子/丈夫讨论育儿的方法时，说着说着确变成了互相指责；当我们和父母/孩子沟通时，明明就一件事就事论事，确变成了翻旧账；和客户/上司，讨论方案时，变成了指责/抱怨……\u003c/p>\u003cp>\u003cstrong>大家可以参考这样的格式：在（\u003c/strong> \u003cstrong>）的时候，或者（\u003c/strong> \u003cstrong>）的时候。\u003c/strong>\u003c/p>\u003cp>注意：只需设想出一个具体的场景即可。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong> \u003c/strong> 在（和丈夫讨论孩子字写的丑）的时候，我们都应该停下挑剔的眼光，停下指责抱怨，而不是让话题越走越远。\u003c/p>\u003cp>分布催化2：\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（规划如何运用）：\u003c/strong>\u003c/p>\u003cp>刚才我们设想好了一个具体的表达场景，现在我们需要在便签纸上写下具体的行动计划。内容包括：具体的时间，具体的场景，和谁说哪些话？先说什么，后说什么？\u003c/p>\u003cp>可以参考一下这种格式：\u003c/p>\u003cp>\u003cstrong>【时间】我想在（），\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【场景】在（）时候，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我会\u003c/strong> \u003cstrong>（放下情绪），\u003c/strong> \u003cstrong>（拉回正题），\u003c/strong> \u003cstrong>（挖掘信息）。以便让话题回归正轨，达到我想要的目的。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp> 【时间】我想在（下周天），\u003c/p>\u003cp>【场景】在（给孩子辅导作业，又一次面临孩子字写的丑的）时候，我会（在和老公商量这件事该怎么解决的时候，当情绪快要歇斯底里爆发的时候，（告诉自己，爆发情绪，这样并不能解决问题。）（不再指责老公花费在孩子的时间上少，而是问他“你觉得我们应该怎么解决这个问题”，将话题拉回正题上），（并进一步问他，我们应该怎样协调时间，你才能花更多的时间在孩子身上？）一遍让话题回归正轨，达到我想要的目的。\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>通过我们今天对拆页的学习和应用，相信我们在面对有批评，抱怨，挑剔的沟通时，我们没有被情绪带着走。\u003c/p>\u003cp>而是积极找出应对的方法，让沟通回归正题，让我们的沟通更高效。而不是受了一肚子气，事儿还没办成。\u003c/p>\u003cp>那我今天的晋级就结束啦！谢谢大家的聆听与参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1671527057000,"updated_at":1672037073000,"ria":true},{"id":12775,"topic":"“三分心注定”提问法","learn_goal":"","remark":"当我们的人生遇到重大选择的时候，不管是自己还是他人，总想要得到他人的建议，好让自己做出更正确的选择，但如何选，最终还是需要倾听自己内心的声音。“三分心注定”的提问方法，帮助大家做出更从心的选择。","level":"TF2-2","duration":17,"status":30,"type":0,"chaishujia":{"username":"周凡","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>\u003cstrong>【打招呼、分组】\u003c/strong>\u003c/p>\u003cp> 大家好，我是周周，用三个标签介绍自己【心理老师】【心理咨询师】【个人公众号运营者】，我现在的一个目标就是想通过自己的输出帮助更多的心理老师上好心理课，并将自己所学心理学知识运用到工作、生活中。\u003c/p>\u003cp> 为了今天学习活动的开展，我把大家分几个小组，从我右手边起，两人或三人为一组（根据现场实际情况来）\u003c/p>\u003cp>\u003cstrong>【FAB法】介绍图书\u003c/strong>\u003c/p>\u003cp>F：特征，核心是书，满足好奇心\u003c/p>\u003cp>今天我为大家拆解的是安德鲁·索贝尔写的《提问的艺术》，这本书告诉我们如何通过有技巧性的提问来提高彼此的沟通效率，并提升自身影响力。 \u003c/p>\u003cp>A：优势，比较\u003c/p>\u003cp>这本书揭示了320个强大问题背后的商业与人生精髓，被誉为“影响无数人的神奇提问书”，一直名列亚马逊商业类图书类前100名，书中涵盖了乔布斯、苏格拉底等著名人物的智慧问题和精彩故事，我们可以跟着大师们一起边学边问边思考。\u003c/p>\u003cp>B（✨）：利益，强调学习者，用于引发兴趣，解决痛苦，突破障碍、实现梦想、获得价值等。\u003c/p>\u003cp>这本书能让我们 ，在工作上，通过提问快速了解客户的真正需求；在人际交往中，学会提问，从而使关系得到提升；在自我成长中，对自我提问，帮助自己找到人生的方向。\u003c/p>\u003cp>今天我们要拆解的这个片段就是在人际交往中，当朋友遇到人生重大选择时，来咨询你的意见，你如何通过提问帮助对方厘清思路，做出内心的选择。\u003c/p>\u003cp>【目标】希望大家在跟随我完成本次RIA现场学习后，学会用“三分心注定”的提问方法，帮助对方做出更符合内心的选择。\u003c/p>","ratings_count":1,"texts":[{"id":16717,"quote":"\u003cp>【R】 \u003c/p>\u003cp>“请尽可能给我打个电话，我需要和你谈一谈。”我正在自己供职的教堂负责11点服务的热线工作，教堂的神父汤姆·塞维尔拉着我的胳膊悄悄对我说，他很着急见我。我是这所教堂的董事会主席，汤姆和我关系非常好。我周一的第一件事就是打电话给他。我正在想最坏的结果。第二天，我坐在了汤姆摆满图书的办公室里。我能看出他正经受着痛苦的煎熬，我从未见过他如此平静。\u003c/p>\u003cp>“我得到了一个新职位，”汤姆说，“你还记得四周前的礼拜日我没来吗？我去纽约的一个教堂做传道者了。他们正在考察我。那是纽约最大、最有声望的教堂。他们已经通知我去他们那里做高级神父了。那可是教堂中最重要的神职人员了。”\u003c/p>\u003cp>“我为你感到骄傲，”我回应道，“但这一点儿都不意外，在你和我们一起工作的这段时间内，我们的教堂规模已经扩大到了三倍，我们的教友都十分地敬重你。最值得骄傲的是你将传道的价值发挥到了极致。请告诉我你的决定是什么？” \u003c/p>\u003cp>“我还没有做出决定。南希不太愿意搬家，但她支持我。 孩子们一点儿都不喜欢纽约，他们在这里有自己的好朋友。他们会联合起来抵制搬家。我该怎么办呢？”\u003c/p>\u003cp>我停顿下来，并立刻陷入对汤姆所面临困境的沉思中。当选择关乎个人的时候，做出选择需要你有足够的勇气，最好的办法就是去挖掘和发现自己内心深处真正最想做的是什么。 \u003c/p>\u003cp>我决定采用加减法帮助汤姆做决定。加减法就是在表格中央划一条竖线，一边是有利的一面，一边则标出弊端。 \u003c/p>\u003cp>于是我开始问汤姆。在有利的一边，有很多好处，如薪水更高、牧师的住宅更大以及信徒人数是我们教堂的四倍，有全职的商务经理以及多达七名的神职人员。而在弊端的一进，所列的弊端显然更多。例如，从刚一开始南希就更愿意留下来， 两个大一点的孩子正在上高中——泰德是校篮球队的， 而法兰是班长。汤姆自己也不太喜欢纽约。单子上罗列的弊端还在增加。他将会把所有的时间和精力都花在传道上，他还会失去自己与教友们已经建立起来的关系和私入联系。他将成为那个教堂的形象代言人，而不是教堂的灵魂与精神人物。最重要的是，汤姆非常担忧离开会给刚发起的资本运作带来负面影响。\u003c/p>\u003cp>最后，我平静地问他：“汤姆，根据你所讲的一切，你觉得什么才是正确的决定？”汤姆从椅子上跳了起来，给了我一个大大的拥抱，说道：“你已经给了我答案。”实际上，我并没有给他答案，是他自己找到了解决方法。\u003c/p>","explains":"\u003cp>【I】有体现出预防学习者可能出现的异议（预测异议；预防讲解；激活应用）；有举例（3’40”)\u003c/p>\u003cp>接下来是我对这个片段的一个拆解，在我们的人际交往过程中，或多或少会遇到他人向我们咨询一些事情，小到买哪件衣服、口红选什么色号、宵夜吃哪一家，大到是否决定辞职、买房选哪个小区、是否当全职妈妈等。有些小事我们很容易就能给出自己的建议，但有些关乎人生的重大选择，我们并不能轻易给出自己的建议。而本书中提供了一个方法，通过“三分心注定”的提问法来帮助对方了解自己内心的真正需求，从而做出更符合心意的选择。\u003c/p>\u003cp>什么是“三分法”呢？\u003c/p>\u003cp>\u003cstrong>一分，分区\u003c/strong>，拿出一张纸，在纸的中间画一条竖线，将白纸分成两个区，一个区是做某个决定的好处，一个区是做决定的坏处。\u003c/p>\u003cp>\u003cstrong>二分，分类\u003c/strong>，通过提问，让对方把做出该决定的好处和坏处分别写在两边，把所有能想到的点都写进去，越多越好；\u003c/p>\u003cp>\u003cstrong>三分，分辨内心，向对方\u003c/strong>提问：“根据你所讲的一切，你觉得什么才是正确的选择？”让对方分清自己内心的真正需求，从而做出选择。\u003c/p>\u003cp>【适用边界】那具体什么情况下适合用这个方法帮助对方做选择呢？我个人觉得生活中一般的选择，比如吃喝玩乐这种简单的，就直接给出自己的建议，毕竟选错了也不会对人生造成大的影响。但如果这个选择对个人有非常重大的意义，是关乎人生的选择，比如工作、结婚、买房买车等等，还是运用“三分心注定”提问法帮助对方，让其自己做出从心的选择。\u003c/p>\u003cp>【预防异议】大家可能会疑惑，这个方法真的会有效吗？万一对方列举了利弊之后，仍然无法做出决定，该怎么办呢？是的，关乎我们人生的重大选择肯定不是在短时间内就能做出来，但通过这样的提问，帮助对方一步步了解自己内心的真正需求，让对方做决定的时候多一些参考依据，可能有些决定就自然而然的产生了，就算当下没有结果，也不代表我们没有帮助到对方。\u003c/p>\u003cp>【举例】上一周，我的闺蜜向我咨询是否要停止现在的工作，全心准备教师考编，我当时就运用了这个方法，首先让她在纸上分区，分好利弊区，接着我问她：“如果你准备全力考编，会有什么好处和坏处呢？”写在纸上，她表示：“如果现在辞职全力考编，好处1是有更多的时间准备，2能腾出时间照顾孩子，3是全力以赴，让自己少一点遗憾；坏处1是收入减少了；2是长时间看书难以坚持；3是考不上的话会很沮丧，还会担心未来”。在她列举完利弊之后，我接着问她：“根据你所列举的一切，你觉得什么才是你真正想做的决定？”她说自己看到辞职后需要长时间看书是自己难以做到的，而且现在的工作也不累，所以边工作边考编更能调节自己的心情。\u003c/p>","interaction":"\u003cp>【分步催化】先激活应用场景，再规划行动步骤（1’+2’)\u003c/p>\u003cp>小伙伴们，在你们的生活中，会遇到以下场景吗？好朋友在国企事业单位上班，每天做一些重复的事，觉得很无聊，来咨询你是不是要跳槽到一个有挑战的新环境；闺蜜生了孩子，为了更好地陪伴孩子成长，来问你可以辞职成为全职太太吗；公司向同事提议去一个新的岗位，虽然工资待遇更好一点，但这里是他从没有接触过的工作内容，他来询问你的意见？接下来请你想象一下，在未来的一周是否会遇到别人来向你咨询如何在两难情境中做选择，把它写在便签纸上：那个情境的对象是谁，发生了什么事情？请大家用两分钟的时间，将你想到的内容写下来，现在开始，写好的小伙伴请看我一眼哦。\u003c/p>\u003cp>【分步催化步骤】\u003c/p>\u003cp>好的，时间到了，那么一周之后，当这个场景真实发生时，对方向你寻求建议和帮助，你灵机一动，想到了我们今天学到的“三分心注定”的提问法，一分，分区；二分，分类；三分，分辨内心；你会如何向对方提问呢？请将你设想的场景及对话写在便签纸上，写完之后小组内进行讨论，就是我们最初分好的小组，之后请一个小伙伴向我们分享一下。\u003c/p>\u003cp>就请我右手边这位坐的最近的小伙伴来分享一下吧。\u003c/p>\u003cp>分享者：\u003c/p>\u003cp> 因为我是小学老师，如果之后继续有家长向我询问是不是应该要辞职从外地回长沙带小孩，我会用这个方法，首先分区，把利弊区分开，从利的方面来说，她可以更及时的了解孩子的信息，而且孩子会更愿意听父母的话，这是对她自己的小孩有好处的，而且低年级的小孩有很多不好的习惯，所以在反馈及时性上有很好的了解；第二呢，她自己可以更好的陪伴孩子成长；第三就是夫妻之间承担了更多的责任或者是彼此分享育儿经验，有助于促进感情；第四，她的父母也能得到更多休息。弊端的话主要还是事业上来说，鼓励她自己列出来面临的情况，可能要升职了，可能年龄30多了，已经积累的人脉会减少；第三就是回来之后可能会有一些矛盾，还有就是孩子本身会有不适应。最后的话，我会向她提问，根据她所讲的一切，她自己觉得，从内心里面更想要做哪种选择，这就是我想的未来的一个场景。\u003c/p>\u003cp> 非常感谢这位小伙伴的给力分享，当然我们只是一个方法的提供者，最终做出决定和选择还是对方本身，根据他自己内心的需求，他会做出自己决定。\u003c/p>\u003cp> 今天我们的拆书活动就到这儿了，希望大家在未来的生活中遇到有人向你咨询人生重大选择的时候，或自己需要做出某个重大决定的时候，都能想起我们今天的“三分心注定”提问法。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1639034777000,"updated_at":1639206966000,"ria":true},{"id":11570,"topic":"找到“我”该过怎样的人生","learn_goal":"","remark":"《提问的艺术：为什么你该这样问》是一本教你如何通过富有技巧性的提问来提高沟通效率并提升自身影响力的书。打破常规，学会问好问题，找到“我”该过怎样的人生，获得更多的人生启示就从学会提问开始。","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"兔小灰","city":""},"club":{"name":"徐州筹备分舵","city":""},"prologue":"\u003cp>【自我介绍】各位好，我是惠秦翔，大家都叫我兔子先生。常言道狡兔三窟，那么这三个兔子洞都分别通向哪里呢？\u003c/p>\u003cp>第一个通向地铁装备行业，我目前的职业是外企的地铁信号工程师。\u003c/p>\u003cp>第二个去往简书作者，闲暇时喜欢在上面更新上班的各种优雅摸鱼技巧。\u003c/p>\u003cp>进入第三个兔子洞你会遇到一位菜鸟军师，帮你从信息整合分析的角度辅助决策并提供有趣的建议。\u003c/p>\u003cp>如果大家想了解其中任意一个洞里乾坤，欢迎稍后一起交流。（1分钟）\u003c/p>\u003cp>【拆书帮介绍】下面，我给大家介绍一下“拆书”是什么？“拆书帮”又是什么？“拆书”是一种学习方法，适用于提升能力、解决问题的成人学习，强调以学习者为中心，关联个人的经验、规划和行动。\u003c/p>\u003cp>具体的拆书方法是“RIA现场学习”和个人的“便签学习法”。R(即reading阅读拆页）：阅读原书中的拆页。I（Interpretation,讲解引导）拆书家讲解引导，促学习者理解知识并关联自己。A（Appropriation,拆为己用），拆书家促进学习者将书中的内容拆为己用。\u003c/p>\u003cp>“而拆书帮”就是基于拆书法的学习爱好者社群，作为非营利的青年自发组织，我们已经拥有了50家分舵，有 40家筹备分舵，覆盖全国28个省67座城市。并在一天天壮大。\u003c/p>","ratings_count":1,"texts":[{"id":15497,"quote":"\u003cp>《提问的艺术》（美）安德鲁 索贝尔；\u003c/p>\u003cp>第三篇 人生篇 电子书p240-241\u003c/p>\u003cp>为了帮助别人弄清楚在人生中究竟什么才是他们真正想做的事情，他们想如何被人记住时，你可以这样问：“如果今天让你来写自己的讣告，你最想怎样来总结你的一生？”\u003c/p>\u003cp>|提问的心得|\u003c/p>\u003cp>如果今天让你来写自己的讣告，你最想怎样来总结你的一生？\u003c/p>\u003cp>讣告通常是为那些离世的人而写的，是家人和朋友用于缅怀那些离世之人的文章。从另一个角度来看，讣告也能成为对活着的人的一个重要提示。提前想象一下有助于你塑造自己的人生。\u003c/p>\u003cp>它向你喻示了什么对你来说才是最重要的，什么才是你真正喜欢、愿意为之投入精力去做的事。写一份讣告的确能让你清楚地知道你正在做的和能做的选择是什么。\u003c/p>\u003cp>什么时候问最合适\u003c/p>\u003cp>●当你指导和督促某人时。\u003c/p>\u003cp>●当一位年轻人在为自己的职业和人生做出重大选择时。\u003c/p>\u003cp>你还可以这样问\u003c/p>\u003cp>●往前看一下你的人生，你觉得什么能给予你最大的成就感？\u003c/p>\u003cp>什么能让你得到最大的满足？\u003c/p>\u003cp>●有没有什么事你还没做但在离开这个世界前一定要做？\u003c/p>\u003cp>接下来这样问\u003c/p>\u003cp>●为什么你要将这些特别的事写入你的讣告？\u003c/p>\u003cp>●什么能让你达成你想要的成就?\u003c/p>","explains":"\u003cp>好的，我看大家已经都阅读完原文片段了。下面由我来带领大家一起拆解一下原文片段的内容。\u003c/p>\u003cp>\u003cem>【WHAT】\u003c/em>\u003c/p>\u003cp>这个片段讲了一个教我们如何引导别人找到真正喜欢的事的方法-讣告提问法\u003c/p>\u003cp>\u003cem>【WHY】 \u003c/em>\u003c/p>\u003cp>每个人最了解的人还是自己，以讣告为基础的提问更容易挖掘被帮助者内心的真实需求。避免我们以己度人，给出不恰当的建议或指导\u003c/p>\u003cp>\u003cem>【HOW】\u003c/em>\u003c/p>\u003cp>这个方法需要我们向求助者提三个问题，分别是：\u003c/p>\u003cp>1、成就来源，将来做成什么事会让你产生极大的成就与满足感？\u003c/p>\u003cp>2、讣告追问，有没有什么事你还没做但在离开这个世界前一定要做？\u003c/p>\u003cp>3、探究原因，为什么要做这件事以及如何做成？\u003c/p>\u003cp>\u003cem>【WHERE】\u003c/em>\u003c/p>\u003cp>当有年轻的朋友面临人生重大抉择找你咨询时可以用到。\u003c/p>\u003cp>自己面临重大决定也可以使用这种方法自助提问找到答案。\u003c/p>\u003cp>或者产品新功能的开发决策内部讨论时也可以应用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong> 下面我讲一下我的切身经历与体会。\u003c/p>\u003cp>三年前有一位朋友托我帮他弟弟选择高考志愿，他喜欢的分数基本只能读二本院校于是我就提了两个问题：\u003c/p>\u003cp>第一个：你觉得将来干什么事情会让你觉得自己有成就感，特别酷？\u003c/p>\u003cp>他回答：我喜欢马斯克，我想自己造中国的特斯拉，我喜欢汽车。但是亲戚都说学车辆工程挣钱太少，那我想要不要去学计算机，这个挣钱而且我也挺喜欢。\u003c/p>\u003cp>第二个问题我问：假设你学了计算机，毕业后钱也挣够了，你想再去干点啥？\u003c/p>\u003cp>小伙子回答：那肯定是去造车呀！\u003c/p>\u003cp>其实我就是想通过这两个问题让他自己去探究自己真正想干的事情。最后再结合他的成绩和行业特点给出建议。\u003c/p>\u003cp>那么我做的究竟怎么样呢？\u003c/p>\u003cp>通过这件事，并结合这个片段，我进行了反思：\u003c/p>\u003cp>关于第一点成就来源和第二点讣告追问我勉强算问的不错，但是第三点我并没有问对不对？\u003c/p>\u003cp>也就是说我并没有帮助他去探究他为什么要去做这件事，他喜欢的到底是“造车”这件事本身，还是这件事所带来的附加收益。比如说，他可能只是喜欢马斯克可以自由地放嘴炮，喜欢特斯拉的智能驾驶而不是车本身。他可能根本也没考虑过这件事如何做成。\u003c/p>\u003cp>所以缺少了第三步的追问会导致我可能已经误导了一位年轻人。\u003c/p>\u003cp>\u003cstrong>A2 \u003c/strong>通过这个片段，结合我的切身经验，我把这个片段拆为己用，具体我是这么计划的：\u003c/p>\u003cp>\u003cem>目标：\u003c/em>一位关系很好的同事最近在咨询我关于转行的可行性，我决定设计这三个问题帮他找到自己想要的答案。\u003c/p>\u003cp>\u003cem>行动：\u003c/em>我的问题设计\u003c/p>\u003cp>1、你将来做成功什么事情会让你觉得这辈子没白来？\u003c/p>\u003cp>2、如果要给自己写一份讣告，什么事情在离开之前必须要做？\u003c/p>\u003cp>3、你转行之后觉得自己必须要具备什么能力？这个能力现在具备吗？如果没有具备对你来说好掌握吗？\u003c/p>\u003cp>相信这一连串的提问能帮助他找到答案。\u003c/p>\u003cp>好，今天的拆页学习就到此结束，希望这个方法可以给大家带来启发。\u003c/p>\u003cp>我是兔子先生，感谢各位的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1621502081000,"updated_at":1621586035000,"ria":true},{"id":11196,"topic":"“你怎么想？”--通过提问可与他人增加链接","learn_goal":"","remark":"学习者知道通过了解“你怎么想”这一问句，知道何时可以使用它。在提问并倾听后，增加与他人的链接。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"朱娣娣","city":""},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>自我介绍：\u003c/p>\u003cp>大家晚上好，非常感谢大家来参加我的1-1级别的拆书分享。我是一位名字很有特点的拆书家，我明明是一位女性，大家却都叫我“娣娣”。这是为什么呢？因为啊我的名字是：朱娣娣。娣呢是小S徐熙娣的娣。下面呢用三个标签来介绍一下自己：标签一：热衷于亲子关系、个人成长的研究与实践；标签二：PET实践者；标签三：一个7岁孩子的妈；\u003c/p>\u003cp>拆书帮介绍：\u003c/p>\u003cp>不知道大家是怎么样知道拆书帮的，我呢是通过Coco的介绍知道了拆书帮，拆书帮的使命就是帮助更多的学习爱好者通过练习使用拆书法，一级一级的打怪最终成为拆书家。\u003c/p>\u003cp>那什么是拆书法呢？拆书的理论基础是成人教育学，落到实践呢就是&quot;RIA方法论”，它是一种学习方法论，强调以学习者为中心，联系学习者的经验，将书中的知识转化为我们自己的能力，触发我们的实际行动进行改变，这样可以解决学习者的问题，并且提升个人工作能力。\u003c/p>\u003cp>拆书法有两种形式，一是供个人学习的便签学习法，它包括的三个步骤是：R就是Reading，指阅读原文片段；I是 Interpretation是解释，指用自己的话阐述原文；A是 Appropriation，代表学习者拆为己用。二是供组织学习的RIA现场学习。现在我们进行的就是一场RIA现场学习。现场学习中的A实际分为三个部分：A1是指向过去，主要为反思经验,A2是指向未来，主要为规划后期应用，A3是现场演练，通过现场拆书家提供的情境及要求进行学习；\u003c/p>\u003cp>以上就是拆书法的介绍，我希望能够通过拆书来构建自己的知识体系，在慢成长的环境里将书里的知识变为自己的能力。\u003c/p>\u003cp>好，接下来开始我的分享：\u003c/p>\u003cp>《哈佛幸福课》是一门研究积极心里学的课程，老师在课上提到他之所以研究“积极心理学”就是从一个提问开始的。他用了这样2个问题进行了对比：第一个问题是1、我们怎么样可以避免消极？第2个问题是2、我们怎么样能变得积极且幸福？\u003c/p>\u003cp>大家看出来这2个问题的差异吗？老师在课上抛出了这样一个问题：知道避免消极的办法了就可以变得积极吗？显然不是。所以从那个时候开始，我注意到提问的重要性。今天为大家分享的片段就来源于一个关于提问的书《提问的艺术》，这本书介绍了在不同的场景下，通过富有技巧性的\u003cem>提问\u003c/em>来提高沟通效率。书里面通过许多真实的故事以及大师们的睿智提问，展现了提问的艺术。\u003c/p>\u003cp>好，接下来我们开始拆书的第一个步骤，R，阅读原文。\u003c/p>\u003cp>下面请大家花两分钟时间进行原文阅读，阅读完后，请抬头示意我一下，谢谢。\u003c/p>","ratings_count":2,"texts":[{"id":15109,"quote":"\u003cp>R:阅读原文片断P86\u003c/p>\u003cp>“四个字就足够!这就是我想要的全部。这该死的四个字!”我现在正坐在乔治的办公室里。他正在怒气冲冲地来回踱步。我看到他脚下的地毯上留下了一条清晰的印迹。\u003c/p>\u003cp>乔治是东南部一所重点大学的副校长。在我的这本书中，他是我所接触的大学官员中职位最高的一位。\u003c/p>\u003cp>“请平静一下，”我安慰道，“别太生气了，先坐下吧。”我接着问道:“这四个字的意思是什么?对你意味着什么?\u003c/p>\u003cp>故事就这样开始了。我在此之前已经从乔治那里大致听说了一些关 于他们校长的事。现在他刚开完学校的一个高层会议。一切都没有取得实质性的进展。\u003c/p>\u003cp>“我们接下来还要和校长开一个愚蠢的会议。他花了整整3个小时的时间就是为了告诉我们他是怎么想的，他想怎样做以及他优先考虑的是什么，还有就是他对学校在其领导下的感想如何等。”乔治继续说着他们校长那谁也无法说服的喋喋不休的固执。我在想，如果说有人听不进别人的话，在倾听方面有障碍的话，那一定是他们校长。\u003c/p>\u003cp>“如果他能在中途停下来一次， 哪怕只是一次，” 乔治继续说道，“问一问我们是如何想的，就足已!我想让他说:“你生么想? &#x27;就只有四个字而已。’\u003c/p>\u003cp>乔治是对的。“你怎么想”这四个字是多么地有力!如果你正在征求一项意见，那么对方想让你做的就是去倾听。你或许听说过一个人说得太多，却从未听说过一个人听得太多了。\u003c/p>\u003cp>有一天晚上，梭罗在他的日志中写道:“今天我得到的最大恭维就是有人问我，我怎么想的，并真诚地聆听了我的答案。”\u003c/p>\u003cp>你第一次穿上溜冰鞋时的样子绝对是滑稽可笑的。同样，所谓聆听的艺术也是靠不住的。乔治所说的那四个字的确是个完美的开始。你要问:“你对此是如何想的?”或者 “你对此有何感受?” 这样的提问清单可以不断延伸。这些问题就是我们所谓的开放式问题。它们不能用简单的“是&quot;或“不是”来作答， 而需要一个更清楚的解释。\u003c/p>\u003cp>接下来你需要去倾听，而且还要专注地去倾听，甚至虔诚地倾听。这似乎有些违反直觉，但提问并聆听能够使你很好地控制谈话的主动权。因为你所提的问题是要求有答案的，因此你完全处在有力的位置上。好的聆听者能够迅速从答案中捕捉到一两个关键点。\u003c/p>","explains":"\u003cp>【why】看到大家都已经示意看完了，那这个片段讲述了问题”你怎么想“的重要性。想象这样的场景：你参加一个沟通会，主持人一个人滔滔不绝的讲着，他如何看待这个问题，他如何思考，这件事该怎么样去做，完全没有给你讲话的空间得间隙。而另一个讨论会上，你和伙伴们需要针对一个问题给出方案，主持人问你“对这个问题，你怎么想？”时给了你发表意见与看法的机会。\u003c/p>\u003cp>这样的两种会议，你更愿意参加哪一种呢？有研究表明，如果一项计划，是有自己参与讨论并制定的，自己的执行度都会更高一些。\u003c/p>\u003cp>更深一层的原因是马斯洛的需求层次里有一层是尊重的需求，里面涉及到一点就是我们有表达我们的想法以及看法的需求。如果一个提问，能够满足我们的深层次的需求，你说他重要不重要呢？\u003c/p>\u003cp>同时，当我们这样问的候，如果可以满足对方的深层需求，我们一定也与对方加深了一些链接。\u003c/p>\u003cp>【when】那我们一般什么时候可以用上这个问题呢？当我们正在讨论一项面临的困难或者未来行动方案时。比如项目进行中遇到了一个难题，需要头脑风暴来解决时。或者当你分享了自己的观点、展示了自己的方案时，比如我们写好逐字稿迫不及待地给师父看的时候，是不是特别想问一句：师父，你怎么看？还有一种情形是，当有人带着问题来请教你时，这也是一种巧妙的回应方式，尤其是孩子来问你一些你没有准备的问题，比如：妈妈，为什么老师要布置这么多作业啊？妈妈，为什么小明他可以吃冰淇淋而我不可以吃呢？为什么他可以看电视而我不能看呢？等等，这些问题，你都可以先回应一句：你怎么想呢？这样的以问题回答问题呢，同时给自己争取一些思考的时间也了解孩子怎么样，以便我们更有针对性的回答孩子。\u003c/p>\u003cp>【how】那针对这个问题，我们可以怎么应用呢？\u003c/p>\u003cp>第一步，提问：你怎么想？\u003c/p>\u003cp>第二步：聆听，也可以说是倾听。倾听就是全身灌注的听对方说话，并用肢体和态度表达对对方的关注。通过这样的提问和倾听还可以与他人建立更深一层的链接。\u003c/p>\u003cp>所以实际上，“你怎么想”这四个字的背后透露出来的一种关注，是一种“被看见”。每个人都渴望被聆听，被人关注。想一想，当有人仔细聆听你的思想，好奇你的看法时，有人关注着你时，这会是一件多么美好的事情呀。\u003c/p>","interaction":"\u003cp>说到这里，我想起了我错失了一个与我儿子深度交流的机会。3月中，武汉的疫情渐渐缓解，我们一家人在外地老家，孩子本应上的学，也在网上一直进行着。公司要求我们在三月底开始返汉，为了安全考虑，我们的决定先让孩子在老家呆着，我和他爸爸先回武汉。那这时，我们就有一个问题了，作业怎么保证呢？没有父母的监督，他会好好完成吗？万一学漏了怎么办？这一系列的问题在我的脑海里面盘旋。于是可想而知，我焦虑了……于是我开始计划，给孩子额外布置了写字，英语，口算等等老师没在课堂上做要求的作业。并且要求孩子在我们离开以后按照计划完成。\u003c/p>\u003cp>当我跟孩子以“宣布”而不是“商量”的语气进行作业安排的时候，他跟我来了个否认三连，我不要，我不想，我不能……结果呢，孩子根本就没有按照我的要求进行作业的完成，有一半偷工减料了。\u003c/p>\u003cp>【分享A2便签（smart）】\u003c/p>\u003cp>我想，【T】在等到我的孩子回武汉以后，我需要再面对面的与他讨论他的作业，我会这样去做。\u003c/p>\u003cp>【S】妈妈：来，妈妈跟你商量个事儿啊，你看啊，上学期都快结束了，因为上课形式的变化，也许这样的上课方式会让我们吸收的知识不全面，为了学习到更全面，我想这样安排你的课后作业，…… 你看怎么样?对这个计划，你有什么想法吗？\u003c/p>\u003cp>孩子：……\u003c/p>\u003cp>然后我再根据他的回答以及他的想法，来跟他一起讨论的制定他课后作业的数量与所需时间【M】，最后再和他一起安排完成作业的时间计划表 。\u003c/p>\u003cp>【A】结果呢，我想一定会比我自行安排会要执行得更好的，即使出现什么意外，我也同样可以用“你怎么想？”然后倾听，来进行调整！\u003c/p>\u003cp>我的分享结束了，希望大家能从我的分享里收获一些内容，如果大家有什么想法可以跟我聊一聊，我很愿意做一个聆听者哟！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1616239793000,"updated_at":1617852425000,"ria":true},{"id":9141,"topic":"答得好不如问的好","learn_goal":"","remark":"揭示了320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"车车","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>开场：\u003c/strong>\u003c/p>\u003cp> 大家好，我是车车，车就是马路上跑来跑去的车。我是一个新手拆书家，很高兴能在拆书帮和大家相遇,希望以后的日子能和大家徜徉在拆书的乐趣里，一起学习， 一起进步。 \u003c/p>\u003cp> 第一个标签是第一次，走上拆书之路对我来说是一个突破也是一个挑战；第二个标签是感谢，感谢拆书帮、感谢我的师傅、感谢所有给过我帮助的人、感谢和我一起经历这么多的每个你；第三我想给大家分享一句电影入殓师的台词：全世界的城镇都是我们的新居，一边演奏一边旅行，一起走吧！ \u003c/p>\u003cp> 好，我们接下来开始今天的分享。\u003c/p>\u003cp>\u003cstrong>拆书帮与拆书法介绍：\u003c/strong>\u003c/p>\u003cp> 首先请允许我班门弄斧一下，给大家说一说我自己理解的拆书帮和拆书法。\u003c/p>\u003cp> 我先从RIA便签法说起， R=Reading，读，阅读原文片段； I=Interpretation，用自己的话重述原文片段； A=Appropriation，原意为挪用，这里引申成拆为己用。\u003c/p>\u003cp> 进一步解释一下这个A: A：联系自己的实际经验。 A1指向过去，是指对过去经历的一个反思， A2指向未来，是对未来事件的一个应用。\u003c/p>\u003cp> “拆书”是“拆书家”通过将一本书里的某个片段利用我上面介绍的RIA便签法，把这个片段拆解出来，并进行引申，然后贯彻到自己今后的思考和行动中。而拆书帮就是“拆书家”利用拆书法进行聚众拆书。拆书帮有两种学习形式，1 个人学习—RIA便签法；2 群体学习—RIA现场学习法。它可以帮助学习者了解和应用拆书法，帮助拆书家不断精进拆书功力，实现自我提升。\u003c/p>\u003cp> 接下来开始拆书。 \u003c/p>\u003cp> 首先和大家做个互动，大家可以回想一下，有没有遇到过下面这种情况：当别人问你们问题时，你们有没有过就这个问题侃侃而谈、滔滔不绝讲了一大堆，但后来对方表示他想问的不是这个意思，浪费了半天口水，还做了无用功？我相信大家都有过这样尴尬的时刻。其实，这种情况在一定程度上是可以避免的，我今天带来的这个片段就可以给大家提供一个方法来化解这样的尴尬。\u003c/p>\u003cp> 下面大家可以花1分钟的时候看一下原文片段。\u003c/p>","ratings_count":1,"texts":[{"id":12903,"quote":"\u003cp>\u003cstrong>你想具体了解我哪方面的情况呢？\u003c/strong> \u003c/p>\u003cp>当别人问我们问题时，我们很少要求对方清楚地说明他们具体想知道什么。你有没有见过有些人就一个错误的问题一口气回答了5分钟？他们认为自己听懂了，但回答的却并不是对方真正想要问的问题。这是多么尴尬的一件事！\u003c/p>\u003cp>\u003cstrong>什么时候问最合适\u003c/strong> \u003c/p>\u003cp>●当你被问到一个总体性问题，而这个问题有可能需要很长的回答时。 \u003c/p>\u003cp>●当时间很短暂，你又想针对自己的目标做些简短回答时。\u003c/p>\u003cp>\u003cstrong>你还可以这样问\u003c/strong> \u003c/p>\u003cp>●（1）你对我经历中的哪部分感兴趣？\u003c/p>\u003cp>●（2）你希望我具体介绍哪方面的情况？ \u003c/p>\u003cp>●（3）在我回答你的问题之前，你是否已经对我们的公司有所了解了？ \u003c/p>\u003cp>●（4）如果我先介绍一些像你这样的客户的案例来开始我们今天的介绍，你觉得如何？ \u003c/p>\u003cp>\u003cstrong>接下来这样问\u003c/strong> \u003c/p>\u003cp>●这样能回答你的提问了吗？\u003c/p>\u003cp>●你还希望我们谈些什么？\u003c/p>","explains":"\u003cp>很多小伙伴已经看完片段了。 \u003c/p>\u003cp>针对片段提供的思路和方法，关于如何利用追问的方法明确对方真正想要问什么，避免答非所问，我据原文的三个黑色标题，总结成以下三个步骤，接下来和大家分享。\u003c/p>\u003cp>第一，分辨问题。\u003c/p>\u003cp>语言是非常神奇的一种文化。在一些特定的场景里，一句话也可能有很多意思，一句干啥呀，可以表达出各种各样的情绪：\u003c/p>\u003cp>开心：干啥呀 生气：干啥呀 害怕：干啥呀。（做语气示范） \u003c/p>\u003cp>提问也是同样的道理，一句“介绍一下你自己”，面试、相亲和拆书这几种场合，他要问的内容肯定不是一回事，你的回答也需要各有侧重，这说明，对方提出的问题是有适用边界的。 \u003c/p>\u003cp>当面对一个目标宽泛、体系庞大、指向模糊，说白了就是很笼统的提问，或者当时间短暂，你又想有针对性地做回答时，我们需要分辨问题，先思考对方真正想问的是什么，才可以精准答疑。\u003c/p>\u003cp>第二，合理追问。\u003c/p>\u003cp>如果有些比较复杂的场合，比如商业沟通、职场交流，很多时候对方不会直话直问，像我这种脑子转数基本等于0的选手，分辨不出对方的用意，怎么办？\u003c/p>\u003cp>1.直接要求对方精准目标。大家可以看一下片段中我做小括号标注的问题（1）和问题（2）。\u003c/p>\u003cp>“不好意思，请问我需要具体介绍/回答/阐述哪一部分的内容呢”\u003c/p>\u003cp>2.如果是没有办法精准的问题，那就缩小回答范畴。大家可以看一下片段中的（3）和（4）。\u003c/p>\u003cp>例如：我从123这3个方面阐述你觉得可以吗？ \u003c/p>\u003cp>第三，再次确认。 \u003c/p>\u003cp>进行完前两步以后，需要进行最后补充和总结，“我所说的内容是否解释清楚了你的疑问？”“还有什么需要我补充的地方吗？”。可能会出现两种情况，1 是的，解释清楚了；2 没有，对方还需要了解更多的内容，这种情况你再根据对方的需求进行答疑就可以了。\u003c/p>\u003cp>至此，这个对话基本上就结束了。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1联系具体经验\u003c/strong>\u003c/p>\u003cp>接下来给大家分享一个我的真实经历。 \u003c/p>\u003cp>我17年毕业后第一次参加面试的时候，准备了很多东西：一大堆读书期间的文字作品，各种各样参加活动的照片，我的身份证，户口本都带上，大张旗鼓地就去面试了。\u003c/p>\u003cp>对方问我第一个问题是介绍一下你自己，我就把从出生到毕业全讲一遍，还把活动照片挨个介绍一遍，中间好几次面试官的表情欲言又止，我自动忽略，继续讲我的。基本上我说完，他们都困了。后面的其他提问环节也进展的惨不忍睹。\u003c/p>\u003cp>这就是我的一个经典大型面试翻车现场。因为没有弄清对方提问的真实意图，自作主张的进行了一番操作，我最后的下场就是没有通过面试。\u003c/p>\u003cp>那通过学习片段，再结合我的经历，我意识到：对方是希望我侧重回答我的专业，我的特长以及我对这份工作的胜任能力等内容，那加入我当时追问：我可以从大学经历、活动经历和特长爱好这三个方面回答吗，说不定我现在就是新东方的老员工了。\u003c/p>\u003cp>\u003cstrong>A2具体应用\u003c/strong>\u003c/p>\u003cp>俗话说，在哪里跌倒就在哪里站起来，我10月29号还有一个面试，如果对方让我介绍自己，我就打算按照片段这个步骤来操作一下。\u003c/p>\u003cp>面试官：你可以介绍一下你自己吗？ \u003c/p>\u003cp>1.分辨问题。\u003c/p>\u003cp>首先我们要分辨对方的问题，这是一个笼统的问题，而且正在面试，我需要在短时间内回答出来。那我可以进行下一步。\u003c/p>\u003cp>2.合理追问。\u003c/p>\u003cp>他是面试官，希望我介绍与岗位职责想匹配的内容，我就围绕三个方面回答，我的专业、我的爱好、我的工作经验。\u003c/p>\u003cp>我的回答：您是要了解我专业方面和工作经验方面的基本情况吗？\u003c/p>\u003cp> 或者，我从专业、爱好、工作经验这几方面介绍您觉得可以吗？\u003c/p>\u003cp>回答补充：我是17年毕业于某某大学，专业是编辑出版，目前在一家公益组织担任宣传主管的职务，全权负责机构的宣传工作，算上加班现在有3年工作经验，爱好读书，平时喜欢做一些辩论、头脑风暴和发言类的活动，我觉得自己履历以及各项指标和贵公司的岗位十分匹配。\u003c/p>\u003cp>3.再次确认。 \u003c/p>\u003cp>我：“我是否阐述清楚了这个问题”或者“我这样的表述您满意吗？”。\u003c/p>\u003cp>面试官:是——话题结束。\u003c/p>\u003cp>面试官：还不够清楚\\全面。\u003c/p>\u003cp>我：请问还有哪些内容是您感兴趣的？或者您觉得我说的哪些内容是需要再补充说明一下的？；\u003c/p>\u003cp>接着，就他的问题再注意回答就好了。 \u003c/p>\u003cp>这样，我的追问会让我的面试过程更轻松，让我的形象更亲切可靠，我与面试官的沟通也会更顺利。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>\u003c/p>\u003cp>总结一下，当有人提出“能否向我们介绍一下你或者你们的情况”这种笼统问题的时候，你可以利用一分辨、二追问、三确认的方法对问题进行精准定位，只有问清楚了、弄懂了对方的真实意图，才可以更好地回答这个问题，从而树立起自身亲切、周密的良好形象，帮助双方建立更好的沟通关系。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1571992074000,"updated_at":1572584051000,"ria":true},{"id":6444,"topic":"通过五个问题来挖掘真实需求","learn_goal":"通过五个问题挖掘自己或对方的真实需求","remark":"","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"各位小伙伴，大家晚上好！我是马文丽。非常高兴大家参加我今天TF2-2的拆书分享。在跟随我完成本次RIA现场学习后，我们就能学会通过问五个问题的方式，帮助自己和他人挖掘真实需求。我们先按照座位，每三人一组。\r\n今天我拆的书是《提问的艺术·为什么你该这样问》，\r\n【F】这本书的作者是来自美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯。这是一本风靡全美、影响无数人的神奇提问书。\r\n【A】这本书揭示了320个强大问题背后的商业与人生精髓。截止到2016年8月，这本书已经\r\n是第10次印刷了。它也一直是亚马逊商业类图书TOP100的榜单上的图书之一。\r\n【B】乔布斯用激动人心的简单问题引领苹果电脑取得了突破性成就，德鲁克以其五大经典管理问题影响了一代又一代的企业家。同样，这本书也可以帮助我们可以在事业、生活的各种场合，随时展开富有成效的对话、迅速解决沟通问题，轻松实现帮助自身以及帮助别人挖掘真实需求。","ratings_count":1,"texts":[{"id":9752,"quote":"\u003cp>提问的艺术P56-P58\u003c/p>\u003cp>“有时候培训并不是最好的开始”，我补充道，“以我的经验来看，那只不过是最后的选择。”直觉告诉我，他并不喜欢我的回答，他最想要的销售培训，但是他还需要什么吗？\u003c/p>\u003cp>五天之后我来到了道森的办公室，小口面这一家有着20年历史的咖啡店烧的咖啡。他向我描述了他的公司、产品以及增长势头强劲的销售队伍。\u003c/p>\u003cp>“我们如今已经是市场的领先者了。我们有用最高的商业品质，就连我们的销售人员也成了竞争对手争相抢夺的炙手可热的商品了。”\u003c/p>\u003cp>这听上去好得有些让人难以置信。我开始了我的第一个“为什么”的问题。我靠在椅子里问道：“那为什么你还需要销售培训呢？”\u003c/p>\u003cp>“哦，这是一万我们需要继续不断提高销售人员的能力。”\u003c/p>\u003cp>我接着问了第二个为什么：“为什么你需要提高你的销售人员的技巧呢？听起来他们应该是行业的佼佼者了。”\u003c/p>\u003cp>“我坚信如果我们能提高他们的销售技巧的话，他们将在新客户开发方面更有效率。”\u003c/p>\u003cp>我接着问了第三个为什么：“那为什么你们需要增加新客户的开发呢？”\u003c/p>\u003cp>他看着我，好像我在问他为什么需要呼吸才能活着一样。\u003c/p>\u003cp>“现有的客户不足以支撑我们的增长目标，因此我们需要开发更多的客户。”我们越来越接近问题的核心了。\u003c/p>\u003cp>于是我又向道森抛出了第四个为什么：“为什么你们不能让现有的客户增长得更快些呢？”\u003c/p>\u003cp>随后我们陷入了长时间的沉默中。他不停地发出哼哼哈哈的声音。我没有再说什么，也没有去打破这一富有成效的沉默，而是等着他回答。\u003c/p>\u003cp>“嗯，我们每年都会有20%的客户流失。”\u003c/p>\u003cp>我几乎能听到每一部恐怖片的恐怖场景出现时伴随的从低音炮传出的低沉而隆隆作响的刺耳的乐声，它往往预示着某种不好的事情即将发生。就像格伦·克洛斯（Glenn Close）在电影《致命的诱惑》中刚从浴缸中跳出来时的场景一样。\u003c/p>\u003cp>“20%。”我随意地重复着这个统计数字，从我的声音中听不出任何判断来。\u003c/p>\u003cp>最后，我问了我的第五个为什么：“我不得不问一下，为什么你们每年会失去20%的客户？”\u003c/p>\u003cp>“我们遇到了许多竞争对手，他们总是以低于成本的价格与我们竞争。但这一定不会持久，他们无法长期维持这样的低价。”\u003c/p>\u003cp>“你怎么知道的？”我决定再给他施加一些压力。\u003c/p>\u003cp>“我们向销售人员调查过，也从一些客户那里听说了这件事。”我已经挖掘够深入的了。\u003c/p>\u003cp>我劝他先将培训的想法搁置一边，对自己的运营先做一次细致的检查。\u003c/p>\u003cp>之后，我访问了公司的销售人员，也拜访了他们流失的客户。真正的问题很快就浮出水面了。道森公司便没有受到低价竞争的冲击，而是产品的质量和物流配送出了问题。由此我更加肯定了自己最初的想法。我告诉我的客户，如果他们不首先解决产品质量和物流配送的问题，即使培训也无济于事。\u003c/p>\u003cp>正因为有了我问客户的这五个为什么，我们在一起合作的项目才更加广泛了，这远比销售培训的影响力更为深远。我帮助道森彻底检查了公司的整个运营环节，从生产到销售，从而使公司走上了可持续发展的正轨。\u003c/p>\u003cp>当有人说“我想要这样”的时候，你需要去发现他们真正需要的是什么。你可以通过问“为什么”去做到这一点。你可以问五遍这个问题。从“你为什么想这样做”或者“为什么会发生”开始问起。\u003c/p>","explains":"\u003cp>好，大家都看好了，故事非常简单，作者通过对当事人道森提问，而且连续提问五次这样的方式，帮助道森意识到，他的真实的需要不是销售培训，而是需要在公司的运营上面做一些调整。当有人或者我们自己说“我想要怎样”的时候，我们需要知道也许这并不是对方或自己真正的需求，这时候我们可以通过问问题，连续问五个问题，来帮助自己或者他人挖掘出真实的需求。\u003c/p>\u003cp>【预防异议】那可能有的伙伴会说：连续问五个问题这种方式“太麻烦了”。“有些时候根本不需要”，五个问题这种方式用于工作分析勉强可以，但是用于谈话的话，这样连续问别人，不会显得“咄咄逼人”吗？即使是问自己，就问几个问题就能实现“自我认知”了，做不到的吧？\u003c/p>\u003cp>不试试看怎么知道呢？生活中，我们经常忽略提问的力量。正如书的名字一样，提问是一种艺术，问题能够让被问的人更加深入的思考他们正在做的事，提问是能够让我们停下来反思的，如果我们学会在适当的时候，敢于提问，这将是个帮助自身或者帮助他人挖掘真实需求的好的做法。那提问可以问什么，也可以问为什么，也可以问怎么，而且不单单可以问别人，也可以问自己。\u003c/p>\u003cp>【举例】举一个例子，大家就能更好的理解啦。前几天，我就用了五个问题的方式来帮助自己找到了真实的需求。朋友有一天来问我说：“你前段时间和我随口念叨的要买的跑步机，买了没有？”我说还没有啊。然后朋友说：“怎么还没买呢，你不是半个月前就和我提过了吗？”是啊，为什么我还在犹豫呢？于是我问了自己五个问题。第一个，当初我为什么要买跑步机，那是因为那段时间开始，我突然长胖了几斤。然后我继续问，我为什么会突然变胖呢？是因为我很久不跑步了。因为我把跑步的习惯丢掉了，接下来我问了自己第三个问题，我为什么会把跑步的习惯丢掉呢？仔细想想，是因为自己平时是早上起来跑步，但是我最近早上起不来。我继续追问自己，为什么最近早上起不来呢？那想想根本原因是晚睡，于是我又问，那为什么晚上不早些睡呢？这时候答案出来了，那是因为晚上在熬夜追剧。问完这五个问题，我立马清晰的意识到，此时我需要的不是一台跑步机，而是我应该早点睡。那我就是通过连续问自己五个问题这样的方式，把自己潜在的需求找了出来，不是买跑步机。而这也是我为什么在犹豫的原因。那正如例子中的我一样，表达出来的需求可能不是自己真实的需求或者动机，所以会出现犹豫或者拖延，这时候如果我们运用五个问题，可以问为什么，可以问什么，可以问怎么这样的方式，就能来挖掘自己的真实需求。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：下面请大家设想一下：自己或者身边的人，是否有一直想要做但还在犹豫的事情，而且很可能未来一周还不会去行动的事情，比如你想开始养成每天读书的好习惯，但是总是光念叨没行动；比如你看到邻居家小孩的兴趣班老师不错，也想给自己的孩子报名一个，却一直没去咨询；比如你一直想要拆书升级，却始终都是有想法没行动；再比如你在工作上一直想找领导沟通新的季度计划，却一直在逃避？\u003c/p>\u003cp>请把这样正在发生以及未来可能发生的场景写在便签纸上，给大家2分钟的时间，写好的请举手示意。\u003c/p>\u003cp>学习者案例记录：&nbsp;\u003c/p>\u003cp>文卿：我有一堆旧衣服准备收拾，但是拖了好久好久，从冬天拖到夏天，夏天马上又到冬天了，一直就没去收拾。\u003c/p>\u003cp>凌梅：我一直想去爬山，但一直没实现\u003c/p>\u003cp>【拆书家提问设计（逐字稿）】：好，那未来的一周，大家遇到了自己所写的场景，你想起今天的拆书，你决定通过问自己或者问别人五个问题来帮助自己或者他人来找到真实需求，这五个问题可以问为什么，可以问怎么，可以问什么，那你决定怎样做来实现这个结果。给大家5分钟时间，写完后请在小组内部分享一下你们的案例。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>文卿：我问了自己五个问题：为什么拖延不去收拾旧衣服。一个是觉得要花很多的精力和时间，自己害怕没这个时间；为什么没这个时间？因为工作太忙了，回家太晚了，回家也太累了，经常想想算了，先睡觉吧，所以一天又过去了；现在想想要调整工作的节奏，还有衣服要分块收拾，比如这个衣橱这周分享；另一个衣橱下周收拾；\u003c/p>\u003cp>凌梅：我问了自己几个问题，为什么想去爬山，就是想放松放松；那为什么想放松放松呢？因为我太累了；为什么会觉得太累了；因为工作时间太长了；为什么会工作时间这么长呢？因为效率太低了，为什么效率会这么低呢，因为自己要做的事情太多了，但是不专注。\u003c/p>\u003cp>好，谢谢各组的分享！通过问五个问题，我们了解发掘到我们各自内心的真实需求。在合适的时机，通过合理的问为什么、问什么以及问怎么，可以帮助我们挖掘到自己或者他人一直说想要但是迟迟还在犹豫的事情背后的真实需求。\u003c/p>\u003cp>今天我的TF2-2拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1541947409000,"updated_at":1541947409000,"ria":true},{"id":6044,"topic":"直击问题核心的方法","learn_goal":"直击问题核心的方法","remark":"用直击问题核心的方法，最大限度地帮助对方，减少对方说话中的迂回，能够直奔谈话的主题。","level":"TF2-3","duration":30,"status":30,"type":0,"chaishujia":{"username":"范范姐","city":"昆明市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是范歆蓉，很高兴和大家一起共同学习拆书法。为让大家列好的学习，一会儿我们继续延用前面的分组。\r\n在跟随我完成本次RIA现场学习后，各位能够在应对前来征求意见或是想将问题抛给你的人时，通过提问来减少彼此谈话中的迂回，直奔谈话主题核心。\r\n下面给大家介绍下这本书：\r\n【F】《提问的艺术》是一本教你如何通过富有技巧性的提问来提高沟通效率并提升自身影响力的书。作者安德鲁•索贝尔和杰罗德•帕纳斯都是很棒的人，他们是所谓的成功人士，并且喜欢把自己的成功经验拿出来和更多人分享。\r\n【A】本书收集整理了320个实用的最具影响力的问题，并将其分成九大类，并配以相应的真实案例，以帮助更多的人学会如何提出具有影响力的问题，从而迅速与他人建立起相互信赖的关系，这无疑是一本不可多得的提升提问技巧和能力的十分实用的书，读后绝对让人受益匪浅\r\n【B】你有没有遇到过时间紧，但对方总是绕来绕去的说不到正题，可你却不知道如何让他聚焦核心问题？你有没有平时总能滔滔不绝的说点什么，可一旦向别人发问，就不知该问点什么？一个高水的问题往往能迅速化解彼此的隔阂，从而拉近彼此的距离；因次，学会提问、提具有影响力和直击人心的问题的艺术，这本书是你的必读书籍！","ratings_count":1,"texts":[{"id":9291,"quote":"\u003cp>接下来，请大家花2分钟时间阅读下原文拆页。\u003c/p>\u003cp>【主题】直击问题核心的方法\u003c/p>\u003cp>【片段来源】：《提问的艺术》P162\u003c/p>\u003cp>我打电话给阿兰，告诉他：“我有一个问题需要请教你。”“好吧，请讲”在一阵寒暄之后，阿兰终于回到了正题上。“我有一位潜在客户，他是芝加哥一家大公司的高管 &nbsp; 。他们公司有一份大单子。他们正着手打造一个雄心勃勃的项目，以期为公司收入带来增长，并建立起更深厚的利润型企业文化。”\u003c/p>\u003cp>我继续向阿兰描述着这个客户的背景，“而且，他希望能为我们之间的电话会议准备一份时间表，甚至包括周末的时间！”\u003c/p>\u003cp>我觉得跟阿兰描述这一切很重要。不，岂止是重要，就是必须！如果他不能全面地了解详情，又怎么能够明白我担忧的问题是什么，又怎么能够给出最恰当的建议呢？于是我又继续地说了好几分钟。\u003c/p>\u003cp>“我能够打断一下吗？”阿兰问道\u003c/p>\u003cp>“当然可以。”我告诉他。\u003c/p>\u003cp>“你的问题是什么？”\u003c/p>\u003cp>我的整个思绪被打乱了。我还有好多详细的信息没有跟他说呢。\u003c/p>\u003cp>“好吧，你知道这个家伙觉得自己就是这个项目的主人，而且……”于是我又开始喋喋不休地向他叙述事情的整个背景，以便他能够做出正确的选择。\u003c/p>\u003cp>阿兰再次打断我说道：“你的问题是什么？5分钟前你就说你有一个问题要问我，那是什么问题？”\u003c/p>\u003cp>我开始有些尴尬。“问题？哦，” 我停了一下，想了想，继续说道，“是这样，我如何与一个控制欲极强、试图事事都凌驾于我的客户打交道？”\u003c/p>\u003cp>阿兰轻声笑道：“我就知道一定有一个核心问题。你看，你没有告诉他们如何写他们要卖给客户的软件，那他们也不应该告诉你如何做咨询。那正是你作为咨询专家所擅长的。你应该告诉客户，他们对你的横加干预就好比，当他自己要购买一辆奔驰车时，不到展厅去买，而是坚持飞到德国奔驰车场去检查汽车组装线，然后建议工人如何制造一辆车一样。奔驰是一个家喻户晓的著名品牌，他们应该相信奔驰的最终产品应该能达到客户较高的期望值。”\u003c/p>\u003cp>“同样，你应该告诉他们，‘你们之所以想雇用我完全是因为我的专业水平、经验以及在行业内的声誉。处理类似的问题我有很丰富的经验，你也需要我替你的这个项目设计出一个最有效的方案。’”\u003c/p>\u003cp>“哦……”这正是我所有的纠结所在。“你在听吗？”阿兰问道，“这是你想要的答案吗？”“哦，是的，这真是太棒了！太谢谢你了！”我连忙说道。“别客气！你还有别的问题吗？”“哦，没了，这已经对我很有帮助了！”我称谢道。“不用客气，有问题，随时打电话给我吧。”阿兰说道。\u003c/p>\u003cp>我想将问题的背景跟阿兰详细道来，但事实上，大多是没必要的。我只需打电话给阿兰简单地说一句：“我有一个问题想请教你。”如果阿兰想知道更多的详情，那他自己会问的。\u003c/p>\u003cp>这种事或许经常也会发生在你身上。有人跟你说：“我想问你一些事。”之后却花了10分钟的时间去说明他们所遇到的复杂情况的每一个细节。此时，你一定想请他重新回到问题的核心上来，这时只需简单地问他一句：“你的问题是什么？”这个问题能够帮助他们迅速看清问题的重点，这就好比早晨透过薄雾照进来的那一缕阳光。\u003c/p>","explains":"\u003cp>好，小伙伴们都已经阅读完了，下面我们来具体解析下。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>从原文拆页里可以看出：任何一个有目的的谈话都有一个核心，而这个核心就问题的所在。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>为什么要学习如何找到核心问题呢？当有人想要征求你的建议却又含糊其辞时，或开始向你详细说明关于这件事情的背景情况，或想把问题抛给你时，你可以用直击问题核心的方法，最大限度地帮助对方，并通过问这个问题，迫使对方将自己的想法具体化，从而减少对方说话中的迂回，以便能够直奔谈话的主题。\u003c/p>\u003cp>【HOW】\u003c/p>\u003cp>具体的做法如下：\u003c/p>\u003cp>\u003cstrong>首先\u003c/strong>：开始和对方谈话时先倾听对方；\u003c/p>\u003cp>\u003cstrong>其次：\u003c/strong>当对方没有直入主题，跟你左讲右讲的绕来绕去时，立刻用“我能先打断一下吗？”或者“可以先停一下吗？”的礼貌问话来让对方停止述说； &nbsp;\u003c/p>\u003cp>\u003cstrong>最后：\u003c/strong>在对方停止后问对方：“你现在的问题是什么？”或“你想解决什么问题？”，直至对方说出他的核心问题；\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这个提问方式适合于对方有问题跟你沟通或请教时，对方一直讲不到重点，或你的时间很紧时使用本方法。\u003c/strong>\u003c/p>\u003cp>【预防可能的异议】\u003c/p>\u003cp>1.有没有人觉得打断别人的时候，觉得不给对方面子或者不太好意思这样做？其实，除了你时间很多，或者对方只想倾诉不想解决问题时，我们在打断对方的时候都要适当进行一些语言的修饰，让对方觉得你是真的想帮他解决问题！\u003c/p>\u003cp>2.在刚才的拆页中有没有觉着不就是个案例嘛，请教他人的时候直接说自己的问题让对方帮解决不就好了吗？要是对方不知道自己的核心问题呢？是的，因为直击问题核心的方法，正是在对方不能直接说出自己的核心问题时使用。\u003c/p>\u003cp>【案例意译】\u003c/p>\u003cp>有一些非常高效的管理者，他们特别会应用提问的方式，帮助对方找到问题的关键，而不是花大把的时间在对方前因后果的描述中。\u003c/p>\u003cp>作为一名行动教练的我，在践行教练管理法的应用过程中，应用提问的方式直击问题的核心，是快速帮对方找到目标的关键。\u003c/p>\u003cp>上周六下午，我的一位职业导师跟我约见面。\u003c/p>\u003cp>见面寒暄后，我开始倾听：她跟我说她刚到这家企业做了商学院任负责人，并讲了企业的一些情况，以及她都做了哪些事。\u003c/p>\u003cp>3分钟后，我打断了她“看来你这三个月做了很多事，那你现在的问题是什么？”她想了想说：“范老师我先说下现状，不然您不了解具体情况，然后再帮我分析看看我下面的安排如何。”\u003c/p>\u003cp>我说“好的，你接下来的工作重点是什么？”她开始说接下来她的计划和公司的目前重点。\u003c/p>\u003cp>5分钟后，我再次打断她：“那你觉得目前你最紧迫的问题是什么？”\u003c/p>\u003cp>她说：“其实这周老板跟我说想让我兼管公司的人力资源总监职务，我以前没做过有些担心，想请您帮我教练一下。”\u003c/p>\u003cp>确认了她今天的核心问题是：想让我用教练的方法帮她理清目前工作目标，于是我用GROW的方式帮她做了T+C的指导，2个小时后我们按时结束了谈话，这2个小时中我帮她解决了她目前的12个问题，并提供了解决方法。\u003c/p>\u003cp>【不按折页做的后果】\u003c/p>\u003cp>如果我没有用直击问题核心的方法，可能我们这下午的2个小时都聊不完，也不可能达到如此高效的解决问题的目的，下次她也不会再来找我帮她指导，也可能不会再如此的信任我了。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>我们刚刚学习了可以用直击问题核心的方法来找到对方问题的核心。现在一起做一个演练，在下面的场景中应用今天所学，该如何去做？\u003c/p>\u003cp>1.请大家认真听一下要演练的场景：\u003c/p>\u003cp>角色A（师父）和角色B（徒弟），徒弟已经连续2周慢于同期伙伴过级了，看到其他伙伴过级，徒弟也非常的着急，结合自己的情况，徒弟给师父打电话寻求帮助。\u003c/p>\u003cp>2.请各组在小组内讨论这个案例，将案例中师父和徒弟的电话对话场景，运用今天所学来设计一段对话，并把对话写在便签上。给大家3分钟的讨论时间，开始。\u003c/p>\u003cp>3.讨论结束后，每组要指定人来扮演角色，一会儿到前面来进行现场演练；\u003c/p>\u003cp>4.好，大家讨论完了，下面就请2位小伙伴来分享你们设计的对话，请先介绍自己和所扮演的角色，再展示对话内容。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【学习者案例记录：现场记录】\u003c/strong>\u003cbr>\u003c/p>\u003cp>大家好，我是鹤哥，我扮演的角色是师父；\u003c/p>\u003cp>大家好，我是小园，我扮演的角色是徒弟，下面开始我们的打电话场景演练：\u003c/p>\u003cp>徒弟：您好！师父！\u003c/p>\u003cp>师父：小园好！\u003c/p>\u003cp>徒弟：师父最近工作忙吗？今天想跟您打电话请教一下。\u003c/p>\u003cp>师父：最近还好，这会有空，你有半个月没交预备表了吧？\u003c/p>\u003cp>徒弟：是啊，师父，这过完一级，这久工作事情也特别多，我们领导给我下了很多的任务，本来不是我的事情也让我来做，弄的我忙的一点空余时间也没有，本来我们筹备分舵安排的一周最少两次过级的，第一周吧因为加班请假，只参加了一次，看其他伙伴过TF2-1和TF2-2，快的都过到了TF2-3了，本来就忙结果还感冒发烧，一弄身体也不好，害的我现在离下周的二级目标成了最后一个没完成了，还有啊，师父，你不知道，他们几个过级跟疯了一样······\u003c/p>\u003cp>师父：我能先打断一下吗？\u003c/p>\u003cp>徒弟：当然可以，师父您说！\u003c/p>\u003cp>师父：你现在的问题是什么呢？\u003c/p>\u003cp>徒弟（先停一下）：师父，是这样的，我连续两周没有进入拆书的状态了，大家过级快的每次都直接过了，我一级报上去了，想休息一下，这不工作身体的事情一多我就停了下来，不过，师父您听我解释啊······\u003c/p>\u003cp>（徒弟继续喋喋不休地向师父解释为什么连续2周停滞的原因，以期师父理解他的不得以）。\u003c/p>\u003cp>师父：亲，能告诉我你目前的问题是什么吗？你一开始就说要请教一下，是要问什么呢？\u003c/p>\u003cp>徒弟：问题？哦，是的，（停一下，做苦恼状）是想请教一下：我对二级的技能点上有些吃力，觉得难度有些大，不知道如何来完成，因为没参加其他伙伴的TF2-1，对于这个部分的拆页选择和内容上不知道怎么下手完成。\u003c/p>\u003cp>师父：我就知道你一定是遇到了障碍，这个问题才是你今天打电话的核心问题。你没有参与其他伙伴的过关现场，可以先学习下伙伴们之前过级的资料，也可以线下跟过了的伙伴聊下心得，最重要的是先把技能点的内容研读清楚，对于技能点上不清楚的部分，你可以给我微信留言，或者现场跟筹备组的伙伴们一起讨论一下。\u003c/p>\u003cp>师父：之前选择书籍的时候，你选的三本书都很不错，就把这三本书的拆页内容做为重点，先选HOW明显的片段来开始，把你训练营的精神拿出来，虽然你慢了别人一点，相信团队的小伙伴都会帮助你一起达到二级的，你们不是要有5个人到二级申请成立分舵嘛，先把2-1的片段选了，试着写下预备表给我看，我再帮你看下是什么情况，好吧？\u003c/p>\u003cp>徒弟：嗯，师父，你说的对，我就是想太多，没有定下来死磕技能点，我这就把TF2-1的预备表写了。\u003cbr>\u003c/p>\u003cp>【总结】\u003cbr>\u003c/p>\u003cp>感谢两位小伙伴的精彩演绎，看来大家对于拆书的心情都非常的有心得啊，互相促进的劲头把师父都影响了，把掌声再次送给努力的自己！\u003c/p>\u003cp>今天我们通过两个角色的扮演，大家都基本掌握了“直击问题核心方法”，也领会到了提问的魅力，希望各位能够在工作和生活中遇到对方一直没有讲到重点，或你的时间很紧时使用本方法减少对方谈话中的迂回，直奔谈话主题核心。祝大家学习开心，谢谢各位！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1536677566000,"updated_at":1536677566000,"ria":true},{"id":5864,"topic":"如何运用圣人思维来解决问题","learn_goal":"学会使用圣人思维来解决问题","remark":"","level":"TF3-2","duration":30,"status":29,"type":0,"chaishujia":{"username":"丹丁先生","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家好，我是丁丹，为了方便记忆可以叫丹丁先生——这还是一个影响历史的人物。三个标签：管理顾问是我目前的职业、人力资源是我的专业领域、情怀勇士是我的处世态度。拆书帮正是需要这种情怀的组织，我也愿意伴随大家一同学习成长。今天很高兴给大家进行TF3-2的拆书分享。\u003c/p>\u003cp>为了让大家能够进行充分的沟通和智慧连接，根据现场情况我们两两分组。\r\n在跟随我完成本次RIA现场学习后，学习者能够运用苏格拉底提问法（行为）来引导对方进行问题的思考（澄清），从而帮助他对问题的理解、透析和解决（界定）。\u003c/p>\u003cp>今天我拆析的书名是《提问的艺术》，作者安德鲁.索贝尔，著名商业战略家，客户关系领域的超级顾问。\r\n【事件场景】在工作和生活中，我们常常会遇到他人向我们寻求建议或倾诉，希望我们给予建议；或者对我们提出要求，希望我们遵从执行。比如：马上高考了，你亲戚向你来寻求孩子报考志愿的建议。或者半年度会议上老总让你说明如何改进客服质量，如何进行更多创新。\r\n【提问】你有没有遇到过类似的情形？你是如何应对这些问题？之后有的结果又是如何？你是否会巴拉巴拉说了很多，最后的谈话也不欢而散？\r\n【影响】我们遇到这些情形时，常常会滔滔不绝，不假思索地向别人表达自己建议，结果落入了无尽的纠缠，反驳、澄清、争论甚至是最后的争执，问题最终无法获得解决，\r\n【解决】《提问的艺术》这本书指导我们问一个好问题要比告知一大推自己的答案更加有效。今天我们就来学习运用苏格拉底提问法来引导对方进行问题的思考，从而帮助他对问题的理解、透析和解决。\r\n &nbsp;\u003c/p>\u003cp>在我们开始讲解之前，先做一个简单的测试题。请大家认真阅读，并在最符合自己情况的选项上打勾，给大家2分钟的时间。\u003c/p>\u003cp>自测题：仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示很符合）\u003c/p>\u003cp>1.在朋友向我提问寻求帮助时，我首先会询问他对问题理解，而不是直接给出答案。1 2 3 4 5 6\u003c/p>\u003cp>2.当朋友向我探讨某个新事物或词时，我会先询问他对这个事物或词的认识，而不直接说出我的观点。1 2 3 4 5 6\u003c/p>\u003cp>3.在朋友向我征询观点时，我总是先邀请他人提出意见，而不是把自己当作专家。1 2 3 4 5 6\u003c/p>\u003cp>4.当朋友对我提出某些要求时，我会先询问他们实现要求后的感受是什么。1 2 3 4 5 6\u003c/p>\u003cp>5.当我向他人寻求帮助时，我会征求他人解决方案，而不是要求他给予问题解决。1 2 3 4 5 6\u003c/p>\u003cp>【互动】我先来了解下，各位的得分情况如何？这组测试主要是测试大家对沟通中提问引导的意识。大家可以算一算自己的分数。有没有在20分以上的？那说明自己的提问引导意识还是不错的，20分以下的，你可要更加认真注意下面环节了。这五个问题贯穿了今天提问法的三个重要步骤。\u003c/p>","ratings_count":1,"texts":[{"id":9079,"quote":"\u003cp>好，接下来先用2分钟时间阅读我用荧光笔标注上下箭头的拆页部分，请完成的伙伴举手向我示意。\u003c/p>\u003cp>《提问的艺术》P169-170\u003c/p>\u003cp>苏格拉底生活在古希腊，他是一位杰出的、善于提具有影的问题的大师。他在教授学生时，并没有采取演讲的方式，而是传授给学生一系列发人深省的问题。通过这些问题，他鼓励学生在学习中提升自己的思维。他总是能揭示出这些问题的本质。尽管只是慢慢地一点点渗透，但却总能直达事物的核心。\u003c/p>\u003cp>苏格拉底总是以“什么是美德”或“什么是美好”这些我们随时都在用的词语开始他的课程。我们真地清楚它们意味着什么吗？今天，世界上的许多大学都在他们的教学中采用了“苏格拉底法”，其中最有名的便是哈佛大学商学院。\u003c/p>\u003cp>苏格拉底将这一方法总结得很透彻。他说：“人类最高级的智慧就是向自己或向别人提问。”\u003c/p>\u003cp>苏格拉底是一位针对雅典社会和政府畅所欲言的评论家。他最终因对统治阶级的抨击而被判了死刑。对此他没有丝毫反抗，而是饮下了一杯毒堇汁。尽管毒堇汁慢慢地浸入了他的心脏，让他离开了人世，但他却给世人留下了历史上最伟大的哲学家之一的名声。\u003c/p>\u003cp>如今，你可以将苏格拉底的方法应用到日常工作和生活中。如何才能像苏格拉底一样思考呢？首先，从提问开始，而不是去阐述、声明或命令。其次，问一些每个人都会想到的、最基本的问题，这可能会让上他们大吃一惊。\u003c/p>\u003cp>例如，在工作中，有人会说：“我们需要更多的创新。”这时你应该问：“你眼中的创新是什么样子？”当听到一个需要更多团队合作的提议时，你可以这样问：“当你提到‘团队’一词时、你的意思是什么？”\u003c/p>\u003cp>诸如此类的问题能够引导对话双方进入更深层次的探讨中，并让对方参与进来，引起他们的思考。你也会因此赢得智慧导师的声誉—引导别人步入正确的方向，而不是将自己的观点强加于人。\u003c/p>","explains":"\u003cp>【WHAT+WHY】好，先问下各位读完刚才这段拆页，你获得的关键词有哪些？（互动）\u003c/p>\u003cp>人们会将遇到的问题向他人倾诉，希望获得预期的反馈。可是倾诉者要么对问题的需求本质不明确，要么就早有答案而只是去寻求他人验证。在不明确倾诉人的状况时，回应者就开始滔滔不绝给予解决方案、行动建议，可想而知得到的一定就是反驳、澄清和争辩，最终无助于问题的解决。\u003c/p>\u003cp>【HOW】那么我们如何在会谈中运用苏格拉底提问法呢？我们通过一个具体案例来讲解相关步骤。\u003c/p>\u003cp>假如一个朋友来跟你探讨小孩高考填报志愿的问题。你该如何应对呢？（互动）\u003c/p>\u003col>\u003cli>\u003cp>统一理解，首先我们要和倾诉者同频，帮助各自对问题有统一的认识。我们可以这样问：“关于专业和学校，你是如何看待的？”而不要立刻根据自己的经验判断来告知答案。这一步是对问题表象的探寻。\u003c/p>\u003c/li>\u003cli>\u003cp>深入透析，帮助对方多维度去分析透彻问题的各个方面，也是最为重要的步骤，这一步使我们接近问题的本质。我们可以这样问：“你是否了解孩子的兴趣爱好和特长？”“你对学校所在地域是如何考虑的？”“你和孩子对未来工作就业是如何设想的？”“你是否跟孩子认真探讨过这些问题？”\u003c/p>\u003c/li>\u003cli>\u003cp>促使行动，问题需要行动解决，而不是兜圈子。在理解问题的表象和本质后，我相信答案已经在倾诉者心中，因此我们需要促进对方解决问题。我们可以这样问：“你现在有什么具体打算？”“我很赞同你的想法，就学校地域的问题不妨找孩子和太太再沟通下如何？”\u003c/p>\u003c/li>\u003c/ol>\u003cp>【预防性异议及适用范围】步骤已经讲解完，三个步骤：统一理解、深入透析，促使解决。有人会问这样做是不是太麻烦了，是否所有的问题都需要这么解决呢？当然不是，这类提问引导的方法主要运用于倾诉者对问题本质不明确，而需要通过提问来启发深入思考时使用，但简单而有明确答案的问题就不适合了。\u003c/p>\u003cp>【举例子】我在举一个实际的例子帮助大家理解。上周有一位HR求职者来向我咨询，希望获得职业发展的指导，我首先问他：“你对职业生涯是如何理解的？”“你希望从我这里或者什么信息？”这就是统一理解。然后我问他：“你对目前的职业有什么不满意或想精进的地方？”“你对未来职业发展的期待是什么样？”深入透析了他对职业发展的本质愿望。最后我提问：“通过沟通，你准备在职业发展方面有什么初步打算？”\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：好，接下来，我想让大家根据分组来做一个情景演练：扮演两位好友的对话，其中一个伙伴想离职换一份工作，正在向他的好友倾诉，寻求意见。另一个伙伴要运用我们今天学习的方法统一理解、深入透析，促使解决帮助他。时间5分钟，然后我们请一个小组现场表演。现在开始。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>倾诉人：最近想换个工作。\u003c/p>\u003cp>倾听者：怎么啦？想换个工作？\u003c/p>\u003cp>倾诉人：觉得工作挺枯燥的。\u003c/p>\u003cp>倾听者：什么原因让你觉得枯燥呢？\u003c/p>\u003cp>倾诉人：因为会计这个职业比较普通，工作过程有比较死板，像机器人似的。\u003c/p>\u003cp>倾听者：嗯，有那么一点点，好像是那么一回事。那你想换什么样的岗位呢？\u003c/p>\u003cp>倾诉人：我找找一个更有挑战性一点的，比较能掌控，而且不是那种重复机械的，是可以参与到企业的运作过程中的工作。\u003c/p>\u003cp>倾听者：那如果你的目标清晰了，你准备什么时候找新工作呢？\u003c/p>\u003cp>倾诉人：我这个月就准备开始找，我准备先把简历做起来。\u003c/p>\u003cp>倾听者：嗯，不错，那就赶紧行动吧，先把简历做好。\u003c/p>\u003cp>【号召鼓掌】大家掌声感谢两位伙伴的分享。【摘要点评】在这个过程我们通过三个问题，你觉得枯燥的原因是什么？为什么枯燥？然后深入透析一下，枯燥的原因是如何造成的，希望做些什么改变。如果在这个过程中倾听者无法反驳和辩驳对方时，要促进对方的行动成功。接下来你准备怎么做，或者说什么时候开始，以确认对方有明确的行动方向。\u003c/p>\u003cp>好的，今天我们学习了运用苏格拉底提问法帮助问题的理解、透析和解决的技巧，最后布置一个作业，设想一下未来的一周内当你遇到什么场景和对象时，你可以运用苏格拉底提问法帮助解决呢？请大家课后在便签纸上完成后提交给我。\u003c/p>\u003cp>好，以上就是我的TF3-2的分享。感谢大家的参与。\u003c/p>\u003cp>朋友问找工作的问题\u003c/p>\u003col>\u003cli>\u003cp>你希望找什么样的工作？什么样的公司？什么地域的公司？什么规模的公司？\u003cbr>\u003c/p>\u003c/li>\u003cli>\u003cp>你能做什么或者超出他人的能力来胜任这个公司的相关职位？\u003c/p>\u003c/li>\u003cli>\u003cp>促成对方的想法，发挥优势能力并体现出来，鼓励对方马上实施。\u003c/p>\u003c/li>\u003c/ol>\u003cp>朋友问买房的问题：\u003c/p>\u003col>\u003cli>\u003cp>你买房的目的是什么？\u003c/p>\u003c/li>\u003cli>\u003cp>如果是刚需提问分析下地理位置，小区配套问题\u003c/p>\u003c/li>\u003cli>\u003cp>如果是投资，提问了解具体的投资增值的理由，是否还有其他投资渠道和方法\u003c/p>\u003c/li>\u003cli>\u003cp>促成对方的行动，落实买或者不买的行动\u003c/p>\u003c/li>\u003c/ol>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1534776883000,"updated_at":1534777080000,"ria":true},{"id":5764,"topic":"避免谈话中漫无目的的迂回","learn_goal":"学会如何快速直接切入核心问题","remark":"想不想试一下谈话全面崩溃时，用哪一个提问来重新开始建立关系？ 这本书里有一个特别巧妙的提问，可以做到。\r\n想知道老板期待你问什么问题吗？这个问题在本书中也有一个章节详细剖析。\r\n好问题往往会引来有深刻见解的答案，或者会直接问题的核心，问题都是有力量的，","level":"TF2-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"锦莉","city":"上饶"},"club":{"name":"上饶三清山分舵","city":"上饶"},"prologue":"\u003cp>&nbsp; \u003cstrong>自我介绍： \u003c/strong>&nbsp; &nbsp; &nbsp; &nbsp; 大家好，我是今天的拆书家锦莉，给大家带来的 TF2-3拆页来自《提问的艺术》一书。&nbsp;\u003c/p>\u003cp>\u003cstrong>分组指令\u003c/strong>：今天我们分组用黑白配来分组。预备开始。 两两一组，分成三组。\u003c/p>\u003cp>&nbsp;\u003cstrong>学习目标：\u003c/strong>希望小伙伴们通过今天的学习，在应对前来征求意见或是想将问题抛给你的人，通过直接了当的提问减少谈话中的迂回，直奔谈话主题核心\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":8966,"quote":"\u003cp>《提问的艺术》P162\u003c/p>\u003cp>我打电话给阿兰，告诉他：“我有一个问题需要请教你。”\u003c/p>\u003cp>“好吧，请讲”在一阵寒暄之后，阿兰终于回到 了正题上。\u003c/p>\u003cp>“我有一位潜在客户，他是芝加哥一家大公司的高管 。他们公司有一份大单子。他们正着手打造一个雄心勃勃的项目，以期为公司收入带来增长，并建立起更深厚的利润型企业文化。”我继续向阿兰描述着这个客户的背景，“而且，他希望能为我们之间的电话会议准备一份时间表，甚至包括周末的时间！”\u003c/p>\u003cp>我觉得跟阿兰描述这一切很重要。不，岂止是重要，就是必须！如果他不能全面地了解详情，又怎么能够明白我担忧的问题是什么，又怎么能够给出最恰当的建议呢？于是我又继续地说了好几分钟。\u003c/p>\u003cp>“我能够打断一下吗？”阿兰问道\u003c/p>\u003cp>“当然可以。”我告诉他。\u003c/p>\u003cp>“你的问题是什么？”\u003c/p>\u003cp>我的整个思绪被打乱了。我还有好多详细的信息没有跟他说呢。\u003c/p>\u003cp>“好吧，你知道这个家伙觉得自己就是这个项目的主人，而且。。。。。”于是我又开始喋喋不休地向他叙述事情的整个背景，以便他能够做出正确的选择。\u003c/p>\u003cp>阿兰再次打断我说道：“你的问题是什么？5分钟前你就说你有一个问题要问我，那是什么问题？”\u003c/p>\u003cp>我开始有些尴尬。“问题？哦，” 我停了一下，想了想，继续说道，“是这样，我如何与一个控制欲极强、试图事事都凌驾于我的客户打交道？”\u003c/p>\u003cp>阿兰轻声笑道：“我就知道一定有一个核心问题。”。。。。\u003c/p>\u003cp>当有人想要征求你的建议却又含糊其辞时，或开始向你详细说明关于这件事情的背景情况时， 你可以这样 问：“你的问题是什么？”&nbsp;\u003c/p>","explains":"\u003cp>\u003cb>图书介绍FAB:\u003c/b>\u003c/p>\u003cp>\u003cstrong>F:\u003c/strong> 《提问的艺术》一书，是亚马逊商业书籍TOP100，由中国人民大学版社出版，两位作者，安德鲁。索贝尔是著名商业战略家，客户关系的超级顾问； 另一位杰罗德。帕纳斯是世界顶级慈善事业咨询师，\u003c/p>\u003cp>这本书会告诉你哪些问题是真正有力量的，以及什么情况下用哪些问题来达成目标。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>： 这本书的每一组问题，都是紧随着真实有效的案例故事引申展开，读来非常轻松，不会枯燥，同时，你又能深刻地体会到 好问题是有力量的。\u003c/p>\u003cp>\u003cstrong>B\u003c/strong>： 想不想试一下谈话全面崩溃时，用哪一个提问来重新开始建立关系？ 这本书里有一个特别巧妙的提问，可以做到。\u003c/p>\u003cp>想知道老板期待你问什么问题吗？这个问题在本书中也有一个章节详细剖析。\u003c/p>\u003cp>好问题往往会引来有深刻见解的答案，或者会直接问题的核心，问题都是有力量的，\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>: 什么是核心问题？每一个有目的性目标性的谈话，都会有一个中心点，核心问题就是直指靶心的提问。比如原文拆页中的“如何与控制欲望极强的客户打交道”\u003c/p>\u003cp>【WHY：】\u003c/p>\u003cp> 为什么要将核心问题单独拿出来学习？核心问题为什么如此重要呢？ 各位在日常工作生活 中，我们是不是经常会碰到谈话云里雾里，东一扯西一扯的人，就好目的地是北京， 他会带着你先去广州逛一下，然后可能再去昆明，运气好能到北京，运气不好一直在兜圈子，到不了目的地。\u003c/p>\u003cp>【HOW]:\u003c/p>\u003cp> 碰到 这样的情况怎么办呢？ \u003c/p>\u003cp>第一： 开始谈话，倾听对方\u003c/p>\u003cp>第二： 一旦发现对方在带你游车河，逛花园，云里雾里时， 礼貌打断，直接提问：“所以，你的问题是什么？”\u003c/p>\u003cp>第三：继续倾听， 如果对方还是在游离状态， 再次打断， 问他的核心问题。\u003c/p>\u003cp>重复以上步骤，直到 对方说出核心问题。\u003c/p>\u003cp>\u003cstrong>[适用边界：]\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这种\u003c/strong>提问方式适合在别人有问题请教时，一直在介绍事件背情或者很琐碎的事情，或者一直在抒发自己的情绪而谈不到重点。或者当你时间很紧事情很多时，你更是特别需要学会这个提问技巧。\u003c/p>\u003cp>\u003cstrong>【案例阐述：】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我\u003c/strong>在一家公司做业务时，在业务旺季，有天早上将近十点时接到一个沈阳客户的电话，先是寒暄。\u003c/p>\u003cp>“冯小姐，你好呀， 我是XXX ， 你还记得我不？ 上回我们一起吃过饭的。”\u003c/p>\u003cp>“哦， 你好，记得记得，你是李姐。请问有什么事情我可以帮到你呢？”\u003c/p>\u003cp>“啊，没事没事，我们沈阳最近家具卖得很火爆呀，好多人结婚呀。”。。。。。。。（我急着要去处理其它事情）就直接打断她的民情汇报，问：“李姐，你有什么问题吗？”\u003c/p>\u003cp>她还是用东北人的热情唠了好一阵，中途打断了几次问她的目的，&nbsp;\u003c/p>\u003cp> 最后才提出她的要求： 是想在没有付订金的情况下要多发一次货运。\u003c/p>\u003cp>如果不几次打断，估计一上午就唠嗑了。 【\u003cstrong>不按折页做的后果\u003c/strong>】\u003c/p>","interaction":"\u003cp>\u003cstrong>A3演练\u003c/strong>\u003c/p>\u003cp>【案例设计】好， 现在我们来当一回霸道总裁，你的公司正在准备并购另一家业务范围不同的公司， 里面涉及到 人员补偿问题，对方公司的人员构成比较复杂，诉求各不相同，有要求经济赔偿，有要求岗位置换，有的希望职位不变。。。。。但 是作为并购方，你是有自己的一套游戏规则，那就是全部按照本公司以往并购案一样处置，条款统一。\u003cbr>\u003c/p>\u003cp>此次负责的HR是一个刚来公司没多久的新人，没有参加过以往的并购案，被对方公司的人五花八门的要求弄得头大，但是没有拍板权，只好来请示霸道总裁。\u003c/p>\u003cp>【小组讨论】现在两两一组演练， 一位扮演总裁， 一位扮演人事， 人事在陈述事件时，总裁要用今天我们所学的核心问题提问法，注意收拢人事的泛泛而言和具体的事例。\u003c/p>\u003cp>【现场演练】好，开始， 时间三分钟， 一会我们请一对小伙伴上来演练。\u003c/p>\u003cp>\u003cstrong>现场案例记录:\u003c/strong>\u003c/p>\u003cp>\u003cb>熊：老板，我现在有问题，并构的公司要求太多了，一百多个员工， 老王家单亲家庭，又有老人，他想要工作不想被炒；小刘家想拿钱走，能力强；还有小张想换工种。。。感觉都很重要，要照顾。\u003c/b>\u003c/p>\u003cp>\u003cb>丹：一刀切\u003c/b>\u003c/p>\u003cp>\u003cb>熊： 啊，一刀切啊。可是职员不满意会告状。或者变成对头。。\u003c/b>\u003c/p>\u003cp>\u003cb>丹： 你到底想知道什么？\u003c/b>\u003c/p>\u003cp>\u003cb>熊：我们人事有没有标准啊，一人会是多少钱补偿？\u003c/b>\u003c/p>\u003cp>\u003cb>丹：就按以往并购的标准操作。\u003c/b>\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学会这个简单的问题，“你有什么问题？” 在合适的时候抛出，不但可以帮助你节约时间，还 可以让对方\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>认真思考谈话的目的。我们也可以问“你希望我给哪方面的建议？”“你谈的几件事情中，最想解决的是哪一件” 真正达成谈话的目的。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1533953204000,"updated_at":1538447652000,"ria":true},{"id":5477,"topic":"像苏格拉底一样思考1","learn_goal":"通过增强个人提问思维意识，从而扩大个人影响力。","remark":"你想提高个人影响力吗？想快速获得潜在客户的尊重与信任吗？想让拟想对象感觉到你的关注吗？如果你希望了解这方面的技能，那就请你7月8日上午到卡斯书吧的拆书现场来吧，让我们带你找到答案，给你支招！","level":"TF2-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"罗巧琴","city":"东莞市"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>学习目标：提高提问意识\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 大家好，我是龙珠，刚才大家已经分过组了，那么我们开始吧。\r\n我今天带来的拆解书籍是《提问的艺术》，本书的两位作者安德鲁和杰罗德分别是客户关系领域的超级顾问、世界顶级的慈善事业咨询师。这本书是教你如何通过富有技巧性的提问来提高沟通效率并提升自身的影响力，它被誉为“风靡全美、影响无数人的神奇提问书”。&nbsp;\u003c/p>\u003cp>大家可能会好奇，对比同类书籍，这本书有什么优势吗？相比其他很多提问类书籍，这本书让人爱不惜手的原因是它的内容分为商业、人际、人生三个不同方面，而且每一章都是用故事案例和大师的睿智问题来体现提问的艺术，实践性很强。\r\n在开始之前，我想让大家设想两个情境，第一，在朋友向你抛出问题时，你会直接告诉他答案或建议还是会提问呢？第二，当你的家人不断向你抱怨时，你是安慰、批评还是会提问呢？我们在未经刻意训练的情况下，通常喜欢的是表达而非提问，为什么呢？因为它是人类的本能，自然反应嘛。\u003c/p>\u003cp>那提问的技能对我们重要吗？回到刚才两个情境，如果你用探究朋友问题根源的想法去提问，他的思路会随着你的问题而拓宽；如果你用关心家人的想法去提问，她会感受到你的重视。如果你不知道该问些什么问题，那么书中33种情境300多个问题可以帮到你，作者为我们提炼了“在正确的时间问正确问题”的关键技能。\u003c/p>\u003cp>好的问题不但能推进我们更深入的思考，更能帮助我们拉近人与人之间的距离、建立良好的人际关系。\r\n接下来，让我们用2分钟阅读一下原文片段吧！\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8647,"quote":"\u003cp>\u003cstrong>像苏格拉底一样思考&nbsp; &nbsp;\u003c/strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;《提问的艺术》P167-170\u003c/p>\u003cp>想象一下：你被绑架失去了自由。你无法再享受阳光的温暖照射。你那舒适的房子也消失了。而此时，你被关在一个伸手不见五指的山洞中，而且它还非常阴森恐怖，温度不超过13摄氏度。此时此刻，你只需要像英国著名诗人柯尔律治所说的“放弃对超现实部分的怀疑而融入其中去享受作品本身”那样，去想象一会儿。\u003c/p>\u003cp>再想象一下：你终身被锁在那个山洞里，面对着一堵内墙。你身后是一堆篝火，它发出的光影投射在了你面前的这面墙上。正因为你被锁住了，无法转身看到光影从何而来，你仅能看到你面前的这堵墙。\u003c/p>\u003cp>接下来，你把时间都花在琢磨篝火投射在墙上的光影上。这些光影不停舞动变化着位置。你赋予这些光影某些意义，并不断地揣测着它们来回移动的原因。你猜想一定是谁故意弄出了这样的影子。这些光影离你是如此地近，以至于你仿佛都能看到黑暗山洞外面的真实世界了。\u003c/p>\u003cp>通过你所看到的这些光影，你得到的生活感悟是什么？你只能看到现实投射在山洞墙上的光影，而非真实的东西。你是否意识到你的认识是多么地贫乏？你对世界即将发生的事情的了解是如此有限，就像你面对山洞的墙时一样感到困顿？\u003c/p>\u003cp>这只是一段离奇而令人毛骨悚然的剧情，还是我们对自己周边生活的认知多么有限的最精确写照呢？\u003c/p>\u003cp>古希腊哲学家苏格拉底将这描述为“洞穴理论”，你可以在《柏拉图的对话》一书中找到这一理论。这本书记录了发生在柏拉图和他的老师苏格拉底之间的一系列对话。苏格拉底曾经说过，哲学家就像一位刚从洞穴中释放出来的犯人一样，现在终于能看到现实的真实面目了。\u003c/p>\u003cp>苏格拉底生活在古希腊，他是一位杰出的、善于提具有影响力的问题的大师。他在教授学生时，并没有采取演讲的方式，而是传授给学生一系列发人深省的问题。通过这些问题，他鼓励学生在学习中提升自己的思维。他总是能揭示出这些问题的本质。尽管只是慢慢地一点点渗透，但却总能直达事物的核心。&nbsp;\u003c/p>\u003cp>如今，你可以将苏格拉底的方法应用到日常工作和生活中。\u003c/p>\u003cp>\u003cstrong>如何才能像苏格拉底一样思考呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先，从提问开始，而不是去阐述、声明或命令。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>其次，问一些每个人都会想到的、最基本的问题，\u003c/strong>这可能会让他们大吃一惊。\u003c/p>","explains":"\u003cp>学习目标：在跟随我完成本次RIA现场学习后，学习者能够提高提问的意识，在与人沟通时不再直接阐述、评论或者发命令，而是通过提问，推进更深入的交流。\u003c/p>\u003cp>（what）很多时候人们遇到的事情或问题并非表面所反映的一样，用提问的方式不但可以避免主观偏见，同时也可以更深入的了解事情或问题的本质。\u003c/p>\u003cp>（why）原文片段的情景貌似离得我们很远，但在现实中，我们面对事情，很多时候会直接进入情景，在受限的情况下作出的评判是不全面的，就像在洞穴中只看到光影一样。比如，你的老婆告诉你，你们的小孩在学校与另外一个小孩发生的一次意外事故，她的描述是客观的吗？你的同事正在向你介绍一个理财产品，但你对理财知悉甚少，那你的评估又会有多准确呢？\u003c/p>\u003cp>苏格拉底运用提问去让人们了解事情的本质就像走出洞穴去了解真相一样，如果我们像苏格拉底一样运用提问拨开云雾，可以怎么做呢？书中给出了两个思维层面。\u003c/p>\u003cp>（how）\u003c/p>\u003cp>第一，面对事情或别人的提问，不先给自己的答案、想法、结论...，而是把想法换成一个问题（注意不是质问）。在这个思维层面主要是强调先拥有提问意识，偿试用提问代替表达。\u003c/p>\u003cp>例如，你跟爱人因为一些事发生争执，爱人说了一句“我受够你的坏脾气了！”（这是爱人的想法）\u003c/p>\u003cp>爱人把想法换成问题：“你生气时是否想过，这会影响你和身边最亲近的人的关系？”\u003c/p>\u003cp>（你随着问题思考而不是立即反驳）\u003c/p>\u003cp>第二，问一些谁都会想当然地回答的问题，把一些习以为常的概念、可能存在的误解的词，用提问弄清楚。\u003c/p>\u003cp>一个词的意思，在不同的人理解上可能会存在不同的定义，对可能会有歧义的词进行提问，沟通更清晰。\u003c/p>\u003cp>最常见的例子有，朋友跟你说：马上就到。“马上”这个词不同的人有不同的理解，它的表示可长可短，这个时候可以进行提问：你的马上是多长时间呢？或者是当你的朋友向你提议：这周我们过一个有趣的假期吧！为了避免误会，你可以追问：你所说的有趣是什么样子的？\u003c/p>\u003cp>（我的A1）我举一个自己的粟子：我的宝宝因为学习需要一部手机，为减少冲突，我们约定晚上10点半后手机放一个固定地方，上上周，10点半过后，宝宝还拿着手机玩，我看到时很生气的说：你违约了，手机要冬眠3天。当时宝宝第一反应像是立刻崩溃了，情绪很激动，对着我不断哭诉。\u003c/p>\u003cp>（应用第一个层面提高提问意识，把想法变为问题）同样的情况在前两天再一次出现了，两个宝宝超过10点半还拿着手机，像是在研究着什么，我当时反思了上次直接下定论，后果是导致宝宝很伤心，这不是我当初想达到的目的。稍作思考，我问：你们在做什么呀？（这个问题一是表示我关心和好奇，想了解宝宝在研究什么；二是希望通过问题让宝宝意识到她们现在的行为），她俩当时的第一反让我记忆犹新，宝宝立刻把手机放回钢琴上，像没事一样走开了。\u003c/p>\u003cp>（坏处）用提问和直接阐述的区别，现在大家能感觉出来了吗？如果我们没有通过提问引发思考，或是没有通过提问更进一步了解对方，而是将自己的想法直接说出，或是把观点强加于人，会更容易发生冲突，也会在不知不觉中产生误会，矛盾会越积越多，对人际关系产生不良影响。\u003c/p>\u003cp>（适用边界）当然，并不是什么时候都用提问，在事情并不是十万火急的时候，在我们想与对方关系更进一步的时候，在我们希望了解更多信息的时候，在这些情况下，可以应用这些思路。\u003c/p>","interaction":"\u003cp>那么，伙伴们，请回顾一下，你最近一次因为直接阐述、声明或将自己的观点强加于他人而造成冲突的一次不愉快经历，下面有一些词，看看哪个词跟你当时的感觉相近：不耐烦、不满、不高兴、愤怒、挫败、烦恼、困惑、害怕、着急、失望、难过、内疚、悲伤…….，这次经历是在什么时候、什么地点、跟谁，因为什么事情引起的？请用2分钟在小组内分享，然后写下来。\u003c/p>\u003cp>瑞云分享A：\u003c/p>\u003cp>瑞云所在公司的部门新来了一位团队负责人，因为对团队成员还不太熟悉，让瑞云帮忙做一份团队人员的工作分工表，工作分工表做好发给大家后，团队其中一位女同事跟瑞云反馈，A项工作不应该是她负责的项目，瑞云觉得A项工作较适合女同事，女同事负责A项工作没有问题，当时是各有各的想法，瑞云未对女同事反馈作调整处理；一周后，团队负责人问分工的完成情况，瑞云想起女同事的反馈，A项工作未有落实分配到人，团队负责人询问A项工作适合分给谁，瑞云在没与女同事进一步沟通了解的情况下，把A项工作较适合女同事的观点直接向团队负责人汇报，团队负责人出于对瑞云的信任，最后把A项工作确定分配给女同事。事后，女同事表示不满，认为瑞云不重视她的意见、故意为难，而瑞云因为未就女同事反馈情况事作进一步了解，将自己的观点强加于人，直接表达了自己观点和想法而感到内疚。\u003c/p>\u003cp>谢谢瑞云的分享，现在我们回顾一下，刚才学习了一是像苏格拉底一样思考，不去阐述、命令或直接给出自己的答案、想法，而是把想法变成问题进行提问，作进一步深入了解；二是通过提问，把一些习以为常的概念、可能存在的误解的词弄清楚。\u003c/p>\u003cp>还回顾了我们最近一次不愉快的经历，那么，请再思考一下，根据刚才学习的思路，在同样情况下，你能怎么做？可以向对方提出什么样的问题呢？\u003c/p>\u003cp>瑞云分享A1+：\u003c/p>\u003cp>如果再遇到同样情况，我会了先不发表自己的想法，跟同事了解工作分工的问题，同事说某项工作安排给她不适合的理由是什么？适合她的工作有哪些？哪些同事适合该项工作？原因是什么？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1531042609000,"updated_at":1531061112000,"ria":true},{"id":5278,"topic":"如何做出更好的选择？","learn_goal":"用加减法，帮助对方做出选择。","remark":"高中时，要选择文科还是理科；\r\n大学毕业，要选择考研还是就业；\r\n找工作时，拿到两份都还不错的offer，\r\n你会如何选择？\r\n","level":"TF2-3","duration":20,"status":29,"type":0,"chaishujia":{"username":"程婷婷","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"各位朋友，大家晚上好。我叫程婷婷，英文名字叫Anny，大家叫我婷婷或安妮都可以。\r\n我的3个标签： 翻译，摄影师，终身学习者。\r\n分组： 接下来为方便我们的讨论，我们进行分组.\r\n【书籍介绍】\r\nF特征：这本《提问的艺术》的作者是美国的安德鲁·索贝尔，讲述了如何通过富有技巧性的提问来提高沟通效率并提升自身影响力。\r\nA优势：被誉为“风靡全美、影响无数人的神奇提问书”，名列亚马逊商业类图书前100名，非常畅销，很多知名咨询公司的CEO和银行主席都推荐这本书，书中用真实的故事和大师们的睿智问题为读者展现了提问艺术的魅力。\r\nB利益：开会讨论时天马行空没有重点，如何提出一个可以让会议迅速回归正题的问题；面对怒气冲天的客户或老板，如何提出一个可以平息对方的怒火的问题；和陌生人见面时，如何提出一个能表现出你在乎对方并迅速打开话题的问题。提问的境界不同，得到的答案往往天差地别，好的提问能够直达问题的核心，释放强大的力量。若你想用提问来提升沟通效率，这本书会给你很大的启发。","ratings_count":1,"texts":[{"id":8401,"quote":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>在跟随我完成本次RIA现场学习后，你将学会用加减法，帮助对方做出选择。\u003c/p>\u003cp>\u003cstrong>&nbsp;原文片段：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>用加减法，帮助对方做出选择\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>“请尽可能给我打个电话，我需要和你谈一谈。”我正在自己供职的教堂负责11点服务的热线工作，教堂的神父汤姆·塞维尔拉着我的胳膊悄悄对我说，他很着急见我。我是这所教堂的董事会主席，汤姆和我关系非常好。我周一的第一件事就是打电话给他。我正在想最坏的结果。第二天，我坐在了汤姆摆满图书的办公室里。我能看出他正经受着痛苦的煎熬，我从未见过他如此平静。\u003c/p>\u003cp>“我得到了一个新职位，”汤姆说，“你还记得四周前的礼拜日我没来吗？我去纽约的一个教堂做传道者了。他们正在考察我。那是纽约最大、最有声望的教堂。他们已经通知我去他们那里做高级神父了。那可是教堂中最重要的神职人员了。”\u003c/p>\u003cp>“我为你感到骄傲，”我回应道，“但这一点儿都不意外，在你和我们一起工作的这段时间内，我们的教堂规模已经扩大到了三倍，我们的教友都十分地敬重你。最值得骄傲的是你将传道的价值发挥到了极致。请告诉我你的决定是什么？”&nbsp;\u003c/p>\u003cp>“我还没有做出决定。南希不太愿意搬家，但她支持我。&nbsp;孩子们一点儿都不喜欢纽约，他们在这里有自己的好朋友。他们会联合起来抵制搬家。我该怎么办呢？”\u003c/p>\u003cp>我停顿下来，并立刻陷入对汤姆所面临闲境的沉思中。当选择关乎个人的时候，做出选择需要你有足够的勇气，最好的办法就是去挖掘和发现自己内心深处真正最想做的是什么。&nbsp;\u003c/p>\u003cp>我决定采用加减法帮助汤姆做决定。\u003cstrong>加减法就是在表格中央划一条竖线，一边是有利的一面，一边则标出弊端。\u003c/strong>&nbsp;\u003c/p>\u003cp>于是我开始问汤姆。在有利的一边，有很多好处，如薪水更高、牧师的住宅更大以及信徒人数是我们教堂的四倍，有全职的商务经理以及多达七名的神职人员。而在弊端的一进，所列的弊端显然更多。例如，从刚一开始南希就更愿意留下来，&nbsp;两个大一点的孩子正在上高中——泰德是校篮球队的， 而法兰是班长。汤姆自己也不太喜欢纽约。单子上罗列的弊端还在增加。他将会把所有的时间和精力都花在传道上，他还会失去自己与教友们已经建立起来的关系和私入联系。他将成为那个教堂的形象代言人，而不是教堂的灵魂与精神人物。最重要的是，汤姆非常担忧离开会给刚发起的资本运作带来负面影响。\u003c/p>\u003cp>最后，我平静地问他：“汤姆，根据你所讲的一切，你觉得什么才是正确的决定？”汤姆从椅子上跳了起来，给了我一个大大的拥抱，说道：“你已经给了我答案。”实际上，我并没有给他答案，是他自己找到了解决方法。&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","explains":"\u003cp>\u003cstrong>【细化行动步骤】\u003c/strong>（3-4分钟）\u003c/p>\u003cp>拆页信息讲了用加减法，帮助对方做出选择，这里面包含了行动建议，我将行动步骤细化为：\u003c/p>\u003cp>1.在表格中央划一条竖线，一边是有利的一面，一边是弊端\u003c/p>\u003cp>2.询问这个选择对你有什么有利之处；有什么弊端，并写下利弊。\u003c/p>\u003cp>3.问对方，根据你所说的及所写的，你觉得什么才是正确的决定？\u003c/p>\u003cp>当面临选择时，选择A或者B，各有利弊，当局者一时拿不定主意，可能不知道自己内心深处真正的需要，你的作用是去帮助对方深入他们自己的内心，去识别他内心的决定。最重要的一点，你不能帮助他做决定，而是询问对方，你觉得什么才是正确的选择？让对方自己找到答案。\u003c/p>\u003cp>比如这周二的时候，我的一个好朋友打电话问我，她到底离职做自由职业者？她说自己思考了2个星期，到底要不要给我打电话聊聊这个事，看得出这件问题困扰了她很久。她目前和我一样，也在从事翻译工作，但是工作有点特殊，带有保密性质。我决定用加减法来帮助她理清思路，我让她拿出一张纸，在表格中央划一条竖线，左边写下做自由职业者带给她的有利之处，右边写下带给她的弊端。我问她，“你觉得你离职做自由职业者的有利之处是什么？”\u003c/p>\u003cp>“一是不用加班，可以安排时间，做自己喜欢做的事，\u003c/p>\u003cp>&nbsp;&nbsp;二是不用做重复枯燥的翻译工作\u003c/p>\u003cp>&nbsp; 三是，不受原有工作限制出国的规定”\u003c/p>\u003cp>“那做自由职业者的有什么弊端呢？”\u003c/p>\u003cp>“一是，对胜任新工作的能力的不确定因素较大；二是，收入不稳定”\u003c/p>\u003cp>最后我问她，根据你讲的和写下的利弊？你觉得什么是正确的决定？\u003c/p>\u003cp>她停顿了半分钟，她在思考。然后她说：“我知道了，我想我知道我的决定了。”\u003c/p>\u003cp>我用加减法，帮助她做出了选择。\u003c/p>","interaction":"\u003cp>拆书家提问设计：看完这个片段，我们知道了用加减法，帮助对方做出选择。现在我们一起做一个演练。请大家认真听一下要演练的场景：小明是西安人，在北京读大学，目前毕业2年了，女朋友是北京人，小明现在在西安的一家规模较大的网络公司的程序员，工资1万，他又找到一份是在北京的今日头条的程序员的工作，工资3万。父母希望他留在西安，小明一时不知道怎么选择，他现在来求助你，帮助他做选择，要不要去北京的大公司？\u003c/p>\u003cp>\u003cstrong>A3【小组讨论及角色扮演】\u003c/strong>\u003c/p>\u003cp>现在，请按照刚刚的分组，进行演练，一人扮演小明，一人扮演小明的好朋友，用加减法来帮助小明做出选择。需要和大家说明的是，解决问题的方法有很多，我们本次角色扮演的目的是让大家练习刚刚学到的新方法，所以请大家用刚刚学到的加减法来帮助小明做选择，演练时间是4分钟，现在开始。4分钟后，我们请一组小伙伴来演示一下，一个人扮演小明，一个人扮演小明的好朋友，来给我们展现一下。4分钟时间到，我们请一组小伙伴来和我们现场演练一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>邢正鹏（小明）：“飞哥，我现在碰到了一个比较困惑的问题，我目前在西安工作2年了，在这边收入也还可以，一个月工资有一万，但是我女朋友在北京，她希望我去北京。北京的话我前段时间在网上看了下，那边也有一个不错的公司，它给我一个月3万的待遇，我父母不同意我去北京，他们希望我留在西安，但我在北京也正好有工作机会，我女朋友也希望我过去，我现在不知道怎么做这个决定，你能帮我分析一下吗？”\u003c/p>\u003cp>高飞（小明的朋友）：“小明，这个确实是一个比较难的一个选择，我建议你可以用加减法来理清一下自己的思路，看看自己内心真正的想法。首先拿出一张白纸，在中间画一条竖线，左边是加的部分，就是有利的部分，右边列出减的部分，就是不利的部分，你先列一下。你列完了之后，现在你觉得去北京有哪些有利的地方？”\u003c/p>\u003cp>邢正鹏（小明）：“我觉得在北京，一是北京比较繁华，就业机会比较多；二是在北京的平台比较好，收入比较高；三是在北京我也能学到更多的东西，得到更好的锻炼；四是能够和女朋友在一块儿；五是将来扎根在北京，以后孩子的教育环境也比在西安好很多。不利的方面：一是父母在西安，离我比较远，不方便相互照顾；二是北京的生存压力比较大，消费也比较高，收入高，支出也大，我还不能确定我能不能胜任北京的工作。”\u003c/p>\u003cp>高飞（小明的朋友）：“现在把有利的和不利的都列出来了，你再审视这个问题，你觉得什么是正确的选择？”\u003c/p>\u003cp>邢正鹏（小明）：“我觉得我还是应该去北京试一试。”\u003c/p>\u003cp>高飞（小明的朋友）：“看来你自己已经找到答案了。”\u003c/p>\u003cp>邢正鹏（小明）：“嗯，谢谢飞哥!”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1528335033000,"updated_at":1528335033000,"ria":true},{"id":5086,"topic":"如何帮助他人做出个人选择","learn_goal":"学习者能够运用加减提问法梳理利弊，问正确决定来帮助他人做决定","remark":"","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"素语","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003c分组>大家好！开始前咱们先分下小组，按照现在的座次来分，这里是第1组，这里是第2组，大家好，我是新手拆书家素语。先说下我的三个标签：喜欢侦探片，喜欢幼儿教育，喜欢心理学！今天由我来给大家分享一下我的TF2-2便签：如何帮助他人做出个人选择？大家通过我们现场的RIA训练学习之后，学习者能够运用加减法梳理利弊并追问正确决定来帮助他人做出个人选择。 \r\n【F特征】今天我要跟大家拆的这本书叫做《提问的艺术》。它的作者是【美】安德鲁·索贝尔和杰罗德·帕纳斯，他们一位是著名的商业战略家，客户关系领域的超级顾问，一位是世界顶级的慈善事业咨询师。作者向我们传授了如何在各种情境下精准判断出需要被提及的问题从而推动事情深入发展的技巧，是一本提升提问技巧的实用宝典。【A优势】本书堪称提问技巧类的黄金宝典，以故事的形式彰显提问的艺术，其中涵盖了众多大师的精彩提问，如德鲁克、乔布斯、苏格拉底等以及商业精英的智慧问题和精彩故事，跟着大师们边学边问边思考，提问技术自然有所长进。【B利益】如果你是打拼职场的商业精英，学习本书可以让你更快速地通过提问了解客户需求，提高工作效率。如果你在人际交往中遇到困难，学习本书可以帮助你通过特别提问来加深和发展你期待的人际关系。如果你正处于迷茫的人生岔路口，学习本书或许可以通过自我提问来拨开迷雾，找到属于自己的人生大路。学习做一位智者，用提问改变人生。","ratings_count":1,"texts":[{"id":8191,"quote":"\u003cp>《提问的艺术》P179\u003c/p>\u003cp>“请尽可能给我打个电话，我需要和你谈一谈。”我正在自己供职的教堂负责11点服务的热线工作，教堂的神父汤姆·塞维尔（ Tom Sewell）拉着我的胳膊悄悄对说，他很着急见我。我是这所教堂的董事会主席，汤姆和我关系非常好。\u003c/p>\u003cp>我周一的第一件事就是打电话给他。我正在想最坏的结果。第二天，我坐在了汤姆摆满图书的办公室里。我能看出他正经受着痛苦的煎熬，我从未见过他如此平静。\u003c/p>\u003cp>“我得到了一个新职位，”汤姆说，“你还记得四周前的礼拜日我没来吗？我去纽约的一个教堂做传道者了。他们正在考察我。那是纽约最大、最有声望的教堂。他们已经通知我去他们那里做高级神父了。那可是教堂中最重要的神职人员了。”\u003c/p>\u003cp>“我为你感到骄傲，”我回应道，“但这一点儿都不意外，在你和我们一起工作的这段时期内，我们的教堂规模已经扩大了三倍，我们的教友都十分地敬重你。最值得骄傲的是你将传道的价值发挥到了极致。请告诉我你的决定是什么？”\u003c/p>\u003cp>“我还没有做出决定。南希不太愿意搬家，但她支持我。孩子们一点儿都不喜欢纽约，他们在这里有自己的好朋友，他们会联合起来抵制搬家。我该怎么办呢？”\u003c/p>\u003cp>我停顿下来，并立刻陷入对汤姆所面临困境的沉思中。当选择关乎个人的时候，做出选择需要你有足够的勇气，最好的办法就是去挖掘和发现自己内心深处真正最想做的是什么。我决定采用加减法帮助汤姆做决定。加减法就是在表格中央划一条竖线，一边是有利的一面，一边则标出弊端。\u003c/p>\u003cp>于是我开始问汤姆。在有利的一边，有很多好处，如薪水更高、牧师的住宅更大以及信徒人数是我们教堂的四倍，有全职的商务经理以及多达七名的神职人员。而在弊端的一边，所列的弊端显然更多。例如，从刚一开始南希就更愿意留下来，两个大一点的孩子正在上高中—泰德（Ted）是校篮球队的而法兰（Fran）是班长。汤姆自己也不太喜欢纽约。\u003c/p>\u003cp>单子上罗列的弊端还在增加。他将会把所有的时间和精力都花在传道上，他还会失去自己与教友们已经建立起来的关系和私人联系。他将成为那个教堂的形象代言人，而不是教堂的灵魂与精神人物。最重要的是，汤姆非常担忧离开会给刚发起的资本运作带来负面影响。\u003c/p>\u003cp>最后，我平静地问他:“汤姆，根据你所讲的这一切，你觉得什么才是正确的决定？”汤姆从椅子上跳了起来，给了我一个大大的拥抱，说道:“你已经给了我答案。”实际上，我并没有给他答案，是他自己找到了解决办法。\u003c/p>\u003cp>这是三年前的事。汤姆从来没有后悔过自己的选择，我也没见过比他更快乐的人了。教堂的信徒继续增长着，布道也比以往更加激励人心。汤姆真是一个快乐而全身心投入的家伙！有时候你不一定要给出自己的意见。如果你能让别人去回答他们自己的问题，结果就好比作家弗吉尼亚·伍尔芙（ Virginia Woolf）笔下所描述的:“在事实被直觉所察觉的那一幸运时刻，就如同瞬间被点亮的那盏明灯一样令人茅塞顿开。当选择取决于个人时，你应该问:“你觉得什么样的决定是最正确的？”让对方自己找到正确的解决方法。\u003c/p>","explains":"\u003cp>【what】这个片段中主要讲述了作者通过提问加减法帮助神父梳理了新职位带来的利弊并最后通过提问让其做出了明确的人生抉择。\u003c/p>\u003cp>【why】大家是不是会有这样的经历，同事们、朋友们或者家人们可能常常会来找你寻求帮助，关于自己的个人选择问题，比如跳槽、留学、搬家甚至是该不该跟男朋友分手。面对这样的咨询，如果能通过提问的方式帮助他人发现希望、梦想，认清自己的角色，理清楚自己的状态，想明白自己的人生路该怎么走，何乐而不为？既帮助了他人，又避免了自己的困扰。\u003c/p>\u003cp>【How】那如何才能通过提问帮助他人做出人生选择呢？读完这个片段后，我们学会了三个步骤：\u003c/p>\u003cp>步骤一：在纸上划一条中线，一边是决定的利处，另一边是决定的弊端；\u003c/p>\u003cp>步骤二：提问决定的好处和弊端并写在纸上；\u003c/p>\u003cp>步骤三：根据纸上梳理的利弊，提问“根据你所讲的一切，你觉得什么才是正确的决定？”\u003c/p>\u003cp>【预防异议】学习了今天的片段后大家可能会有疑虑，当别人问我该怎么选择的时候，我真的只要这么简单地提问他就好了么？我真的不需要给出自己的建议么？万一我问了半天，他依然不知道该如何是好怎么办呢？确实，有些时候人生选择并不是那么容易就能做出的，而这样的提问方式关键在于可以帮助他人深入内心去挖掘自己真正的渴求，如果理清楚了自己的所求，很多时候做出最后的决定是自然而然的事了。那么这就很考验我们提问的技术了，需要我们反复操练提问这项技艺，才能更快更有益地帮助到他人。\u003c/p>\u003cp>【举例】接下来跟大家分享一个我自己的亲身经历，熟悉我的人都知道，我大学毕业后的第一份工作是在国企，后来干了两年跳槽去了外企，当我已经在外企呆了两年的时候，我的好朋友小Q找到了我，她是当时和我一起进国企的同伴中关系最好的。她跟我诉苦，抱怨国企效率低工资又涨不上去，领导官僚做派，说她想跳槽，可又担心这担心那。说了几次之后，我就鼓动她跳槽，一方面我现在的工作我自己很满意，告诉她工作可以很快乐，另一方面她这样负面的工作情绪对她自己的提升并没有什么帮助，未来的职业发展也会停滞不前。我自认为我讲的很在理了，可她最后还是没有采纳我的建议，依然过着一边抱怨一边混的日子，说了几次之后，我也就放弃了，她再提跳槽，我就跟她说你自己想想好。今天学习了这个片段，我感觉豁然开朗了，我就不应该直接给她指出我认为的方向，下次她再提跳槽的事，我应该首先提问她她跳槽的利和弊，看看究竟是什么让她一次又一次地举棋不定，她真正的内心需求是什么？当她自己已经清晰地了解了自己的所求之后再问她：“你觉得什么才是正确的决定？”\u003c/p>\u003cp>【适用边界】那么是不是所有他人的人生选择问题都适合用这提问的方法呢？当然不是，此方法适用于那些于个人意义重大，对于重要他人有影响的重要人生抉择，那些日常琐事的选择就不需要如此大费周章了。\u003c/p>\u003cp>【不这么做的坏处】那如果我们没有像这样通过提问来引导他人做出个人选择会有什么坏处呢？也许是你滔滔不绝地给出了自己的建议后，别人最后并不领情，依然苦恼或者做出完全和你建议相反的决定；也许是你对他说这是你自己的事情，当然要你自己做决定，对方就对你贴上冷漠无情的标签，从此疏离你。&nbsp;\u003c/p>","interaction":"\u003cp>&nbsp;【A2分步催化1】那接下来请大家注意仔细听，以下哪种情景你将会碰到呢？\u003c/p>\u003cp>国内有稳定工作的表弟申请到了国外的研究生留学机会来咨询你，闺蜜怀孕了跑来问你要不要辞职做全职妈妈，同事谈了新的恋情却老要两地跑就要不要搬去对方的城市问你意见......，请想象一下，在未来的一周你可能遇到的实际情境，把它写在便签上。情景是什么？发生了什么？下面就请大家用2分钟时间，将你想到的情景故事写在便签上，好现在开始。写好的伙伴请向我举手示意。&nbsp;\u003c/p>\u003cp>2分钟后【A2分步催化2】好，时间到，我看大家都已经写的差不多了。那么接下来，还是刚才你自己写的场景和话题，再设想一下：当你终于忍不住正要开口给对方建议的时候，这时你突然想起了今天的拆书，请仔细思考一下，应该如何应用刚才学到的方法来帮助他人做出决定。给大家4分钟的时间，把你的设想情景及对话写在便签上，写完之后小组讨论一下，之后我们请一个小伙伴出来跟我分享下。\u003c/p>\u003cp>（4分钟后）好，时间到，请一位小伙伴跟我来分享一下他将遇到情景及如何应对。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>沈老师：正好我有个朋友说这周末会来找我咨询关于是否要辞职，到时候她问我究竟她应该辞职转行做现在兼职的这个工作呢还是依然从事现在的工作，我就可以用现在这个办法，先用加减法提问来梳理，她离开现在工作专做兼职的这件事的利和辞职的弊端分别是什么，等她梳理完了之后，我再问她，“根据你刚才所讲的这一切，什么才是正确的决定？”推动她自己的反思，促使她做出有利于自己的决定。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1525577186000,"updated_at":1525577186000,"ria":true},{"id":4781,"topic":"沟 通 02","learn_goal":"学会提问，终结批评，解决问题","remark":"《提问的艺术》是一本教你如何通过富有技巧性的提问来提高沟通效率并提升自身影响力的书。\r\n人们普遍我们认为，我们之所以赢得生意是因为自己的聪明和勤奋以及只说对的事，然而本书打破常规，强调巧妙提问远比给出答案更为重要。\r\n无论德鲁克这样的大师，还是乔布斯这样的奇才，抑或是苏格拉底这样的圣人，提问都在他们的一生中扮演了重要的角色。\r\n对我们而言，无论想快速获得生意，立即获得潜在的客户的尊重与信任，让会议不偏离主题，还是想让交谈对象感到备受关注，保持良好人际关系，获得更多人生启示……，无疑都得学会聪明地提问。\r\n本书用具体的问题，真实的案例，为读者打造了一个提升提问技巧的实用宝典。问得不同，人生便不同。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"行知行晓","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是晓。今天为大家带来《提问的艺术》这本书里的一个片段，希望大家跟我进行完现场RIA学习后，能在有人发飙或有其他消极情绪的场景下，通过提问的方式，终止消极情绪者的消极情绪宣泄，并引导ta进入到解决问题的道路上来。\r\nF：《提问的艺术》是美国两位管理咨询师的合著，是沟通这个主题下的提问的技巧合集。此书通过作者大量的亲身成功案例的方式，来讲述提问在解决问题上面的四两拨千斤之力。\r\nA：此书既有故事又有实操方法，是一本趣味性与实用性兼具的小书。这本书每个问题单独成章，可以随时随地翻到哪里看哪里，就像一本工具书，适合随身携带随时翻看。\r\nB：通过此书，我们能学会迅速提高沟通技能的小技巧，从而可以立竿见影的提高我们在工作中/家庭中或社交中的沟通效率甚至做事效率。通过今天节选片段的学习，我们能在面对有人发飙或情绪失控时候力挽狂澜，进而推进事情的解决。","ratings_count":1,"texts":[{"id":7835,"quote":"\u003cp>电话会议一开始就十分糟糕。电话另一头是我的客户和他公司的另一名高管比尔。我之前从未见过比尔。他现在非常生气。“这简直乱了套了,”他在电话中咆哮道,“恕我直言,你建议的方法简直就是多余的!我不明白它怎么可能解决这一切。”\u003c/p>\u003cp>比尔咆哮、抱怨和批评了近25分钟。他不断抱恕那个他们正在进行的项目还没有结果。他指责合伙人的自满以及他们太关注于内部的那些事了。但很显然，他并没有提及事实，那就是他们所面临的资金缺口。他也没有提及他们]应该从哪里入手，而合伙人应该做哪些改进。\u003c/p>\u003cp>离会议结束还有5分钟时，我轻轻地插了一句:“比尔，我能问你一个问题吗？”“嗯，可以。”他不屑地回答道。“当你面对年轻的合伙人时，你认为他们要做些什么才能够建立起一种紧密的客户关系,也就是你希望他们应该多做些什么?”\u003c/p>\u003cp>之后，大家沉默了片刻。比尔急切地说道:“嗯，这是个好问题!”之后比尔又大声地说:“哎!现在你已经把我拉回正轨了!”他的声音里夹杂着几许发泄后的兴奋。又停顿了一会儿，他补充道:“嗯…好，让我们言归正传。”\u003c/p>\u003cp>接着他开始说他希望看到的改变:“他们需要一张像你发送给我的那种导图。是的，从最上面的一页开始。我认为他们有三件事情需要做得更好。”他不再咆哮了,怒气也逐渐消失了。突然之间，就像上帝指使的一样，暴风雨停止了，海面又重新恢复了平静。这时，我们才真正进入关于这些事情的实质性讨论中。\u003c/p>\u003cp>几个月后，在比尔的批准下，我又和这家公司开始了新的合作项目。这不是因为我卖了什么东西给他们，而是因为我在关键的时候问了一个正确的问题。\u003c/p>\u003cp>一个好的问题就像一剂能够抚平坏情绪的良药，将他人拉回真正重要的事情上来。当我问比尔“你希望他们应该多做些什么”时，,我就将脱轨的对话重新拉回到了正确的轨道上来。\u003c/p>\u003cp>人们经常抱怨别人并坚持让他们做出改变。你应该通过问这个问题将他们从批评上拉回到解决问题的轨道上来：“你希望他们应该多做些什么？”\u003c/p>","explains":"\u003cp>与人沟通中，难免有些批评、抱怨、指责甚至吵架的场景。面对这种场景，有的人选择以默不作声来回应，有的人选择以其人之道还治以其人之身的方式来回应。然而，不论哪种方式，都不是一个很好的选择。而我们刚刚读过的拆页就提供了第三种回应方式：向有情绪的人提一个问题：“你希望他/我（们）多做些什么？”。通过这个提问，使对方意识到ta需要停止发脾气，而要关注如何解决问题。\u003c/p>\u003cp>一般来说，在抱怨或批评的背后，都暗藏着对他人行为的或明或暗的要求。通过对于别人希望他人做什么的提问，能让对方将情绪宣泄转移到自己希望的行为上来，一旦完成这个转移，事情就朝向解决问题的角度进发了。\u003c/p>\u003cp>如果不这么做，而听任抱怨或指责的继续，那将会有一些列糟糕的状况出现：比如浪费时间、引起他人的不满、给人留下无法解决问题只会抱怨指责的印象、影响人际关系，最重要的是问题本身并没有得到解决。\u003c/p>\u003cp>比如我爸如果看到我某件事儿做的方法不对，他就会发脾气。他脾气比较急，常用的沟通方式就是批评与指责，而每当此时，我就会跟他吵架。一旦吵架，我们就都限于情绪中了，结果，我爸不会想教我正确方法了，而我做事的方式还是老样子，并且吵架也会恶化我们之间的关系。而如果在他发脾气时候，我不是跟他吵架，而他，“你希望我该如何做呢？”那我爸极为可能马上就把精力转移到教我正确方法上来了。\u003c/p>\u003cp>在用这个问题的时候，还需要注意时机。要在批评抱怨或发飙者的情绪有所缓解的时候，再抛出这个问题，或者在抛出问题之前，对对方的情绪表达下的认同。这样效果比较有保证。\u003c/p>\u003cp>另外，使用了这个问题以后，为了保证效果，避免比如对方仍然以气比较有话来回应你，我们还可以根据情况继续追问：“你认为他/我（们）之所以那样做了或没做是因为什么”。这些追问再加上，一般人应该不会还继续抱怨、指责或批评下去了。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 接下来，请小伙伴们各自想一想，找一个自己所认识的脾气最火爆的人，或者一个喜欢抱怨批评的人，然后回忆一下，在你再跟ta的交往中，有没有他对你的抱怨、批评或指责的情形，或者你见过的他对其他人这样的抱怨、指责或批评，面对这些场景，你当时是怎么回应的？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>小伙伴A分享道\u003c/strong>：我的直属上司一直有点受压制，属于比较憋屈的状态，很多时候，在他给我讲我的问题时候，喜欢用不好听的话批评我，并也容易泛化起来抱怨很多其他的事情。而我一般只是通过嗯嗯这样的语言来回应他。这样的情况让我特别糟心，我一方面是受到了批评心情不好，另一方面，他批评完我后也不告诉我他的期望，我还得猜他希望我怎么做，这使我很郁闷。\u003c/p>\u003cp>A1+：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 通过小伙伴A的分享，我们也看到了他领导这种抱怨、批评不但没解决问题反而给A带来了很大的困扰。相信大家各自回忆的情境中，都会或多或少有些让人不满的地方。那么，接下来，请你想一想，如果再次面对同样的场景，你会如何运用今天的技巧----用一个问题“你希望他/我（们）多做些什么？”来终止对方的情绪，进而引导ta到解决问题的道路上来呢。请大家针对刚刚自己回忆的场景，按照今天学到的技巧，来写一个应对方案。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>&nbsp;小伙伴A继续分享道\u003c/strong>：如果再次面对领导的批评，等领导的情绪差不多了，我会说“领导您说的对，您的心情我理解，我呢因为经验少，做的事可能还不够好。那么，您觉得我该多做些什么来改善我的问题呢？”通过这个问题，我相信我的领导接下来会讲注意力转移到告诉我要多做点什么上来了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 小伙伴A不但使用了今天片段中的问题“你希望我多做点什么”，还在此之前加上了一些对领导的情绪起安抚作用的话语。这样一来，使用问题来终止情绪，并且进入到解决问题的方向上来的可能性就非常有保证了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1520856583000,"updated_at":1520860076000,"ria":true},{"id":4733,"topic":"沟 通 01","learn_goal":"学会提问，增进了解，建立关系","remark":"《提问的艺术》是一本教你如何通过富有技巧性的提问来提高沟通效率并提升自身影响力的书。\r\n\r\n人们普遍我们认为，我们之所以赢得生意是因为自己的聪明和勤奋以及只说对的事，然而本书打破常规，强调巧妙提问远比给出答案更为重要。\r\n\r\n无论德鲁克这样的大师，还是乔布斯这样的奇才，抑或是苏格拉底这样的圣人，提问都在他们的一生中扮演了重要的角色。\r\n\r\n对我们而言，无论想快速获得生意，立即获得潜在的客户的尊重与信任，让会议不偏离主题，还是想让交谈对象感到备受关注，保持良好人际关系，获得更多人生启示……，无疑都得学会聪明地提问。\r\n\r\n本书用具体的问题，真实的案例，为读者打造了一个提升提问技巧的实用宝典。问得不同，人生便不同","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"行知行晓","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是晓。今天我带来1-2的过级分享，我的分享用时大约一刻钟。首先，用三个标签来介绍下自己，拆书帮喜乐分舵的宣传长老，一步三回头但是依然挣扎着前进的自我成长实践者，一个很好的倾听者，因为我内向，比起说，我更愿意听。然而，读了《提问的艺术》这本书后，我知道，我其实也不是个很好的倾听者，因为我只是把说话的机会让给了别人了，自己选了被动的听而已。而一个好的倾听者是需要主动去听的，是需要通过提问以便更多得了解对方的。所以，为了使自己成为一个更好的倾听者，今天带来这本《提问的艺术》与大家分享。此书既有故事又有实操方法，是一本趣味性与实用性兼具的小书。通过此书，你能学会迅速提高沟通技能的小技巧，从而可以立竿见影的提高你在工作中/家庭中或社交中的沟通效率甚至做事效率。并且这本书每个问题单独成章，可以随时随地翻到哪里看哪里，就像一本工具书，适合随身携带随时翻看。","ratings_count":2,"texts":[{"id":7785,"quote":"\u003cp>当你让谈话都在围绕着自己时，别人也许会认为你很聪明，但这并不能在你们之间建立起信任，也就无从了解对方。同时，也失去了一次建立深厚友谊的机会。因此，若要推销自己，可以尽力表现自己的聪明。如果想建立良好的关系，那么就应该将表演的机会让给别人。想要赢得他人的心，就要多向他人提问，以表达你的兴趣和鼓励他人进行深度对话或多说一些话，是每个优秀提问者的任务。\u003c/p>\u003cp>你可以先这样问：“关于这件事，你能再多说一点吗？”接下来再这样问：“什么时候？发生了什么事？后来怎么样了？为什么呢？”弄清楚对方的情况和需求后，你才会知道该怎么去做，而对方也会从你的问题中体会到你对他的关心和重视。\u003c/p>\u003cp>“你能多跟我讲讲吗？”是一个简单而有效的问题，不妨经常这样问别人，以开启更为流畅的交谈。\u003c/p>\u003cp>当对方回答时，你可以进一步问对方：“能跟我多讲讲吗？”这样会让你们之间的对话和交流更加畅通。不要小看这样一个简单的问话，它可以用在任何场合使用，将对方迅速带入到互动的对话中。\u003c/p>\u003cp>“你能多跟我说说吗？”是一个随时都能用上的有效问题，甚至每天都可以用。\u003c/p>","explains":"\u003cp>回想一下，在生活中你是否遇到过与别人聊了很久关系却没有任何改变的情形：比如，你们尽管各自讲了很多，然而结束之后你们并不想再次见面了？比如，你一个人滔滔不绝地自嗨，而对方却一脸懵逼或心不在焉？比如，你俩都在尬聊了，其实恨不得马上走人，但是却还不得不在一起继续聊？ \u003c/p>\u003cp>天啊，光想想这些情景就让人难过。这些难过的情景有一个共同点，就是你没有让别人感受到你对他的兴趣与重视，没有把表演的机会让给对方。所以，结果基本上是，你们的天谈完了就完了，彼此之间可能没有信任的增加与感情的增进，也可能顺便把合作的可能丧失了。\u003c/p>\u003cp>这里分享一个作者自己的例子。作者的银行经理给他打过一年的电话了，想约见面，而作者一直没时间。一天中午，作者终于跟他的银行经理约了午饭。从一见面开始到会面结束，作者的银行经理一直在说自己，从自己怎么做上经理的到最近要去哪里度假，而没问作者一个关于作者的生意或职业的问题。作者认为这样的会面就是浪费时间。而因为不了解作者的事情，银行经理除了没有改善与作者的关系，甚至丧失了改进了自己服务或实现更多业务推广的机会。\u003c/p>\u003cp>其实，若想与人建立良好关系，应该让对方多谈自己，给对方表演的机会，让对方觉得你对他很感兴趣，想要了解他更多。这种方法，会让对方对你产生非常多的好感，是建立良好关系的开始。\u003c/p>\u003cp>让对方多谈自己的具体方法是多向对方提问。向对方提问，可以用一个很简单却非常有效的句子“关于这件事，你能再多说一点吗？”开始。这个问题一抛出来，对方就会跟你讲他的更多的事情。在对方谈自己事情的过程中，你可以进一步就对方事情的when、what、how、why等进行提问，以便让对方更充分地表达自己。这样一来，你能了解对方的更多信息，对方对你的好感也能让你赢得他的信任，甚至是心！\u003c/p>\u003cp>在作者的例子里，银行经理不应该把聊天变成自己的独角戏，而应该更多的是让出舞台让作者多说些关于自己的事情，从而维护作者与银行的关系，甚至挖掘更多的服务机会。\u003c/p>\u003cp>“你能多跟我讲讲吗？”这个问题可以在任何时候任何场合与任何人使用，尤其是你想进行深度对话或鼓励对方多说一些话的时候。同时，加上5W1H的任何问题，你可以获得源源不断的对方的信息，从而使对方对你的喜爱越来越多，并允许你对他产生影响力。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;通过这个拆页，我们了解到，如果你想与别人建立良好的关系，想对别人施加一些影响，你需要在聊天的过程中让对方多谈一些，可以通过“关于这件事你可以多说一些吗？”这样一个问题来达到这样的目的。那么，请回想下自己有没有相关的经验或类似的经历，即使不是自己的，你见过的或听过的其他人的也行。然后，将这些经历在小组中分享一下。我们正好是偶数人数，大家各自与你对面的小伙伴组成一个小组，时间两分钟。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;小组分享后，小伙伴A给大家分享道：春节假期期间，我与本地的A朋友一起接待了外地来的B朋友，我们三个都是第一次见面。我与A作为地主，按理我们应该让B多说些自己的事情，一方面能表达我们的地主之谊以及对B的尊重，另一方面，也能让我们更多的了解B。然而，在实际的聊天中，我们的A朋友却滔滔不绝地讲了自己的种种，即使我们打断都没有用。会面结束之后，我与B都对A的印象不太好，我们默默达成了一致，以后不想再跟A一起会面了。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;今天，我们一起学习了一个提问的技巧“你能多说一些吗？”通过这个技巧，我们可以做一个优秀的倾听者，做一个让别人喜欢我们的人，做一个通过提问而增加与他人的感情的人，甚至是影响他人的人。接下来，请大家根据今天分享的内容写一个A2便签，就是写一个接下来在什么情况下，你将怎么运用今天学的这个提问的一个计划。这个计划要能贴到冰箱上去执行的，要符合SMART原则。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; A2学习者案例记录：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我想下周一下班时更多地了解下新来的实习生H。她是本地某大学的大四学生，目前跟着我实习，我们相处了一段时间了。然而，除了谈工作，我对她个人所知甚少。我们有时候下班时能一起走一段路。\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;下周一下班一起走路时，我会问她“你周末干啥了？”我猜测，她可能会去看个电影、逛街买衣服或吃饭之类的。不论她说哪个，我都可以问“能跟我多说一下你看的电影/吃的饭/逛街的经历吗？”之后，可以针对她的回复继续问。细节问完了，还可以问你还喜欢看啥其他的电影/吃其他的啥/买啥其他的衣服/你对衣服的审美如何看？然后可以继续问，除了这些，你还有其他爱好吗？如此往复。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;通过这种对话，我可以了解我的实习生的业余爱好，更多的性格特征，甚至其他的我不曾料到的事儿。谁知道呢？让我们拭目以待！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1520252778000,"updated_at":1520252778000,"ria":true},{"id":4714,"topic":"用加减法帮助对方做出选择","learn_goal":"用加减法帮助对方做出选择，学会做选择","remark":"我们工作，生活，会遇到许许多的选择，就像人生的岔路口，该往哪个方向走，我们会做比较，会纠结，而最后做出的选择也一定是非常不情愿的舍弃一个，满不甘心的走向另外一条路，鱼和熊掌不可兼得，那么，我们该如何做出最好的选择而不后悔，这里，就是答案。","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"刘志学","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>自我介绍:（1分钟）\u003c/p>\u003cp>&nbsp;拆书帮的各位小伙伴，大家晚上好，我是今晚的第一位拆书家，志学，我的三个标签:学英语，卖保险和做主持，希望大家能够记住我，一个阳光帅气的小伙子，今天，我给大家分享的是书籍《提问的艺术》当中的一个片段:用加减法帮助对方做出选择，希望能对各位参加小伙伴在生活工作中面临选择难题时，提供一点帮助。\r\n拆书和拆书帮介绍:（2分钟）\u003c/p>\u003cp>&nbsp;拆书法是一种成人学习的方法论，是将知识内化成学习者的能力。那我们为什么读书或者拆书呢，我们成年人读书无外乎就是想解决自己在工作或者生活中遇见的问题或者是提升个人的能力，比如演讲，沟通。拆书法就很好的把书中知识关联到我们以往的经验，并且制定以后执行的具体方案。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;拆书法分为个人学习拆书法和组织学习的拆书法：个人学习的应用就是便签法，就是我手里拿的三种颜色的便签。组织学习，就是今天这样这样爱学习小伙伴聚集到一起，然后由一位拆书家带着一本书的某个片段带领大家进行现场学习，引导促进小伙伴把知识拆为己用。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;拆书帮是一个公益社群，是基于拆书法由一群爱学习的小伙伴建立的。全国各地都有拆书帮的分舵。拆书帮的使命就是帮助学习爱好者成为拆书家。\u003c/p>","ratings_count":2,"texts":[{"id":7766,"quote":"\u003cp>\u003cstrong>【图书介绍】《\u003c/strong>\u003cstrong>提问的艺术\u003c/strong>\u003cstrong>》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【主题介绍】\u003c/strong>\u003cstrong>用加减法帮助对方做出选择\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【总时长】\u003c/strong>\u003cstrong>10-15 \u003c/strong>\u003cstrong>min\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cstrong>【阅读时长R】3&nbsp;\u003cstrong>min\u003c/strong>\u003c/strong>\u003c/strong>\u003c/p>\u003cp>“请尽可能给我打个电话，我需要和你谈一谈。”我正在自己供职的教堂负责11点服务的热线工作，教堂的神父汤姆·塞维尔（　Tom　Sewell）拉着我的胳膊悄悄对我说，他很着急见我。我是这所教堂的董事会主席，汤姆和我关系非常好。\u003c/p>\u003cp>我周一的第一件事就是打电话给他。我正在想最坏的结果。第二天，我坐在了汤姆摆满图书的办公室里。我能看出他正经受着痛苦的煎熬，我从未见过他如此平静。“我得到了一个新职位，”汤姆说，“你还记得四周前的礼拜日我没来吗？我去纽约的一个教堂做传道者了。他们正在考察我，那是纽约最大、最有声望的教堂。他们已经通知我去他们那里做高级神父了。那可是教堂中最重要的神职人员了。”\u003c/p>\u003cp>　　“我为你感到骄傲，”我回应道，“但这一点儿都不意外在你和我们一起工作的这段时期内，我们的教堂规模已经扩大了三倍，我们的教友都十分地敬重你。最值得骄傲的是你将传道的价值发挥到了极致。请告诉我你的决定是什么？\u003c/p>\u003cp>　　“我还没有做出决定。南希不太愿意搬家，但她支持我。孩子们一点儿都不喜欢纽约，他们在这里有自己的好朋友，他们会联合起来抵制搬家。我该怎么办呢？\u003c/p>\u003cp>　　我停顿下来，并立刻陷人对汤姆所面临困境的沉思中。当选择关乎个人的时候，做出选择需要你有足够的勇气，最好的办法就是去挖掘和发现自己内心深处真正最想做的是什么。\u003c/p>\u003cp>\u003cstrong>我决定采用加减法帮助汤姆做决定。加减法就是在表格中央划一条竖线，一边是有利的一面，一边则标出弊端。\u003c/strong>\u003c/p>\u003cp>于是我开始问汤姆。在有利的一边，有很多好处，如薪水更高、牧师的住宅更大以及信徒人数是我们教堂的四倍，有全职的商务经理以及多达七名的神职人员。而在弊端的一边，所\u003c/p>\u003cp>列的弊端显然更多。例如，从刚一开始南希就更愿意留下来，两个大一点的孩子正在上高中—泰德（Ted）是校篮球队的，而法兰（Fran）是班长。汤姆自己也不太喜欢纽约。\u003c/p>\u003cp>单子上罗列的弊端还在增加。他将会把所有的时间和精力都花在传道上，他还会失去自己与教友们已经建立起来的关系和私人联系。他将成为那个教堂的形象代言人，而不是教堂的灵魂与精神人物。最重要的是，汤姆非常担忧离开会给刚发起的资本运作带来负面影响。\u003c/p>\u003cp>　　最后，我平静地问他：“汤姆，根据你所讲的这一切，你觉得什么才是正确的决定？”汤姆从椅子上跳了起来，给了我个大大的拥抱，说道：“你已经给了我答案。”实际上，我并没有给他答案，是他自己找到了解决办法。\u003c/p>\u003cp>　　这是三年前的事。汤姆从来没有后悔过自己的选择，我也没见过比他更快乐的人了。教堂的信徒继续增长着，布道也比以往更加激励人心。汤姆真是一个快乐而全身心投入的家伙！\u003c/p>\u003cp>　　有时候你不一定要给出自己的意见。如果你能让别人去回答他们自己的问题，结果就好比作家弗吉尼亚·伍尔芙（　Virginia　Woolf）笔下所描述的：“在事实被直觉所察觉的那幸运时刻，就如同瞬间被点亮的那盏明灯一样令人茅塞顿开。”\u003c/p>\u003cp>当选择取决于个人时，你应该问：“你觉得什么样的决定是最正确的？”让对方自己找到正确的解决方法。\u003c/p>","explains":"\u003cp>\u003cstrong>I:（1分钟）\u003c/strong>我们工作，生活，会遇到许许多的选择，就像人生的岔路口，该往哪个方向走，我们会做比较，会纠结，而最后做出的选择也一定是非常不情愿的舍弃一个，这时就需要我们挖掘和发现自己内心深处真正想做的是什么，\u003cstrong>1，静下心来，仔细的思考，画一条竖线，2，\u003c/strong>\u003cstrong>列出做这件事情的好处与坏处\u003c/strong>，你就会发现最后的答案，做与不做哪个是你内心深处真正想要的。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1.（3分钟）\u003c/strong>在我们的生活当中呢，会遇到很多这样类似的问题，好比我们上高中做题时，会不会经常遇到这样一道选择题，觉得选项A对，但是B也有可能，这时，我们会纠结，到底选择哪个，到底选哪一个，而且，一但我们不能正确的面对自己的选择，我们的心情会受到极大的影响，会影响整场考试的状态，记得在北京第一次参加拆书帮活动时，自己的内心便十分的纠结，我石家庄的朋友给我推荐的是西二旗的紫禁之巅分舵，而我在东三环住，来回路程接近四个小时，我在去的路上还在纠结，去，还是不去，我自己的心情非常的不好，纠结了好久，内心两个小人在不断争吵，一个小人说，去啊，去啊，你不是想像在石家庄一样参加拆书活动么？而另外一个小人，立马就会跳出来，不去，不去，远死了，还要走那么远。\u003cstrong>我深吸了一口气，内心深处画了一条竖线，问了一下自己，我为什么要去参加拆书帮的活动呢？第一，我喜欢读书，喜欢从书中获取知识，丰富自己，奈何自己读的书并不多，我期望能在拆书帮学到更多的知识，第二，我期望自己在北京能有自己的两个团体，一个是工作团体，一个是生活团体，工作团体，显然就是我现在的同事，而生活，拆书帮无疑是最好的选择。\u003c/strong>\u003c/p>\u003cp>我为什么不想去，只是因为路程太远，回家可能会晚，路上时间会长，在路上会花费我一天当中很大的部分，优劣列出，我很快就发现了正确答案，我想要的，远远高出我所担忧的，就这样子，开启了我北京的第一场拆书之旅，才有了，紫禁推荐而入翰林，才能站在这里给大家分享。\u003c/p>\u003cp>\u003cstrong>A2:（2分钟）\u003c/strong>临近新年了，给大家分享一个我最近的纠结之处，我这周末就可以回家休年假，但又觉得自己应该在北京多待几天，处理处理自己的事情，\u003cstrong>于是我画了一条竖线，分析了回家的好处与坏处，好处是我能早点见到父母，能够睡懒觉，能够帮姐姐服装店打打酱油。坏处是我期望两天工作之后的自由时间会不复存在，我工作的善后工作也无法进行。一比较，我就发现了自己真正想要的，我决定12号再回家。\u003c/strong>\u003c/p>\u003cp>这就是我今天的分享，希望对各位小伙伴能有所收获。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1519918021000,"updated_at":1527255154000,"ria":true},{"id":4679,"topic":"如何更好地通过提问来引导对方积极思考","learn_goal":"掌握三步提问引导法可以帮助他人激发独立思考力","remark":"","level":"TF3-2","duration":30,"status":29,"type":0,"chaishujia":{"username":"什刹海","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"伙伴们！晚上好，我是拆书家李朋三。很高兴，每周五的活动，伙伴们都积极参与，风雨无阻，当然今天的天气还不错。不破不能立，不拆不成器，今天我们的TF3-2 拆书之旅开始啦！\r\n【学习目标】在跟随我完成本次RIA现场学习后，学习者能够学会通过使用苏格拉底的思考方法，并提出有启发的问题，引导对方去积极思考\r\n【分组】根据现场的人数我们分成2组，每位拆书家带一组伙伴\r\n【图书介绍】\r\n今天要给大家拆的这本书是\u003c提问的艺术>，作者是安德鲁·索贝尔 美国著名商业战略家，客户关系领域的超级顾问，这是一本教你如何通过富有技巧性的提问来提高沟通效率并提升自身影响力的书\r\n【事件场景】 不知道大家在平时有没有遇到过这样的经历，当朋友来寻求帮助的时候，一开始你确实是出于好意帮忙并给出了一大堆的建议，然而建议的效果却并不理想，甚至还有可能造成朋友的反感；\r\n【友情提醒】评委老师，好，由于开场部分字数限制，余下部分转移至【I拆解部分】","ratings_count":1,"texts":[{"id":7722,"quote":"\u003cp>\u003cstrong>《提问的艺术》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>像苏格拉底一样思考\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>苏格拉底生活在古希腊，他是一位杰出的、善于提具有影的问题的大师。他在教授学生时，并没有采取演讲的方式，而是传授给学生一系列发人深省的问题。通过这些问题，他鼓励学生在学习中提升自己的思维。他总是能揭示出这些问题的本质。尽管只是慢慢地一点点渗透，但却总能直达事物的核心。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>苏格拉底总是以“什么是美德”或“什么是美好”这些我们随时都在用的词语开始他的课程。我们真地清楚它们意味着什么吗？今天，世界上的许多大学都在他们的教学中采用了“苏格拉底法”，其中最有名的便是哈佛大学商学院。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>苏格拉底将这一方法总结得很透彻。他说：“人类最高级的智慧就是向自己或向别人提问。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>苏格拉底是一位针对雅典社会和政府畅所欲言的评论家。他最终因对统治阶级的抨击而被判了死刑。对此他没有丝毫反抗，而是饮下了一杯毒堇汁。尽管毒堇汁慢慢地浸入了他的心脏，让他离开了人世，但他却给世人留下了历史上最伟大的哲学家之一的名声。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如今，你可以将苏格拉底的方法应用到日常工作和生活中。如何才能像苏格拉底一样思考呢？首先，从提问开始，而不是去阐述、声明或命令。其次，问一些每个人都会想到的、最基本的问题，这可能会让上他们大吃一惊。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>例如，在工作中，有人会说：“我们需要更多的创新。”这时你应该问：“你眼中的创新是什么样子？”当听到一个需要更多团队合作的提议时，你可以这样问：“当你提到‘团队’一词时、你的意思是什么？”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>诸如此类的问题能够引导对话双方进入更深层次的探讨中，并让对方参与进来，引起他们的思考。你也会因此赢得智慧导师的声誉—引导别人步入正确的方向，而不是将自己的观点强加于人。\u003c/strong>\u003c/p>","explains":"\u003cp>【友情提醒】评委老师，好，由于开场部分字数限制，【图书介绍】余下部分转移至【I拆解部分】\u003c/p>\u003cp>【事件场景】比如说：有一天，朋友来找你，想让你给他推荐下你比较喜欢的一些手机app给他，你一看帮他的机会来了，就直接说：我给你推荐一个看视频段子的APP吧，这款软件真是不错……然后就开始巴拉巴拉的说了一大通，你觉得自己说的很好，而且是真诚推荐的；但是对方可能会想：“我根本就不喜欢什么视频段子，咱们还是朋友呢，原来你一点都不了解我”，本来好好的一次帮忙反而造成了朋友的内心不愉快，让这次谈话变得有些尴尬或者是陷入了僵局。\u003c/p>\u003cp>【提问】遇到这类事情，我们的心情是怎样的呢？我们又会产生怎样的想法与情绪呢？\u003c/p>\u003cp>【影响】你是不是觉得自己很无奈，甚至还有些委屈，心里可能会想我明明自己说的是大实话啊，这款app真的很好的，不看肯定会后悔的，\u003c/p>\u003cp>然而结果会如何呢？冷场、彼此谈话陷入僵局、友谊出现隔阂，帮忙反而成了帮倒忙，彼此之间也都不开心\u003c/p>\u003cp>长此以往，你就会发现，愿意来找你聊天说话的人越来越少，共同话题也越来越少，你会不会变得心情沮丧呢？\u003c/p>\u003cp>【解决】那么，怎样才能解决以上发生的问题呢？答案就是，学会有效的提问；也就是《提问的艺术》这本书中所提到的 “答的好不如问的好”，在沟通中，不要急于给出答案，而是提出好的问题，好的问题能帮助我们了解对方的真实想法，好的问题能够帮助我们拨开重重迷雾，看清问题本质，让对方更有兴趣、更重视双方的谈话。\u003c/p>\u003cp>【[A1]促动参与自测题】\u003c/p>\u003cp>拆书家提问设计\u003c/p>\u003cp>（逐字稿）：在阅读原文片段前，先请大家来做一个简单的测试，看看我们在倾听他人时的表现 。以下5个题目，请按照1~6分的标准给自己打分，1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示非常符合，请用“√”方式）。\u003c/p>\u003cp>给大家一分钟的时间，做好的伙伴请举手示意\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1. 当家人或者同事在向我咨询自身专业事情时，我不会选择刻意的表现自己有多么的专业，而是选择尊重他们，发自内心并真诚地了解他们的真实想法。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2. 当朋友向我倾诉目前TA所面临的问题时，我不会马上给出答案，而是尽量使用提问的方式去引导TA自己去找寻解决方案。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.当别人来找我要产品、方案、信息等等，无论我是否能够提供解答，我都会通过提问的方式来了解对方此次来的最终目的是什么。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4. 在自己面试的准备过程中，一般自己不仅准备：要说什么，还会花很多精力去准备自己需要向面试官提问些什么。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5. 在参加一些开放性的学习等分享、演讲类活动时，自己通常会提前准备一些好的问题，用来与分享者、讲者进行更加深入的沟通\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【[I]解释自测题】\u003c/p>\u003cp>自测量表是采用行为特征量化的方式，让我们在学习前了解现状的一种测评方法\u003c/p>\u003cp>好了，想必大家的结果都出来了。那我现在讲解一下：\u003c/p>\u003cp>测试表中一共有5道题，主要是测试大家是否有提问的这种潜意识体现？\u003c/p>\u003cp>第1-3的测试题是在测试我们能否及时给予对方提问的反馈\u003c/p>\u003cp>第4、5问题是测试我们是否会在事前准备提问\u003c/p>\u003cp>大家可以算一算自己的分数。\u003c/p>\u003cp>那么基本上\u003c/p>\u003cp>20分以上的，说明你的提问意识还是不错的，\u003c/p>\u003cp>20分以下的，可能要注意了，因为你的提问意识还不够好，需要进一步的加强\u003c/p>\u003cp>当然测评结果不是唯一的标准和一成不变的，只是我们当下现状的一种反映，同时也是让我们在提问他人的意识方面给到一个更好的参照和新的起点。\u003c/p>\u003cp>【I拆书家拆解引导】\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>估计大家看完拆页后可能会这么想？\u003c/p>\u003cp>这种启发式提问，都适用于哪方面的沟通探讨呢？\u003c/p>\u003cp>它比较适合时间以及氛围相对轻松的一些沟通交流的场合，前提是彼此双方都比较有时间对某个问题进行深入的探讨这一类的沟通交流。那么假如是时间较为紧张的商务谈判或者是上对下的这种简单任务传达，就不太适合这种过于迂回的提问沟通交流方式了。\u003c/p>\u003cp>【what+强化讲解概念I】\u003c/p>\u003cp>首先今天的拆页，主要讲了哪些内容呢？今天的拆页，主要叙述的\u003c/p>\u003cp>这个片段主要讲的就是我们为什么需要在沟通对话中用提问的方式进行引导，比如让对方参与进来，引起他们的思考，正确的方向等等，因为书上写的比较细致，相信大家都可以理解，我只是重点讲解一下问题与提问的区别。\u003c/p>\u003cp>问题是要求回答或解答的题目或是需要解决的矛盾、疑难等，它的属性是相对静态的，因为它就在那里\u003c/p>\u003cp>而提问则不同，提问是指在一定的情境下，一方为促进沟通交流而向另一方抛出一些问题解决的任务并期望对方积极反应作答的一类主动行为。这里它属于动态的\u003c/p>\u003cp>【WHY】那为什么我们要通过提问来引导对方进行积极思考呢？\u003c/p>\u003cp>那是因为阐述、声明或命令性的沟通对话会带来许多不良后果，比如:观点强加于人，对方没有参与感。\u003c/p>\u003cp>【How】那么如何才能通过提问来引导对方进行积极思考呢？\u003c/p>\u003cp>有以下三个步骤让你学会通过提问来引导对方思考\u003c/p>\u003cp>1.先倾听然后询问对方的想法，比如：你是怎么想的呢？ 对于你来说，什么才是重要的呢？\u003c/p>\u003cp>2.通过关键词促进理解：哦，你理解的“工作和家庭的平衡”是具体是什么意思呢？\u003c/p>\u003cp>3.和对方一起找办法：关于这个问题，你自己现在有什么办法吗？或者我们一起想想，用什么样的方式和办法去解决它会更好？\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>那么为了便于大家的理解，下面我举一个例子详细地来说明一下。\u003c/p>\u003cp>这周一时候，朋友约我见面，大体是说要跟我咨询下关于他究竟该不该辞掉现在这份工作的问题，那么我想自己既然是生涯规划师，能帮上忙就尽量帮他一下吧\u003c/p>\u003cp>见面后，我先耐心地听他说了关于目前工作的一些具体情况，比如：环境、人际关系、个人发展等问题\u003c/p>\u003cp>听他简单说完，我就运用了第一招“询问对方的想法”问他：“哦，你觉得现在的这份工作对你来说，意义在哪里呢？\u003c/p>\u003cp>然后他就说：工作的意义就是给了我生活的来源，但是太忙了整天加班，我完全无法平衡自己的工作与陪伴家人和做自己想做的事情之间的关系，心里一直比较焦虑和烦躁\u003c/p>\u003cp>接着第二招“通过关键词促进理解”接着提问：哦，那你是怎么理解平衡的呢？你认为对你来说，现阶段什么才是最重要的呢？\u003c/p>\u003cp>他回答说：现在家里小孩还小，有爸妈在帮我带，现阶段对我最重要的是自我提升。\u003c/p>\u003cp>继续第二招：那你觉得现在这份工作能满足你的自我提升吗？\u003c/p>\u003cp>他又说：其实，现在这份工作还行吧，确实也能学到很多东西，但是我感觉自己大都时候都是力不从心的那种感觉，就是觉着自己能力达不到吧。\u003c/p>\u003cp>第三招来了“和对方一起找办法”我又问：哦，听你这么一说，问题的主要原因可能还不在于这份工作，或许更多的是你自己认为个人能力达不到，所以让你感觉力不从心，那么你觉得会不会有什么其它办法可以更好的来提升下自身的能力呢？\u003c/p>\u003cp>然后，我就和他在接下来的时间里一起对于提升能力的话题做了进一步的深入探讨，并帮他找到了自己适合的方向和目标，他很开心，我当然也很高兴，因为帮助了他。\u003c/p>","interaction":"\u003cp>【促动参与】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>那么接下来，咱们大家就来做个小的场景演练。请各小组选择一个场景，要求是要用到我们刚刚分享的通过提问来引导对方积极思考进行交谈，帮助你与更共同参与彼此之间的沟通与对话，并进入更深层次的探讨。\u003c/p>\u003cp>场景1：\u003c/p>\u003cp>【时间】周六上午10点\u003c/p>\u003cp>【地点】某处星巴克咖啡馆\u003c/p>\u003cp>【人物】小张和朋友小刘\u003c/p>\u003cp>【背景】小张是一位单身白领，她朋友小刘27岁刚刚结婚，正好周末，两个人约好一起聊天，虽然小刘是新婚但是她却一脸愁容，\u003c/p>\u003cp>为什么呢？因为小刘自己刚刚换了一份很有挑战性同时也比较适合她的工作，这当然是挺好的\u003c/p>\u003cp>但是工作要经常加班，婚后他老公就非常有意见，要求她尽快把工作辞掉换一份轻松不加班的工作，然后为此她自己就内心比较纠结，到底要不要换工作呢？有换了工作以后，自己会不会开心呢？\u003c/p>\u003cp>【对话】\u003c/p>\u003cp>小张\u003c/p>\u003cp>小刘\u003c/p>\u003cp>讨论思路：请按照刚刚分享的步骤对场景进行分析讨论，编写剧本。\u003c/p>\u003cp>1、小组内可以两人组成一组，一个人扮演孩子妈，一个人扮演小罗\u003c/p>\u003cp>2、先根据场景讨论，扮演小张的需要通过“我们刚才的提问三步骤”的提问技巧，来引导对方进行思考。三个步骤可以交替使用，\u003c/p>\u003cp>然后最终的对话不一定要有结论，没有必要非得讨论出到底要不要换工作这么个结果，\u003c/p>\u003cp>我们的目标是去引导小刘自己去思考问题，对于她来说什么是重要的就可以。\u003c/p>\u003cp>3、好，现在先给大家1分钟左右把故事的对话大纲先构思一下并写在咱们的便签上，然后再给大家5分钟左右的时间进行角色扮演，然后我们再选出一个小组进行分享，时间是2分钟左右\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>小张（沈老师扮演）、小刘（素语扮演）\u003c/p>\u003cp>素语：哎，你说这怎么办呐？我这刚换的工作，我老公要叫我辞职，你说这到底要怎么啊？\u003c/p>\u003cp>沈老师：哦，那你自己是怎么想的呢？\u003c/p>\u003cp>素语：我吧，因为是刚换的工作，这份工作我自己还是挺满意的，我真不想辞职，但是因为这个工作刚开始吧，不太熟练，所以就是会老是加加班；我呢，现在是新婚，老公现在肯定是不愿意啊，所以啊，就是会有些家庭矛盾；但我自己还是不想换工作，所以就想自己平衡下工作关系和家庭关系，\u003cbr>\u003c/p>\u003cp>沈老师：那你觉得什么样的情况下，才算是“平衡”呢？\u003c/p>\u003cp>素语：就是我能处理好工作上的一些事务的同时我还能有足够的时间来照顾到家庭生活来陪伴我的爱人，\u003c/p>\u003cp>沈老师：那这个“足够的时间”是你自己限定的还是你老公来界定的呢？\u003c/p>\u003cp>素语：我老公希望我下午6点之前就下班，但我现在就是每天忙到七八点\u003c/p>\u003cp>沈老师：那就是说，你能否6点之前抓紧利用工作时间把工作完成呢？\u003c/p>\u003cp>素语：也对啊，我可能工作效率上要提高一下，只要是我刚开始的工作做的不太熟练，想着自己在接下来需要这上面多花点心思和时间提高我的工作效率来尽量满足6点下班我老公的提出的需求，\u003c/p>\u003cp>沈老师：对，毕竟是新工作嘛，你也肯定会有一个磨合期，一方面你可以不断的提高工作效率，另一方面你是否也可以跟你老公商量沟通协商下\u003c/p>\u003cp>素语：嗯嗯，是的\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>好，小伙伴们讲的都非常棒，拆为己用是咱们拆书帮学习的秘笈。所以这里要给大家布置个小作业：\u003c/p>\u003cp>为什么要这样做呢，主要是因为你虽然已经知道了如何通过提问去引导对方积极思考，也记住了其中的关键点，但由于这并不是你的习惯，你可能还是会出现以前的那种阐述性建议或者评价。\u003c/p>\u003cp>所以，事后复盘的方法可以帮助你更有效的把这个拆页拆为己用并学以致用，那么就请大家接下来的一个星期内，\u003c/p>\u003cp>当你遇到了家人因为换工作的选择苦恼来找你寻求帮助\u003c/p>\u003cp>或是好朋友遇到了和自己的另一半吵架而产生的苦恼来找你帮忙分析等等诸如此类的情况，又或者是其它的一些事情\u003c/p>\u003cp>那么请你刻意的留心自己在与朋友同事之间沟通时，是如何运用通过提问来引导对方积极思考的方法的，把你们的对话记录下来，就比如我们刚才沈老师和素语之间的沟通对话，然后再把自己的经验心得发到我们的群里分享就可以了\u003c/p>\u003cp>【学习者案例】&nbsp;\u003c/p>\u003cp>静静老师分享&nbsp;\u003cbr>\u003c/p>\u003cp>【时间】周一下班后\u003c/p>\u003cp>【地点】某处喜茶餐厅\u003c/p>\u003cp>【人物】静静和她表妹姗姗\u003c/p>\u003cp>【背景】静静是一位企业财务人员，今天正好下班早，意外的是只有周末才来到访的姗姗突然下班后约她聊聊，姗姗最近和男朋友吵架了，心情很郁闷，不知道该怎么办？\u003c/p>\u003cp>姗姗：静姐，你知道吗？张某某最近当着他朋友的面跟我大吵了一架，一点也没有让着我的意思，气死我啦，你说我应该怎么办啊？要不要和他分手呢?\u003c/p>\u003cp>静静：哦，是么，看把你给气的，那你自己现在是怎么想的啊？\u003c/p>\u003cp>姗姗：我觉得他特别不能理解我，都交往两年多的时间了；遇到点小事我任性一点怎么啦？你说，他一个大男人每个月赚那么一点钱我都没有嫌弃他，他倒好，居然还当着自己的朋友面冲我发火，一点情面也不讲，\u003c/p>\u003cp>静静：哦哦，他不能理解你，那你说说看，怎样才能算“理解”你呢？\u003c/p>\u003cp>姗姗：就是我偶尔任性而为的时候，让着我一点呗，其实我也知道自己有时候是不太讲道理，可是女生一般都是这样的啊，再有就是我不开心的时候，多哄着我点，我就觉得挺好的了；再说啦，今天他当着别人的面冲着我凶，我就是气不过，虽然我也能明白他是在朋友面前要面子，但是也得考虑下我的感受不是？\u003c/p>\u003cp>静静：原来是这样啊，听你这么一说他确实今天做的有些欠妥，估计当时大家都在气头上，可是事情总要解决才行啊，对吧，那就让我们一起想想看，有没有什么好的办法让他能主动的理解你好吧，\u003c/p>\u003cp>姗姗：嗯嗯，好的，我想也是的，其实仔细考虑下，我自己也有不对的地方，那我以后就也稍微自省下呗，当然如果能够办法多理解我一点会更好，\u003c/p>\u003cp>静静：是啊，你这么想就对了，那你再跟我详细说说呗。\u003c/p>\u003cp>…………\u003c/p>\u003cp>经过了一个多小时的攀谈，静静帮助姗姗一起找到了不错的几点“高招”，姗姗觉得还不错，两人一起的这次交流沟通很愉快\u003c/p>\u003cp>【结语】\u003cbr>\u003c/p>\u003cp>非常感谢大家参加我今天3-2的分享，大家发现了吗？当身边人向你倾诉时，通过这些基础的提问，你可以不妄加判断，而是真正的聆听对方的真实想法，提问、倾听，这样一来一回，加深了你们相互的深层次沟通和理解，甚至有可能她自己的问题迎刃而解，提问的魅力就在于此。\u003c/p>\u003cp>最后送大家一句话：提出正确的问题，往往等于解决了问题的大半。——海森堡，\u003c/p>\u003cp>由衷希望大家，包括我自己，都可以成为一个善于提问的人。&nbsp; &nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1518521811000,"updated_at":1518522535000,"ria":true},{"id":4606,"topic":"如何利用一个好问题治疗一个坏情绪","learn_goal":"如何利用一个好问题治疗一个坏情绪","remark":"","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"丹丁先生","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家好，我是丁丹，方便记住也可以叫我丹丁先生，今天很高兴给大家进行TF2-1的拆书分享。\r\n分组：为了让大家能够进行充分的沟通和智慧连接，根据现场情况我们两两分组。\r\n在跟随我完成今天的RIA现场学习后，学习者能够学会在对话中遇到批评指责时使用提问将沟通带回到解决问题的轨道上。\r\n今天我拆析的书名是《提问的艺术》，\r\nF:本书的作者是安德鲁.索贝尔，著名商业战略家，客户关系领域的超级顾问，经常为《哈佛商业评论》《纽约时报》以及《今日美国》等知名媒体撰稿。\r\nA：这本书雄踞亚马逊商业类图书排行榜TOP100，风靡全美，影响了无数人。《一分钟经理人》作者肯布兰佳和美国前总统克林顿新闻发言人迈克科瑞也鼎力推荐。\r\nB1：书中归纳总结了320个实用的精彩问题，通过阅读本书，能帮助我们深刻理解各场景中的提问艺术，并在工作、生活、交往中获得运用。\r\nB2：今天我分享的片段就是借助作者多年的顾问经验，来掌握如何在对话中化解批评抱怨的提问技巧。","ratings_count":1,"texts":[{"id":7645,"quote":"\u003cp>接下来就请大家用2分钟的时间，阅读我用荧光笔标注上下箭头的拆页部分，请完成的伙伴举手向我示意。\u003c/p>\u003cp>拆页原文：\u003c/p>\u003cp>不要去消除批评，而要去解决问题。\u003c/p>\u003cp>\u003cstrong>什么时候问最合适\u003c/strong>\u003c/p>\u003cp>l&nbsp; 当别人抱怨工作时。\u003c/p>\u003cp>l&nbsp; 当某人遭到别人的挑剔和批评时。\u003c/p>\u003cp>\u003cstrong>你还可以这样问\u003c/strong>\u003c/p>\u003cp>l&nbsp; 如果你能让别人做出一件完全不同的事——采取能对行为产生巨大影响的行动的话，你希望那将是什么？\u003c/p>\u003cp>l&nbsp; 你希望他们做出什么样的改变？\u003c/p>\u003cp>\u003cstrong>接下来这样问\u003c/strong>\u003c/p>\u003cp>l&nbsp; 你为什么认为他们没有在做那些事？\u003c/p>\u003cp>他们之所以做错是因为他们缺乏常识和技能，还是因为他们的企业要求他们那么做，或是因为他们根本没有能力做到？\u003c/p>","explains":"\u003cp>好时间到，如果还有伙伴没有读完也不要紧，我将在下面的分享中继续为你进行讲解。\u003c/p>\u003cp>在工作或生活中，我们与同事或亲人的对话时往往会遇到这种情况，双方本来为了一个问题进行讨论，但对方不断进行批评抱怨，甚至说话内容已经离开了问题的讨论范围。此刻我们必须通过提问把对话拉回到解决问题的轨道上来。\u003c/p>\u003cp>\u003cstrong>不这么做的坏处：\u003c/strong>其实对方是希望通过批评来让他人行为作出改变，但如果我们没有及时作出正确的反馈，那么问题的讨论将被抱怨所引领，紧接着很有可能使得对方闭口不言甚至激怒。最终结果是问题没有解决，情绪矛盾加大。\u003c/p>\u003cp>\u003cstrong>举个例子（反例）：\u003c/strong>记得我刚晋升公司总监的那年年底，部门人员流动量加大，公司财务副总就对我抱怨，希望我注意团队融合，不要搞小团体主义排除异己。我听到这个指责十分恼火，直接跟他理论关于搞小团体的问题。结果大家的情绪都搞得非常激动，整个对话没有任何关于人员流动量大的讨论。\u003c/p>\u003cp>\u003cstrong>应该如何做（HOW）：\u003c/strong>\u003c/p>\u003cp>由此可见在遇到批评时：\u003c/p>\u003cp>第一、要控制好自己的情绪、不要急于消除批评，认真聆听对方批评的问题。\u003c/p>\u003cp>第二、针对批评的内容，在恰当的时机提出问题，比如“你希望在这个问题上对方做哪些努力？”这是一个很好的启发式问题。我当时可以这么问“请问你希望我在部门人员流动的问题上再做哪些努力？”\u003c/p>\u003cp>第三、针对对方的回答继续进一步追问，探究批评的事实依据，统一双方的信息，将对话拉回到解决问题的轨道。“你是通过什么事实/依据来判定对方的行为和你希望相左？”\u003c/p>\u003cp>当你听到抱怨时，无论是针对你还是任何其他人，现在就立刻通过聆听批评的问题，提问行为如何改变，探求批评的事实依据这三个步骤，我相信对方一定会停止抱怨，思考你的提问，而更专注于问题的解决了，这样对话的效果会明显提升。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验（显像提问）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>接来下，请大家回顾一下你经历的一次同事或朋友批评抱怨的对话，他生气地大声指责，手掌狠狠地拍打着桌子，愤怒的唾沫几乎喷到你的脸颊。你当时如何做呢？请把这样的经历写在便签纸上，1分钟时间，写好的伙伴请举手示意。现在开始！\u003c/p>\u003cp>好，我们先在小组内进行分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者：培训项目安排跟老总沟通，受到老总的批评和抱怨，老总抱怨我项目课程安排没有模版，上课时间经常调整。我很生气。\u003c/p>\u003cp>学习者：客户来到公司咨询，我感觉客户的购买意愿不强，于是没有按照客户介绍的流程，领导在一旁听到了这个过程给予了批评。我当时心里很不舒服，也没有辩驳。\u003c/p>\u003cp>好，感谢这位伙伴的分享。\u003c/p>\u003cp>【A1+】反思加工\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>通过今天的拆页学习，如果上天再给你一次机会，你是如何来处理那次对话呢？请在便签纸上写出你的做法。1分钟时间，现在开始！（复述下三个步骤）\u003c/p>\u003cp>好，大部分伙伴已经完成了。那就先在小组内分享一下吧。\u003c/p>\u003cp>3分钟后，我们再请一个伙伴向大家分享一下他改进后的做法。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者：第一步先认真聆听老总的批评，第二步提出问题“哪些方面让老总感到不爽？什么地方获得了误解？制作模版的主要目的是为了什么？”第三步了解下一步工作的目标和改进方向。\u003c/p>\u003cp>好，感谢这位伙伴。\u003c/p>\u003cp>好，以上就是我的TF2-1的分享。感谢伙伴们的参与，我将珍惜每次与各位产生的智慧链接，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1517399304000,"updated_at":1517399362000,"ria":true},{"id":4337,"topic":"用提问的方式引导他人参与思考","learn_goal":"用提问的方式引导他人参与思考","remark":" 苏格拉底是一位杰出的、善于提出具有影响力问题的大师。他教授学生时，并没有采取演讲的方式，而是传授给学生一系列发人深省的问题。通过这些问题，他鼓励学生在学习中提升自己的思维。他总能揭示出这些问题的本质。尽管总是慢慢地一点点渗透，但却总能直达事务的核心。\r\n\r\n   本期，我们将学习用提问的方式引导他人参与思考，激发团队的群体智慧。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"李明轩","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"大家好，我是我爱流。通信行业码农，工作三年，今天想跟大家聊聊职场中如何带人。\r\n大家一定有过带人的经历，比如工作了两年，上级让你带个新员工；或者在拆书帮混了一年变成了老腊肉，新来一个小鲜肉，请你带他上车，打怪升级。本来是一件增加团队战斗力的好事，但是你发现有时候你给了明确指示，这些新手仍然get不到你想要的点。这时候你该怎么办呢？\r\n答案就在这本书中【举起】， \r\n《提问的艺术》，作者 安德鲁和杰罗德。\r\n这本书从商业、人际交往、人生等三个方面提出320个问题，展示了如何提问的魅力。\r\n它风靡全美，影响无数人，被称为神奇的提问书。\r\n它，能够帮助我们在发展深入关系的同时获得解决问题的力量。\r\n今天我们要从这本书中学习，当你处于领导地位时，如何通过提问的方式引导他人达到你期望的结果。","ratings_count":1,"texts":[{"id":7335,"quote":"\u003cp>给大家\u003cstrong>2\u003c/strong>\u003cstrong>分钟\u003c/strong>时间\u003cstrong>阅读\u003c/strong>手中的\u003cstrong>拆页\u003c/strong>片段，看完请抬头示意我。\u003c/p>\u003cp>好，我看大部分小伙伴已经看完了。\u003cstrong>对吗\u003c/strong>\u003cstrong>~眼神示意\u003c/strong>\u003c/p>","explains":"\u003cp>这个片段所讲述的方法，\u003cstrong>适用于 \u003c/strong>我们与他人协同完成一项任务，\u003cstrong>尤其是你处于领导\u003c/strong>或主导地位时，更加适用。\u003c/p>\u003cp>\u003cstrong>片段中的步骤偏概念性，我将其，细化为三步，\u003c/strong>大家请看拆页第二面\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：要有提问意识。（停顿）\u003c/strong>因为提问比陈述，更容易使对方，由\u003cstrong>被动接受\u003c/strong>转变为\u003cstrong>主动思考\u003c/strong>，我们只要问出第一个问题就算成功一半了。\u003c/p>\u003cp>\u003cstrong>第二步：用疑问句，从概念或动机、与目标差距，及解决方法上开始提问。\u003c/strong>\u003c/p>\u003cp>（\u003cstrong>停顿）\u003c/strong>提问时一定要使用疑问句，不能是反问句，反问句有点像命令和责备，反而会激起对方抵抗情绪。从概念到解决方法这四点是推进任务的必经之路，根据你实际情况选取一点提问。\u003c/p>\u003cp>\u003cstrong>第三步：反复提问，将对方思考引向你期望的结果。（停顿）\u003c/strong>从开始提问到解决问题有一个过程，我们可以从上一步列举的四个方面\u003cstrong>逐渐深入\u003c/strong>地提问，不断的让对方，引发思考，只有他自己才能准确权衡，他所处的环境和条件。\u003c/p>\u003cp>\u003cstrong>举个例子\u003c/strong>，我在公司带一个应届生，他遇到问题会主动找我寻求帮助。最初，他提出问题后，我都会思考一番将我的解决办法告诉他\u003cstrong>（注意，我没有提问，违反了第一步）\u003c/strong>，他就按照我的想法去做\u003cstrong>，\u003c/strong>我觉得如此几次他会有所提高。但是，这种情况没有改善，我似乎变成了问题的解决者，而他成了执行者。\u003c/p>\u003cp>\u003cstrong>后来\u003c/strong>，他再找我请教问题，我听完他的描述就问他\u003cstrong>（注意，我使用第一步，开始提问）\u003c/strong>我问他\u003cstrong>，\u003c/strong>“你提出这个问题之前肯定已经有你的思考，能先说一下你的想法是什么吗？”\u003cstrong>（注意，这里使用了第二步，用疑问句从解决方法开始提问）\u003c/strong>他思考了一番，说出了我没想到的解决方法，达到的效果是相同的，我只帮他修正了几个细节。\u003cstrong>（注意，这其中我按照第二步的几个方面反复提问，\u003c/strong>直到引导他达到我期望的结果\u003cstrong>）\u003c/strong>。\u003c/p>\u003cp>大家可以看到，我运用这三步提问法，让同伴从被动执行转变为主动思考，最终解决问题\u003cstrong>(05:00)\u003c/strong>\u003c/p>","interaction":"\u003cp>好，结合我刚才的分享，大家是不是对这三步比较清楚了呢？\u003c/p>\u003cp>分步催化（1）&nbsp; \u003cstrong>（05:00）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现在请你们每个人想一个\u003c/strong>，你处于主导地位与他人协作完成一项任务，的经历，最好是对方没有达到你期望结果。\u003c/p>\u003cp>比如在工作中，你和另一名同事一起做一个项目，你和同事说了要这样做，但是同事做出的结果和你预期的相去甚远。\u003c/p>\u003cp>或者在社团中，你和一群小伙伴要做一个活动，但是大家都不太积极。\u003c/p>\u003cp>大家用1分钟时间回忆一下，将\u003cstrong>关键词\u003c/strong>写在 \u003cstrong>A1:过往经验 \u003c/strong>下面空白处&nbsp; \u003cstrong>(06:30)\u003c/strong>\u003c/p>\u003cp>分步催化（2）&nbsp; \u003cstrong>（06:30）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>好的，看到大家已经有写出来的了\u003c/strong>。没想出来没关系，后面还有时间。\u003c/p>\u003cp>那么假设给你一次机会再回到当时那个场景，结合今天所学的知识，你\u003cstrong>怎么做会更好\u003c/strong>？\u003c/p>\u003cp>大家用3分钟时间，在刚才分好的小组内交流一下\u003cstrong> &nbsp;(10:00)\u003c/strong>\u003c/p>\u003cp>我们请一位小伙伴分享一下他的经历。&nbsp; \u003cstrong>(10:00)\u003c/strong>\u003c/p>\u003cp>(如果跑偏，我帮他总结一下，回归主题方法。)\u003c/p>\u003cp>他的故事中应用了/没有应用 xx步骤，达到了/没有达到预期结果。\u003c/p>\u003cp>\u003cstrong>(11:00)\u003c/strong>\u003c/p>\u003cp>------\u003cbr>\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>肺水鱼 人力资源\u003c/p>\u003cp>最近人员离职高发，人员离职时，他希望离职者能写下自己的工作操作规范流程，万一交接不清楚时，继任者可以通过自己看操作规范完成相应的工作。\u003c/p>\u003cp>但是人员离职时，心不在这了，敷衍了事。\u003c/p>\u003cp>肺水鱼反思，当时沟通不到位，应该问他“你对标准规范是什么概念？” 也没有多次沟通，了解对方有没有什么疑问点。\u003c/p>\u003cp>拆书家点评\u003c/p>\u003cp>肺水鱼举了一个自己主导的，员工离职时写工作操作流程规范的经历。\u003c/p>\u003cp>这是一个反面案例，他用声明的方式交代离职员工写操作规范。但是离职者心不在焉没达到他的预期。\u003c/p>\u003cp>肺水鱼在反思中运用了第二步，用疑问句从概念上对离职员工提问，以确认对方清楚地理解他这么做的目的。\u003c/p>\u003cp>接着又运用了第三步，反复提问，解决离职员工在完成这件事过程中可能出现的疑问。\u003c/p>\u003cp>相信他在未来如果再次遇到这种情况，一定能使用今天的方法，引导出他期望的结果。\u003c/p>\u003cp>------\u003c/p>\u003cp>A2\u003c/p>\u003cp>最后一个环节，大家用一分钟时间，在拆页背面的绿色标签，写下你在未来一周可以预见的，你将要处于\u003cstrong>主导地位\u003c/strong>与他人协作一项任务，将如何运用今天的方法，提前应对可能发生的情况。 &nbsp;注意这是\u003cstrong>未来\u003c/strong>即将发生的\u003c/p>\u003cp>要有\u003cstrong>具体的事件\u003c/strong>，可能发生的\u003cstrong>未达到预期的情形\u003c/strong>，以及你要\u003cstrong>如何提问\u003c/strong>，和你\u003cstrong>期望结果\u003c/strong>。\u003c/p>\u003cp>不能只是表决心哦。 \u003cstrong>(12:00) 根据现场情况 延时至（13:00）\u003c/strong>\u003c/p>\u003cp>------\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>陈佳 \u003c/p>\u003cp>近期将有某市政业务招投标，我打算和同事一起开会商讨。\u003c/p>\u003cp>在会上我先不发表自己的意见，而是向同事们提出几个问题：\u003c/p>\u003cp>1.&nbsp; 某市的采购流程是怎样的？\u003c/p>\u003cp>2.&nbsp; 人员如何分工？\u003c/p>\u003cp>3.&nbsp; 信息如何有效传递？\u003c/p>\u003cp>拆书家点评\u003c/p>\u003cp>陈佳在团队中起主导作用，她通过第一步提问的意识，来改变之前发表意见的做法。\u003c/p>\u003cp>然后她按照第二步的建议，使用疑问句从她的项目中各方面开始进行提问。\u003c/p>\u003cp>我们可以预见，这些问题将调动团队其他人的思考，将大家的意识引导到统一战线。\u003c/p>\u003cp>她提出了不止一个问题，来引导大家达到最终目的，确定完整的投标准备工作。\u003c/p>\u003cp>------\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1514589190000,"updated_at":1514589190000,"ria":true},{"id":4191,"topic":"不要滔滔不绝，忘了对方的感受","learn_goal":"学习者能够在别人问了一个总体性的问题后，向对方清楚地了解他们","remark":"你是否曾经在面试中，因为面试官问了“介绍下自己吧”，一时不知道从哪儿说起便把自己的经历从头到尾讲了一遍？结果面试官貌似也没有很大兴趣的样子你是否在工作中遇到一些供应商，一上门就滔滔不绝跟你介绍了二十分钟自己的公司和产品，然而却不是你关心的？你有没有见过一些人就一个错误的问题一口气回答了五分钟，然而回答的却并不是对方真正想要的问题？本周跟随倩倩老师带拆的这个片段，学习如何既考虑到对方的感受，又把对方想了解的情况弄清楚的提问方法。","level":"TF2-3","duration":20,"status":0,"type":0,"chaishujia":{"username":"倩倩老师","city":""},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"学习目标：\r\n在跟随我完成本次RIA现场学习后，学习者能够在别人问了一个总体性的问题后，向对方清楚地了解他们具体想知道什么，以避免答非所问，或者滔滔不绝回答后却不是对方想了解的。\r\n图书介绍（3 mins）\r\n拆书家：大家好，我是倩倩老师，今天我带拆的片段选自这本《提问的艺术》。 \r\nF：《提问的艺术》如它的书名，强调的是巧妙的提问远比给出答案更为重要。是一本教你如何通过富有技巧性的提问来提高沟通效率并提升自身影响力的书，\r\n被誉为“风靡全美、影响无数人的神奇提问书”。作者安德鲁·索贝尔是著名商业战略家，客户关系领域的超级顾问，曾成功帮助众多企业和个人与客户建立起终身关系。 \r\nA：本书分为“商业篇”、“人际交往”、“人生篇”三个篇章，以讲故事的方\r\n式，通过大量的真实的例子向我们传授如何在各种情境下精准判断出需要提出的\r\n问题，从而推动事情的深入发展。看起来通俗易懂，每一篇的后面又针对不同的\r\n话题额外罗列出了一些具有影响力的问题，以便帮助你在不同的场景中轻松自如\r\n地应用它们。全书总共加起来有320个问题。 \r\nB：学会并运用好提问的技巧，能够让你在工作和生活中的效率得到显著提升。","ratings_count":0,"texts":[{"id":7172,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（引导）\u003c/strong>大家可以想一下你在生活中可能常常遇到这样的情况：当你拜访客户时，是否遇到客户一上来就问“你能给我介绍一下你们公司的大概情况吗？”，\u003c/p>\u003cp>当你在面试时是否遇到过面试官一上来就说“你能在一分钟内简单介绍一下你自己吗？”。每当遇到这样的问题，是否总是不知道该从哪儿说起，特别是在时间不是那么充分的情况下。今天我们就来看一下片段教我们如何来处理，大家可以用两分钟的时间来阅读下片段，读完请大家举手示意&nbsp;\u003c/p>\u003cp>\u003cstrong>R \u003c/strong>\u003cstrong>阅读原文片段\u003c/strong>\u003c/p>\u003cp>巧的是，一年后的今天，我和我的高级合伙人德威特先生出席了一次似曾相识的销售会议。他是经历过数百场会议的资深人士，可以说是一位智者。我们的客户也提出了相同的问题：“你们何不先介绍一下你们的公司来开始我们今天的会议呢？”德威特若有所思地停顿了片刻，然后抬起头问客户：“那您具体需要了解些什么呢？”对方陷入了沉默中。\u003c/p>\u003cp>通常，问了一个问题后，如果对方沉默，我们就会换个说法再问一遍这个问题。我们是不会允许会议陷入沉默的，但德威特是一个例外，他习惯于保持沉默。很久以前他曾告诉过我：“一旦说完你想要说的，或问完问题，就闭嘴吧！”\u003c/p>\u003cp>过了一会儿，客户具体地说道：“好吧，我们当然已经很了解你们是做什么的了。我们只是特别想知道你们在亚洲的运营能力如何以及你们内部是如何一起工作的。”这无疑将会议带入了一个互动的交流氛围中了。\u003c/p>\u003cp>“我很好奇，你能具体描述一下你想了解的‘内部一起工作’的意思吗？是什么促使你提出了这个问题？”接下来，他又问了一些引人深思的问题，并与客户一起分享了最近遇到的一些案例，大多都是我们如何帮助老客户的有趣故事。\u003c/p>\u003cp>通过德威特的提问，我们了解到这家公司与其他咨询公司曾经有过不愉快的合作经历。这家公司曾在广告中号称自己是一家全球性的公司，然而公司内部的各个部门却从来没有齐心协力地一起合作过。我们还了解到了这家公司的亚洲扩展计划，也弄清了他们寻找外援的真正原因。\u003c/p>\u003cp>德威特还做了一些让我至今难忘的事。他当着客户的面夸赞我。为什么他不夸夸自己呢？他没有在客户面前炫耀自己从业25年的丰富经验，也没有吹嘘他那杰出的专业知识，而只是跟客户说他为自己的团队有我这样的合作伙伴而感到幸运，还说我是他们前途无量的年轻合伙人之一，也是他们当中工作最努力的一个。这次讨论与众不同，绝对比上一次我和电信公司的会谈精彩得多，这才是建立新关系的一次良好的开始。\u003c/p>\u003cp>一周之后，那家公司再次打电话给德威特，邀请我们去做进一步的探讨，之后又制定了方案。德威特一直和他们合作到八年之后他退休的那一天。如今，他们成了我的终身客户。自从那次会议之后，我非常乐意跟随德威特并向他学习。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书家：（\u003c/strong>WHAT\u003cstrong>）\u003c/strong>这个片段讲了一个故事：作者和自己的合伙人参加的一次销售会议，通过几个回合的顺利沟通，最终拿到合作项目的经历。整个故事呈现了他们的沟通过程，比如我们可以看到，一开始客户提出了一个总体性的问题：“你们何不先介绍一下你们的公司来开始我们今天的会议么？”这是一个很常见的甲方见乙方会提出的第一个问题。那作者方是如何回答的呢？（参与者）：“您具体需要了解些什么呢？”对方在沉默一会儿后具体地提出了自己的问题：“想知道你们在亚洲的运营能力如何以及你们内部是如何一起工作的？”作者方基于对方的具体问题，又进一步向对方提问以明确他们指的“了解内部一起工作”的具体意思以及原因。通过这样一步步的提问，了解到了对方的具体情况也针对性地回答了对方的问题。 \u003c/p>\u003cp>总结来说，这个片段的案例教给了我们当别人向我们问了一个总体性的问题，我们应该怎么回答的思路。那再看具体的方法前，我们可以先来想一下，什么样的情况下，我们通常遇到类似提问：（WHEN）\u003c/p>\u003cp>1.&nbsp; 当你被问到一个总体性的问题，而这个问题有可能需要很长的回答时。比如昨天朋友看我在看书，突然问我：有什么提高看书效率的方法？ 他突然这么一问这么宽泛的问题，其实我是有点懵逼的，不知道怎么回答他。\u003c/p>\u003cp>2.&nbsp; 在当时对话的情况下，时间很短暂，你又想针对自己的目标做个很简短的回答时。比如电梯里遇到领导，他向你询问工作情况。\u003c/p>\u003cp>那上述的这些情况，我们需要去思考怎么样通过更好的提问去进行下一步的沟通。\u003c/p>\u003cp>\u003cstrong>（HOW细化行动步骤）:\u003c/strong>\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp; 判断问题回答的难易程度及当下的沟通情境。eg:比如你去找领导谈事情，但是领导又很忙，找他的人很多，你的会谈时间被压缩；或者是对方已经给定限定的沟通时间。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp; 之后，针对对方提出的总体性问题，问清楚对方具体想知道什么 \u003c/p>\u003cp>我们可以给出几个提问句式： \u003c/p>\u003cp>▪ 你想具体了解我哪方面的情况呢？ \u003c/p>\u003cp>▪ 你对我经历中的哪部分感兴趣？ \u003c/p>\u003cp>▪ 你希望我具体介绍哪方面的情况？ \u003c/p>\u003cp>▪ 在我回答你的问题之前，你是否已经对我们的公司有所了解了？ \u003c/p>\u003cp>▪ 如果我先介绍一些像你这样的客户的案例来开始我们今天的介绍，你觉得如何？ \u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; 再具体的沟通中，进一步通过提问想对方确认自己是否已清楚了解他所问具体内容指向 。\u003cstrong>（举例）\u003c/strong>因为我老板是外国人，所以我也和他一起参加很多员工招聘的面试，有时候他英语问了一个问题，其实对方并没有很听懂，但就开始balabala回答了一堆，这个时候我会忍不住想要告诉他，其实老板问的不是你回答的那方面的问题。所以最好有一个再次确认的环节。\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp; 最后询问对方是否还有进一步想了解的内容，比如可以用下面的句式： \u003c/p>\u003cp>▪ 这样能回答你的提问了吗？ \u003c/p>\u003cp>▪ 你还希望我们谈些什么？ \u003c/p>\u003cp>这个片段也同时给到我们一个提示，在你提问的时候，最好不要问大而泛的总体\u003c/p>\u003cp>性问题。Eg:在一些演讲和分享场合，到了现场观众自由提问环节，有的观众提\u003c/p>\u003cp>出的大而泛的问题，让演讲者很为难。所以提问也是思考水平的重要体现。\u003c/p>","interaction":"\u003cp>A3 情景演练（7 mins） \u003c/p>\u003cp>以下有两个场景，大家可以用今天片段里学习的提问方法进行演练。要求：两人\u003c/p>\u003cp>一组，一人先提出一个总体性的问题，继而另一人通过提问去了解具体想知道什\u003c/p>\u003cp>么，具体沟通环节可以参考我们how的步骤。 \u003c/p>\u003cp>场景一：你作为公司销售人员，到客户公司进行拜访，打算向客户介绍自己的公司及产品。你去拜访的这个公司的客户一上来就问了你一个总体性的问题：“你们的产品特色是什么？”以此句作为前面开头，大家继续往下沟通。\u003c/p>\u003cp>场景二：面试场景，一人为面试官，一人为应聘者，面试官一上来就问了面试者一个问题：“你可以简单介绍一下你自己吗？”\u003c/p>\u003cp>这两个场景你们任选一个，在小组内准备5分钟的沟通对话，之后我们请两个组来各自展示一下他们的表演。\u003c/p>\u003cp>学习者案例记录：（选择面试场景）\u003c/p>\u003cp>参与者1（面试官）：你可以介绍你自己吗？\u003c/p>\u003cp>参与者2（面试者）： 您是想了解我工作相关的自己介绍吗？\u003c/p>\u003cp>参与者1：我是想了解一下你上一份工作所做的内容对现在我们招聘的这个岗位有何帮助或最有直接关联的部分？\u003c/p>\u003cp>参与者2：那我了解了，我叫……，有四年的基金行业工作经验，，之前我跟一个同事操作过一个产品，收益率达到25%，市场反响也很好……\u003c/p>\u003cp>参与者1：那你觉得作为基金行业的从业者，你个人性格中有哪些特质很符合行业要求？\u003c/p>\u003cp>参与者2：基金从业者需要操盘，要求性格冷静，这点我觉得我很符合要求。其次是准确抓住市场行情，我有多方面了解信息的渠道，且有整合能力。第三点，我性格里有很好的一点，善于宣传产品的优势……。\u003c/p>\u003cp>参与者1：好的，明白了。您还有什么想要了解的吗？\u003c/p>\u003cp>参与者2：我想了解下公司对女性操盘手有什么看法？可能这是一个题外话题\u003c/p>\u003cp>参与者1：你可以从我们公司的架构、女性领导及女员工的比例看出，我们是非常欢迎女性员工的，且公司也在产假、各种福利上也给予了充分的照顾。不知道我这样的回答你是否满意\u003c/p>\u003cp>参与者2：很满意。\u003c/p>\u003cp>总结：感谢两组参与者的分享，我们可以看到在刚才她们的对方中，面试者用到了提问去清楚询问面试官具体想知道什么，也通过提问去确认自己是否理解面试官的问题，最后也继续询问了面试官是否与进一步想要了解的问题。\u003c/p>\u003cp>今天我们带拆的片段主要学习的是在别人问了一个总体性的问题后，我们向对方清楚地了解他们具体想知道什么，以避免答非所问，或者滔滔不绝回答后却不是对方想了解的。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1512566911000,"updated_at":1512566959000,"ria":true},{"id":3818,"topic":"学会提问哟","learn_goal":"坚持站在问题的核心处，帮助他人抓住问题重点","remark":"你身边是否有这样的人？滔滔不绝的说了半小时，却依然没有说到重点!ta说的累，你听的也累!然而，你也没办法打断ta，并且为此头疼。其实，这个问题是可以解决的！很简单，一句提问就能达到目的。想要此利器，请本周日来百新书局，和Enya一起学习《提问的艺术》吧！会让你恍然大悟的！","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"鸳鸯","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是喜乐分舵的拆书家Enya，我先做下自我介绍，3个标签：一、医美工作者，是我的本职工作、二、拆书家，是我的业余爱好，三、动漫迷，3个标签都是体现美的，我的工作是提升外在美的、拆书是提升内在美的、动漫代表二次元美，都是和美相关的。用FAB法介绍这本书。 F 特征：\r\n今天拆的这本《提问的艺术》，是2个美国人写的，安德鲁•索贝尔，杰罗德•帕纳斯，本书包含了320个强大问题，用具体的问题，真实的案例，为读者打造了一个提升提问技巧的实用宝典。\r\nA 优势：\r\n这本书风靡美国，影响了无数人，是沟通类书籍中的另类，大多数沟通书籍讲的是回答的艺术（比如：《非暴力沟通》），而本书讲的是提问的艺术，强调巧妙提问远比给出答案更重要，并通过生动的案例指导读者通过巧妙提问来提高沟通效率。\r\nB 利益：\r\n无论你是想快速勾搭一个妹子，还是想立马谈成一个大单，还是想得到老板的信任，保持良好人际关系，哪怕你只是想让会议不偏离主题，等等等等。。。。都可以通过学习本书，得到启发，找到解决的方法。\r\n我们今天学习的目标是：学会坚持站在问题核心处提问的技巧","ratings_count":0,"texts":[{"id":6745,"quote":"\u003cp>　　我打电话给阿兰，告诉他：“我有一个问题需要请教你。”“好吧，请讲。”在一阵寒暄之后，阿兰终于回到了正题上。“我有一位潜在客户，他是芝加哥一家大公司的高管。他们公司有一份大单子。他们正着手打造一个雄心勃勃的项目，以期为公司收入带来增长，并建立起更浓厚的利润型企业文化。”我继续向阿兰描述着这个客户的背景，“而且，他希望能为我们之间的电话会议准备一份时间表，甚至包括周末的时间！”\u003c/p>\u003cp>　　我觉得跟阿兰描述这一切很重要。不，岂止是重要，简直就是必须！如果他不能全面地了解详情，又怎么能够明白我担忧的问题是什么，又怎么能够给出最恰当的建议呢？于是我又继续说了好几分钟。\u003cbr>\u003c/p>\u003cp>　　“我能够打断一下吗？”阿兰问道。\u003cbr>\u003c/p>\u003cp>　　“当然可以。”我告诉他。\u003cbr>\u003c/p>\u003cp>　　“你的问题是什么？”我的整个思绪被打乱了。我还有好多详细的信息没有跟他说呢！\u003cbr>\u003c/p>\u003cp>　　“好吧，你知道这个家伙觉得自己就是这个项目的主人，而且……”于是我又开始喋喋不休地向他叙述事情的整个背景，以便他能够做出正确的选择。\u003cbr>\u003c/p>\u003cp>　　阿兰再次打断我说道：“你的问题是什么？ 5分钟前你就说你有一个问题要问我，那是什么问题？”\u003cbr>\u003c/p>\u003cp>我开始有些尴尬。“问题？哦，”我停了一下，想了想，继续说道，“是这样，我如何与一个控制欲极强、试图事事都凌驾于我的客户打交道？”\u003c/p>","explains":"\u003cp>这个片段讲述的是一个案例：\u003c/p>\u003cp>·“我”请教“阿兰”（滔滔不绝几分钟还没说到重点）\u003c/p>\u003cp>·“阿兰”打断“我”（你的问题是什么？）\u003c/p>\u003cp>·“我”继续描述细节（滔滔不绝又是5分钟）\u003c/p>\u003cp>·“阿兰”再打断“我”（你的问题是什么？）\u003c/p>\u003cp>·“我”思考后给出问题。\u003c/p>\u003cp>从“我”开始请教，到最终提出问题，经历了这样一个过程：请求——寒暄——描述细节（几分钟）——被打断——继续描述细节（5分钟）——2次被打断——提出具体问题。\u003c/p>\u003cp>从这个过程我们可以看出，提问者不能迅速抓住重点，倾听者在巧妙的时机打断对方，引导他找到问题的核心，引导的过程只用了一个技能，就是：在恰当的时机提出“你的问题是什么”。这句话非常简单，但是恰当的时机是什么时候呢？每个人可能不一样，但是我们通过上面过程的梳理，可以看出，2次描述细节的时间分别是，几分钟、5分钟，这个几分钟我们推断为10分钟以内，和后面描述的5分钟大致相同，那么我们在以后的应用中，就可以这样去做，当对方描述问题5分钟左右仍然没抓住重点的时候，反问他“你的问题是什么？”。这就是坚持站在问题的核心处去提问的技巧。\u003c/p>\u003cp>在这里还要注意下这个方法的适用边界，这个方法适合在他人向你提出问题或请教的时候，而不是闲聊或正常沟通的时候。\u003c/p>\u003cp>我们为什么要在遇到上述情况时这样打断对方呢？因为如果你不打断他，他可能会继续滔滔不绝1小时；你还会浪费很多时间和精力；你没有帮他解决问题，他可能还会怀疑你的能力；而且你会感觉很累，甚至很烦躁。\u003c/p>","interaction":"\u003cp>【A1】 &nbsp;\u003c/p>\u003cp>提问：你有没有遇到这样的人，他想征求你的意见，却上来就花费很多的时间去描述具体细节，这个时候你的感受是怎样的？你当时是不是没有及时打断他，你是怎么回复他的呢？请回想一下，3人一组，每人1分钟相互分享一下。\u003c/p>\u003cp>\u003cstrong>学习者记录：\u003c/strong>\u003c/p>\u003cp>学习者A：前阵子我有个闺蜜找我倾诉，当时我正在工作，她电话打过来，说她在工作中遇到一个难题，自己独立解决不了，她找A同事协助，A同事态度很差......巴拉巴拉说了十几分钟，一直在围绕A同事态度的恶劣，没有说出具体的问题，因为她情绪比较激动，我不好意思打断，但是自己工作又很忙，当时急的冒冷汗，就希望她快点把问题讲完，于是不停地催问她“然后呢...”，然后她仍然不在重点上，当电话讲到20分钟的时候，我迫不得已挂掉了电话，问题也并没有解决。\u003c/p>\u003cp>【A1+】 \u003c/p>\u003cp>提问：如果你再次遇到一个讲了10分钟依然没讲到主题的提问者，根据我们今天学到的方法，结合你自己的经验，你会怎么做呢？3人一组，每人1分钟相互分享一下。\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者记录：\u003c/strong>\u003c/p>\u003cp>学习者A：如果我闺蜜再打电话想我求助，如果她滔滔不绝很久还没说到重点，我会在她描述细节5分钟之后打断她，问她“你的问题是什么？”不会顺着她的话题走。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1507550149000,"updated_at":1507902121000,"ria":true},{"id":3692,"topic":" 如何做出更好的选择？","learn_goal":"学会做选择的思路和方法","remark":"高中时，要选择文科还是理科；\r\n大学毕业，要选择考研还是就业；\r\n找工作时，拿到两份都还不错的offer，\r\n你会如何选择？","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"程婷婷","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"各位朋友，大家晚上好。我叫程婷婷，我的英文名字叫Anny，大家叫我婷婷或安妮都可以。【学习目标】在跟随我完成本次RIA现场学习后，你将学会用加减法，帮助对方做出选择。\r\nF特征：这本《提问的艺术》的作者是美国的安德鲁·索贝尔，讲述了如何通过富有技巧性的提问来提高沟通效率并提升自身影响力。\r\nA优势：被誉为“风靡全美、影响无数人的神奇提问书”，名列亚马逊商业类图书前100名，非常畅销，很多知名咨询公司的CEO和银行主席都推荐这本书，书中用真实的故事和大师们的睿智问题为读者展现了提问艺术的魅力。\r\nB利益：开会讨论时天马行空没有重点，如何提出一个可以让会议迅速回归正题的问题；面对怒气冲天的客户或老板，如何提出一个可以平息对方的怒火的问题；和陌生人见面时，如何提出一个能表现出你在乎对方并迅速打开话题的问题。提问的境界不同，得到的答案往往天差地别，好的提问能够直达问题的核心，释放强大的力量。若你想用提问来提升沟通效率，这本书会给你很大的启发。","ratings_count":0,"texts":[{"id":6604,"quote":"\u003cp>\u003cstrong>用加减法，帮助对方做出选择\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>“请尽可能给我打个电话，我需要和你谈一谈。”我正在自己供职的教堂负责11点服务的热线工作，教堂的神父汤姆·塞维尔拉着我的胳膊悄悄对我说，他很着急见我。我是这所教堂的董事会主席，汤姆和我关系非常好。我周一的第一件事就是打电话给他。我正在想最坏的结果。第二天，我坐在了汤姆摆满图书的办公室里。我能看出他正经受着痛苦的煎熬，我从未见过他如此平静。 \u003c/p>\u003cp>“我得到了一个新职位，”汤姆说，“你还记得四周前的礼拜日我没来吗？我去纽约的一个教堂做传道者了。他们正在考察我。那是纽约最大、最有声望的教堂。他们已经通知我去他们那里做高级神父了。那可是教堂中最重要的神职人员了。”\u003c/p>\u003cp>“我为你感到骄傲，”我回应道，“但这一点儿都不意外，在你和我们一起工作的这段时间内，我们的教堂规模已经扩大到了三倍，我们的教友都十分地敬重你。最值得骄傲的是你将传道的价值发挥到了极致。请告诉我你的决定是什么？”&nbsp;\u003c/p>\u003cp>“我还没有做出决定。南希不太愿意搬家，但她支持我。&nbsp;孩子们一点儿都不喜欢纽约，他们在这里有自己的好朋友。他们会联合起来抵制搬家。我该怎么办呢？” \u003c/p>\u003cp>我停顿下来，并立刻陷入对汤姆所面临闲境的沉思中。当选择关乎个人的时候，做出选择需要你有足够的勇气，最好的办法就是去挖掘和发现自己内心深处真正最想做的是什么。&nbsp;\u003c/p>\u003cp>我决定采用加减法帮助汤姆做决定。\u003cstrong>加减法就是在表格中央划一条竖线，一边是有利的一面，一边则标出弊端。\u003c/strong>&nbsp;\u003c/p>\u003cp>于是我开始问汤姆。在有利的一边，有很多好处，如薪水更高、牧师的住宅更大以及信徒人数是我们教堂的四倍，有全职的商务经理以及多达七名的神职人员。而在弊端的一进，所列的弊端显然更多。例如，从刚一开始南希就更愿意留下来， 两个大一点的孩子正在上高中——泰德是校篮球队的， 而法兰是班长。汤姆自己也不太喜欢纽约。单子上罗列的弊端还在增加。他将会把所有的时间和精力都花在传道上，他还会失去自己与教友们已经建立起来的关系和私入联系。他将成为那个教堂的形象代言人，而不是教堂的灵魂与精神人物。最重要的是，汤姆非常担忧离开会给刚发起的资本运作带来负面影响。\u003c/p>\u003cp>最后，我平静地问他：“汤姆，根据你所讲的一切，你觉得什么才是正确的决定？”汤姆从椅子上跳了起来，给了我一个大大的拥抱，说道：“你已经给了我答案。”实际上，我并没有给他答案，是他自己找到了解决方法。&nbsp;\u003c/p>\u003cp>P180-182\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;（原文片段完）\u003c/p>","explains":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>拆书家讲解引导\u003c/strong>\u003cstrong>&nbsp;细化行动步骤\u003c/strong>（3-4分钟）\u003c/p>\u003cp>拆页信息讲了用加减法，帮助对方做出选择，这里面包含了行动建议，我将行动步骤细化为：\u003c/p>\u003cp>1.在表格中央划一条竖线，一边是有利的一面，一边是弊端\u003c/p>\u003cp>2.询问这个选择对你有什么有利之处；有什么弊端，并写下利弊。\u003c/p>\u003cp>3.问对方，根据你所说的及所写的，你觉得什么才是正确的决定？\u003c/p>\u003cp>当面临选择时，选择A或者B，各有利弊，当局者一时拿不定主意，可能不知道自己内心深处真正的需要，你的作用是去帮助对方深入他们自己的内心，去识别他内心的决定。最重要的一点，你不能帮助他做决定，而是询问对方，你觉得什么才是正确的选择？让对方自己找到答案。\u003c/p>\u003cp>比如这周二的时候，我的一个好朋友打电话问我，她到底是离职做自由职业者还是继续做现在的工作？她说自己思考了2个星期，到底要不要给我打电话聊聊这个事，看得出这件问题困扰了她很久。她目前和我一样，也在从事翻译工作，但是工作有点特殊，带有保密性质。我决定用加减法来帮助她理清思路，我让她拿出一张纸，在表格中央划一条竖线，左边写下离职做自由职业者带给她的有利之处，右边写下带给她的弊端。我问她，“你觉得你离职做自由职业者的有利之处是什么？”\u003c/p>\u003cp>“一是不用加班，可以安排时间，做自己喜欢做的事，\u003c/p>\u003cp>&nbsp;&nbsp;二是不用做重复枯燥的翻译工作\u003c/p>\u003cp>三是为我做自由职业者做准备\u003c/p>\u003cp>四是，不受原有工作限制出国的规定”\u003c/p>\u003cp>“那你离职做自由职业者的有什么弊端呢？”\u003c/p>\u003cp>“一是，对胜任新工作的能力的不确定因素较大\u003c/p>\u003cp>&nbsp;二是，收入不稳定”\u003c/p>\u003cp>最后我问她，根据你讲的和写下的利弊？你觉得什么是正确的决定？\u003c/p>\u003cp>她停顿了半分钟，她在思考。\u003c/p>\u003cp>“我知道了，我想我知道我的决定了。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我用加减法，帮助她做出了选择。\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>场景设计\u003c/strong>\u003cstrong>】\u003c/strong>（1分钟）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计\u003c/strong>：看完这个片段，我们知道了用加减法，帮助对方做出选择。现在我们一起做一个演练。请大家认真听一下要演练的场景：小明是西安人，在北京读大学，目前毕业2年了，女朋友是北京人，小明现在在西安的一家规模较大的网络公司的程序员，工资1万，他又找到一份是在北京的今日头条的程序员的工作，工资3万。父母希望他留在西安，小明一时不知道怎么选择，他现在来求助你，帮助他做选择，要不要去北京的大公司？\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>小组讨论及角色扮演\u003c/strong>\u003cstrong>】\u003c/strong>（9分钟）\u003c/p>\u003cp>现在，请按照刚刚的分组，进行演练，一人扮演小明，一人扮演小明的好朋友，用加减法来帮助小明做出选择。大家还记得加减法的具体行动步骤吗？1.在表格中央划一条竖线，一边是有利的一面，一边是弊端2.询问这个选择对你有什么好处，有什么弊端，可以写下来 3.问对方，根据你所说的/所写的，你觉得什么才是正确的决定？\u003c/p>\u003cp>演练时间是4分钟，现在开始。4分钟后，我们请一组小伙伴来演示一下，一个人扮演小明，一个人扮演小明的好朋友，来给我们展现一下。 &nbsp;&nbsp;\u003c/p>\u003cp>4分钟时间到，我们请一组小伙伴来和我们现场演练一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1505728748000,"updated_at":1506394838000,"ria":true},{"id":3664,"topic":"如果通过简单的提问把主动权交给对方从而建立良好的沟通关系","learn_goal":"如果通过简单的提问把主动权交给对方从而建立良好的沟通关系","remark":"","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"豆小燃","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是豆小燃，我是一名新手拆书家，目前的职业是互联网运营，喜欢阅读，喜欢分享。【分组】请大家3人一组，等一下有组内讨论和小伙伴的分享，谢谢大家。\r\n【设置目标】今天我们一起学习的主题是：如何用提问的方式让沟通更有效。在跟随我本次现场RIA学习之后，大家能够学会如何在与别人沟通的时候，通过提出简单的问题，达到更多地让对方表达，并建立良好的关系的目的。","ratings_count":0,"texts":[{"id":6571,"quote":"\u003cp>《提问的艺术》第二章\u003c/p>\u003cp>当你让谈话都在围绕着自己时，别人也许会认为你很聪明，但这并不能在你们之间建立起信任，也就无从了解对方。同时，也失去了一次建立深厚友谊的机会。因此，若要推销自己，可以尽力表现自己的聪明。如果想建立良好的关系，那么就应该将表演的机会让给别人。想要赢得他人的心，就要多向他人提问，以表达你的兴趣和鼓励他人进行深度对话或多说一些话，是每个优秀提问者的任务。\u003c/p>\u003cp>你可以先这样问：“关于这件事，你能再多说一点吗？”接下来再这样问：“什么时候？发生了什么事？后来怎么样了？为什么呢？”弄清楚对方的情况和需求后，你才会知道该怎么去做，而对方也会从你的问题中体会到你对他的关心和重视。“你能多跟我讲讲吗？”是一个简单而有效的问题，不妨经常这样问别人，以开启更为流畅的交谈。\u003c/p>\u003cp>当对方回答时，你可以进一步问对方：“能跟我多讲讲吗？”这样会让你们之间的对话和交流更加畅通。不要小看这样一个简单的问话，它可以用在任何场合使用，将对方迅速带入到互动的对话中。“你能多跟我说说吗？”是一个随时都能用上的有效问题，甚至每天都可以用。\u003c/p>","explains":"\u003cp>【Feature特征】\u003c/p>\u003cp>今天我和大家分享的片段来自《提问的艺术》一书，它是一本教你如何通过富有技巧性的提问来提高沟通效率并提升自身影响力的书。作者是两位美国人，一位是《哈佛商业评论》特约撰稿人安德鲁·索贝尔，另一位是世界顶级的慈善事业咨询师杰罗德·帕纳斯。本书2014年出版，印刷了10次以上，是“拆书帮”推荐的读本。\u003c/p>\u003cp>【Advantage优势】\u003c/p>\u003cp>一位天天面对提问的人——美国前总统克林顿的新闻发言人迈克科瑞这样评价：“在白宫时，我曾学习过回答的艺术，但这本书让我明白，事情的关键在于要问正确的问题”。书中列出了以商业、人际交往及人生的320个最实用的问题，涉及生活的各个方面，通过场景化的举例，实用的方法，希望每个读者都能有所收获。\u003c/p>\u003cp>【Benefit利益】\u003c/p>\u003cp>为什么我们总是想表达自己，而很少去想对方想说什么？你有没有遇到过Po出一个问题，结果对方get不到你的点？提什么样的问题才让对方乐意敞开心扉，与我们深入交流呢？\u003c/p>\u003cp>一个好的问题远比问题的答案更有力量，学会好的提问技巧并用起来，能够让你在工作和生活中的效率得到显著提升。\u003c/p>\u003cp>今天和各位小伙伴分享的主题是，如何用提问打开对方的心扉，让沟通更有效，选自《提问的艺术》第二章。想要快速了解对方的想法，建立信任的关系，你可以尝试用一个个简单而有效的问题，让对方打开心扉。2分钟时间，请大家阅读今天的拆页。\u003c/p>\u003cp>\u003cem>(\u003c/em>\u003cem>拆书技能观察点5：FAB介绍法中能够清晰辨别出FAB）\u003c/em>\u003c/p>\u003cp>\u003cem>(\u003c/em>\u003cem>拆书技能观察点2：选择图书是实用类或者理论类图书）\u003c/em>\u003c/p>\u003cp>\u003cstrong>【I】包含预防异议&nbsp;\u003c/strong>\u003c/p>\u003cp>想要真心交朋友的话，可以让对方多表现一下他自己，试着用提问的方式，鼓励对方说出自己的观点，这样既表达了你的好感，又可以让聊天更加轻松愉快。\u003c/p>\u003cp>我们可以试着这样问：“咱们聊聊这个事吧？”，鼓励对方表达自己的想法，然后接着说“这个事哪天发生的？都发生了什么？后来怎么样了？”，让对方感受到你的真诚，并且愿意向你倾诉，后面再接着问“可以给我多说点吗？”，用提问建立彼此之间的信任关系。\u003c/p>\u003cp>【预防异议】可能有小伙伴会问，这么几句简单的问话，会有什么效果啊？如果对方不愿意和我说下去的话，怎么办呢？事实上，改变自己比改变对方容易的多，换一种提问方式，至少有百分之五十的可能性获得我们期待的结果，如果我们试着去思考，如何用一个好问题引起对方的兴趣，对方至少能够感受到我们的真诚，这就为建立信任，赢得对方的心创造了条件。\u003c/p>\u003cp>【举个栗子】\u003c/p>\u003cp>前几天和老公吵了一架，起因是他想给闺女报一个英语班，我觉得闺女太忙了不想再报班了。上班路上我正好看到这个片段，我决定尝试一下换种方式去和他聊聊。\u003c/p>\u003cp>回到家我问他——“这会儿咱俩都忙完了，聊聊粘粘报班的事情吧？”\u003c/p>\u003cp>他说：“现在粘宝学的舞蹈是锻炼身体的，可以再来点知识课，动静结合！”\u003c/p>\u003cp>我问他：“为什么要学那么多知识啊？咱俩说说呗？”\u003c/p>\u003cp>他说：“粘宝八岁了，这个年纪记忆力好，报个英语班可以多学点知识，也可以多认识点小伙伴呢。”\u003c/p>\u003cp>等他说完，我感到他已经放下了情绪，开始对我敞开心扉了。接下来我问他“原来你考虑的这么远啊，你再把想法说给我听听呢？”，渐渐地，我们都不再那么激动了，同时也意识到，我们的初衷都是一样的，都是为了孩子好，到底要不要报英语班，我们决定带着粘粘去感受一下，然后再做决定。\u003c/p>\u003cp>\u003cem>(\u003c/em>\u003cem>拆书技能观察点6：I的讲解中有举例说明）\u003c/em>\u003c/p>\u003cp>\u003cem>（拆书技能观察点7： I环节提到了学习者可能产生的异议，并给了预防性的讲解）\u003c/em>\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cstrong>【A2】催化应用（分步催化1）&nbsp;\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【提问设计】&lt;情景模式&gt;&nbsp;\u003c/strong>\u003c/p>\u003cp>以下哪种场景你会遇到？给客户推销产品时，你一直滔滔不绝说产品如何好，而对方说，“嗯，好，我知道了。”，没有给你什么反馈；儿子刚上一年级，你和同学家长第一次见面，想要建立良好的关系，该说点什么呢？你去相亲，第一次见面就比较满意，感觉还挺不错，为了进一步发展彼此的关系，你希望通过这次聊天，获得对方的好感； \u003c/p>\u003cp>想象一下未来一周可能遇到的情景有哪些？2分钟时间，请大家将类似的一个场景写在便签上，等下请一位小伙伴分享。\u003c/p>\u003cp>\u003cem>（拆书技能观察点8： A2分步催化中，提问中包括情境和场景，有学习者受启发联系到自己的具体应用场景）\u003c/em>\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>胡奇伟：之前我们推销课程的时候，的确会遇到这种聊不下去的情况，家长来校区试听课程，我直接问他，你了解过我们公司吗？家长说没有呢。这时候我说，我们鸿蒙教育成立十三年了，有各种类型的课程，绘画班，思维记忆班，学前班等，今天孩子来听的绘画课我看孩子挺感兴趣的……这时候家长就会一脸迷茫的看着我，最多说一句，嗯好的，好的。我们就聊不下去了。这是我最开始做课程介绍的时候出现的情况，家长也不吭气了，最多说一句，嗯，嗯。后来我觉得越来越尴尬。\u003c/p>\u003cp>噜啦啦：我觉得儿子上一年级，遇到学生的家长，也是想认识一下，刚开始见面，又不知道说什么好。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用（分步催化2）&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【设计提问】\u003c/strong>\u003c/p>\u003cp>那么接下来，面对刚才可能遇到的场景，你决定尝试一下用提问的方式将谈话的主动权交给对方，希望对方更多的表达，接下来你怎么做呢？\u003c/p>\u003cp>2分钟时间，请大家写到便签上，然后讨论一下，每个小伙伴都尽量表达一下自己的观点。等一下我们请几位小伙伴来进行分享。\u003c/p>\u003cp>\u003cem>（拆书技能观察点9：分步催化中指令清晰，有学习者根据指令，规划处了以后可以如何做的具体计划。）\u003c/em>\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>冉冉：我今天第一次来参加拆书帮线下活动，感觉氛围挺好，我想融入进来，是不是可以这样问问新人，你都喜欢看什么书呢？能给我们分享一下吗？你从哪里知道拆书帮的？找一些大家都会感兴趣的话题开始聊，这样大家也愿意表达自己的想法，不会很尴尬。\u003c/p>\u003cp>噜啦啦：每次拆书帮线下活动都会遇到新来的小伙伴，之前的流程是大家先来一轮自我介绍，然后我会介绍一下拆书帮，便签读书法是什么，郑州分舵发展到什么程度了，但是遇到中途来的小伙伴，会有一些疑问。那我应该这样问，你了解的拆书帮是什么样的？对我们我们线下活动有什么样的问题，什么样的期待？\u003c/p>\u003cp>胡奇伟：后来我再介绍我们的课程，我可以用一下今天学习的这个片段的内容，和家长聊天的时候，可以先问一些引起家长兴趣的话题，比如孩子今年几岁了，在哪里上学呢？有没有学过画画？从哪里知道我们的课程呢？接下来可以接着问，孩子来学画画是孩子主动要求的，还是您想要培养一下孩子的艺术细胞，开发一下孩子的思维能力，让家长主动打开话匣子，然后我可以再问问家长，您希望孩子在课程中学到哪方面的知识呢？这样会取得家长的信任，我也可以了解到家长对孩子教育这方面的观念，着重点是什么，这样来上课的话，我可以针对性地再给家长讲一些我们的课程设计理念，这样给他的感觉也比较好，我们的关系也会更融洽。\u003c/p>\u003cp>接下来我们总结一下：今天我们学习了如何用有效的提问，鼓励对方表达，赢得信任，最终建立良好的关系。一个好的提问是用主动积极的方式，去打动对方的心，看似简单的几句话，却充满了力量。想要沟通的更顺畅，更有效，就好好琢磨一下，自己该如何提问吧！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1505373951000,"updated_at":1505374841000,"ria":true},{"id":3331,"topic":"提问的艺术—像苏格拉底一样思考","learn_goal":"应用苏格拉底的方法，提出有启发的问题，引导对方思考","remark":"《提问的艺术》这本书告诉我们“答的好不如问的好”，在沟通中，不要急于给出答案，而是提出好的问题，好的问题能帮助我们了解对方的真实想法，好的问题能够帮助我们拨开重重迷雾，看清问题本质，让对方更有兴趣、更重视双方的谈话。《提问的艺术》这本书是两位咨询对他们商业与人生提问的总结，书中通过一个个有力的提问再现对话的场景，涉及商业领域、人际交往和自我对话，一共320个强有力的问题，这些问题可以帮助我们了解对方，深化人际关系，销售更多的产品和服务，或者鼓励自己，战胜自己。","level":"TF3-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"勍勍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"事件： 生活中，我们常常习惯性地命令或建议别人去做什么？怎么做？\r\n比如，你的老公跟你说：“你看看，你今天不在家，小孩今天好调皮，饭不好吃，觉也不好好睡，怎么搞？”\r\n你听到了，觉得他应该担当起父亲的责任，于是说：“你要耐心一点嘛，小孩子吃饭要哄着吃的”巴巴拉拉说了一通......\r\n老公听了，有点不耐烦的说： “我哪里不耐心啦，今天喂饭喂了一个多小时，算了我搞不好，还是你来吧。”\r\n影响：你听了就火了，夫妻大战可能上演。可能老公的本意确实是想请教你怎么带小孩，但是被你的评判和命令很反感，就不想做了。\r\n解决：《提问的艺术》这本书告诉我们“答的好不如问的好”，在沟通中，不要急于给出答案，而是提出好的问题，好的问题能帮助我们了解对方的真实想法，好的问题能够帮助我们拨开重重迷雾，看清问题本质，让对方更有兴趣、更重视双方的谈话。《提问的艺术》这本书是两位咨询对他们商业与人生提问的总结，书中通过一个个有力的提问再现对话的场景，涉及商业领域、人际交往和自我对话，一共320个强有力的问题，这些问题可以帮助我们了解对方，深化人际关系，销售更多的产品和服务，或者鼓励自己，战胜自己。","ratings_count":0,"texts":[{"id":6181,"quote":"\u003cp>\u003cstrong>《提问的艺术》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>像苏格拉底一样思考\u003c/strong>\u003c/p>\u003cp>苏格拉底生活在古希腊，他是一位杰出的、善于提具有影的问题的大师。他在教授学生时，并没有采取演讲的方式，而是传授给学生一系列发人深省的问题。通过这些问题，他鼓励学生在学习中提升自己的思维。他总是能揭示出这些问题的本质。尽管只是慢慢地一点点渗透，但却总能直达事物的核心。\u003c/p>\u003cp>苏格拉底总是以“什么是美德”或“什么是美好”这些我们随时都在用的词语开始他的课程。我们真地清楚它们意味着什么吗？今天，世界上的许多大学都在他们的教学中采用了“苏格拉底法”，其中最有名的便是哈佛大学商学院。\u003c/p>\u003cp>苏格拉底将这一方法总结得很透彻。他说：“人类最高级的智慧就是向自己或向别人提问。”\u003c/p>\u003cp>苏格拉底是一位针对雅典社会和政府畅所欲言的评论家。他最终因对统治阶级的抨击而被判了死刑。对此他没有丝毫反抗，而是饮下了一杯毒堇汁。尽管毒堇汁慢慢地浸入了他的心脏，让他离开了人世，但他却给世人留下了历史上最伟大的哲学家之一的名声。\u003c/p>\u003cp>如今，你可以将苏格拉底的方法应用到日常工作和生活中。如何才能像苏格拉底一样思考呢？首先，从提问开始，而不是去阐述、声明或命令。其次，问一些每个人都会想到的、最基本的问题，这可能会让上他们大吃一惊。\u003c/p>\u003cp>例如，在工作中，有人会说：“我们需要更多的创新。”这时你应该问：“你眼中的创新是什么样子？”当听到一个需要更多团队合作的提议时，你可以这样问：“当你提到‘团队’一词时、你的意思是什么？”\u003c/p>\u003cp>诸如此类的问题能够引导对话双方进入更深层次的探讨中，并让对方参与进来，引起他们的思考。你也会因此赢得智慧导师的声誉—引导别人步入正确的方向，而不是将自己的观点强加于人。\u003c/p>","explains":"\u003cp>【A1】环节：\u003cstrong>量表自测\u003c/strong>\u003c/p>\u003cp>在开始拆书之前呢，我想大家先做一个小测试：\u003c/p>\u003cp>在发给大家的资料中，最下面有个测试表，请认真阅读，并在最符合自己情况的下面打勾，给大家2分钟的时间。\u003c/p>\u003cp>自测题：仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示很符合）\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、 当下属、孩子或弟弟妹妹等向我询问事情，我不会刻意表现专业，而是尊重他们，发自内心地想了解他们的真实想法。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、 当朋友向我倾诉她现在所面临的问题时，我不会马上给出建议，而是提问尽量让她自己找到解决方案。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、 别人找我要产品、方案、信息等等，无论我是否能够提供，我都会提问一下对方想要这个的最终目的。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、 面试前我不仅准备我要说什么，而且会花很多精力准备要问面试官什么。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、 在参加一些开放性的学习活动，我会准备一些事先想好的问题，期待与讲师做深入的沟通。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>测试表中一共有5道题，主要是测试大家是否有提问意识？\u003c/p>\u003cp>第1、2、3问题是测试我们是否能够及时提问反馈\u003c/p>\u003cp>第4、5问题是测试我们是否有刻意的准备提问\u003c/p>\u003cp>大家可以算一算自己的分数。20分以上的，说明自己的提问意识还是不错的，20分以下的，可能要注意了，你的提问意识需要加强咯。\u003c/p>\u003cp>\u003cstrong>【与学习者的简短互动】\u003c/strong>\u003c/p>\u003cp>好的，大家都阅读完了原文的片段后，能看到提问的几个关键词是什么呢？\u003c/p>\u003cp>1、提问，2、最基本的问题（或更多答案）\u003c/p>\u003cp>好的，大家说的都特别好。我总结苏格拉底式的提问就是三个不要和三个要：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>不要这样做\u003c/p>\u003c/td>\u003ctd>\u003cp>你应该这样做\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>做评判或给命令：\u003c/strong>你这样不行的....你要.........做， \u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>问想法：\u003c/strong>你是怎么想的呢？ 对于你来说，什么才是重要的呢？\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>做阐述：\u003c/strong>哦，你在工作上花费太多时间了......我之前也是这样子，忙得不了两头\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>促理解：\u003c/strong>哦，你理解的“工作和家庭的平衡”是什么呢？\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>提建议：\u003c/strong>我提议......这样做比较好......\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>找办法：\u003c/strong>关于这个问题，有什么办法吗？或者我们一起想想，有什么解决办法吗？\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【举例】\u003c/strong>：比如，当对方问你，他究竟该不该辞掉现在这份工作？\u003c/p>\u003cp>你要怎么回答呢？不要着急做评判，哦，你不想做这份工作啦？\u003c/p>\u003cp>\u003cstrong>问想法：\u003c/strong>你可以问，她的想法：“哦，你觉得现在的这份工作对你来说，意义在哪里呢？ \u003c/p>\u003cp>对方答：工作的意义就是给了我生活的来源，但是太忙了，我完全没有时间陪伴小孩，我没办法做到工作和生活的平衡？\u003c/p>\u003cp>\u003cstrong>促理解：\u003c/strong>哦，那你是怎么理解平衡的呢？你认为对你来说，现阶段什么才是最重要的呢？\u003c/p>\u003cp>对方答：我现在的小孩还小，有爸妈在帮我带，现阶段对我最重要的是自我提升。\u003c/p>\u003cp>\u003cstrong>促理解：\u003c/strong>那你觉得现在这份工作能满足你的自我提升吗？\u003c/p>\u003cp>对方答：其实，现在这份工作还是可以的，它让我学到很多东西，但是我感觉我时候力不从心，感觉能力达不到。\u003c/p>\u003cp>\u003cstrong>找办法：\u003c/strong>哦，原来可能不一定是这份工作的问题，而是你觉得你能力达不到，所以让你感觉力不从心，那觉得有什么办法可以提高自身的能力呢？\u003c/p>\u003cp>那么接下来，你们就可以一起对于提升能力的话题做进一步的探讨。\u003c/p>\u003cp>当朋友向你倾诉时，通过这些基础的提问，你可以不妄加判断，而是真正的聆听对方的真实想法，提问、倾听，这样一来一回，加深了你们相互的深层次沟通和理解，甚至有可能她自己的问题迎刃而解，提问的魅力就在于此。\u003c/p>\u003cp>\u003cstrong>【适用边界】：\u003c/strong>这种启发式提问，比较适合时间氛围相对轻松的场合，双方有比较有时间对这个问题进行深入的探讨。如果是时间紧张的商务谈判和上对下的简单任务传达，这种时候就不太适合怎么过于迂回的提问了。\u003c/p>","interaction":"\u003cp>好的，接下来，我想让大家分成小组，来做一个情景演练：\u003c/p>\u003cp>\u003cstrong>案例场景：\u003c/strong>\u003c/p>\u003cp>你是一位2岁孩子的妈妈，你一位关系很好的女性朋友小罗28岁刚刚新婚了，你恭喜她终于找到了幸福，她却一脸愁容，说自己刚刚换了一份很有挑战性的工作，但是他老公希望他们尽快要孩子，她一直纠结，到底要不要孩子？有了孩子后，会不会对她的工作带来不利。\u003c/p>\u003cp>\u003cstrong>具体要求：\u003c/strong>\u003c/p>\u003cp>1、两人组成一组，一个人扮演孩子妈，一个人扮演小罗\u003c/p>\u003cp>2、先根据场景讨论，扮演孩子妈的需要通过“问想法、促理解和找办法”的提问技巧，来帮助对方进行思考。三个步骤可以交替使用，对话不一定要有结论，到底要还是不要孩子，我们的目标是引导小罗自己思考，对于她来说什么是重要的。\u003c/p>\u003cp>3、5分钟讨论时间，5分钟后进行角色扮演\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>【房明】：恭喜你呀，完成了人生的一件大事，找到了自己的幸福\u003c/p>\u003cp>【新悦】：别提了\u003c/p>\u003cp>【房明】：怎么啦？我感觉你好像不太开心，是遇到什么难事了吗？\u003c/p>\u003cp>【新悦】：我刚结婚，还没度蜜月呢？我老公就希望尽快要孩子，是他们希望，又不是我希望，你看我时间精力不足，都不敢要孩子，我不敢想以后了。\u003c/p>\u003cp>【房明】：看来你们之间有个问题，就是该不该要孩子上，你觉得要孩子和不要孩子，你的生活会发生什么改变吗？\u003c/p>\u003cp>【新悦】：你看我工作还在发展期，如果要孩子的话，老板就不会给我升职加薪了，在工作上就会缺乏成就感，会很不开心。另外我觉得我们经济上还没有这个准备，但是如果不要孩子，我老公也会说我，公公婆婆也不会给我好脸色，所以，我就在这之间纠结。\u003c/p>\u003cp>【房明】：看起来你纠结的点，还是倾向于不想要孩子，是吗？那你有想过你不想要孩子，你会遇到哪方面的障碍？有没有想过怎么去克服这些障碍？你有想过怎么说服你老公和家人\u003c/p>\u003cp>【新悦】：我现在想想，生孩子这个事情可以是在我工作相对比较稳定之后，比如一两年之后，我再来考虑，我可以把生孩子这件事情先列上日程，这样子他就不会是遥遥无期的等待。我想就就是找个心平气和的场合，大家坐下来沟通吧，我也表达我对孩子的喜爱，和他说如果做好了这份工作的意义何在，比方说我的收入提高啊，等等。\u003c/p>\u003cp>【房明】：你看你现在已经想到答案了。\u003c/p>\u003cp>【新悦】：好的，非常感谢你。\u003c/p>\u003cp>\u003cstrong>拆书家反馈点评：\u003c/strong>\u003c/p>\u003cp>非常棒，我们刚刚两位学习者演绎的这个场景中有非常好运用了今天的提问技巧，比如：\u003c/p>\u003cp>你觉得生孩子和不生孩子之间，你的生活会发生什么变化吗？\u003cstrong>问想法\u003c/strong>\u003c/p>\u003cp>你会遇到哪方面的障碍？\u003cstrong>促理解\u003c/strong>\u003c/p>\u003cp>有没有想过怎么去克服这些障碍？\u003cstrong>找办法\u003c/strong>\u003c/p>\u003cp>通过这些提问，让处在迷局中的朋友自己找到问题的关键与解决的办法。\u003c/p>\u003cp>\u003cstrong>【布置任务】\u003c/strong>\u003c/p>\u003cp>好的，我们今天学习了苏格拉底提问的技巧，请想象一个自己可能给提建议的对象，场景，想一想，如果不给对方建议，你可以怎么提问，我们把我们今后可能运用的场景和方法写下来，填到这张纸上。\u003c/p>\u003cp>\u003cstrong>可能提建议的对象：\u003c/strong>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong>可能提建议的场景：\u003c/strong>\u003cstrong> \u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果不提建议，可以怎么做：\u003c/strong> \u003c/p>\u003cp>好的，我今天的拆解就到这里，谢谢大家！\u003c/p>\u003cp>【学习者A2】\u003c/p>\u003cp>\u003cstrong>可能提建议的对象：\u003c/strong>朋友\u003c/p>\u003cp>\u003cstrong>可能提建议的场景：\u003c/strong>和朋友喝下午茶\u003c/p>\u003cp>\u003cstrong>如果不提建议，可以怎么做：\u003c/strong>提问朋友的疑问或困扰？\u003c/p>\u003cp>这个疑问或困扰的本质是什么？\u003c/p>\u003cp>不同的选择会有什么改变？如果跨越这些障碍？\u003c/p>\u003cp>【学习者A2】\u003c/p>\u003cp>\u003cstrong>可能提建议的对象：\u003c/strong>同事\u003c/p>\u003cp>\u003cstrong>可能提建议的场景：\u003c/strong>和同事讨论工作问题\u003c/p>\u003cp>\u003cstrong>如果不提建议，可以怎么做：\u003c/strong>提问同事对这个工作的想法？\u003c/p>\u003cp>这个工作遇到了什么困难？\u003c/p>\u003cp>有什么办法可以解决这些困难？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1501584680000,"updated_at":1501584680000,"ria":true},{"id":3330,"topic":"不要滔滔不绝，却忘了客户的感受","learn_goal":"运用提问的三步法技巧，当别人问了一个大而全的问题时，适当提问","remark":"《提问的艺术》这本书告诉我们“答的好不如问的好”，在人际交往中，好的问题远比问题的答案更有力量。《提问的艺术》这本书是两位咨询对他们商业与人生提问的总结，书中通过一个个有力的提问再现对话的场景，涉及商业领域、人际交往和自我对话，通过这些强有力的问题，可以帮助我们深化人际关系，可以帮助我们销售更多的产品和服务，同时还能鼓励自己，战胜自己。","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"勍勍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"事件场景：\r\n不知道大家有没有碰到过这样的场景，\r\n当别人问我们问题的时候，我们本能的想给出一个答案，然后开始滔滔不绝，却忘了对方的感受。\r\n比如对方问你：“你能介绍一下你的方案吗？”，你从“背景，方法，计划”等等洋洋洒洒的介绍了半天，最后可能对方只是关心你的这个方案需要多少预算。\r\n提问：在客户让我们给他介绍方案的时候，我们该如何应对？是一股脑把你知道的都告诉他吗？ \r\n影响：当你滔滔不绝回答对方的问题，而并不是对方想听的时候，对方会表现出不耐烦，对话可能草草结束，这样的谈话是相当低效的。\r\n解决：在面对客户给我们提出一个问题后，我们总是急于给出答案，而《提问的艺术》这本书告诉我们“答的好不如问的好”，在人际交往中，好的问题远比问题的答案更有力量。《提问的艺术》这本书是两位咨询对他们商业与人生提问的总结，书中通过一个个有力的提问再现对话的场景，涉及商业领域、人际交往和自我对话，通过这些强有力的问题，可以帮助我们深化人际关系，可以帮助我们销售更多的产品和服务，同时还能鼓励自己，战胜自己。","ratings_count":0,"texts":[{"id":6180,"quote":"\u003cp>\u003cstrong>《提问的艺术》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不要滔滔不绝，却忘了客户的感受\u003c/strong>\u003c/p>\u003cp>巧的是，一年后的今天，我和我的高级合伙人德威特（Dewt）先生出席了一次似曾相识的销售会议。他是经历过数百场会议的资深人士，可以说是一位智者。我们的客户也提出了相同的问题：“你们何不先介绍一下你们的公司来开始我们今天的会议呢？”德威特若有所思地停顿了片刻，然后抬起头问客户：“那您具体需要了解些什么呢？”对方陷入了沉默中。\u003c/p>\u003cp>通常，问了一个问题后，如果对方沉默，我们就会换个说法再问一遍这个问题。我们是不会允许会议陷入沉默的，但德威特是一个例外，他习惯于保持沉默。很久以前他曾告诉过我：“一旦说完你想要说的，或问完问题，就闭嘴吧！”\u003c/p>\u003cp>过了一会儿，客户具体地说道：“好吧，我们当然已经很了解你们是做什么的了。我们只是特别想知道你们在亚洲的运营能力如何以及你们内部是如何一起工作的。”这无疑将会议带入了一个互动的交流氛围中了。\u003c/p>\u003cp>“我很好奇，你能具体描述一下你想了解的‘内部一起工作’的意思吗？是什么促使你提出了这个问题？”接下来，他又问了一些引人深思的问题，并与客户一起分享了最近遇到的一些案例，大多都是我们如何帮助老客户的有趣故事。\u003c/p>\u003cp>通过德威特的提问，我们了解到这家公司与其他咨询公司曾经有过不愉快的合作经历。这家公司曾在广告中号称自己是客户的感受一家全球性的公司，然而公司内部的各个部门却从来没有齐心协力地一起合作过。我们还了解到了这家公司的亚洲扩展计划，也弄清了他们寻找外援的真正原因。\u003c/p>\u003cp>德威特还做了一些让我至今难忘的事。他当着客户的面夸赞我。为什么他不夸夸自己呢？他没有在客户面前炫耀自己从业25年的丰富经验，也没有吹嘘他那杰出的专业知识，而只是跟客户说他为自己的团队有我这样的合作伙伴而感到幸运，还说我是他们前途无量的年轻合伙人之一，也是他们当中工作最努力的一个。这次讨论与众不同，绝对比上一次我和电信公司的会谈精彩得多，这才是建立新关系的一次良好的开始。\u003c/p>\u003cp>一周之后，那家公司再次打电话给德威特，邀请我们去做进一步的探讨，之后又制定了方案。德威特一直和他们合作到八年之后他退休的那一天。如今，他们成了我的终身客户。自从那次会议之后，我非常乐意跟随德威特并向他学习。\u003c/p>","explains":"\u003cp>\u003cstrong>事件场景\u003c/strong>：\u003c/p>\u003cp>不知道大家有没有碰到过这样的场景，\u003c/p>\u003cp>当别人问我们问题的时候，我们本能的想给出一个答案，然后开始滔滔不绝，却忘了对方的感受。\u003c/p>\u003cp>比如对方问你：“你能介绍一下你的方案吗？”，你从“背景，方法，计划”等等洋洋洒洒的介绍了半天，最后可能对方只是关心你的这个方案需要多少预算。\u003c/p>\u003cp>\u003cstrong>提问\u003c/strong>：在客户让我们给他介绍方案的时候，我们该如何应对？是一股脑把你知道的都告诉他吗？ \u003c/p>\u003cp>\u003cstrong>影响\u003c/strong>：当你滔滔不绝回答对方的问题，而并不是对方想听的时候，对方会表现出不耐烦，对话可能草草结束，这样的谈话是相当低效的。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>在面对客户给我们提出一个问题后，我们总是急于给出答案，而《提问的艺术》这本书告诉我们\u003cstrong>“答的好不如问的好”\u003c/strong>，在人际交往中，好的问题远比问题的答案更有力量。《提问的艺术》这本书是两位咨询对他们商业与人生提问的总结，书中通过一个个有力的提问再现对话的场景，涉及商业领域、人际交往和自我对话，通过这些强有力的问题，可以帮助我们深化人际关系，可以帮助我们销售更多的产品和服务，同时还能鼓励自己，战胜自己。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>那我今天和大家分享的就是这里面第一章节商业篇的片段，希望大家在跟随我完成本次拆书后，当别人问了一个大而全的、不能在短时间内给出答案的问题时，能够运用今天学习的提问三步法技巧，准确抓到对方实际想要了解的具体问题，从而给出有针对性的解答。\u003cbr>\u003cbr>\u003c/p>\u003cp>【R】阅读原书拆页（2分钟）\u003c/p>\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>好的，大家已经阅读完了原文的片段，片段里的这个案例无疑是一个成功的商业案例。\u003c/p>\u003cp>\u003cstrong>互动：\u003c/strong>那我想问一下大家，这个案例成功在哪里呢？\u003c/p>\u003cp>是的，我们看到，当客户提出一个大而全的问题时，德威特没有立刻给出答案。反问了一个关键的问题：“那您具体需要了解些什么呢？”\u003c/p>\u003cp>在客户做了具体回答之后，德威特又问了一个问题：“我很好奇，你能具体描述一下你想了解的“内部一起工作”的意思吗？”\u003c/p>\u003cp>通过这两个问题，德威特慢慢问出了客户的真实需求，并与客户建立了良好的关系。\u003c/p>\u003cp>\u003cstrong>强化讲解概念：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【易混淆的概念】\u003c/strong>\u003c/p>\u003cp>好的，那么我们知道不要着急给出答案，但是应该如何提问呢？\u003c/p>\u003cp>\u003cstrong>提问就是不断的提问对方吗？\u003c/strong>\u003c/p>\u003cp>当然不是，当对方提了一个大而全的问题之后，你可以适时的问一个具体的问题，让你的回答更有针对性。如果有必要做回答和阐述的时候，还是需要回答和进行阐述的。\u003c/p>\u003cp>\u003cstrong>【举例】：\u003c/strong>比如当对方问你，你能介绍一下拆书帮吗？\u003c/p>\u003cp>然后你问：“你想了解具体了解拆书帮什么呢？”\u003c/p>\u003cp>对方可能说：“拆书帮是读书会吗？”\u003c/p>\u003cp>那么这时，你是需要具体对拆书帮进行介绍的，让对方了解基本概念。\u003c/p>\u003cp>\u003cstrong>当对方问了我们一个大而全的问题时，我们具体该怎么做呢？\u003c/strong>\u003c/p>\u003cp>我们不妨运用书中的技巧，先\u003cstrong>询问细节：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>比如：\u003c/strong>\u003c/p>\u003cp>“你具体想了解拆书帮的什么情况呢？”\u003c/p>\u003cp>&nbsp;“你之前在哪里知道拆书帮的呢？”\u003c/p>\u003cp>&nbsp;“你参加过拆书帮的活动活动吗？”\u003c/p>\u003cp>根据对方回答的内容，再进行回答。\u003c/p>\u003cp>\u003cstrong>再比如：\u003c/strong>\u003c/p>\u003cp>对方回答说：“我主要是想了解一下拆书的学习方法，现在买了很多书，但是总感觉读不下去。”这时，我们可以问：“哦，这样啊，\u003cstrong>那你感觉读不下去的主要原因是什么呢？您买这些书的目的是什么呢？\u003c/strong>。”这是\u003cstrong>探寻动因。\u003c/strong>这样可以了解到对方想参加拆书帮，具体的目的是什么，他有哪方面的需求，再做具体的介绍。\u003c/p>\u003cp>回答完对方的问题后，我们最后对问题的回答进行\u003cstrong>适时确认\u003c/strong>。比如：我刚刚的回答你满意吗？我的回答有回答您的问题吗？\u003c/p>\u003cp>通过这样的三步提问，可能让我们不盲目作答，节省双方的时间。\u003c/p>\u003cp>\u003cstrong>【适用场景】\u003c/strong>\u003c/p>\u003cp>当你被问到一个总体性问题，而这个问题有可能需要很长的回答时。\u003c/p>\u003cp>当时间很短暂，你又想针对自己的目标做些简短回答时。\u003c/p>\u003cp>你就可以应用到我们今天的提问技巧\u003c/p>\u003cp>\u003cstrong>总结起来有三点：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>询问细节。\u003c/strong>这时可以提问 “你之前是否有对相关情况有所了解呢？”或者 “你想具体了解哪方面的情况呢？”。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>探寻动因。\u003c/strong> “对于这件事，您想要了解的目的是什么呢？”“您预期的期望是怎么样的呢？” \u003c/p>\u003cp>3\u003cstrong>.\u003c/strong>\u003cstrong>适时确认。\u003c/strong>回答完对方的问题候，可以说：“我的回答有回答您的问题吗？” \u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这里需要注意的是，以上的提问技巧特别适合于一些商务的场合，比如给客户介绍方案时，给陌生的朋友推荐产品，或者初次见面的伙伴介绍拆书帮等等。\u003c/p>\u003cp>在平常朋友闲聊等等就不太合适追问过多的细节了。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2催化应用：拆书家提问设计：\u003c/strong> \u003cstrong>教学习者编剧本\u003c/strong>\u003c/p>\u003cp>那么，接下来，我想让大家练习一个具体应用的场景，小伙伴们想象一个商务谈判或者双方对话的场景，可以是一个你向对方介绍你公司的产品或者服务，或者是你向对方介绍拆书帮或者是梦想赋能班，甚至是你去面试面对面试官等等都可以，大家可以先构想一下可以应用的场景。\u003c/p>\u003cp>\u003cstrong>【学习者场景记录】\u003c/strong>\u003c/p>\u003cp>【姚倩】：我是做金融的，平时经常有人问我，听说做很多人通过金融获得了一些额外的收入，你跟我讲讲吧？这就是一个很大、很泛的问题\u003c/p>\u003cp>【房明】：我是做老师的，平时经常有学生问我，拆书法是什么呢？\u003c/p>\u003cp>你会如何与对方展开一场对话，记得要运用我们上面的提问技巧，询问细节、探寻动因。 \u003c/p>\u003cp>\u003cstrong>请尝试编写一个小剧本，有地点、人物、情节变化和当时双方的对话等。\u003c/strong>\u003c/p>\u003cp>两两组成小组，讨论5分钟，记得把你的提问摘要写在一张纸上，\u003c/p>\u003cp>五分钟后我们请人来讲讲他的剧本。\u003c/p>\u003cp>\u003cstrong>【学习者编剧本】\u003c/strong>\u003c/p>\u003cp>场景：未来给我的学生来介绍拆书帮，比如有学生看了我在微信群里转发了一篇赵周老师的公众号文章，来问我问题，我可以应用这样的提问三步法来更有针对性的介绍。\u003c/p>\u003cp>【学生】：老师，什么是RIA便签读书法啊？\u003c/p>\u003cp>【房明】：看来，你已经看了这篇文章了，对便签读书法感兴趣，我想具体问一下你，文章里面也有说，便签读书法你是自己看书的时候用的，还有线下大家一起学习的时候来用的，你更想了解哪一个呢？\u003c/p>\u003cp>【学生】：嗯，自己看书的时候用的\u003c/p>\u003cp>【房明】：那我想再具体问一下，你自己看的话，是在哪方面有困惑，是不知道怎么来看书呢？还是不知道怎么将书本的知识应用？\u003c/p>\u003cp>【学生】：知识应用吧，因为买了很多书，都不知道怎么用？\u003c/p>\u003cp>【房明】：哦，就是看了很多书，但是不知道怎么用起来，是吗？好，那我给你简单介绍一下，个人看书的时候，你可以写三个便签，第一张便签I，当你看到一段让你心动的片段，用你自己的话重述，第二张便签是A1，就是联系你过往的经验，把你过去失败的经验记录下来，第三张便签就是应用，既然你已经有过往的失败经验，接下来你就要想，那我怎么来改进呢？你改进的目标是什么呢？如果你要采取下一步改进行动的话，你要什么时间完成，怎么完成，把这个写在A2便签上，然后贴在冰箱上，这样就是将书本知识应用的特别好的方法，便签读书法。\u003c/p>\u003cp>【学生】：原来是这样，那老师我明白了。\u003c/p>\u003cp>【房明】：那我刚刚的回答，回答了你的问题吗？\u003c/p>\u003cp>【学生】：嗯嗯，非常清楚。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>我提炼了一下两位的对话，房明在这个过程中，有提了三个关键问题：\u003c/p>\u003col>\u003cli>\u003cp>你看书的场景是什么？\u003c/p>\u003c/li>\u003cli>\u003cp>你看书的困惑在哪里？\u003c/p>\u003c/li>\u003cli>\u003cp>我的答复有回答了你的问题吗？\u003c/p>\u003c/li>\u003c/ol>\u003cp>都有应用到我们今天的提问技巧，唯一可以改善的地方，可以把封闭式给学生做选择题的提问，替换为开放式的提问，这样可以更加打开学生的思维。\u003c/p>\u003cp>\u003cstrong>拆书家总结：\u003c/strong>好的，我们今天学习了回答大而全问题的提问技巧，总结一下就是三步提问法：1、询问细节，2、探寻东一，3、适时确认，通过这三个技巧明确对方具体想知道什么？可以让你们的谈话更有效率，深化双方的关系。\u003c/p>\u003cp>\u003cstrong>【作业】\u003c/strong>\u003c/p>\u003cp>那么在接下来，我希望大家可以想象一个你可以应用这种提问技巧的场景，比如：领导问你最近工作的情况如何啊？\u003c/p>\u003cp>客户问你，你能介绍一下你们的产品或服务吗？\u003c/p>\u003cp>朋友问你，能不能介绍一下你现在总是在拆书，都做些什么啊？\u003c/p>\u003cp>等等......写一下你们应用的场景在便签纸上。\u003c/p>\u003cp>好的，接下来一周之内，尝试在和对方对话的过程中，运用这种提问技巧，询问细节和探寻动因，事后你们的对话记录下来，在下周四前发布到我们的微信群中，期待大家的分享，谢谢。\u003c/p>\u003cp>\u003cstrong>【学习者\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>计划】\u003c/strong>：计划在接下来一周，有人问我关于金融理财方面的情况时，我可以具体问问他：他之前有了解过相关的理财产品吗？他对于理财的期望是什么？，帮助我更有针对性的给对方介绍\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1501584507000,"updated_at":1501584507000,"ria":true},{"id":3015,"topic":"《提问的艺术》勍勍TF3-3过级","learn_goal":"学会使用正确的提问方式，使对方对你的讲话感兴趣，通过有力的提","remark":"《提问的艺术》这本书告诉你，乔布斯、德鲁克、苏格拉底这些大师们都有一个共同点，就是“善于提问”，书中总结了商业领域、人际交往以及个人领域的320个实用的最具影响力的问题，它通过真实的场景故事，阐述了用正确方法问问题的基本技能。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"勍勍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"【场景法介绍图书】\r\n事件场景：你在生活中是否有碰到过类似的事情？你满心欢喜终于约到了一个潜在客户去拜访，你提前精心准备好了你要演示的产品介绍PPT。可是，当你跟客户介绍产品的时候，你讲的口沫横飞，客户却一脸茫然，甚至流露不耐烦的神情。\r\n影响：这时，你感觉到了不对劲，但是又不知道该怎么办？你本能的加快了语速，匆匆结束了汇报。客户礼貌性地说：“感谢你的介绍，我后面还有一个会议，今天就先到这吧。” 这场来之不易的约见，就这样草草结束了。\r\n提问：你一定再想，为什么客户对我的介绍不感兴趣？是我的产品有问题，还是我的介绍有问题？可能都不是，只是你没有提问。\r\n解决： 《提问的艺术》这本书告诉你，乔布斯、德鲁克、苏格拉底这些大师们都有一个共同点，就是“善于提问”，书中总结了商业领域、人际交往以及个人领域的320个实用的最具影响力的问题，它通过真实的场景故事，阐述了用正确方法问问题的基本技能。\r\n今天我们要拆解的第一个片段是销售的秘诀，告诉我们世上最成功的销售员是如何提问的。","ratings_count":0,"texts":[{"id":5810,"quote":"\u003cp>\u003cstrong>原文片段1：\u003c/strong>\u003cbr> 　　销售成功的秘诀是什么？是去说服一位潜在的买家与你合作吗？只有当买家的需求被清晰地识别，才有可能产生真正的买家，并建立起值得信赖的关系来，价值也才能被真正体现。世上最成功的销售人员会通过问最伟大的问题去创造这些条件。\u003c/p>\u003cp>　　他们是不会通过故弄玄虚的PPT演示来与潜在客户建立起信任关系的。相反，他们会通过向客户问一些具有思想深度和能体现见识的问题，来体现他们丰富的学识和经验。他们通过问问题来发现潜在的需求，并识别是否有问题存在或有他们能抓住的机遇。最好的销售人员也是通过利用这些问题来建立情感联系的。去了解其他人并向他们表达自己的关怀吧。\u003c/p>\u003cp>　　当你第一次遇到某个人时，无论你是在销售产品、服务还是创意，强有力的问题将能够让你快速赢得尊重，这就是建立信任关系的第一步。\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>好的，希望今天大家在跟随我完成本次拆书学习后，当你在向客户销售产品或服务时，能学会通过问题发现对方的需求。\u003c/p>\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>简短互动：\u003c/strong>\u003c/p>\u003cp>在这个片段中，销售人员成功的秘诀是什么？（通过提问，清晰地识别对方的需求）\u003c/p>\u003cp>\u003cstrong>概念讲解：\u003c/strong>\u003c/p>\u003cp>我们来看看一般的销售人员和成功的销售的区别。\u003c/p>\u003cp>一般的销售更在意自己的产品或服务。成功的销售更看重客户的需求。\u003c/p>\u003cp>具体的表现呢：\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>不知道大家注意到了商场里面的新手销售和老手销售的区别。\u003c/p>\u003cp>上次去商场买鞋子，一位年轻的销售人员过来。\u003c/p>\u003cp>新手销售：小姐，买鞋子吗？\u003c/p>\u003cp>我：我随便看看。\u003c/p>\u003cp>新手销售：哦，这个是我们最近的新款，皮子软，款式新，上脚特别好看。\u003c/p>\u003cp>我：哦，好的，我再看看吧。\u003c/p>\u003cp>然后，我就自己去了下一家。\u003c/p>\u003cp>老手销售：小姐，看鞋子吗？您是想买上班穿的，还是平时休闲穿的呢？\u003c/p>\u003cp>我：哦，我想买上班穿的。\u003c/p>\u003cp>老手销售：哦，这样啊，那您平时习惯穿高跟，还是低跟的呢？\u003c/p>\u003cp>我：平时穿高跟嫌累，一般穿休闲鞋，但是上班有时要见客户，想要买双合脚的又不太累的鞋子。\u003c/p>\u003cp>老手销售：哦，我们店刚好有一款鞋子，只有5CM高，是今年流行的粗跟款，穿上去既职业也不累，非常适合您，我拿给您试一下，您穿什么码？我拿给您试一下。\u003c/p>\u003cp>好，销售达成。\u003c/p>\u003cp>\u003cstrong>方法总结：\u003c/strong>\u003c/p>\u003cp>从这个例子我们可以看出，老手销售和新手销售的区别，不要着急去销售产品，而是关注对方的需求。提问步骤：\u003c/p>\u003cp>1、在提问对方的需求时，保持谦逊、好奇的心态，可以询问对方的使用场景、个人喜好等等。\u003c/p>\u003cp>2、谈话的焦点尽量聚焦对方，即便是谈论你的产品，也要告诉他产品对于他的好处。\u003c/p>\u003cp>3、就算客户出于各种原因不打算购买，也不需要强推，聆听对方的需求和想法已经让你和他拉近了距离。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong> \u003c/p>\u003cp>下面请大家编一个故事，这个故事里需要有两个人物，一个是销售，一个是客户，作为销售需要询问到对方的需求，销售你看到的任何物品，比如我们面前的杯子、你的笔等等。\u003c/p>\u003cp>建议包括：对话的过程，对方会如何表现，你会如何应对；对方会说什么，你会说什么。\u003c/p>\u003cp>\u003cstrong>【提示】：\u003c/strong>3轮左右对话，提问对方需求即可。\u003c/p>\u003cp>请大家把对话要点记录在便签上，时长3分钟。\u003c/p>\u003cp>完成后：请2个伙伴分享下你的故事，分享时长不要超过1分钟\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>场景：服装店，店员向顾客推荐童装\u003c/p>\u003cp>学习者1：哥，你好，这款衣服是我们今天刚到的新款。你家小朋友几岁啦？\u003c/p>\u003cp>学习者2：5岁\u003c/p>\u003cp>学习者1：5岁啊，我想你也知道现在小朋友的衣服不仅仅追求舒适感，也追求时尚感，这套衣服设计很时尚，另外，我再拿两套给你看看。你看看这个款是偏休闲。\u003c/p>\u003cp>学习者1：我小朋友爱玩，容易把衣服弄脏。\u003c/p>\u003cp>学习者2：那这一套衣服就比较适合，纯棉的，比较容易清洗。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>学习者前面有提问，对方的小孩年龄多大？\u003c/p>\u003cp>其实客户是有提出的需求的，比如舒适性和容易清洗。\u003c/p>\u003cp>我们销售人员如果能够准确抓住对方的需求，就能够更好的销售产品。\u003c/p>\u003cp>【分享总结】：\u003c/p>\u003cp>好的，总结一下，我们通过对一个小故事的拆解和分享，让我们知道我们可以通过询问对方的使用场景和个人喜好，了解对方的需求。\u003c/p>\u003cp>说起来比较简单哈，但是我们实际做起来会怎么样呢？接下来，我会发一个测试题给大家，测测你的平常沟通的习惯是怎样的？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":5811,"quote":"\u003cp>\u003cstrong>自测题：\u003c/strong>仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示很符合）\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、 我在与客户沟通时，会注意观察客户的微表情与肢体动作。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、 我会注意到谈话是否偏离主题。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、 我对客户想谈话的话题有浓厚的兴趣与好奇心。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、 我在沟通过程中，会注意使用提问的方式进行。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、 在谈话过程中，相比较自己的主题，我会更在意客户想探讨的主题。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>原文片段\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>当一个人开始目光游离，且没有任何问题时，就是时候该做点什么了。你遇到麻烦了。\u003c/p>\u003cp>我正在和一家大型专业服务类公司的共同主席凯瑟琳开会。这次会议早在几周前就定下来了。会议议程的是共同回顾一下我在为他们公司所做的咨询项目的进展情况。我提前做了充足细致的准备，并给凯瑟琳带去了简要的文件。文件清晰精炼地概述了项目的进展情况，足以给人留下深刻的印象。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;我们的讨论大约进行了20多分钟，我就发现凯瑟琳心不在焉，整个人坐立不安，根本不在状态。她没有问任何精彩的跟进性问题，更糟糕的是，她的眼睛开始盯着黑莓手机看了。你一定能想象得出当时的情境有多令人沮丧。有人试图表现出一副专心听你讲的样子，却低下头偷偷看他们手中的智能手机。凯瑟琳的心不知道跑哪里去了。\u003c/p>\u003cp>&nbsp; &nbsp;我暂停下来。和这位繁忙的高管坐在一起，时间仿佛凝固了。“凯瑟琳，”我问道，“今天早上我们讨论的重点是什么？”她突然坐直了，警觉了起来。我在等待她的回答。\u003c/p>\u003cp>&nbsp; “嗯，好的，”她开始慢条斯理的回答道，“你的汇报很有帮助，我觉得你的概述和建议很有价值。做得很好！”\u003c/p>\u003cp>&nbsp; “谢谢你的肯定！但接下来我们应该集中讨论什么？”\u003c/p>\u003cp>&nbsp; 凯瑟琳抬头看着我，皱着眉摇了摇头，叹息道：“我想我的团队还没有准备好，他们无法跟上进度。”\u003c/p>\u003cp>&nbsp; “请再说详细一点，当你告诉我他们还没有准备好时，你预见到了什么吗？什么事无法继续下去了？”\u003c/p>\u003cp>&nbsp; 我们转移了话题，接下来的半个小时我们都在讨论有关她的团队的事。我问了许多有力的问题，凯瑟琳更进一步说明了目前的形势。我提出了一些初步措施，以便让她的团队更好地配合项目的战略指标。我们把其余的有关项目进展的讨论挪到了下一次讨论。我之前为这次会议精心准备的文件看来是派不上用场了。也许它已经达到了应有的效果。\u003c/p>\u003cp>&nbsp; 当我起身准备离开的时候，凯瑟琳问我：“我们能在下周就此问题再重新碰一下面吗？你刚才问了许多很专业的精彩问题，你的建议也很棒。我想和你一起好好深入探讨一下。”\u003c/p>","explains":"\u003cp>【A1】量表自测\u003c/p>\u003cp>在发给大家的资料中，上面有个测试表，请认真阅读，并在最符合自己情况的下面打勾，给大家2分钟的时间。\u003c/p>\u003cp>【I】量表解释\u003c/p>\u003cp>请完成打分的伙伴，把分数加一下，有没有大于20分的，有没有小于12分的？\u003c/p>\u003cp>这个测试的目的，是让大家了解自己的沟通习惯。\u003c/p>\u003cp>分数大于20分的，说明你更善长提问，并且更关注客户的利益；分数越低，低于12分的，说明你需要好好提高你的提问能力了哦？\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>好的，那么接下来我们进行第二个片段的拆解，希望今天大家在跟随我完成这个拆书学习后，能够在对方表现心不在焉时，及时提问，明确谈话焦点，关注对方的利益和价值。\u003c/p>\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>在这个片段是一个故事，讲了一个咨询顾问专业、精彩的咨询过程，怎么体现他的专业呢，他本来是准备了一个项目进度汇报，但是在他讲解的过程中，对方心不在焉了，这时，他做了什么？\u003c/p>\u003cp>\u003cstrong>【简短互动】（\u003c/strong>他停了下来，提了一个问题“今天早上我们讨论的重点是什么？” ）是的，这个问题非常关键，体现出你对对方诉求的关注。\u003c/p>\u003cp>\u003cstrong>概念讲解：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>WHY\u003c/strong>\u003cstrong>】：\u003c/strong>关注对方的述求为什么那么重要？\u003c/p>\u003cp>就算你们已经熟悉，就算是你们的话题已经事先确定；你仍然有可能讲的东西并非是对方关心的事情，对方这时就会走神，甚至表现的心不在焉。如果你能将谈话的焦点放在对方最重要的事情上，那对有助增强你谈话的吸引力和影响力。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>what\u003c/strong>\u003cstrong>】：\u003c/strong>那么如何用提问的方式关注对方的述求呢？\u003c/p>\u003cp>\u003cstrong>【适用边界】：\u003c/strong>\u003c/p>\u003cp>1、在你和客户或者领导讨论项目进展时。\u003c/p>\u003cp>2、在你做销售定位时，进一步咨询时。\u003c/p>\u003cp>3、在你和家人的重要沟通时。\u003c/p>\u003cp>你都可以尝试通过提问来探询谈话对象的诉求点。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3【微行动学习】\u003c/strong>\u003c/p>\u003cp>接下来，我们想大家3~5个人组成一个小组，我们来进行一个小组讨论。（全场共三组）\u003c/p>\u003cp>\u003cstrong>讨论问题：\u003c/strong>你是否遇到过你在夸夸奇谈，而对方却心不在焉的情况？（小组内分享，确定一个最有讨论价值的情景问题）\u003c/p>\u003cp>\u003cstrong>分析原因：\u003c/strong>你觉得对方不关注的原因是什么？\u003c/p>\u003cp>\u003cstrong>解决方案：\u003c/strong>你觉得如何运用提问的技巧，明确谈话焦点？\u003c/p>\u003cp>\u003cstrong>注意事项：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、记录\u003c/strong>：请大家把讨论记录在便签纸上，\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、发表：\u003c/strong>5分钟后，我们请小组派代表来进行你们小组讨论的结果\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习者案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、问题场景：\u003c/strong>是否遇到过你在夸夸奇谈，而对方却心不在焉的情况？\u003c/p>\u003cp>小组1：与对方讨论旅游的事情，对方无回应\u003c/p>\u003cp>小组2：培训讲课时，学习者心不在焉\u003c/p>\u003cp>小组3：工作汇报时，领导或参与者心不在焉\u003c/p>\u003cp>\u003cstrong>二、分析原因：\u003c/strong>\u003c/p>\u003cp>小组1：对对方观察不够，缺少互动，找不到对方需求点\u003c/p>\u003cp>小组2：讲师自身原因，不了解学员需求，知道需求讲师也不响应，学员对内容没兴趣。\u003c/p>\u003cp>小组3：不了解领导需求，汇报的深度不够（缺乏数据事实支持），其他人没有角色带入感。\u003c/p>\u003cp>\u003cstrong>三、解决方案：\u003c/strong>\u003c/p>\u003cp>小组1：第一步，启动观察；第二步增强互动，询问对方的状态和想法，如“看你不在状态的样子，是不是太累啦？”“你对旅游有什么看法吗？”；第三步如果这次不在状态，邀约下次讨论。\u003c/p>\u003cp>小组2：第一步，启动观察；第二步提问对方应用场景，比如“你觉得你在什么情况下需要用到今天所学的知识”，提问对方想要有什么收获，如“你想在今天的课堂上收获什么？”；第三步老师现场调整讲课内容，或者老师课后复盘，下次课程进行改进。\u003c/p>\u003cp>小组3：第一步，询问领导需求，比如您希望今天的汇报达到什么目的或效果？第二步汇报有重点，有结构，观点先行，论据支撑。第三步，与与会者有互动，询问大家对于汇报主题的想法。\u003c/p>\u003cp>\u003cstrong>【拆书家总结反馈】：\u003c/strong>\u003c/p>\u003cp>总结，我们今天的讨论成果斐然，无论是生活的、工作的还是培训的，我们都讨论了一个关于提问可以应用的场景。\u003c/p>\u003cp>总结起来，我们如何应对，当我们在夸夸其谈，而对方缺心不在焉的情况呢？步骤有三：\u003c/p>\u003cp>第一步：启动观察，如果对方已经不在状态了，可以暂停对话。\u003c/p>\u003cp>第二步：明确焦点，通过询问对方现在的状态、想法、需求，明确谈话的重点。\u003c/p>\u003cp>第三步：进一步探讨，针对对方感兴趣的想法和需求，和对方进行进一步的探讨。\u003c/p>\u003cp>【A2规划应用】\u003c/p>\u003cp>好的，今天我们学习了如何针对对方的述求进行提问，接下来，我希望大家规划一下我们接下来的应用。\u003c/p>\u003cp>\u003cstrong>【布置任务】\u003c/strong>\u003c/p>\u003cp>1、确定一个你明天要进行的一场对话\u003c/p>\u003cp>2、设计一下你会如何进行这场对话\u003c/p>\u003cp>把你要问的问题写下来，要使用今天所学的方法\u003c/p>\u003cp>请1位代表来分享你们的讨论要点，每人分享不要超过1分钟\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>学习者：\u003c/p>\u003cp>1、场景：明天和领导就线上培训项目的谈话\u003c/p>\u003cp>2、现象：培训上交作业的情况参吃不齐。\u003c/p>\u003cp>3、询问领导：你这样安排的目的是什么？大家到底是要了解产品的知识，还是要熟悉培训的流程？\u003c/p>\u003cp>那你觉得这样的效果和之前的培训，哪一种的效果会更好？\u003c/p>\u003cp>询问学员的培训需求\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>你明天与领导讨论培训效果的事情\u003c/p>\u003cp>你会通过什么样的问题询问领导的需求？ \u003c/p>\u003cp>领导办这个培训班想要达到的目的是什么？效果和之前有对比？\u003c/p>\u003cp>你后面还有一个建议的方案，大家看到她这样梳理以后，明天和领导的谈话就会更有效率，大家看到了A2的行动计划就是这样，希望大家在课后把我们的行动计划PO到微信群。\u003c/p>\u003cp>好的，我今天的拆解就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1498225969000,"updated_at":1498225969000,"ria":true},{"id":3014,"topic":"《提问的艺术》像苏格拉底一样思考-TF3-2过级","learn_goal":"学习应用苏格拉底的方法，把提建议改为提问题，运用基本问题，引","remark":"《提问的艺术》这本书收集了320个实用的最具影响力的问题，从商业领域、人际交往领域和个人领域三个方面指导职场人士通过提问迅速与他人建立起相互信赖的关系。\r\n今天我们拆解的片段是介绍如何提出有启发的问题，引导对方自己找出想要的答案。希望大家在跟谁我拆书之后，学习应用苏格拉底的方法，把提建议改为提问题，运用基本问题，引导对方进行思考。","level":"TF2-4","duration":25,"status":0,"type":0,"chaishujia":{"username":"勍勍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"大家好，我是今天的拆书家勍勍。\r\n【A1】量表自测\r\n在开始拆书之前呢，我想大家先做一个小测试：\r\n在发给大家的资料中，最下面有个测试表，请认真阅读，并在最符合自己情况的下面打勾，给大家2分钟的时间。","ratings_count":0,"texts":[{"id":5809,"quote":"\u003cp>\u003cstrong>《提问的艺术》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>像苏格拉底一样思考\u003c/strong>\u003c/p>\u003cp>苏格拉底生活在古希腊，他是一位杰出的、善于提具有影的问题的大师。他在教授学生时，并没有采取演讲的方式，而是传授给学生一系列发人深省的问题。通过这些问题，他鼓励学生在学习中提升自己的思维。他总是能揭示出这些问题的本质。尽管只是慢慢地一点点渗透，但却总能直达事物的核心。\u003c/p>\u003cp>苏格拉底总是以“什么是美德”或“什么是美好”这些我们随时都在用的词语开始他的课程。我们真地清楚它们意味着什么吗？今天，世界上的许多大学都在他们的教学中采用了“苏格拉底法”，其中最有名的便是哈佛大学商学院。\u003c/p>\u003cp>苏格拉底将这一方法总结得很透彻。他说：“人类最高级的智慧就是向自己或向别人提问。”\u003c/p>\u003cp>苏格拉底是一位针对雅典社会和政府畅所欲言的评论家。他最终因对统治阶级的抨击而被判了死刑。对此他没有丝毫反抗，而是饮下了一杯毒堇汁。尽管毒堇汁慢慢地浸入了他的心脏，让他离开了人世，但他却给世人留下了历史上最伟大的哲学家之一的名声。\u003c/p>\u003cp>如今，你可以将苏格拉底的方法应用到日常工作和生活中。如何才能像苏格拉底一样思考呢？首先，从提问开始，而不是去阐述、声明或命令。其次，问一些每个人都会想到的、最基本的问题，这可能会让上他们大吃一惊。\u003c/p>\u003cp>例如，在工作中，有人会说：“我们需要更多的创新。”这时你应该问：“你眼中的创新是什么样子？”当听到一个需要更多团队合作的提议时，你可以这样问：“当你提到‘团队’一词时、你的意思是什么？”\u003c/p>\u003cp>诸如此类的问题能够引导对话双方进入更深层次的探讨中，并让对方参与进来，引起他们的思考。你也会因此赢得智慧导师的声誉—引导别人步入正确的方向，而不是将自己的观点强加于人。\u003c/p>\u003cp>自测题：仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1表示很不符合，6表示很符合）\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、 当朋友向我倾诉她现在所面临的问题时，我不会马上给出建议，而是提问尽量让她自己找到解决方案。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、 别人找我要产品、方案、信息等等，无论我是否能够提供，我都是特别关心他想要这个的最终目的。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、 面试前我不仅准备我要说什么，而且会花很多精力准备要问面试官什么。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、 在参加一些开放性的学习活动，我会准备一些事先想好的问题，期待与讲师做深入的沟通。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、 当下属、孩子或弟弟妹妹等向我询问事情，我不会刻意表现专业，而是尊重他们，发自内心地想了解他们的真实想法。\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;&nbsp;&nbsp; 2&nbsp;&nbsp;&nbsp; 3&nbsp;&nbsp;&nbsp; &nbsp; 4&nbsp;&nbsp;&nbsp; 5&nbsp;&nbsp;&nbsp;&nbsp; 6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>【I】解释\u003c/p>\u003cp>测试表中一共有5道题，主要是测试大家是否有提问意识？大家可以算一算自己的分数。20分以上的，说明自己的提问意识还是不错的，20分以下的，可能要注意了，你的提问意识需要加强咯。\u003c/p>\u003cp>为什么提问的意识和能力那么重要？\u003c/p>\u003cp>因为好的提问可以让对方更有兴趣、更重视你的话；\u003c/p>\u003cp>好的提问可以引导话题、促动交流；\u003c/p>\u003cp>好的提问可以能够让你获得他人尊重。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>\u003cstrong>事件场景\u003c/strong>：前段时间，我有个项目是做内训师比赛辅导，一个学员问我：“刘老师，您觉得我这个课程如何设计的出彩呢？” \u003c/p>\u003cp>\u003cstrong>提问\u003c/strong>：我为了体现我的专业性，就开始跟他说，嗯，好的课程应该是怎么怎么样的？介绍了一堆我们公司的课程设计方法，还演示了几个我们公司好的课程，苦口婆心的说了一大通，我感觉是对他有帮助的，结果呢？\u003c/p>\u003cp>\u003cstrong>影响\u003c/strong>：大家听了半天，还是没有感觉，最后还是问我，老师，你说的这些太高大上了，我只想知道具体我这个课程怎么做呢？最后，我当然只能再问问他自己，和他梳理他自己课程的逻辑和思路。这也让我感觉到，在辅导时不要着急给出答案，而是要针对学员具体情况，具体分析。最好是通过提问，让他挖掘出自己的经验和优秀做法。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那么，怎么才能提出好的问题呢？《提问的艺术》这本书收集了320个实用的最具影响力的问题，从商业领域、人际交往领域和个人领域三个方面指导职场人士通过提问迅速与他人建立起相互信赖的关系。\u003c/p>\u003cp>今天我们拆解的片段是介绍如何提出有启发的问题，引导对方自己找出想要的答案。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>希望大家在跟谁我拆书之后，学习应用苏格拉底的方法，把提建议改为提问题，运用基本问题，引导对方进行思考。\u003c/p>\u003cp>\u003cstrong>【与学习者的简短互动】\u003c/strong>\u003c/p>\u003cp>好的，大家都阅读完了原文的片段后，能看到提问的几个关键词是什么呢？\u003c/p>\u003cp>1、提问，2、最基本的问题（或更多答案）\u003c/p>\u003cp>好的大家都总结的特别好。我总结苏格拉底式的提问就是不直接给出答案，而是先问一个基本的问题，那么具体怎么做呢？\u003c/p>\u003cp>书中有一个表格，我重新整理了一下，给大家看一下：\u003c/p>\u003cp>\u003cstrong>不要这样做\u003c/strong>\u003c/p>\u003cp>\u003cstrong>提建议：\u003c/strong>你应该.........\u003c/p>\u003cp>\u003cstrong>给答案：\u003c/strong>“某某”的意思就是.......\u003c/p>\u003cp>\u003cstrong>显专业：\u003c/strong>这方面我比较专业，我来告诉你们.......\u003c/p>\u003cp>\u003cstrong>你应该这样做\u003c/strong>\u003c/p>\u003cp>\u003cstrong>问想法：\u003c/strong>对于这件事，你是怎么想的呢？\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>：比如，当对方问你究竟该如何处理她和婆婆的关系时？不要着急给答案，而是询问一下，她的想法：“哦，听起来，你和你婆婆的关系不太好，那么你是怎么想的呢？” \u003c/p>\u003cp>\u003cstrong>促理解：\u003c/strong>你觉得怎么理解“某某”的呢？.......\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>：比如，当对方说：“我想和婆婆和谐相处”，那么你可以问她：“那么，你认为的和谐相处是什么样的状态呢？”，比如不争执、相敬如宾，还是要更进步能相互理解。\u003c/p>\u003cp>\u003cstrong>征方案\u003c/strong>：那么你觉得解决这个问题，你有想过一些办法吗？\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>：你可以说：“看起来，你很想改善你和婆婆之间的关系，那么，对于这个问题，你有想过什么办法吗？”\u003c/p>\u003cp>当朋友向你倾诉时，通过这些基础的提问，你可以不妄加判断，而是真正的聆听对方的真实想法，提问、倾听，这样一来一回，加深了你们相互的深层次沟通和理解，甚至有可能她自己的问题迎刃而解，提问的魅力就在于此。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】角色扮演：\u003c/strong>\u003c/p>\u003cp>好的，接下来，我想让大家分成小组，来做一个情景演练：\u003c/p>\u003cp>背景是这样的：你的一位朋友，最近工作太忙，已经连续2周经常加班，照顾不到家庭，她跟你不停在倾诉：“她现在需要家庭和工作的平衡”，你如何用苏格拉底提问的技巧，帮助她自己思考。请至少设计3组对话，尝试提出基础性问题，让对方打开话匣子。\u003c/p>\u003cp>大家先演练一下，五分钟后我们请人来扮演。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>【三木】：我跟你讲啦，最近经常加班了，白加黑连续两周，都没有自己的时间了，有时候还通宵在单位睡觉，这日子没发活了，真是的。\u003c/p>\u003cp>【可可】：那你是觉得，你这种状态已经严重影响你生活了吗？\u003c/p>\u003cp>【三木】：是的呀，我当然是想要自己的生活呀，工作只是生活的一部分，我不能因为加班而抛弃我的生活，这不是我想要的。\u003c/p>\u003cp>【可可】：那是不是你对工作这样一个期待，就是工作和生活能够有一个平衡，这样一种状态。\u003c/p>\u003cp>【三木】：对，我的理想状态应该是能养家糊口，同时还能有自己的时间，这就是最好的。\u003c/p>\u003cp>【可可】：那你这个加班是经常性的加班，还是偶尔的应急的加班呢？\u003c/p>\u003cp>【三木】：就是经常性的加班，加班\u003c/p>\u003cp>【可可】：那你有没有考虑过换一份工作或者是其他的方法来改善？\u003c/p>\u003cp>【三木】：你这么一说，我还真的是哦，没想过这个问题，但是，这可能是个方法，而且现在这个工作太忙了，我改变不了，可能换个工作就解决了。\u003c/p>\u003cp>【可可】嗯，那我觉得你这些想法可以和你上司沟通一下，看看可不可以对你的工作做一些调整。\u003c/p>\u003cp>【三木】：嗯，好的好的。\u003c/p>\u003cp>\u003cstrong>拆书家反馈点评：\u003c/strong>\u003c/p>\u003cp>可可在前面提的几个问题特别好：\u003c/p>\u003cp>你是觉得，你的工作影响了你的生活吗？\u003c/p>\u003cp>你觉得，你需要工作和生活的平衡吗？你觉得是工作和生活需要对半分时间？\u003c/p>\u003cp>但是，三木没有回答，这个时候你也没有去用到我们今天的方法，促进他对于平衡的理解。\u003c/p>\u003cp>你在最后还是提了建议，你说是不是可以换个工作，是不是和你的上司去谈一谈啊，其实在这个时候，你是可以提一些开放性的问题，比如：“那你是不是有想过一些办法来进行改善呢？”，运用到我们的提问的第三步，征方案。运用开放式的提问，让对方自己找到解决方案。\u003c/p>\u003cp>\u003cstrong>A2【布置任务】\u003c/strong>\u003c/p>\u003cp>好的，我们今天学习了苏格拉底提问的技巧，把提建议换成提问，但是我想你们仍然可能给对方提建议，为了刻意练习提问技能，我希望在未来一周里，请你留意自己给别人提建议的场景，把你们的对话记录下来，然后试着把当时的建议改成提问，PO到会员群。\u003c/p>\u003cp>好的，我今天的拆解就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1498222483000,"updated_at":1498222483000,"ria":true},{"id":2253,"topic":"提问开场技巧","learn_goal":"运用提问的两步法技巧，在短时间内抓住对方的真正需求","remark":"不知道大家有没有过这样的经历，当你信心满满精心做好了给客户或者领导汇报的报告，结果客户或领导，看都没看或者根本不关心？\r\n那我今天和大家分享的就是这里面第一章节商业篇的片段，希望大家在跟随我完成本次拆书后，能够在商务领域，运用提问的两步法技巧，现场演练对话，在短时间内抓住对方的真正需求或意图，与对方建立良好的沟通与互动。","level":"TF2-4","duration":25,"status":0,"type":0,"chaishujia":{"username":"勍勍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"大家好，我是今天的拆书家勍勍。不知道大家有没有过这样的经历，当你信心满满精心做好了给客户或者领导汇报的报告，结果客户或领导，看都没看或者根本不关心？\r\n前两天我跟着我经理去见客户，向客户汇报一个我们的评审方案，这个方案的前期是经理交代给我做的，我觉得写的也非常的清楚明白，包括工作内容、工作流程和评审安排等等。结果，拿到客户那里之后，客户说不好意思，现在她接下来有个会议，我们就在位置上简单聊一下吧，于是准备的PPT完全没有用上。\r\n“你能简单介绍一下你的方案吗？”\r\n我开始仔细在脑袋里搜索，开始介绍了：“背景，方法，计划”等等，等我介绍到一半的时候，我注意到了对方开始拿着手机看他的东西，我不知道客户是因为忙，还是对我的方案不感兴趣，我开始有点着急，语速自然的加快，后面草草的就把方案讲完了。好在，当时我的经理，及时的接住了话茬，然后和客户开始了后面的对话，否则我也不知后面该如何结束。\r\n提问：在给客户介绍方案的时候，如何才能让对方想听呢？ \r\n影响：当客户已经在心不在焉的看手机，或者直接截断你说还有会议要开，下次再说的时候，也许这次的生意就黄了。\r\n解决：现在我们知道在做咨询和客户沟通的过","ratings_count":0,"texts":[{"id":4921,"quote":"\u003cp>\u003cstrong>《提问的艺术》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不要滔滔不绝，却忘了客户的感受\u003c/strong>\u003c/p>\u003cp>巧的是，一年后的今天，我和我的高级合伙人德威特（Dewt）先生出席了一次似曾相识的销售会议。他是经历过数百场会议的资深人士，可以说是一位智者。我们的客户也提出了相同的问题：“你们何不先介绍一下你们的公司来开始我们今天的会议呢？”德威特若有所思地停顿了片刻，然后抬起头问客户：“那您具体需要了解些什么呢？”对方陷入了沉默中。\u003c/p>\u003cp>通常，问了一个问题后，如果对方沉默，我们就会换个说法再问一遍这个问题。我们是不会允许会议陷入沉默的，但德威特是一个例外，他习惯于保持沉默。很久以前他曾告诉过我：“一旦说完你想要说的，或问完问题，就闭嘴吧！”\u003c/p>\u003cp>过了一会儿，客户具体地说道：“好吧，我们当然已经很了解你们是做什么的了。我们只是特别想知道你们在亚洲的运营能力如何以及你们内部是如何一起工作的。”这无疑将会议带入了一个互动的交流氛围中了。\u003c/p>\u003cp>“我很好奇，你能具体描述一下你想了解的‘内部一起工作’的意思吗？是什么促使你提出了这个问题？”接下来，他又问了一些引人深思的问题，并与客户一起分享了最近遇到的一些案例，大多都是我们如何帮助老客户的有趣故事。\u003c/p>\u003cp>通过德威特的提问，我们了解到这家公司与其他咨询公司曾经有过不愉快的合作经历。这家公司曾在广告中号称自己是客户的感受一家全球性的公司，然而公司内部的各个部门却从来没有齐心协力地一起合作过。我们还了解到了这家公司的亚洲扩展计划，也弄清了他们寻找外援的真正原因。\u003c/p>\u003cp>德威特还做了一些让我至今难忘的事。他当着客户的面夸赞我。为什么他不夸夸自己呢？他没有在客户面前炫耀自己从业25年的丰富经验，也没有吹嘘他那杰出的专业知识，而只是跟客户说他为自己的团队有我这样的合作伙伴而感到幸运，还说我是他们前途无量的年轻合伙人之一，也是他们当中工作最努力的一个。这次讨论与众不同，绝对比上一次我和电信公司的会谈精彩得多，这才是建立新关系的一次良好的开始。\u003c/p>\u003cp>一周之后，那家公司再次打电话给德威特，邀请我们去做进一步的探讨，之后又制定了方案。德威特一直和他们合作到八年之后他退休的那一天。如今，他们成了我的终身客户。自从那次会议之后，我非常乐意跟随德威特并向他学习。\u003c/p>","explains":"\u003cp>好的，大家已经阅读完了原文的片段，片段里的这个案例无疑是一个成功的商业案例。\u003c/p>\u003cp>\u003cstrong>互动：\u003c/strong>那我想问一下大家，这个案例成功在哪里呢？\u003c/p>\u003cp>是的，我们看到，当客户提出一个大而全的问题时，德威特反问了一个关键的问题：“那您具体需要了解些什么呢？”\u003c/p>\u003cp>在客户做了具体回答之后，德威特又问了一个问题：“我很好奇，你能具体描述一下你想了解的“内部一起工作”的意思吗？”\u003c/p>\u003cp>通过这两个问题，德威特慢慢问出了客户的真实需求，并与客户建立了良好的关系。\u003c/p>\u003cp>\u003cstrong>强化讲解概念：\u003c/strong>\u003c/p>\u003cp>好的，那么如何运用这种提问的技巧呢。\u003cstrong>我总结有两点：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>询问细节。\u003c/strong>当别人问一个大问题时，不妨追问对方更具体想了解的内容。这时可以提问“你想具体了解哪方面的情况呢？”\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>适时确认。\u003c/strong>比如“你之前是否有对相关情况有所了解呢？”\u003c/p>\u003cp>“对于这个问题，您之前是怎么考虑的呢？”\u003c/p>\u003cp>举一个我遇到的例子，比如之前有朋友微信加了我，问：“你能介绍一下拆书帮吗？我挺好奇的？”你会怎么做呢？我之前可能巴拉巴拉说一通，赵周老师，《这样读书就够了》，拆书方法、分舵活动，等等，之后就没有然后了。\u003c/p>\u003cp>大家想想看，如果运用提问的技巧，我该如何问他呢？\u003c/p>\u003cp>&nbsp;“你之前在哪里知道拆书帮的呢？”\u003c/p>\u003cp>&nbsp;“你参加过拆书帮的线上活动或者线下活动吗？”\u003c/p>\u003cp>“你想了解的是拆书的学习方法还是想参与其中，成为一名引导大家学习的人呢？”\u003c/p>\u003cp>询问到对方的真实需求后，我再来有针对性的介绍，比如拆书方法啦，拆书活动啦，或者是拆书训练营等等。往往通过这些问题，我明确了对方的需求，哪怕是从未见面的只是微信沟通，也与对方建立了更深的链接。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这里需要注意的是，以上的提问技巧特别适合于一些商务的场合，比如给客户介绍方案时，给陌生的朋友推荐产品，或者初次见面的伙伴介绍拆书帮等等。\u003c/p>\u003cp>\u003cstrong>【什么时候问最合适】\u003c/strong>\u003c/p>\u003cp>当你被问到一个总体性问题，而这个问题有可能需要很长的回答时。\u003c/p>\u003cp>当时间很短暂，你又想针对自己的目标做些简短回答时。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong> \u003cstrong>教学习者编剧本A2\u003c/strong>\u003c/p>\u003cp>那么，接下来，我想让大家练习一个具体应用的场景，小伙伴们想象一个商务的场合，可以是一个你们公司的产品介绍，或者是拆书帮的介绍，或者梦想赋能班的介绍，等等都可以，你会如何与对方展开一场对话，记得要运用我们上面的提问技巧，询问细节、适时确认。 \u003c/p>\u003cp>\u003cstrong>请尝试编写一个小剧本，有地点、人物、情节变化和当时双方的对话等。\u003c/strong>\u003c/p>\u003cp>两两组成小组，讨论5分钟，记得把你的提问摘要写在一张纸上\u003c/p>\u003cp>五分钟后我们请人来讲讲他的剧本。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>光头刘，背景：我们确定了一个产品，我的幼儿教育机构最近推出了一款叫“富氢水”产品，这个是一个保健品，主要的作用是调整亚健康，美容养颜和减肥的，作为老师也有推广的目标，所以需要用到提问的方式来引导销售。\u003c/p>\u003cp>角色对话：\u003c/p>\u003cp>光头刘：啰啰，来接小孩啊，我你样子，好像很累耶，是不是最近工作非常忙啊？\u003c/p>\u003cp>啰啰：是的，是有点忙\u003c/p>\u003cp>光头刘：哦，不容易啊，为了这个家庭，你也付出很多啊。你这样天天这么忙，会不会掉进亚健康的状态里面啊？\u003c/p>\u003cp>啰啰：我感觉我已经掉进这个坑了\u003c/p>\u003cp>光头刘：您对您现在的身体感觉怎么样？\u003c/p>\u003cp>啰啰：状态非常差，睡眠也睡不好，非常疲惫。\u003c/p>\u003cp>光头刘：哦哦，非常疲惫。所以，你有没有针对性的做一些调理啊，比如锻炼身体啊，做一些健康的运动啊，或者吃一些保健的药品啊\u003c/p>\u003cp>啰啰：没有哦，都没空去思考这些问题\u003c/p>\u003cp>光头刘：哦，这么忙啊，要记得照顾好自己的身体才能更好的照顾好你的女儿，你看你的女儿那么可爱。要是没有一个健康的身体，你怎么能让她跟你一样健康的成长呢？\u003c/p>\u003cp>啰啰：嗯，是的。\u003c/p>\u003cp>光头刘：如果你真的那么忙，没有时间去锻炼身体的话，可以先从保健品方面入手哦？\u003c/p>\u003cp>啰啰：嗯，是可以考虑考虑\u003c/p>\u003cp>光头刘：你一般平时会吃哪些方面的保健品啊？\u003c/p>\u003cp>啰啰：暂时还没有吃过什么保健品？\u003c/p>\u003cp>光头刘：现在有很多直销公司啊，安利纽崔莱那些，都有很多保健营养品，它主要是针对人的一些微量元素去进行一些调理。我最近也听到一款叫“富氢水”的保健品，听说这个东西还蛮不错的，因为富含了一些有益的物质，其实我们学校的老师都有使用这个，效果还蛮不错的，你要不要了解一下，对美容养颜都有帮助的。\u003c/p>\u003cp>啰啰：哦，那可以啊。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>我提炼了一下两位的对话，光头刘在这个过程中，有提了两个关键问题去询问具体需求：\u003c/p>\u003cp>1、&nbsp;&nbsp; 你之前有没有做过一些调理啊？\u003c/p>\u003cp>2、&nbsp;&nbsp; 你一般平时有用哪些保健品啊？\u003c/p>\u003cp>在这个对话中，还是有不断的通过提问去询问对方的细节和需求，这一点确实运用到了我们今天学到的这个知识点。\u003c/p>\u003cp>另外的一组也讨论了，在面试的环节也可以运用到提问的艺术。\u003c/p>\u003cp>\u003cstrong>拆书家总结：\u003c/strong>好的，我们今天学习了商务场合的开场提问技巧，大家注意到今天我们的重点没有在怎么去推销你的产品，其实这本书的后面也介绍相关的方法，我们今天主要分享的是前面的这个两个环节，询问细节和适时确认，就是明确对方的需求。\u003c/p>\u003cp>\u003cstrong>【A2作业】\u003c/strong>\u003c/p>\u003cp>那么在接下来一周，我希望大家可以尝试运用一下这种提问技巧在你的工作中，对比一下，把你运用这种提问技巧的过程，写下来，发布到我们的微信群中，期待大家的分享，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1490689335000,"updated_at":1490689335000,"ria":true},{"id":1487,"topic":"如何通过提问找到对方的关注度","learn_goal":"用提问的方式找到对方的关注度，从而对你的讲话讲话或建议感兴趣","remark":"当你在台上演讲的时候，听众低着头不配合、提问没有反应；你在部门开会的时候，你的伙伴却在玩手机，对你的讲话根本不感兴趣；你跟客户介绍产品的时候，你讲的口沫横飞，客户却一脸茫然，甚至流露不耐烦的神情；你和家人聊天的时候，一个讲的滔滔不绝，一个却是自顾自做事情。\r\n遇到这类情况，你是生气发火吗？生气发火后的效果怎么样呢？你可能还用过提高你的声音的方法来引起对方的注意力吧？结果又是怎么样呢？你想不想有更好的方法去解决呢？\r\n如果不能在工作和生活中引起对方的关注度，演讲和开会就失去了意义，客户也不会接受你的产品，家庭也会产生很多的矛盾。\r\n那么这本书就告诉你，怎样用正确的提问方式，使对方对你的讲话感兴趣","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家好，我是金家东。今天很高兴由我来给大家做TF3-1的拆书分享。\r\n【学习目标】在跟随我完成本次RIA现场学习后，学习者能够用提问的方式找到对方的关注度，今天我们拆的书叫《提问的艺术》，它的作者是美国的安德鲁.索贝尔 杰罗德.帕纳斯。【事件】当你在台上演讲的时候，听众低着头不配合、提问没有反应；你在部门开会的时候，你的伙伴却在玩手机，对你的讲话根本不感兴趣；你跟客户介绍产品的时候，你讲的口沫横飞，客户却一脸茫然，甚至流露不耐烦的神情；你和家人聊天的时候，一个讲的滔滔不绝，一个却是自顾自做事情。【提问】遇到这类情况，你是生气发火吗？生气发火后的效果怎么样呢？你可能还用过提高你的声音的方法来引起对方的注意力吧？结果又是怎么样呢？你想不想有更好的方法去解决呢？【影响】如果不能在工作和生活中引起对方的关注度，演讲和开会就失去了意义，客户也不会接受你的产品，家庭也会产生很多的矛盾。【解决】那么这本书就告诉你，怎样用正确的提问方式，使对方对你的讲话感兴趣，从而达成双方思路的共振，顺利实现你的目标。","ratings_count":0,"texts":[{"id":4011,"quote":"\u003cp>当一个人开始目光游离，且没有任何问题时，就是时候该做点什么了。你遇到麻烦了。\u003c/p>\u003cp>&nbsp;&nbsp;我正在和一家大型专业服务类公司的共同主席凯瑟琳开会。这次会议早在几周前就定下来了。会议议程的是共同回顾一下我在为他们公司所做的咨询项目的进展情况。我提前做了充足细致的准备，并给凯瑟琳带去了简要的文件。文件清晰精炼地概述了项目的进展情况，足以给人留下深刻的印象。\u003c/p>\u003cp>&nbsp;&nbsp;我们的讨论大约进行了20多分钟，我就发现凯瑟琳心不在焉，整个人坐立不安，根本不在状态。她没有问任何精彩的跟进性问题，更糟糕的是，她的眼睛开始盯着黑莓手机看了。你一定能想象得出当时的情境有多令人沮丧。有人试图表现出一副专心听你讲的样子，却低下头偷偷看他们手中的智能手机。凯瑟琳的心不知道跑哪里去了。\u003c/p>\u003cp>&nbsp;&nbsp;我暂停下来。和这位繁忙的高管坐在一起，时间仿佛凝固了。“凯瑟琳，”我问道，“今天早上我们讨论的重点是什么？”她突然坐直了，警觉了起来。我在等待她的回答。\u003c/p>\u003cp>&nbsp;&nbsp;“嗯，好的，”她开始慢条斯理的回答道，“你的汇报很有帮助，我觉得你的概述和建议很有价值。做得很好！”\u003c/p>\u003cp>&nbsp;&nbsp;“谢谢你的肯定！但接下来我们应该集中讨论什么？”\u003c/p>\u003cp>&nbsp;&nbsp;凯瑟琳抬头看着我，皱着眉摇了摇头，叹息道：“我想我的团队还没有准备好，他们无法跟上进度。”\u003c/p>\u003cp>&nbsp;&nbsp;“请再说详细一点，当你告诉我他们还没有准备好时，你预见到了什么吗？什么事无法继续下去了？”\u003c/p>\u003cp>&nbsp;&nbsp;我们转移了话题，接下来的半个小时我们都在讨论有关她的团队的事。我问了许多有力的问题，凯瑟琳更进一步说明了目前的形势。我提出了一些初步措施，以便让她的团队更好地配合项目的战略指标。我们把其余的有关项目进展的讨论挪到了下一次讨论。我之前为这次会议精心准备的文件看来是派不上用场了。也许它已经达到了应有的效果。\u003c/p>\u003cp>&nbsp;&nbsp;当我起身准备离开的时候，凯瑟琳问我：“我们能在下周就此问题再重新碰一下面吗？你刚才问了许多很专业的精彩问题，你的建议也很棒。我想和你一起好好深入探讨一下。”\u003c/p>","explains":"\u003cp>通过阅读刚才的片段，&nbsp;我们看到了“提问”的重要性，什么时候不说话？什么时候提问？怎么样去提问？每一步都非常重要。\u003c/p>\u003cp>【案例】下面我和大家分享一个场景：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;今天晚上又很晚才到家，这已经是这周的第二次了，老婆一脸生气的坐在沙发上。我赶紧解释是因为陪客户的原因才晚回来的，而且不断的讲这个客户的重要性。然而老婆的脸上只有2个字：不听，不听，不听。。。。。这时候你的错误在于只顾自己的理性解释，不关注对方的心理感受。\u003c/p>\u003cp>这时候我们要像拆页中讲的那样“暂停下来”，只要走过去抱住她，轻轻的对她说：“老婆，刚才你生气的时候在想什么啊？”就像拆页中说的“我们转移了话题”，先把关注度放在对方的身上，让她把自己生气时候的想法说出来，她把心中的气发完了，内心就平静了。\u003c/p>\u003cp>接着我们可以继续问她（保持靠紧她的姿势）：“老婆，你现在是怎么想的啊？”她可能会说：我也理解你是工作的原因，但是你要提前告诉我，或者尽量减少应酬的次数，早点回家陪陪我。让对方把要求讲出来，我们就可以根据对方的要求去想解决的方案，这样的方案对方会更加容易接受。\u003c/p>\u003cp>最后我们可以就家庭的规划，共同描绘一下未来的前景。这是和对方达成了目标的一致性。\u003c/p>\u003cp>【概念】我们讲话“停下来”的目的，是为了倾听对方的真实想法，从而纠正我们的谈话方向，与对方保持一致性。这样才能达成共同的目标。\u003c/p>\u003cp>【具体步骤】所以当我们在侃侃而谈，对方却显得心不在焉或者不耐烦的时候。这时候我们要做的事情是：1、立刻停下自己的讲话。2、我们可以问他：你在想什么呢？3、我们还可以接着问他：你可以把你的想法再详细说一下吗？4、回到客户感兴趣的话题，我们才能拉近与客户的距离，从而达成我们的目标。\u003c/p>\u003cp>【提问、知识点逻辑】这4步，最难的是哪一步呢？我认为第一步“闭嘴”是最难的，对方相信你，你的解释就是多余的，对方不相信你，你的解释更加没有必要。\u003c/p>\u003cp>【边界】这个片段的提问方式仅仅用于对方心不在焉或者不耐烦的时候，对于其他状态的时候，不在讨论范围之内。\u003c/p>","interaction":"\u003cp>【A2】拆书家提问设计（逐字稿）：\u003c/p>\u003cp>&nbsp;&nbsp;在工作或生活中，我们经常会遇到家人间的沟通、你的演讲会、公司或者部门的会议、你和客户的面谈等等，你希望如何的运用以上4个步骤呢？你又希望达成怎样的结果呢？\u003c/p>\u003cp>&nbsp;&nbsp;请分组编一段小故事，写出关键信息就可以了，设计出人物（譬如夫妻）、情节变化（包括：起因{回家晚了，老婆生气}、经过{4个步骤}、结果{夫妻和睦}）和当时双方的对话、动作等，其中部分对话要使用以上4个步骤的提问技巧，摘要写在一张纸上。时间五分钟，五分钟后我们请人站起来来讲讲他的剧本。为什么要用编剧本的方式来设计，从心理学角度，编剧本是心理对照，让自己先在脑海中过一遍，就像运动员在脑海里想练习的动作如同真实的练习一样，可以提高工作或生活中的成功率。请大家现在开始…\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、人物：母子（秦老师分享）\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp;起因：儿子上高二，这次数学考试下降很多。这次放学回家就开始玩电脑，我很生气，上去就把电脑关了，并且把他骂了一顿，结果儿子赌气睡觉，书也没有看。\u003c/p>\u003cp>&nbsp; &nbsp;经过：经过这次拆书学习，我会这样与儿子交流。（1）立刻停止自己的责骂。（2）走过去轻轻摸摸儿子的头，告诉他：妈妈刚刚不应该骂你，你学习压力也大，难得放松一下也可以的。儿子，你现在想什么呢？儿子会告诉他，这次考试不好，心情很差，现在也没办法看书。（3）等他心情平复以后，再接着问他：儿子，你能把你的打算告诉我吗？儿子会说：妈妈放心好了，我制定了学习计划，我会好好努力的。（4）母子就学习计划进行了讨论。\u003c/p>\u003cp>&nbsp; &nbsp;结果：母子双方达成共识，又开心在一起啦。\u003c/p>\u003cp>2、人物：我和客户（马老师分享）\u003c/p>\u003cp>&nbsp; &nbsp;起因：客户来咨询女儿美国留学的事情，我滔滔不绝的把公司的情况、留学的好处讲了一大堆，但是客户低头看手机，对我的讲话不感兴趣。\u003c/p>\u003cp>&nbsp; &nbsp;经过：（1）我立刻停下讲话。（2）我问客户：你是怎么想的呢？客户说：你们的报价太贵了，我一个外甥女在加拿大留学，费用比你们便宜好多。（3）我告诉客户：我们公司也有留学加拿大的项目，的确比留学美国便宜好多，而且你外甥女在那里，你女儿在加拿大也有所照应。接着我问他：你现在有什么想法呢？（4）我们就留学加拿大的事情进行了讨论。\u003c/p>\u003cp>&nbsp; &nbsp;结果：双方开心的签订了加拿大的留学合同。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1480554734000,"updated_at":1487933496000,"ria":true},{"id":1327,"topic":"《提问的艺术》","learn_goal":"学习回答提问的技巧","remark":"当别人问我们问题时，清楚地说明他们具体想知道的问题","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"宋懿玲","city":"贵阳"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我叫宋懿玲，大学学习的音乐教育，一直从事传统饰品的手工制作，喜欢阅读也热爱学习，对于拆书帮的学习方法很喜欢，希望通过拆书帮的学习在提升自我价值的同时也能结交到更多志趣相投的小伙伴共同学习成长！拆书的＂拆＂不是＂拆散＂，是转化和内化。＂拆书＂，就是强调把图书的知识拆页转化为学习者的能力，是指把图书的知识片段转化成学习者自己的能力。是一种学习方法论，适用于提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心。要把知识关联学习者的经验、规划具体的运用。拆书法分应用与个人学习的拆书帮便签读书法，和应用于组织学习的拆书帮现场学习法（也叫RIA现场学习法）两种。R环节是阅读原书拆页。I环节是拆书家对原文知识拆页的讲解和对现场学习者的引导。A环节就是拆为己用了，有3种做法：A1激活学习者经验，A2催化学习者应用，A3促动学习者现场演练。 这是拆为己用的3个核心动作。成人学习是要以自己为中心，而最好的方法是教会别人。而拆书帮则是学习爱好者社群，表现为各地拆书帮分舵及拆书俱乐部，为公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":3771,"quote":"\u003cp>|提问的心得|\u003c/p>\u003cp>　　你想具体了解我哪方面的情况呢？\u003c/p>\u003cp>　　当别人问我们问题时，我们很少要求对方清楚地说明他们具体想知道什么。你有没有见过有些人就一个错误的问题一口气回答了 5分钟？他们认为自己听懂了，但回答的却并不是对方真正想要问的问题。这是多么尴尬的一件事！\u003c/p>\u003cp>　　什么时候问最合适\u003c/p>\u003cp>　　● 当你被问到一个总体性问题，而这个问题有可能需要很长的回答时。\u003c/p>\u003cp>　　● 当时间很短暂，你又想针对自己的目标做些简短回答时。\u003c/p>\u003cp>　　你还可以这样问\u003c/p>\u003cp>　　● 你对我经历中的哪部分感兴趣？\u003c/p>\u003cp>　　● 你希望我具体介绍哪方面的情况？\u003c/p>\u003cp>　　● 在我回答你的问题之前，你是否已经对我们的公司有所了解了？\u003c/p>\u003cp>　　● 如果我先介绍一些像你这样的客户的案例来开始我们今天的介绍，你觉得如何？\u003c/p>\u003cp>　　接下来这样问\u003c/p>\u003cp>　　● 这样能回答你的提问了吗？\u003c/p>","explains":"\u003cp>在现在社会，我们获取信息最为常用的，最快捷，最高效的方法就是提问与回答，在提问与回答中，提问者常常发生词不达意的情况，回答者是用耳朵听，光听也会有误解，这也会造成回答者回答与提问无关的内容。这样一来提问者即得不到满意的回答而回答者也是无言以对了。语言本来就是误会的根源，做不到有效沟通，就是浪费时间。在这种情况下怎么样才能做到能让对方满意的有效回答，是值得思考的，有一种简单的方法能改变哪就是＂转换＂，也就是转换角色，让回答者转换为提问者，从而明确提问者的问题，在把问题在具体化。哪接下来转换应当怎么做在什么情况下来转换，原文片段给出2点最合适时间。\u003c/p>\u003cp>　　1.当你被问到一个总体性问题，而这个问题有可能需要很长的回答时。\u003c/p>\u003cp>　　2.当时间很短暂，你又想针对自己的目标做些简短回答时。\u003c/p>\u003cp>　根据以上两点判断以后，我们可以明确在什么时候转换角色才能达到有效回答，哪在明确转换以后，就要将问题更具体化，怎么具体，以下4点提问法就很明确，（也可根据自身情况来发出明确的提问）：\u003c/p>\u003cp>　　1.你对我经历中的哪部分感兴趣？\u003c/p>\u003cp>　　2.你希望我具体介绍哪方面的情况？\u003c/p>\u003cp>　　3.在我回答你的问题之前，你是否已经对我们的公司有所了解了？\u003c/p>\u003cp>　　4. 如果我先介绍一些像你这样的客户的案例来开始我们今天的介绍，你觉得如何？\u003c/p>\u003cp>　　把问题具体化之后，在最后可以这样问；＂这样能回答你的提问了吗？＂把对方引入到你具体的问题里面来，明确他想要的回答，这样你的回答就很轻松了。\u003c/p>\u003cp>根据原文片段指出的以上几点，合理转换就能避免无效的提问与回答了。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>2016年7月初，我遇到一位对我工作室比较感兴趣的朋友，他提问到＂我知道你们是做和传统文化有关的东西，我大概看了下，很感兴趣，但你们范围挺广，具体做什么我还是很模糊！能介绍一下吗＂面对问题我比较棘手，我们只要传统文化的都做，也没规划过，接下来，我从服饰到头饰到传统婚礼礼仪等等，都作了一些简短介绍，整个过程用了1个多小时的时间，结果还是没让他完全明白，反而让他感觉更混乱了。\u003c/p>\u003cp>A2\u003c/p>\u003cp>2016年9月24号实体开业，精简工作室介绍内容，对于提问时，转换角色，转换为反提问者，在将问题具体化。面对提问做到以下几点：\u003c/p>\u003cp>　　1.提问者哪部分感兴趣？\u003c/p>\u003cp>　　2.提问者希望我具体介绍哪方面的情况？\u003c/p>\u003cp>　　3.在我回答提问者问题之前，他是否已经对我们的有所了解了？\u003c/p>\u003cp>4.明确自己工作内容的范围\u003c/p>\u003cp>5．及时开会来解决讨论\u003c/p>\u003cp>&nbsp;我今天的分享到此结束谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479356477000,"updated_at":1479363075000,"ria":true},{"id":1222,"topic":"如何提问让别人接受我们的产品或建议","learn_goal":"通过提问训练让别人接受我们的产品或建议","remark":"这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。让我们一起跟随大师，做一个智者，用提问来改变自己的人生。","level":"TF2-2","duration":18,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"今天我们拆的书叫《提问的艺术》，它的作者是美国的安德鲁.索贝尔 杰罗德.帕纳斯。\r\n这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。\r\n你有没有面对客户滔滔不绝，却忘了客户的感受？有没有面对销售的瓶颈而一筹莫展？想知道通过怎样的提问能够让你的伙伴做的更好吗？怎样用提问去探寻客户的真实需求？一共320个问题，告诉你用正确的提问方式解决你的一切问题。","ratings_count":0,"texts":[{"id":3473,"quote":"\u003cp>&nbsp; &nbsp;你们准备购买吗？你之前听说过这样的说法吗？“无论我们如何费尽口舌地不断说服他们，他们却还是不会掏钱购买，最后只能无果而终。”当听到人们准备购买时，那是多么让人兴奋的一件事。买家会将手伸向你，对你们之间的互动表现出浓厚的兴趣。如果以下4个条件都不存在的话，他们就不会购买你的产品、服务或创意。\u003cbr>\u003c/p>\u003cp>1、买家是否有问题要问或是否有提问的机会？\u003cbr>你应该这样问对方：你现在的成本开支主要来源于哪里？如果你不能解决这个问题，会给你带来什么样的结果？你认为这次机会有价值吗？这是你最优先的考虑之一吗？\u003cbr>2、买家是否有问题要解决？\u003cbr>你应该这样问对方：谁有问题要解决？你负责解决这个问题吗？谁对解决这个问题所需的费用有决策权？在这件事情的解决上谁需要介入？\u003cbr>3、买家是否对目前的承诺或改进明显不满？\u003cbr>你应该这样问对方：这就是你受够了的主要原因吗？你是否还有要补充说明的？你为什么觉得现在是时候需要新的资源来取而代之了？你的努力是否有效解决了这个问题？\u003cbr>4、买家信任你并相信你就是他们想要的最佳人选吗？\u003cbr>你应该这样问对方：你正在寻找其他什么样的解决方案？你是如何评价我们在这一领域的能力的？你对我们或我们的方案有什么顾虑吗？\u003c/p>","explains":"\u003cp>在别人接受你的产品或建议之前需要通过提问解决他们4个问题：1、他的需求是什么？2、这个产品或建议对他是否有利？3、他的痛点在哪里？4、他是否信任你？\u003c/p>\u003cp>伙伴们，可能你们感觉要问4个问题太麻烦了，而且比较书面化，我们之前的做法是：介绍了产品以后，直接问客户买还是不买，同意还是不同意？这样多省事啊。事实上，不这么做会更麻烦。因为没有通过这4个问题的提问，就找不到别人为何要接受你的产品或建议的原因，也就难以达成结果，造成了时间精力上的浪费。总之，虽然麻烦，但是值得。\u003c/p>\u003cp>我曾经也是和你们一样的想法，但是自从用了以上的方法后，感觉成功率提高了很多：上周一和一个投资客户见面，我按照原书拆页的建议，问下面4个问题：（1）你有几种投资增值的方式？这是找到需求，即倾向于什么样的投资方式。（2）是你自己操作的吗？这是找到是否与他的利益有关。（3）你对这几种投资方式满意吗？这是找到痛点，找到他对其他公司不满意的地方。（4）你对我们公司的投资方案有什么顾虑吗？这是找到信任感，是否信任你，信任你的公司？。结果成功做了一笔投资。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分步催化1）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：伙伴们，请想一想，最近一个月内，在一个休闲的茶庄，耳边有轻轻的音乐，你和你的朋友或家人，喝着茶，聊着天。你是想让他接受你的产品？还是接受你的建议？或者仅仅是接受你的一个想法？请大家思考并想出具体情境后，加工一个具体的例子，说明今后你有可能会遇到的一个场景，把这个场景写下来。给大家1分半钟。\u003c/p>\u003cp>好了的伙伴向我举手示意\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003c/p>\u003cp>1、和领导沟通人效提升项目的思路。\u003cbr>\u003c/p>\u003cp>2、让客户接受你的咨询项目。\u003c/p>\u003cp>3、来公司办理出国留学的学生，我想说服学生父母同时办理签证。\u003c/p>\u003cp>4、下周一和天宁区一个客户确定读书会的方案。\u003c/p>\u003cp>【A2】催化应用（分步催化2）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：伙伴们设想一下，在最近的一个月内，我们再回到上面的场景，你是如何按照原文拆页的4个提问方法，用正确的提问方式让别人来接受你的产品或者建议的？\u003c/p>\u003cp>下面，给大家2分钟的时间写在便签纸上，写好后每位伙伴在各自的小组内交流分享。（给大家4分钟时间。）\u003c/p>\u003cp>最后，每组分别请一位伙伴用1-2分钟的时间给我们做分享。\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003c/p>\u003col>\u003cli>\u003cp>让客户接受你的咨询项目：\u003cbr>\u003c/p>\u003cp>（1）您为什么想咨询这个项目呢？找到需求。\u003c/p>\u003cp>（2）是您想做这个项目还是帮别人咨询？找到是否对他有利。\u003c/p>\u003cp>（3）您对以前同样的项目满意吗？您希望通过我们这个项目解决什么问题？找到痛点。\u003c/p>\u003cp>（4）我这样的方案可以接受吗？找到是否对我有信任感。\u003c/p>\u003c/li>\u003cli>\u003cp>如何说服学生的父母同时办理出国签证？\u003c/p>\u003cp>（1）您为什么要送孩子出国留学呢？找到需求。\u003c/p>\u003cp>（2）签证的有效期是10年，你们什么时候去美国看孩子都可以的。找到对他有利的地方。\u003c/p>\u003cp>（3）孩子学业太忙回不来，父母和孩子上方会想念的。而且你们不想参加孩子的毕业典礼吗？找到痛点。\u003c/p>\u003cp>（4）你们有绿卡，对孩子的留学签证的成功帮助很大啊。通过有效说服，产生信任感。\u003c/p>\u003c/li>\u003c/ol>\u003cp>非常感谢两位伙伴的精彩分享，也谢谢在座的各位伙伴，今天我的分享到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1477804689000,"updated_at":1477804689000,"ria":true},{"id":1207,"topic":"如何问“五个为什么”","learn_goal":"如何用五个为什么找到问题的核心","remark":"《提问的艺术》是美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯共同著作的。这本书自2014年1月出版，现在已经是第10次印刷了，也是“拆书帮”推荐的读本。","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位小伙伴，大家晚上好！我是刘云汉。今天很高兴和大家一起进行TF2-2的拆书。在跟随我完成本次RIA现场学习后，我们就能学会在合适的时机追问五个为什么，了解对方的真实意图、发现真正的原因。\r\n今天我拆的这个片段来自美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯共同著作的《提问的艺术》。这本书自2014年1月出版，现在已经是第10次印刷了，也是“拆书帮”推荐的读本。\r\n在本书第4页，美国畅销书《基金之父》作者罗恩.罗宾荪是这样介绍本书的：“《提问的艺术》是一本适合人人都读的书。安德鲁和杰罗德在书中告诉我们如何以一种”最可能引出具有深刻见解答案的方式”提出”最好的问题”。另外，作者还提供了上百个你曾经渴望去问的问题。这本书能够让你的会谈比以前更有成效。”\r\n学会了这本书，我们可以在事业、生活的各种场合，随时展开富有成效的对话、帮助解决很多沟通问题，与家人好友还可以深入对话，推动情感交流。","ratings_count":0,"texts":[{"id":3451,"quote":"\u003cp>当有人说“我想要这样”的时候，你需要去发现他们真正需要的是什么。你可以通过问“为什么”去做到这一点。你可以问五遍这个问题。从“你为什么想这样做”或者“为什么会发生”开始问起。\u003c/p>\u003cp>“为什么”这个问题如果用错了时间和对象的话，就将变成一个可怕的问题。它听上去像是暗藏着潜在的反对之意，像是批评、挑刺和找茬儿。它会引起对方的反感。\u003c/p>\u003cp>“为什么”也能成为一个有力的问题。它能够让被问的人更加深入的思考他们正在做的事，并帮助他们直达事情的核心。“为什么”能够让我们停下来反思，并检查我们的行动，从而避免机械的一路向前冲。\u003c/p>","explains":"\u003cp>好，大家都看好了—我可以先问一下：在座的有在企业做技术的，了解“五个Why”的方法的吗？\u003c/p>\u003cp>（大家回答：没有），那我给大家举个例子：（手指头顶，刚刚有水流声）。“为什么有水流声”“哪里漏水了”“为什么漏水？”“有个阀门质量不好”“为什么会买质量不好的？”“因为价钱便宜”“为什么因为价钱便宜就买质量不好的东西？”“因为我们也没有这种采购管理的制度”—好，真正的原因出来了：没有采购管理制度。---五个为什么，就是让我们通过连续追问“为什么”，了解对方真实的想法；或者帮助对方了解自己真实的需求，达到自我认知的目的\u003c/p>\u003cp>可能有人会说：五个why用于工作的根因分析可以，怎么能用于谈话呢？这样连续问别人，不会显得“咄咄逼人”吗?问几个问题就能帮人“自我认知”？做不到吧！\u003c/p>\u003cp>真的做不到吗？正如这段文字所说：“为什么”也能成为一个有力的问题。它能够让被问的人更加深入的思考他们正在做的事，并帮助他们直达事情的核心。“为什么”能够让我们停下来反思”。如果我们学会在适当的时候、敢于问出来，这将是个“有力的问题”。\u003c/p>\u003cp>我在日常的财务审批工作中，是很喜欢问“为什么”的，问得最多的是“为什么不比价？”“为什么不集中招标？”前几天，设备部顾经理找我要买滤网等零配件，这已经是今年第N次采购了。我就问他“为什么不集中招标？”“因为没有年用量的数据”“为什么不用以前的历史记录作参考呢？”“因为以前都是零星采购的没有记录”“为什么不记录呢？”“这些都是设备管理的基础资料啊，因为没有人要求呢？”“因为没有考核”“为什么需要考核呢？”“考核的数据肯定是领导重视的，这一块以前就没有重视过。”\u003c/p>\u003cp>你们看，通过这五个“为什么”的询问，我和他都了解到：真实的原因还是管理层对这项工作的重视程度不够。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：下面请大家想一想：我们在日常生活中有没有可以应用这五个“为什么”的情况，比如某个客户总在找借口就是不肯签单？比如你们对小孩子的教育有不同的观点？比如，今天我们一起来拆书，有没有想过为什么？……\u003c/p>\u003cp>请把这样的情况写在纸上，2分钟，写好的请举手示意\u003c/p>\u003cp>学习者案例记录： \u003c/p>\u003cp>同学A：老公想生二胎；\u003c/p>\u003cp>同学B：和老师沟通时，他突然有些不快情绪…..\u003c/p>\u003cp>拆书家提问设计（逐字稿）：好，现在我们就尝试一下，选择“你今天为什么会来这里”这个话题，两两一组，应用五个“为什么”的方法，一个人提问，一个人回答。请提问者用“为什么”提出有价值的问题，不断挖掘，一直找到被问者的真实需求，通常是价值观、人生观方面的问题，比如自我实现、奉献等字眼。\u003c/p>\u003cp>说明几点：一是“五个为什么”不一定就是五个，可多可少；二是五个“为什么”的“why”根据情况有时候变成“What”也是可以的；三是这里对提问双方的要求都比较高，允许双方有思考时间。请大家先演练一下，5分钟。最后我们请每一组报告一下各自的成果。\u003c/p>\u003cp>（5分钟以后）。好，我看大家都完成了。请各小组分享一下你们的案例。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>同学A组：“文丽，今天晚上你为什么会来这里？”\u003c/p>\u003cp>“因为我想加入拆书帮”\u003c/p>\u003cp>“为什么想加入拆书帮呢？”\u003c/p>\u003cp>“因为据我之前的了解，拆书帮对我会有很大的帮助。”\u003c/p>\u003cp>“有什么帮助呢？”“对我的个人成长方面会有很大的提升。”\u003c/p>\u003cp>“为什么你会有个人要提升或者成长的需求呢？”\u003c/p>\u003cp>“首先是工作需要不断的更大的进步，其二是未来自己的职业发展做储备”\u003c/p>\u003cp>“为什么会对工作提升、职业发展储备有这样的考虑呢？”\u003c/p>\u003cp>“因为其中之一是我读书有点慢，其二是读了不会学以致用。拆书帮可以帮助我解决这两个问题。”\u003c/p>\u003cp>（3分钟后）好，谢谢各组的分享！我们开始的问题只是“你为什么会来这里”，通过问“五个为什么”，我们了解发掘到了我们各自内心的真实需求：拆书帮能够帮助我们每个人提升个人技能、积累知识、解决读书慢的问题、使我们学以致用、帮助我们做好未来规划等。\u003cbr>\u003c/p>\u003cp>怎么把“五个为什么”应用到我们的工作生活中呢？大家都掌握了吧？（纷纷发言：“随时都可以用！”）那我们就从刚才大家写的题目开始—因为时间有限，我们只是挑了一个做范例—请大家回去问自己或者和家人，用“五个为什么”解决你的问题！\u003c/p>\u003cp>今天我的TF2-2拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1477573580000,"updated_at":1477639908000,"ria":true},{"id":1206,"topic":"如何提出封闭式问题避免兜圈子","learn_goal":"在谈话对方犹豫不决的时候，学会问明确的封闭问题“是还是不是”","remark":"《提问的艺术》是美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯共同著作的。这本书自2014年1月出版，现在已经是第10次印刷了，也是“拆书帮”推荐的读本。\r\n在本书第4页，美国畅销书《基金之父》作者罗恩.罗宾荪是这样介绍本书的：“《提问的艺术》是一本适合人人都读的书。安德鲁和杰罗德在书中告诉我们如何以一种”最可能引出具有深刻见解答案的方式”提出”最好的问题”。另外，作者还提供了上百个你曾经渴望去问的问题。这本书能够让你的会谈比以前更有成效。”\r\n学习了这本书，我们可以在事业、生活的各种场合，随时展开富有成效的对话、帮助解决","level":"TF2-1","duration":17,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫刘云汉，很高兴今天和大家一起完成2-1的拆书活动。\r\n在跟随我完成本次RIA现场学习后，学习者能够在谈话对方犹豫不决、要弄清对方是否全身心投入的时候，学会问明确的封闭问题“是还是不是”。\r\n今天我要拆的片段来自这本书《提问的艺术》。这是美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯共同著作的。这本书自2014年1月出版，现在已经是第10次印刷了，也是“拆书帮”推荐的读本。\r\n在本书第4页，美国畅销书《基金之父》作者罗恩.罗宾荪是这样介绍本书的：“《提问的艺术》是一本适合人人都读的书。安德鲁和杰罗德在书中告诉我们如何以一种”最可能引出具有深刻见解答案的方式”提出”最好的问题”。另外，作者还提供了上百个你曾经渴望去问的问题。这本书能够让你的会谈比以前更有成效。”\r\n学会了这本书，我们可以在事业、生活的各种场合，随时展开富有成效的对话、帮助解决很多沟通问题，与家人好友还可以深入对话，推动情感交流。","ratings_count":0,"texts":[{"id":3450,"quote":"\u003cp>当你试着让某人在某件事上做出明确回答时，或者是促使他们下定决心时，有许多提问方式。有温和的请求的提问方式，如“你觉有得...如何”。但有时候，你不能给对方留有动摇的余地。\u003cbr> 当你想获得直接而由衷的回答时，封闭式问题会很有成效：用恰当的方式有目的地提出一个封闭式问题，是还是不是，对于提问者来说，是力量和高要求的最好结合。\u003c/p>","explains":"\u003cp>好，大家都看好了—内容不多，看上去容易理解：就是在沟通中，当你看到对方犹豫不决的时候，或者某个重要任务，需要搞清对方是否愿意全身投入的时候，用封闭式的提问方法“是还是不是？”引发对方思考、并下定决心，作出承诺。\u003c/p>\u003cp>如果不这样做呢？那么很可能我们各说各的理由，大家都有道理，于是不停地绕圈子，讨论了半天，也没有一个结果，沟通效率很差。\u003c/p>\u003cp>我今天是第二次选择这个片段了。为什么呢？有两个原因：一是我作为财务经理，往往坚持原则、得罪人多，平时沟通就比较温和，喜欢用商议的形式，以示尊重、合作，但是过于温和就容易被别人以各种理由“绕圈子”，上次拆书以后，我知道了问封闭式的问题其实也是帮助对方下决心，因此我有所变化、但还是没有能应用自如，被“绕圈子”得不到明确支持的情况时有发生，我还需要强化这种理念；二是推己及人，我想很多小伙伴或许有同样的问题，我希望帮助大家了解、掌握这种方法，提高沟通效率。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：下面请大家也回忆一下我们在工作、生活中，和同事，或者下属，甚至家人、亲戚，在交流的过程中有没有出现过这样的情况：你有一件事，需要得到他的支持。你主动过去找到他，谈了这件事怎么怎么重要，希望得到他的支持。然而他却是含糊其辞、讲了各种困难，就是不给你一个明确的答复，然后你们不停地在那里绕圈子……\u003c/p>\u003cp>请把这样的经历简单地写到纸片上，2分钟时间，写好的请举手示意。\u003c/p>\u003cp>学习者案例记录：（马文丽）我在接待客户、预约面谈孩子的留学方案时间的时候，很多家长在电话里面嗯嗯嗯的听我说，然后就说我们再考虑考虑，就是不明确来还是不来。\u003c/p>\u003cp>拆书家提问设计（逐字稿）：好，现在请大家想一想：如果还是在当时的情境下，让你换一个封闭式的问题来提问，你会怎么问，能够达到更好的效果呢？\u003c/p>\u003cp>请在小纸片的下面写出来。1分钟。写好的请举手示意。\u003c/p>\u003cp>（1分钟以后）。好，我看大家都完成了。请大家在小组内分享一下你们的案例。\u003c/p>\u003cp>学习者案例记录：（马文丽）以后，碰到客户在电话里面再这样的时候，我会说：我也知道您对孩子的教育非常重视，对我们公司的服务也很认可，才来找我们的。您也希望当面了解情况会更加具体、贴近您孩子的情况。这个星期六我们方便，您来还是不来？\u003c/p>\u003cp>（6分钟后）好，今天我的TF2-1拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1477573366000,"updated_at":1477573366000,"ria":true},{"id":1203,"topic":"了解为什么你该这样问","learn_goal":"学习如何通过提问找到客户的关注点","remark":"这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。让我们一起跟随大师，做一个智者，用提问来改变自己的人生。","level":"TF2-1","duration":17,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"今天我们拆的书叫《提问的艺术》，它的作者是美国的安德鲁.索贝尔 杰罗德.帕纳斯。\r\n这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。\r\n你有没有面对客户滔滔不绝，却忘了客户的感受？有没有面对销售的瓶颈而一筹莫展？通过怎样的提问能够让你的伙伴做的更好？怎样用提问去探寻客户的真实需求？一共320个问题，告诉你用正确的提问方式解决你的一切问题。","ratings_count":0,"texts":[{"id":3447,"quote":"\u003cp>（p74）我们今天讨论的重点是什么？\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; 如果你所谈论的事情不能与谈话对象最关心的诉求相吻合的话，那么他们将会表现得心不在焉。如果你能将谈话的焦点放在对对方最重要的事情上，那对提高你们关系的密切性和影响力具有意想不到的作用。\u003c/p>\u003cp>&nbsp; &nbsp; 什么时候问最合适？\u003c/p>\u003cp>&nbsp; &nbsp; 1、在和客户或老板讨论进展情况的会议上。\u003c/p>\u003cp>&nbsp; &nbsp; 2、在做销售定位时。\u003c/p>\u003cp>&nbsp; &nbsp; 3、当你和爱人或关系密切的人在一起时。\u003c/p>\u003cp>&nbsp; &nbsp; 你还可以这样问\u003c/p>\u003cp>&nbsp; &nbsp; 1、你今天想谈点什么？\u003c/p>\u003cp>&nbsp; &nbsp; 2、你在想什么？\u003c/p>\u003cp>&nbsp; &nbsp; 3、只剩20分钟了，还有什么是我们今天应该讨论却被漏掉的？\u003c/p>\u003cp>&nbsp; &nbsp; 接下来这样问\u003c/p>\u003cp>&nbsp; &nbsp; 1、你能就那件事再多说一点吗？\u003c/p>\u003cp>&nbsp; &nbsp; 2、那件事背后的情况是怎样的？\u003c/p>\u003cp>&nbsp; &nbsp; 3、为什么现在这对你很重要？\u003c/p>","explains":"\u003cp>当我们面对客户在侃侃而谈的时候，客户却显得心不在焉。这时候我们要做的事情是：1、立刻停下自己的讲话。2、我们可以问他：你在想什么呢？3、我们还可以接着问他：你可以把你的想法再详细说一下吗？4、回到客户感兴趣的话题，我们才能拉近与客户的距离，从而达成我们的目标。\u003c/p>\u003cp>&nbsp; &nbsp;我们有没有听课的时候老师讲的很枯燥，下面的人都在玩手机的情况？有没有和一个朋友聊天的时候，你朋友一个人在滔滔不绝的讲，你感到很厌烦，却又不好意思打断他的讲话的时候？同样你滔滔不绝的讲话，也会引起别人的厌烦。因为客户朋友对你的讲话不敢兴趣而不会听你说，你不但失去了这次和客户接近的机会，相信以后也没有这个机会了，这样你就会失去一份订单、或者失去一个朋友、或者失去一个合作机会、或者失去一个演讲的效果。所以我们这样做虽然麻烦还是很必要的。\u003cbr>&nbsp; &nbsp;&nbsp;上周和一个企业的人事经理面谈关于“企业培训计划”的事情，在介绍我们公司的培训体系和计划的过程中，我看见他有心不在焉的情绪，就立刻停下来问他：你是怎么想的呢？他说自己的公司还没有这样的培训预算。我接着问他：你能够详细的讲一下你的具体想法吗？他说：公司现在没有培训部门，也没有培训专员，只想先从新员工开始培训，让他们对企业的制度和经营有所了解，根据这次培训后的效果，再制定下一步培训计划。然后我针对他公司的具体情况进行交流，从而双方制定了符合他们公司实际情况的初步培训计划。\u003c/p>","interaction":"\u003cp>A1激活经验（显像提问）\u003c/p>\u003cp>拆书家提问设计（逐字稿）:\u003c/p>\u003cp>&nbsp; 伙伴们，有没有遇到这种情形：当我们面对客户侃侃而谈，恨不得把我们所知道的统统告诉客户。而客户一言不发地坐在那里，脸上是一片茫然；或者客户在自顾自的看手机，根本不在听你的讲话。我相信这样的结果应该可想而知的。\u003c/p>\u003cp>&nbsp; 请想一想，你最近一次这样不好的交流沟通或者培训行为发生在什么时候？是什么事情？请反思一下你与客户沟通不好的这个场景，用便签纸记录下来。给大家1分半钟。\u003c/p>\u003cp>&nbsp; 好了的伙伴向我举手示意.\u003c/p>\u003cp>学习者案例记录（逐字稿）：\u003c/p>\u003cp>1、客户带孩子来咨询美国留学的事情，学生的姐姐在加拿大读书，到了现场，我主动介绍留学优势、国家概况等，讲了半个多小时。客户明显没有认真听讲，结果没有达成目标。（马文丽）\u003c/p>\u003cp>2、周二公司开例会，我组织的，没有公司的其他高层领导参加，我也没有收手机。结果出现汇报的人在汇报，其他人在看手机。（独独）\u003c/p>\u003cp>A1+（反思加工）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：如果时光可以倒流，让你再次回到那个场景，用原文拆页的方法，你会怎么做呢？\u003c/p>\u003cp>&nbsp; 下面，给大家2分钟的时间写在便签纸上，写好后每位伙伴在各自的小组内交流分享。（给大家4分钟时间。）\u003c/p>\u003cp>&nbsp; 最后，AB两组各请一位伙伴分别用1分钟的时间给我们做分享.\u003c/p>\u003cp>学习者案例记录（逐字稿）：1、（马文丽）立刻停下来，问：你在想什么呢？客户说兴趣不大。接着再问：那你是怎么看待孩子的留学的呢？客户谈了孩子姐姐留学在国外的事情。最后我们就孩子姐姐的留学情况交流了很长时间，并且对加拿大留学的情况表示了兴趣。\u003c/p>\u003cp>2、（独独）（1）立刻让汇报的人停下来。（2）问看手机的人：你对他的汇报有什么想法或者看法呢？（3）接着问:你能够详细地说一下你的建议吗？我们自己能够做到的是什么呢？（4）最后问问他们有什么需要解决的，针对他们的问题开始讨论。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1477544648000,"updated_at":1477544648000,"ria":true},{"id":655,"topic":"要去解决问题，而不是去消除批评？","learn_goal":"顺利通过2-1","remark":"是否有遇到例会中各部门各执一词，争论不休，生活中小伙伴对你抱怨不停，你的反应是什么呢？是加入到争论中，继续表述自己的观点，还是不发表言论，让时间解决问题，本周让我们一起拆解片段“要去解决问题，而不要去消除批评”，从而机智的回应批评。\r\n","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"刘红艳","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，今天我要拆解的书目是安德鲁•索贝尔、杰罗德•帕纳斯的《提问的艺术》，亚马逊商业类图书top100就包含此书，施耐德CEO,美国前总统克林顿新闻发言人，以及百利公司创始人都给这本提问的艺术很高的赞誉。书中的案例都是真是故事，所以很生动，具有带入感，大家生活中有没有遇到下面情景，1、你爱人或者对象抱怨：你根本不知道我要什么，从来不关心我，你不懂我，2、参加的会议课程拖延，你不停的看着手表，算着时间，3、现在做的工作，或者学习的专业，不是自己喜欢的，大家面对以上的情况都是怎么处理的呢？大家可以去此书中寻求答案，本书用320个问题为我们揭示了商业、人生的精髓，接下来我们分一下组，3人一组，开始我们的拆解。","ratings_count":0,"texts":[{"id":2025,"quote":"\u003cp>请大家用2分钟时间阅读原文拆页，看完请举手示意。\u003c/p>\u003cp>&nbsp; &nbsp; 比尔咆哮、抱怨和批评了近25分钟。他不断抱怨那个他们正在进行的项目没有结果。他指责合伙人的自满以及他们太关注于内部的那些事了。但很显然，他并没有提及事实，那就是他们所面临的资金缺口。他也没有提及他们应该从哪里入手，而合伙人应该做哪些改进。\u003c/p>\u003cp>离会议结束还有5分钟，我轻轻地插了一句：“比尔，我能问你一个问题吗？”\u003c/p>\u003cp>“恩，可以。”他不屑地回答道。\u003c/p>\u003cp>“当你面对年轻的合伙人时，你认为什么才能够建立起一种紧密的客户关系，也就是你希望他们应该多做些什么？”\u003c/p>\u003cp>之后，大家沉默了片刻。比尔急切地说道：“恩，这是个好问题！”之后比尔又大声的说：“哎！现在你已经把我拉回正轨了！”他的声音里夹杂着几许发泄后的兴奋。又停顿了一会儿，他补充道：“恩、、、、、、、好，让我们言归正传。”\u003c/p>\u003cp>接着他开始说他希望看到的改变：“他们需要一张像你发送给我的那种导图。是的，是最上面的一页开始。我很喜欢它，我认为他们有三件事情需要做的更好。”他不在咆哮了，怒气也逐渐消失了。突然之间，就像上帝指使一样，暴风雨停止了、海平面又重新恢复了平静。这时，我们才真正进入关于这些事情的实质性讨论中。\u003c/p>\u003cp>人们经常抱怨别人并坚持让他们做出改变。你应该通过问这个问题将他们从批评上拉回到解决问题的轨道上来，“你希望他们应该多做些什么？”\u003c/p>\u003cp>什么时候问最合适\u003c/p>\u003cp>l&nbsp; 当别人抱怨工作时\u003c/p>\u003cp>l&nbsp; 当某人遭遇到比人的挑剔和批评时\u003c/p>\u003cp>你还可以这样问\u003c/p>\u003cp>l&nbsp; 如果你能让别人做出一件完全不同的事—采取能对行为产生巨大影响的行动的话，你希望那将是什么？\u003c/p>\u003cp>l&nbsp; 你希望他们做出什么样的改变？\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 有一家酒店，是集洗浴、餐饮、住宿于一体的公司，某一天的例会，讨论解决客人跑单问题，会议一开始，总经理开始发话，最近怎么回事，总有客人跑单，怎么跟的单子，这都是第几次了，看看前台结账现在挂着的，你们自己垫付吗？各部门经理，你们一天天都在干什么？这要不是财务查出来，你们还不知道呢吧，各部门经理默不出声，总经理开启了抱怨模式，就这样几十分钟过去了，轮到各部门说话了，各部门经理也开始喊冤，觉得自己每天也很辛苦，自己也不愿意发生这种事，你一句，我一句，会议还停留在问题上，时间浪费了，问题也没有得到解决。如果当时有人问总经理，你希望各部门应该多做什么？总经理的思路应该和我们原文片段的主人公一样回到正轨，即各部门需要怎么配合，防止跑单现象的再次发生，一种是消除批评、反击、解释，一种是解决问题，问对方“你希望他们应该多做什么？”，结果完全不一样，生活中我们可能也会听到身边的伙伴抱怨，领导不好，同事难相处，班干部除了评定各种奖金的时候积极，平时基本不管事，领导抱怨下属执行力不强等，我们都可以用刚刚看到的这句“你希望他们应该多做什么？”去回应\u003c/p>","interaction":"\u003cp>A1&nbsp;&nbsp; 拆书家提问设计（逐字稿）：最近一次看到身边伙伴生气、不开心、甚至愤怒，是什么时候？当时听到的抱怨、批评是什么？请想一想在小组内分享。\u003c/p>\u003cp>学习者案例记录：闺蜜抱怨男朋友，周末没时间陪自己，周内发微信也没有及时回复，自己觉得是不是男朋友不喜欢自己了，心里很难过。\u003c/p>\u003cp>A2&nbsp;&nbsp; 拆书家提问设计（逐字稿）：刚大家都有回忆自己最近一次面对的抱怨、批评是什么，以及当时自己的反应，如果再遇到这样的情况，怎样应用今天学到的“你希望他们应该多做什么？”去更好的回应，请每位小伙伴将上面的案例重新加工，并在组内分享。\u003c/p>\u003cp>学习者案例记录：下属抱怨客户，自己一般是听完员工的抱怨，然后问员工，如果你是客户你怎么想的，应用今天的主题，就可以问员工你希望客户多做什么？引发员工的思考，考虑是自己沟通执行的问题，还是我们的客户确实难缠。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1469972672000,"updated_at":1469972672000,"ria":true},{"id":508,"topic":"如何通过提问让别人接受我们的方案","learn_goal":"通过围绕四个问题提问让别人接受我们的产品或建议","remark":"今天我们拆的书叫《提问的艺术》，它的作者是美国的安德鲁.索贝尔   杰罗德.帕纳斯。\r\n这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。\r\n你有没有面对客户滔滔不绝，却忘了客户的感受？有没有面对销售的瓶颈而一筹莫展？想知道通过怎样的提问能够让你的伙伴做的更好吗？怎样用提问去探寻客户的真实需求？一共320个问题，告诉你用正确的提问方式解决你的一切问题。","level":"TF2-2","duration":18,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"伙伴们，晚上好！我是金家东，很高兴今天由我给大家做TF2-2的分享。在跟随我完成本次RIA现场学习后，学习者就知道如何劝说别人接受你的产品或建议。今天我们拆的书叫《提问的艺术》，它的作者是美国的安德鲁.索贝尔 杰罗德.帕纳斯。\r\n这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。\r\n你有没有面对客户滔滔不绝，却忘了客户的感受？有没有面对销售的瓶颈而一筹莫展？想知道通过怎样的提问能够让你的伙伴做的更好吗？怎样用提问去探寻客户的真实需求？一共320个问题，告诉你用正确的提问方式解决你的一切问题","ratings_count":0,"texts":[{"id":1246,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;如何通过提问让别人接受我们的方案？《提问的艺术》P18\r\n你们准备购买吗？你之前听说过这样的说法吗？“无论我们如何费尽口舌地不断说服他们，他们却还是不会掏钱购买，最后只能无果而终。”当听到人们准备购买时，那是多么让人兴奋的一件事。买家会将手伸向你，对你们之间的互动表现出浓厚的兴趣。如果以下4个条件都不存在的话，他们就不会购买你的产品、服务或创意。\r\n1、买家是否有问题要问或是否有提问的机会？\r\n你应该这样问对方：你现在的成本开支主要来源于哪里？如果你不能解决这个问题，会给你带来什么样的结果？你认为这次机会有价值吗？这是你最优先的考虑之一吗？\r\n2、买家是否有问题要解决？\r\n你应该这样问对方：谁有问题要解决？你负责解决这个问题吗？谁对解决这个问题所需的费用有决策权？在这件事情的解决上谁需要介入？\r\n3、买家是否对目前的承诺或改进明显不满？\r\n你应该这样问对方：这就是你受够了的主要原因吗？你是否还有要补充说明的？你为什么觉得现在是时候需要新的资源来取而代之了？你的努力是否有效解决了这个问题？\r\n4、买家信任你并相信你就是他们想要的最佳人选吗？\r\n你应该这样问对方：你正在寻找其他什么样的解决方案？你是如何评价我们在这一领域的能力的？你对我们或我们的方案有什么顾虑吗？\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;在别人接受你的产品或建议之前需要通过提问解决他们4个问题：1、他的需求是什么？2、这个产品或建议对他是否有利？3、他的痛点在哪里？4、他是否信任你？\r\n伙伴们，可能你们感觉要问4个问题太麻烦了，而且比较书面化，我们之前的做法多省事啊。事实上，不这么做会更麻烦。因为没有通过这4个问题的提问，就找不到别人为何要接受你的产品或建议的原因，也就难以达成结果，造成了时间精力上的浪费。总之，虽然麻烦，但是值得。\r\n我曾经也是和你们一样的想法，但是自从用了以上的方法后，感觉成功率提高了很多：上周一和一个投资客户见面，我按照原书拆页的建议，问下面4个问题：（1）你有几种投资增值的方式？这是找到需求。（2）是你自己操作的吗？这是找到他的利益。（3）你对这几种投资方式满意吗？这是找到痛点。（4）你对我们公司的投资方案有什么顾虑吗？这是找到信任感。结果成功做了一笔投资\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【A2】催化应用（分步催化1）:伙伴们，请想一想，最近一个月内，在一个轻松的环境里，和你的朋友或家人，喝着茶，聊着天。你是想让他接受你的产品？还是接受你的建议？或者仅仅是接受你的一个想法？请大家思考并想出具体情境后，加工一个具体的例子，说明今后你有可能会遇到的一个场景。给大家1分半钟。\r\n好了的伙伴向我举手示意\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、面试的场景。\u003c/p>\u003cp>2、向客户推荐微教室。\u003c/p>\u003cp>&nbsp;【A2】催化应用（分步催化2）:伙伴们设想一下，在最近的一个月内，我们再回到上面的场景，你是如何按照原文拆页的方法，用正确的提问方式让别人来接受你的产品或者建议的？\r\n下面，给大家2分钟的时间写在便签纸上，写好后每位伙伴在各自的小组内交流分享。（给大家4分钟时间。）\r\n最后，AB两组各请一位伙伴分别用1分钟的时间给我们做分享\r\n &nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、面试的场景：\u003c/p>\u003cp>（1）你想找什么样的工作？有什么要求？\u003c/p>\u003cp>（2）你负责解决过什么事情或者问题？具体描述一下可以吗？\u003c/p>\u003cp>（3）原来的公司哪一点让你感到遗憾？\u003c/p>\u003cp>（4）你喜欢米素公司的哪些方面？\u003c/p>\u003cp>2、向客户推荐微教室\u003c/p>\u003cp>（1）你目前的导购是怎么培训的？培训对他们有帮助吗？\u003c/p>\u003cp>（2）后期是否市场部会对接项目？\u003c/p>\u003cp>（3）你为什么现在先上这个APP？\u003c/p>\u003cp>（4）你对我们提供的APP功能设计方案有什么建议？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1466039670000,"updated_at":1466039670000,"ria":true},{"id":500,"topic":"五个为什么","learn_goal":"通过问“五个为什么”，了解真正原因或者动机","remark":"美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯共同著作的《提问的艺术》是“拆书帮”推荐的读本。\r\n在本书的第4页，美国畅销书《基金之父》作者罗恩.罗宾荪是这样介绍这本书的：“《提问的艺术》是一本适合人人都读的书。安德鲁和杰罗德在书中告诉我们如何以一种”最可能引出具有深刻见解答案的方式”提出”最好的问题”。另外，作者还提供了上百个你曾经渴望去问的问题。这本书能够让你的会谈比以前更有成效。”\r\n学会了这本书，我们可以在事业、生活的各种场合，随时展开富有成效的对话、帮助解决很多沟通问题。","level":"TF2-2","duration":18,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，今天很高兴和大家一起完成TF2-2的拆书。我是刘云汉。\r\n今天我要拆的这本书是美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯共同著作的《提问的艺术》。这本书自2014年1月出版，现在已经是第10次印刷了，也是“拆书帮”推荐的读本。\r\n在本书第4页，美国畅销书《基金之父》作者罗恩.罗宾荪是这样介绍本书的：“《提问的艺术》是一本适合人人都读的书。安德鲁和杰罗德在书中告诉我们如何以一种”最可能引出具有深刻见解答案的方式”提出”最好的问题”。另外，作者还提供了上百个你曾经渴望去问的问题。这本书能够让你的会谈比以前更有成效。”\r\n学会了这本书，我们可以在事业、生活的各种场合，随时展开富有成效的对话、帮助解决很多沟通问题，与家人好友还可以深入对话，推动情感交流。","ratings_count":0,"texts":[{"id":1193,"quote":"《五个为什么探索对方的真实需求》，选自《提问的艺术》P58-59\r\n当有人说“我想要这样”的时候，你需要去发现他们真正需要的是什么。你可以通过问“为什么”去做到这一点。你可以问五遍这个问题。从“你为什么想这样做”或者“为什么会发生”开始问起。\r\n“为什么”这个问题如果用错了时间和对象的话，就将变成一个可怕的问题。它听上去像是暗藏着潜在的反对之意，像是批评、挑刺和找茬儿。它会引起对方的反感。\r\n“为什么”也能成为一个有力的问题。它能够让被问的人更加深入的思考他们正在做的事，并帮助他们直达事情的核心。“为什么”能够让我们停下来反思，并检查我们的行动，从而避免机械的一路向前冲。","explains":"好，大家都看好了—这段话不长，也很容易理解：五个Why的方法，事实上我们很多人可能都听过、甚至很熟悉了。但是，在我们的谈话中，我们用过吗？应用得怎么样？可能有人会说：五个why用于工作的根因分析可以，怎么能用于谈话呢？这样连续问别人，不会显得“咄咄逼人”吗?做不到啊！\r\n真的做不到吗？正如这段文字所说：“为什么”也能成为一个有力的问题。它能够让被问的人更加深入的思考他们正在做的事，并帮助他们直达事情的核心。“为什么”能够让我们停下来反思”。如果我们学会在适当的时候、敢于问出来，这将是个“有力的问题”。\r\n我在日常的财务审批工作中，是很喜欢问“为什么”的，问得最多的是“为什么不比价？”“为什么不集中招标？”前几天，设备部顾经理找我要买滤网等零配件，这已经是今年第N次采购了。我就问他“为什么不集中招标？”“因为没有年用量的数据”“为什么不用以前的历史记录作参考呢？”“因为以前都是零星采购的没有记录”“为什么不记录呢？”“这些都是设备管理的基础资料啊，因为没有人要求呢？”“因为没有考核”“为什么需要考核呢？”“考核的数据肯定是领导重视的，这一块以前就没有重视过。”\r\n通过这五个“为什么”的询问，我和他都了解到：真实的原因还是管理层对这项工作的重视程度不够。--五个“为什么”帮助我们了解了解决问题的核心。","interaction":"【A2】催化应用（分步催化1）\r\n下面请大家想一想：我们在日常生活总有没有可以应用这五个“为什么”的情况，比如某个客户总在找借口就是不肯签单？或者接下来的端午节你想全家出游，而你爱人却只想待在家里？某个同事向你提出要你做某件事，但是你却觉得那是他自己的事？…\r\n请把这样的情况写在纸上，2分钟，写好的请举手示意\r\n好，现在请大家就刚才写下来的人和事，设想一下：如果明天你就遇见他了，你们在宽松的沙发上坐着，喝着茶，或者在你最喜欢的一个环境里，你们很友好的聊到了这个话题，你怎么应用这五个“为什么”的方法，去问哪几个问题，从而帮助你们解决问题？\r\n请把这几个“为什么”在小纸片的下面写出来。2分钟。写好的请举手示意。\r\n（2分钟以后）。好，我看大家都完成了。请大家在小组内分享一下你们的案例。\r\n有哪位小伙伴愿意和我们大家一起分享一下吗？\r\n（吴智才）明天端午节出去玩，问“你们明天想去那里玩？”“你为什么想去那里？”“去那里我们能有哪些活动？”等。\r\n（6分钟后）好，谢谢蒋玉萍和吴老师的分享！\r\n今天我的TF2-2拆书分享就到这里，谢谢大家！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1465910003000,"updated_at":1465910003000,"ria":true},{"id":456,"topic":"为什么你该这样提问","learn_goal":"学习我应该怎么问","remark":"这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。让我们一起跟随大师，做一个智者，用提问来改变自己的人生。","level":"TF2-1","duration":14,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"伙伴们，晚上好！我是金家东，很高兴今天由我给大家做TF2-1的分享.\r\n在跟随我完成本次RIA现场学习后，学习者就知道如何劝说客户购买你的产品和服务。今天我们拆的书叫《提问的艺术》，它的作者是美国的安德鲁.索贝尔 杰罗德.帕纳斯。这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。\r\n你有没有面对客户滔滔不绝，却忘了客户的感受？有没有面对销售的瓶颈而一筹莫展？通过怎样的提问能够让你的伙伴做的更好？怎样用提问去探寻客户的真实需求？一共320个问题，告诉你用正确的提问方式解决你的一切问题。","ratings_count":0,"texts":[{"id":1062,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;如何试图劝说别人购买？《提问的艺术》P18\r\n你们准备购买吗？你之前听说过这样的说法吗？“无论我们如何费尽口舌地不断说服他们，他们却还是不会掏钱购买，最后只能无果而终。”当听到人们准备购买时，那是多么让人兴奋的一件事。买家会将手伸向你，对你们之间的互动表现出浓厚的兴趣。如果以下4个条件都不存在的话，他们就不会购买你的产品、服务或创意。\r\n1、买家是否有问题要问或是否有提问的机会？\r\n你应该这样问对方：你现在的成本开支主要来源于哪里？如果你不能解决这个问题，会给你带来什么样的结果？你认为这次机会有价值吗？这是你最优先的考虑之一吗？\r\n2、买家是否有问题要解决？\r\n你应该这样问对方：谁有问题要解决？你负责解决这个问题吗？谁对解决这个问题所需的费用有决策权？在这件事情的解决上谁需要介入？\r\n3、买家是否对目前的承诺或改进明显不满？\r\n你应该这样问对方：这就是你受够了的主要原因吗？你是否还有要补充说明的？你为什么觉得现在是时候需要新的资源来取而代之了？你的努力是否有效解决了这个问题？\r\n4、买家信任你并相信你就是他们想要的最佳人选吗？\r\n你应该这样问对方：你正在寻找其他什么样的解决方案？你是如何评价我们在这一领域的能力的？你对我们或我们的方案有什么顾虑吗？\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;在买家购买之前需要通过提问解决他们4个问题：1、买家的需求是什么？2、谁负责买单？3、买家的痛点在哪里？4、买家是否信任你？\r\n如果我们不按照拆页的方法提问，买家会：1.对你的产品不敢兴趣而不会听你说。2、即使听你说了，也不会购买你的产品、服务和创意。\r\n以前做保健品销售的时候，通过对客户的身体检测而给他们配产品，虽然了解了客户的需求，也让客户产生一定的危机感，但是由于缺少前期的交流，没有用正确的提问方式了解客户的痛点和让他信任你，往往会使销售失败。\r\n &nbsp; 下周要和一个投资客户见面，我会按照原书拆页的建议，问下面4个问题：你有几种投资增值的方式？是你自己操作的吗？你对这几种投资方式满意吗？你对我们公司的投资方案有什么顾虑吗？相信会取得好的结果。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;A1拆书家提问设计（逐字稿）：伙伴们，有没有遇到这种情形：当我们面对客户侃侃而谈，恨不得把我们所知道的统统告诉客户。而客户一言不发地坐在那里，脸上是一片茫然，其结果应该可想而知。\r\n请想一想，最近一次的这样销售行为发生在什么时候？是什么事情？请用便签纸记录下来。给大家1分半钟。\r\n好了的伙伴向我举手示意&nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、员工总是不愿意参加培训。\u003c/p>\u003cp>2、向老板推销我对线下人员的配置。\u003c/p>\u003cp>A1+拆书家提问设计（逐字稿）：想想看，根据拆页里的方法，再次面对客户的时候，我们怎样用提问的方式来打开客户的心门，从而达成买单。\r\n下面，给大家2分钟的时间写在便签纸上，写好后每位伙伴在各自的小组内交流分享。（给大家4分钟时间。）\r\n最后，AB两组各请一位伙伴分别用1分钟的时间给我们做分享。&nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1、员工不愿意参加培训：\u003c/p>\u003cp>（1）你觉得你最近工作在哪方面有困难？\u003c/p>\u003cp>（2）你觉得你需要解决什么问题吗？\u003c/p>\u003cp>（3）这就是你所有的困难吗？\u003c/p>\u003cp>（4）你觉得这个培训能够帮助你吗？\u003c/p>\u003cp>2、向老板推销我对线下人员的配置\u003c/p>\u003cp>（1）作为老板，什么事情都卡在他的手上，你出差了怎么办？\u003c/p>\u003cp>（2）你这样做，对公司和你自己有利吗？\u003c/p>\u003cp>（3）你样样自己做，累吗？\u003c/p>\u003cp>（4）想不想有其他的解决方法？ &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1465439430000,"updated_at":1465439854000,"ria":true},{"id":424,"topic":"如何用封闭式问题提问避免兜圈子","learn_goal":"学习者在谈话对方犹豫、需要其全身心投入的时候，学会封闭式提问","remark":"这本书是美国安德鲁.索贝尔和杰罗德.帕纳斯共同著作的《提问的艺术》。是“拆书帮”推荐的读本。\r\n在本书的第4页，美国畅销书《基金之父》作者罗恩.罗宾荪是这样介绍这本书的：“《提问的艺术》是一本适合人人都读的书。安德鲁和杰罗德在书中告诉我们如何以一种”最可能引出具有深刻见解答案的方式”提出”最好的问题”。另外，作者还提供了上百个你曾经渴望去问的问题。这本书能够让你的会谈比以前更有成效。”\r\n学会了这本书，我们可以在事业、生活的各种场合，随时展开富有成效的对话，帮助解决很多沟通问题，与家人好友还可以深入对话，推动情感交流。","level":"TF2-1","duration":17,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"小伙伴们，大家晚上好！我叫刘云汉，很高兴今晚和大家一起拆解TF2-1。在跟随我完成本次RIA现场学习后，学习者能够在谈话对方犹豫不决、要弄清对方是否全身心投入的时候，学会问明确的封闭问题“是还是不是”。\r\n今天我要拆的这本书是美国著名商业战略家、《哈佛商业评论》《纽约时报》的撰稿人安德鲁.索贝尔、以及世界顶级慈善事业咨询师杰罗德.帕纳斯共同著作的《提问的艺术》。这本书自2014年1月出版，现在已经是第10次印刷了，也是“拆书帮”推荐的读本。\r\n在本书第4页，美国畅销书《基金之父》作者罗恩.罗宾荪是这样介绍本书的：“《提问的艺术》是一本适合人人都读的书。安德鲁和杰罗德在书中告诉我们如何以一种”最可能引出具有深刻见解答案的方式”提出”最好的问题”。另外，作者还提供了上百个你曾经渴望去问的问题。这本书能够让你的会谈比以前更有成效。”\r\n学会了这本书，我们可以在事业、生活的各种场合，随时展开富有成效的对话、帮助解决很多沟通问题，与家人好友还可以深入对话，推动情感交流。","ratings_count":0,"texts":[{"id":957,"quote":"用封闭式问题摆脱兜圈子的烦恼（《提问的艺术》第35页整页）\r\n当你试着让某人在某件事上做出明确回答时，或者是促使他们下定决心时，有许多提问方式。有温和的请求的提问方式，如“你觉有得...如何”。但有时候，你不能给对方留有动摇的余地。\r\n当你想获得直接而由衷的回答时，封闭式问题会很有成效：用恰当的方式有目的地提出一个封闭式问题，是还是不是，对于提问者来说，是力量和高要求的最好结合。","explains":"好，大家都看好了—内容不多，看上去容易理解：就是在沟通中，当你看到对方犹豫不决的时候，或者某个重要任务，需要搞清对方是否愿意全身投入的时候，用封闭式的提问方法“是还是不是？”。引发对方思考、并下定决心，作出承诺。\r\n如果发不出这样的提问，很可能我们不停地绕圈子，沟通效率很差。\r\n我看到这一段文字时，感触是很深的，因为我好像从来没有这么直截了当地问过—一来我喜欢用商议的形式，以示尊重、合作，觉得这样问有点强势；二来也担心把对方逼急了，直接拒绝。甚至对下属也是这样。有一次，我要求成本会计登记《设变单》的数据，她跑过来抱怨这个工作量大，认为这是研发项目经理的事。我反复和她讲解财务应该为项目经理提供支持，然后听她说她的理由，却始终没有问一句“你做还是不做”？ \r\n不这样问的后果呢？就是我们浪费了半天时间，互相重复理由，她最终去做了，但心不甘情不愿。为什么呢？因为是被我说服的，我没有用提问让她自己思考该不该做，她内心没有接受；而我呢，也没有显示出一个领导应有的智慧和魄力。","interaction":"【A1】拆书家提问设计（显像提问）：下面请大家也回忆一下我们在工作、生活中，和同事，不仅我说的下属，也可以是领导、同级别同事、甚至家人、亲戚，在交流的过程中有没有出现过这样的情况：你有一件事，需要得到他的支持。你主动过去找到他，谈了这件事怎么怎么重要，希望得到他的支持，想听听他的意见。然后他开始讲各种困难，听上去也挺有道理，然后你们不停地在那里绕圈子……\r\n请把这样的经历简单地写到纸片上，2分钟时间，写好的请举手示意。\r\n学习者案例记录：（独独）与新销售经理沟通装修工作需要从客服剥离的问题，他一直强调想让新装修内勤先学习的问题，沟通一个小时都没有结果。\r\n【A1+】（反思加工）拆书家提问设计（逐字稿）：好，现在请大家想一想：如果还是在当时的情境下，让你换一个封闭式的问题来提问，你会怎么问，能够达到更好的效果呢？\r\n请在小纸片的下面写出来。1分钟。写好的请举手示意。\r\n（1分钟以后）。好，我看大家都完成了。请大家在小组内分享一下你们的案例。\r\n学习者案例记录：（金家东）在下周的新员工销售技能培训上，我会这样问营销部：“我需要你们帮我讲这堂课，请问可以还是不可以？”\r\n谢谢金老师的分享！今天我的TF2-1拆书分享就到这里，谢谢大家！","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1464877166000,"updated_at":1464877730000,"ria":true},{"id":423,"topic":"如何通过提问了解对方的需求","learn_goal":"通过提问明确对方的需求，避免误会","remark":"《提问的艺术：为什么你该这样问》：作者是安德鲁.索贝尔   杰罗德.帕纳斯，这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。让我们一起跟随大师，做一个智者，用提问来改变自己的人生。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"伙伴们，大家好！我是金家东。今天我为大家介绍的书是：《提问的艺术：为什么你该这样问》：作者是安德鲁.索贝尔 杰罗德.帕纳斯，这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。让我们一起跟随大师，做一个智者，用提问来改变自己的人生。","ratings_count":0,"texts":[{"id":954,"quote":"如何通过提问了解对方的需求？《提问艺术》P12\r\n你想具体了解我哪方面的情况呢？当别人问我们问题时，我们很少要求对方清楚地说明他们具体想知道什么。你有没有见过有些人就一个错误的问题一口气回答了5分钟？他们认为自己听懂了，但回答的却并不是对方真正想要问的问题。这是多么尴尬的一件事。\r\n什么时候问最合适？1、当你被问到一个总体性问题，而这个问题有可能需要很长的回答时。2、当时间很短暂，你又想针对自己的目标做些简短回答时。\r\n你还可以这样问：1、你对我经历中的哪部分感兴趣？2、你希望我具体介绍哪方面的情况？3、在我回答你的问题之前，你是否已经对我们的公司有所了解？4、如果我先介绍一些像你这样的客户的案例来开始我们今天的介绍，你觉得如何？\r\n接下来这样问：这样能回答你的提问了吗？你还希望我们谈些什么？","explains":"当有人提出”能否向我们介绍一下你们公司的情况“这样的问题时，你一定要让他们说的具体一些。同样，当有人问你”你能介绍一下自己吗？“你可以问他”你想具体了解我哪方面的情况呢？“上周一客户有意向来理财，他说：”请介绍一下你的公司吧“。我从他的话语中听出他对我们公司的实力有疑问，担心自己的资金安全问题。于是我说：“你是否是想了解我们公司的实力和客户资金的流向问题？”“是的”客户说，我就我们公司的实力背景和客户的资金流向做了介绍，客户了解后也爽快的签约了。","interaction":"请大家回忆一下，当你的客户对你说：”能否向我们介绍一下你们公司的情况“。当时的你是怎么样对待的?给小组4分钟时间讨论一下，并把你们的想法写在便签纸上。下面请一位小伙伴来给大家分享一下。\r\n请设想下，下周客户可能向你提一个总体性问题，你可能需要30分钟左右的时间回答时，你如何提问了解对方的需求？先想一想，再给大家1分钟时间将想法写在便签纸上。完成后请举手示意。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1464844461000,"updated_at":1464844461000,"ria":true},{"id":387,"topic":"为什么你该这样问","learn_goal":"学习我应该怎么问","remark":"这是一本风靡全美、影响无数人的神奇提问书，揭示320个强大问题背后的商业与人生精髓，用真实故事和大师们的睿智问题展示提问艺术的魅力，直达问题核心，释放伟大问题的力量。让我们一起跟随大师，做一个智者，用提问来改变自己的人生。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"金家东","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位伙伴晚上好！我叫金家东，黄金的“金”，家庭的“家”，栋梁的“东”，大概是父母希望我成为家庭的栋梁之才吧。来自于江苏易天集团。88年师范毕业，做4年职业高中老师，主要教物理、计算机、电子类课程。92年下海经商，在新北区和湖塘开了十多年的连锁超市。后来由于大型超市开张（譬如华联、苏果、乐购等），市场竞争激烈而转行，08年加入易天集团人事部，现在主要负责培训方面的工作。今后希望自己在培训和营销方面有所发展。\r\n接下来我来讲讲拆书和拆书帮的含义\r\n拆书：“拆”不是“拆散”，是转化和内化。是强调把图书的知识拆页转化为学习者的能力。它分为个人学习的拆书法和组织学习的拆书法：个人学习的应用是便签法，它分成R（原书拆页）I（对原文知识点的理解和对现场学习者的引导）A（拆为己用）三部分。让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。\r\n“拆书帮”：是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。它是公益性组织，其使命是帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":924,"quote":"D29：如何提问才能推动别人将自身潜能发挥极致？《提问的艺术》P29\r\n这是你能做到的最好了吗？\r\n当别人很有希望去尽最大的努力时，以及当你想要鼓励别人去挑战自我的极限时，你应该连续不断地问他们这个问题。\r\n通常，当我们尽到自己最大的努力时，我们就能够战胜平庸。平庸是卓越的敌人，就像格勒善法则所说的“劣币驱逐良币”一样。一些企业提供的客户服务很糟糕，但却还不知道自己为什么会失去市场份额。某些大学生在学业上不肯付出努力，却总想着在毕业时能得到一份满意的工作。冷漠只能让人失去努力奋斗的激情。这个问题能够激励他人向更高的目标前进，让他们更加关注怎样才能做得更好。\r\n什么时候问最合适？\r\n1、当你要求同事为你完成一项任务或项目时。\r\n2、当你试着让孩子尽最大努力来达到更高要求时。\r\n3、当你正在为一项任务而工作，无论它是怎样的一个任务，请问一下自己：这真是我能做到的最好了吗？\r\n你还可以这样问：还有提升空间吗？有什么办法让他变得更好些？\r\n接下来这样问：还有什么能阻止你？你觉得它值得你尽最大努力吗？这件事情最成功的地方是什么？还有提升空间吗？","explains":"【I】：当你想要推动别人将自身的潜能发挥极致的时候，当你需要别人尽最大努力工作的时候，你可以这样问：这是你能做到的最好了吗？\r\n这是一个非同寻常的强有力的问题，尽管一定要慎重地使用它—因为她能够让人几近疯狂，但还是应该使用。通过问这个问题，你将帮助他人成就他们认为自己不可能做到的事情。\r\n你可以在以下情况使用：1、当你要求同事为你完成一项任务或项目的时候，你可以问：这是你能做到的最好了吗？2、当你试着让孩子尽最大的努力来达到更高的要求的时候，你可以问：这是你能做到的最好了吗？3、当你正在为一项任务而工作，无论它是怎样的一个任务，请问一下自己：这真是我能够做的最好的了吗？","interaction":"A1：上周让一个同事做一个培训评估表，我对她说：你应该做怎样的表格？表格里面应该分成哪几类？每一个类别的打分应该是多少？由什么来判别分数的高低？由谁来打分等等。以前我认为只有这样才能够做到更好。没有让他自身发挥潜能、让他尽最大努力、让他自我思考。这样他就没有成长，今后还是样样依赖于我。\r\nA2：下周让他做《魅力演说》决赛的流程，当他交给我流程的时候，第一次我会问：这是你能做到的最好了吗？第二次交给我时我会问：你有什么办法可以做的更好吗？第三次交给我时我会问：我知道你尽力了，但是还有提升的空间吗？","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1464421881000,"updated_at":1464423271000,"ria":true},{"id":373,"topic":"追溯根源的问题往往更有力 ","learn_goal":"顺利通过1-1","remark":"  通过不同的提问，改变你朋友的生活或者工作，通过提问，表现：  出尔很关心对方，通过提问赢得信任与理解，本书介绍了不同场合的不同提问，  来更好白面对生活工作中的问题","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"刘红艳","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是刘红艳，名字有着浓郁的家乡特色，“山丹丹开花红艳艳”大家也可以叫我包子，由《这样读书就够了》和拆书帮结缘，找到我们的西安筹备分舵，希望可以通过不断的思考以及分享提升个人能力，同时将拆书帮分享给其他伙伴，很高兴认识大家。\r\n“拆书”一种全新的读书方式，改变我们之前看完书籍之后没有然后的状态，以我们每一个读者为中心，以提升能力、解决问题为目标，把知识关联我们的经验，规划具体的应用，提出具体行动建议，将知识转化为自己的能力。拆书可以分为个人学习和组织学习，个人学习即为便签法，让你读一本书便能达到参加同主题培训的效果，组织学习是一位拆书家拿一本书加工出一场现场学习，引导大家拆为己用，拆书家创造的价值不亚于培训师。\r\n 众多喜爱读书，认同拆书法的拆书家组成了社群-拆书帮，帮助更多爱好者成为拆书家。","ratings_count":0,"texts":[{"id":912,"quote":"当你问别人“你当初是如何开始的？＂其实也是在帮助对方发现自我不平凡的一面。每一位朋友、同事甚至陌生人都会有一段让他们觉得弥足珍贵的故事：他们是如何选择自己的职业的？他们是如何遇上自己的另一半的？在去洛杉矶途中的一次偶遇是如何成就他们的一段美好缘分的？当他们愿意将这些故事拿出来与你分享时，也是你们之间友好关系建立的开始。\r\n什么时候问最合适\r\n任何时候，当你邀请他人与你分享他们当初是如何开始他们事业或人生中某段经历时。\r\n你还可以这样问\r\n 当对方是一对夫妇时，你可以这样问:“你们俩是如何开始你们的爱情故事并终成眷属的？”\r\n 当对方是一位艺术家或音乐家时，你可以这样问：“谁是你的恩师？你是如何开始学习这门艺术的？”\r\n 对于任何人，你都可以这样问:“你在哪里长大的？你又是如何最终做到的？”","explains":"双向的对话才能让沟通进行的更加顺利，对话中一个人表达了很多，若对方的反应只是“恩”“奥”“啊”很简短的应答，或者是常见的简单赞美，“挺好的”“那不错”往往会结束一段对话，一个好的提问可以让我们更好的了解一个人，也可以帮助我们建立良好的关系。比如“你是如何加入拆书帮的”“你们是怎么认识的”“最近新的项目进展的怎样”","interaction":"A1\r\n上周小伙伴告诉我，她做了一个项目，虽然不是很大，但是还是很开心，我说挺好的，但是没有提问，没有进一步的关心，虽然我很为她高兴，但是由于我只是简单的倾听，没有进一步的提问，所以沟通很快结束。\r\nA2\r\n从今天起，学会用提问引导沟通：\r\n小伙伴分享时，可以问：\r\n1、 你怎么着手新项目的？\r\n2、 做了哪些准备？\r\n3、 过程中遇到什么困难没，怎么解决的？\r\n可以和同事聊以下话题，建立良好的沟通\r\n1、 你当初是如何开始健身的？\r\n2、 你是如何和游戏行业结缘的？\r\n3、 你家是哪里的？可以介绍一下吗？\r\n4、 换新发型了？哪里剪的呢？\r\n工作中，生活中我们都可以用类似的提问，让沟通很好的进行。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1464218901000,"updated_at":1464218977000,"ria":true},{"id":349,"topic":"如何围绕决策提问来解决会议拖延症","learn_goal":"了解制定决策对于会议的重要性，学会围绕决策提问","remark":"《提问的艺术》是【美】马德路.索贝尔、杰罗德.帕纳斯合作完成的。自2014年1月出版，现在已经是第10次印刷了，也是“拆书帮”推荐的读本。\r\n我们都知道会提问的重要性了。那怎么样提问呢？这本书就是来回答这个问题的。本书共分商业、人际交往、人生3篇共33节，每节一个主题，含案例+理论+应用心得+何时用+怎么用，每节3-6页，很适合阅读、应用。","level":"TF1-2","duration":14,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"小伙伴们，晚上好！我叫刘云汉。今天我要拆的这本书是《提问的艺术--为什么你该这么问》。这本书是美国的商业战略家马德路.索贝尔，和世界顶级的咨询师杰罗德.帕纳斯合著的一步作品，有过20多名美国著名管理专家推荐，也是“拆书帮”推荐的读本。本书共分商业、人际交往、人生3篇共33节，每节一个主题，含案例+理论+应用心得+何时问+接下来怎么问，从而把谈话层次不断深入。","ratings_count":0,"texts":[{"id":894,"quote":"打破会议拖延症--“如何围绕决策提问，提高会议效率”。\r\n在每一个组织中，都存在着拖延现象。“我确实应该为自己的拖延症做点什么，但我却抽不出时间来做。”\r\n人们往往害怕作出决定，他们担心得罪权势和既得利益者。比起要承担责任的决策来说，不做决定会更容易些。罗列一份良好的行动清单的确很容易、风险也很低，但它并不能帮助你达到真正重要的目的。\r\n当你们在一起做决策时，就意味着大家讲拧在一起对事情作出一致确认，其结果就是对于一致通过的行动步骤要坚决执行。","explains":"大家是不是都认同“会议拖延症”的问题：议而不决，或者会议似乎也决定了一些行动计划，但是真正的问题却一直没有解决？ 一个核心原因就是会议没有形成真正的“决策”。\r\n我们公司就有这样的会议：去年3月份，我们在QOS会议上就提出“电费超预算”的问题，然后每个月都会讨论一下这个问题，但一直到年底，这个问题都没有解决。每次会议好像都有行动计划，谁做什么，但是始终没有搞清楚究竟电费为什么超预算、能不能节约、哪里能节约。\r\n看了这一段，我恍然大悟：这些行动计划都是各部门针对问题“我要做点什么”，但有很安全地不去承担责任，比如财务说：你们把数据给我们，我们来分析等，实际上都没有围绕问题去寻求解决方案，都不是决策：我们应该做什么？\r\n如果我们要改变这样的情形，就可以用今天学习的方法，“这是我们的决策吗？还是仅仅一份工作清单？”我们要的是决策。","interaction":"拆书家提问设计（激活经验）：请大家回忆一下我们的工作中有没有开过这样的会议：会前没有人明确说明会议目的，会议也没有作出什么决定，好像也有行动计划，但是真正的问题却一直没有解决？\r\n请把这样的一次会议写在小纸片上，我们用1分钟的时间。写好的请举手示意。\r\n（1分钟以后）好！我看大家都完成了。我们接下来分组讨论，小组内部分享一下。\r\n我看大家讨论得很热烈啊！请哪位小伙伴和我们分享一下好吗？\r\n学习者案例记录：（独独）与生产培训部门沟通一线培训执行不到位情况，讲了很多现状、原因，却没有说到怎么改进、执行到位。\r\n拆书家提问设计（催化应用）：谢谢金老师的分享！\r\n接下来请大家接着刚才所写的内容，想一想：在接下来的一周内你们要召开什么会？你将如何应用“围绕决策提问”的方法，提高我们的会议效率？\r\n请大家花2分钟时间写一下。好了请举手示意。\r\n（2分钟以后）。好，大家都完成了，效率很高啊！\r\n这次我们请另一组的分享一下好吗？\r\n学习者案例记录：下周组织生产培训会议，针对目前问题如何改进执行到位，并在最后确定：我们的决定如下：……大家都同意了吧？\r\n好，谢谢各位的分享！\r\n本次我的拆书分享就到这里，谢谢大家！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1463669720000,"updated_at":1463670111000,"ria":true},{"id":333,"topic":"如何开启沟通的阀门","learn_goal":"了解聆听的重要性，学会用“你怎么想”让对方说话，用心倾听","remark":"渴望被聆听是人希望被尊重、被了解的天性，我们在工作和生活中，要想和沟通对象建立良好的关系，就需要认真聆听。\r\n问一句“你怎么想”，很容易就能让沟通对象感受被尊重和需要，从而打开对方的心扉。\r\n认真、用心倾听、用眼睛、肢体语言去反馈、鼓励，才能听到更多、从而了解、学习更多，也更有利于对方同样回馈和接受你的方案。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"刘云汉","city":"常州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，今天很高兴由我来给大家做TF1-1的拆书分享。首先做个自我介绍，我叫刘云汉，泰州兴化人，上海财经大学企业财务专业毕业，工作25年，前11年在政府机关，近14年在外资企业，一直做财务，现在拆书帮常州筹备分舵还是负责财务。很荣幸加入拆书帮，希望通过这样的组织环境和大家一起学习、成长。\r\n今天我要拆的这本书是【美】马德路.索贝尔、杰罗德.帕纳斯《提问的艺术》，\r\n分商业、人际交往、人生3篇共33节，每节一个主题，含案例+理论+应用心得+何时用+怎么用，每节3-6页，很适合阅读、应用。","ratings_count":0,"texts":[{"id":872,"quote":"如何开启沟通的阀门\r\n《提问的艺术》P88\r\n“比起满足他的要求，大多数人更愿意你去聆听他的故事。”通过“你怎么想”这样超级有力的问题，可以让你身边的人感受到你非常愿意倾听他的心声。你将开启沟通的阀门，成为吸收信息的海绵。\r\n接下来就是倾听，积极地去倾听，专注地去倾听，默默地去倾听，用你的眼睛去倾听，倾听！","explains":"和大家分享的这一段，指明：渴望被倾听是人的天性。人们需要被关注、被尊重。一句“你怎么想？”显示了你的谦虚和对他人的尊重，让别人把想法说出来，认真聆听，不仅能吸收别人的智慧，你的真诚更容易让别人也接受你的意见。","interaction":"我曾经为RD Financial Gates report找过Rogelio征求意见，但是并没有真正地听进去，还是用的自己的想法在设计。这让我对他是否真的接受我的全部思路没有把握，而且我并没有真的听到有启发的信息来改进我的设计。\r\n5月15日前，我把初稿设计出来发给Rogelio，5月20日前找他当面讨论。这一次，我就用“你怎么想”引导他说出他的意见，针对上次初步认可的五点内容，从报表格式的设计、表现形式、询问：“你看这是不是你想要的？”“还有什么需要补充吗？”“这是电子表，你是否认为线性图或者哪种图形方式更好？”等，让他说出他的意见。他说话的时候，我需要特别注意凝神倾听，不打断，不确定的词句，要修改的部分，都用我的语言重复，以确认，真正向他学习一些改善的思路。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1463063352000,"updated_at":1463063396000,"ria":true},{"id":160,"topic":"如何探索对方真实需求","learn_goal":"如何通过提问来探索对方真实需求","remark":"书籍是《提问的艺术—为什么你该这么问》，英文标题《Power Questios》，作者是安德鲁.索贝尔，全书共分享了320个强大的问题。我们今天看其中的一个提问方法：连问5个为什么来探寻对方的需求。","level":"TF3-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"西里孟钢","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1457968511000,"updated_at":1457968511000},{"id":158,"topic":"如何针对客户利益和价值提问","learn_goal":"学完后，知道如何针对客户利益提问","remark":"一个平息对方怒火的问题，一个赢得信任的问题。如何关注客户和利益来达成我们的沟通目的。","level":"TF3-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"西里孟钢","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"书名是提问的艺术，为什么你该这样问，我喜欢看书的英文名称，英文是Power Question，副标题是build relationships ,win new business,and influence others，可以帮助我们处理人际关系，商业关系和影响他人的能力。作者安德鲁和杰罗德是成功的企业家和咨询顾问，和我们分享了320个问题。今天的拆书主题是针对客户利益进行提问。\r\n事件：比如当你和老公在谈即将到来的十一旅行计划时，你的老公是否有点心不在焉，似乎完全没有听到你的说什么。\r\n提问：为什么老公对你谈的旅行计划完全不感兴趣？\r\n影响：你本来兴致盎然的一次旅行，现在可能浇了一盘冷水。甚至可能会取消这次旅行计划。\r\n解决：这本书里提供的方法，不仅可以帮助我们解决与家人的沟通，也可以帮助我们在职场中的运用，通过有效提问power question来增加我们的影响力，增加我们的幸福指数。","ratings_count":0,"texts":[{"id":208,"quote":"当一个人开始目光游离，且没有任何问题时，就是时候该做点什么了。你遇到麻烦了。\r\n我正在和一家大型专业服务类公司的共同主席觊瑟琳开会。这次会议早在几周前就定下来了。会议议程是共同回顾一下我在为他们公司所做的咨询项目的进展情况。我提前做了充足细致的准备，并给凯瑟琳带去了简要的文件。文件清晰精炼地概述了项目的进展情况，足以给人留下深刻的印象。\r\n我们的讨论大约进行了20多分钟，我就发现凯瑟琳心不在焉，整个人坐立不安，根本不在状态。她没有问任何精彩的跟进性问題，更糟糕的是，她的眼睛开始盯着黑莓手机看了。\r\n你一定能想象得出当时的情景有多令人沮丧。有人试图表现出一副专心听你讲的样子，却低下头偷偷看他们手中的智能手机。觊瑟琳的心不知道跑到哪里去了。\r\n我暂停下来。和这位繁忙的高管坐在一起，时间仿佛凝固了。“觊瑟琳，”，我问道，“今天早上我们讨论的重点是什么？”她突然坐直了，警觉了起来。我在等待她的回答。“嗯，好的，”她开始慢条斯理地回答道，“你的汇报有帮助，我觉得你的概述和建议很有价值。做得很好！”\r\n“谢谢你的肯定！但接下来我们应该集中讨论什么？”\r\n觊瑟琳抬头看着我，皱着眉摇了摇头，叹息道：“我想我的团队还没有准备好，他们无法跟上进度。”\r\n“请再说详细一点，当你告诉我‘他们还没有准备好’时，你预见了什么吗？什么事无法继续下去了？”\r\n我们转移了话题，接下来的半个小时我们都在谈论有关她的团队的事。我问了许多有力的问题，觊瑟琳更进一步说明了目前的形势。我提出了一些初步措施，以便让她的团队更好地配合项目的战略目标。我们把其余的有关项目进展的讨论搜到了下一次讨论。我之前为这次会议精心准备的文件看来是派不上用场了。也许它已经达到了应有的效果。\r\n在我起身准备离开的时候，觊瑟琳问我：“我们能在下周就此问题再重新碰一下面吗？你刚才问了许多很专业的精彩问题，你的建议也很棒。我想和你一场好好深入探讨一下。”\r\n我们不妨按一下快进键。根据我们6个月前那次会谈的初衷，觊瑟琳正在为她的团队管理带来一场深刻的变革。同时，她也邀请我与他们开展一对一的工作，以提高他们的工作效率。\r\n正是我问觊瑟琳的这个简单而直接的问题“我们今天应该讨论的重点是什么”，帮她回到了改进组织的道路上来，也加深了我和她之间的关系。当你把时间共存对双方都真正重要的事情上时，你们之间的关系自然就得到了升华和发展； 这也能幸你们情感上的共鸣，让你们之间的关系更加紧密和牢靠。\r\n多年前向我咨询过的一位CEO曾说了一些让我终生难忘的话，道出了相互关联的关键所在。他说：“当你为客户的成长和利益着想时，他们将永远对你充满兴趣；如果你只被他们当作成本管理时，那他们随时都会裁掉你。”因此，你必须和他人 最基本的愿望和目标息息相关，这样你才能成为他们成长和利益的一部分，才能被他们视为投资而非成本。\r\n----------------------------------\r\n当别人心烦意乱或走神的时间，或当你意识到你没有谈到他们最关心的事情上时，你一定要问：“我们今天应该讨论的重点是什么？”\r\n -----------------------------------","explains":"在这个片段中，凯瑟琳对我的问题和建议的评价是什么？（专业、精彩）\r\n我问的这个简单而直接的问题是什么？（我们今天应该讨论的重点是什么）\r\n请大家完成自测题\r\n为了解更关注自己的利益，还是更关注客户的利益，我们来做一下自我测试吧。\r\n请仔细阅读下面的5个问题，按照1-6分的标准给自己打分，1代表完全不符合，6代表非常非常符合。请仔细阅读正面表格中的每句话，根据自己的实际情况为自己打分。（1表示很不符合，6表示非常符合）\r\n1、我在与客户沟通时，会注意观察客户的微表情与肢体动作。\r\n1分，2分，3分，4分，5分，6分\r\n2、我会注意到谈话是否偏离主题\r\n1分，2分，3分，4分，5分，6分\r\n3、我对客户想谈话的话题有浓厚的兴趣与好奇心\r\n1分，2分，3分，4分，5分，6分\r\n4、我在沟通过程中，会注意使用提问的方式进行。\r\n1分，2分，3分，4分，5分，6分\r\n5、在谈话过程中，我会更在意自己的主题，还是客户想探讨的主题？\r\nA、我会更在意自己的主题\r\nB、还是客户想探讨的主题\r\n请完成打分的伙伴，把1-4的分数加一下，有没有大于20分的，有没有小于12分的？\r\n这个测试的目的，是了解大家自己的沟通风格和沟通习惯。分数越好，说明你更善长提问，并且更关注客户的利益；分数越低，说明你需要更多的进行提问，更多的关注客户的利益。\r\n举例子：比如片段中是观察到“凯瑟琳走神了”；现在我观察到“大家正在注视着我“，大家希望今天的活动对你有收获，和大家利益相关。\r\n我们来看看这个成功的对话过程是如何进行的。\r\n在谈话到一半时，我注意到“凯瑟琳走神了”，反应她对目前正在讨论的话题不感兴趣；这是第1步，启动观察；\r\n在这里为何要询问“今天我们讨论的重点是什么？”客户要讨论的“重点”就是客户所“关心的利益点”，我们不会直接问“客户你的利益是什么”，或者问“客户你想要什么”。这里的“重点”，其实也就是“利益点”。\r\n接下来第2步，我问“今天我们讨论的重点是什么？”她的反应是身子做直了；我把这一步总结为“明确焦点”\r\n片段中，这里凯瑟琳关注的是团队的进度问题。\r\n比如，在一个软件开发项目中，和客户谈需求时，会问客户：你想实现的主要功能有哪些？\r\n明确客户关心的重点功能模块。\r\n方法总结：\r\n通过这个故事，可以总结为3个步骤：\r\n1、启动观察：“凯瑟琳走神了”，反应她对目前正在讨论的话题不感兴趣；\r\n2、明确焦点：今天我们要讨论的重点是什么\r\n3、进一步探讨：能否再说详细一点吗？预见了什么，发生了什么？","interaction":"我正在讲一个旅行计划，LG观察到LG有点心不在焉，似乎完全没有听到你的说什么。（启动观察）\r\n这时，你开始暂停你的讲述，你开始用眼睛看着他的脸，开始说：你想要的完美旅行，是什么样子的？\r\nLG开始把头抬起来，有点奇怪的盯着你看。\r\nLP“我希望我们可以有一个完美的开心旅行，你能谈谈你的想法吗？”（今天你想讨论的重点是什么）\r\nLG额，让我想想。对了，（恍然大悟状）我想带你来一次浪漫的海岛之旅，结婚时因为工作忙，没有时间请婚假，还没有过带你蜜月旅行，我可不想给你留下这个遗憾。\r\nLP（开心状）好啊，有没有什么具体地点的想法吗？（步骤3：进一步探讨）\r\nLG我觉得长滩或夏威夷不错， 最近我有一个同事刚刚去过长滩。我可以电话咨询一下他的安排。。。\r\n拆书家提问设计\r\n（逐字稿）：\r\n你已经多久没有和家人坐下来好好聊聊天，谈谈心了？今天回家，找一位家人。可能是LP/LG，爸爸或妈妈\r\n约他见面或电话沟通\r\n把你自己的想法和欲望放在一边，关注一下对方的想法和利益\r\n你会如何问呢？\r\n把你的开场白和问题写下来。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1457879414000,"updated_at":1457879414000,"ria":true},{"id":155,"topic":"如何针对客户利益提问","learn_goal":"学完后，可以针对客户利益进行提问","remark":"一个力挽狂澜的问题，一个平息对方怒火的问题，一个老板期待你问的问题，一个让会议迅速回归正确的问题，一个能赢得信任和理解，迅速改善关系的问题。好问题蕴含着富有深刻见解的答案，学会用问题来打造专业而极具个人魅力的影响力。","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"西里孟钢","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"书名是提问的艺术，为什么你该这样问，我喜欢看书的英文名称，英文是Power Question，副标题是build relationships ,win new business,and influence others，可以帮助我们处理人际关系，商业关系和影响他人的能力。作者安德鲁和杰罗德是成功的企业家和咨询顾问，和我们分享了320个问题。今天的拆书主题是针对客户利益进行提问。\r\n事件：比如当你和老公在谈即将到来的十一旅行计划时，你的老公是否有点心不在焉，似乎完全没有听到你的说什么。\r\n提问：为什么老公对你谈的旅行计划完全不感兴趣？\r\n影响：你本来兴致盎然的一次旅行，现在可能浇了一盘冷水。甚至可能会取消这次旅行计划。\r\n解决：这本书里提供的方法，不仅可以帮助我们解决与家人的沟通，也可以帮助我们在职场中的运用，通过有效提问power question来增加我们的影响力，增加我们的幸福指数","ratings_count":0,"texts":[{"id":204,"quote":"P071-073\r\n当一个人开始目光游离，且没有任何问题时，就是时候该做点什么了。你遇到麻烦了。\r\n我正在和一家大型专业服务类公司的共同主席觊瑟琳开会。这次会议早在几周前就定下来了。会议议程是共同回顾一下我在为他们公司所做的咨询项目的进展情况。我提前做了充足细致的准备，并给凯瑟琳带去了简要的文件。文件清晰精炼地概述了项目的进展情况，足以给人留下深刻的印象。\r\n我们的讨论大约进行了20多分钟，我就发现凯瑟琳心不在焉，整个人坐立不安，根本不在状态。她没有问任何精彩的跟进性问題，更糟糕的是，她的眼睛开始盯着黑莓手机看了。\r\n你一定能想象得出当时的情景有多令人沮丧。有人试图表现出一副专心听你讲的样子，却低下头偷偷看他们手中的智能手机。觊瑟琳的心不知道跑到哪里去了。\r\n我暂停下来。和这位繁忙的高管坐在一起，时间仿佛凝固了。“觊瑟琳，”，我问道，“今天早上我们讨论的重点是什么？”她突然坐直了，警觉了起来。我在等待她的回答。“嗯，好的，”她开始慢条斯理地回答道，“你的汇报有帮助，我觉得你的概述和建议很有价值。做得很好！”\r\n“谢谢你的肯定！但接下来我们应该集中讨论什么？”\r\n觊瑟琳抬头看着我，皱着眉摇了摇头，叹息道：“我想我的团队还没有准备好，他们无法跟上进度。”\r\n“请再说详细一点，当你告诉我‘他们还没有准备好’时，你预见了什么吗？什么事无法继续下去了？”\r\n我们转移了话题，接下来的半个小时我们都在谈论有关她的团队的事。我问了许多有力的问题，觊瑟琳更进一步说明了目前的形势。我提出了一些初步措施，以便让她的团队更好地配合项目的战略目标。我们把其余的有关项目进展的讨论搜到了下一次讨论。我之前为这次会议精心准备的文件看来是派不上用场了。也许它已经达到了应有的效果。\r\n在我起身准备离开的时候，觊瑟琳问我：“我们能在下周就此问题再重新碰一下面吗？你刚才问了许多很专业的精彩问题，你的建议也很棒。我想和你一场好好深入探讨一下。”\r\n我们不妨按一下快进键。根据我们6个月前那次会谈的初衷，觊瑟琳正在为她的团队管理带来一场深刻的变革。同时，她也邀请我与他们开展一对一的工作，以提高他们的工作效率。\r\n正是我问觊瑟琳的这个简单而直接的问题“我们今天应该讨论的重点是什么”，帮她回到了改进组织的道路上来，也加深了我和她之间的关系。当你把时间共存对双方都真正重要的事情上时，你们之间的关系自然就得到了升华和发展； 这也能幸你们情感上的共鸣，让你们之间的关系更加紧密和牢靠。\r\n多年前向我咨询过的一位CEO曾说了一些让我终生难忘的话，道出了相互关联的关键所在。他说：“当你为客户的成长和利益着想时，他们将永远对你充满兴趣；如果你只被他们当作成本管理时，那他们随时都会裁掉你。”因此，你必须和他人 最基本的愿望和目标息息相关，这样你才能成为他们成长和利益的一部分，才能被他们视为投资而非成本。\r\n----------------------------------\r\n当别人心烦意乱或走神的时间，或当你意识到你没有谈到他们最关心的事情上时，你一定要问：“我们今天应该讨论的重点是什么？”\r\n -----------------------------------","explains":"I互动：\r\n在这个片段中，凯瑟琳对我的问题和建议的评价是什么？（专业、精彩）\r\n我问的这个简单而直接的问题是什么？（我们今天应该讨论的重点是什么）\r\n概念讲解：\r\n我们来看看这个成功的对话过程是如何进行的。\r\n在谈话到一半时，我注意到“凯瑟琳走神了”，反应她对目前正在讨论的话题不感兴趣；这是第1步，启动观察；\r\n在这里为何要询问“今天我们讨论的重点是什么？”客户要讨论的“重点”就是客户所“关心的利益点”，我们不会直接问“客户你的利益是什么”，或者问“客户你想要什么”。这里的“重点”，其实也就是“利益点”。\r\n接下来第2步，我问“今天我们讨论的重点是什么？”她的反应是身子做直了；我把这一步总结为“明确焦点”\r\n片段中，这里凯瑟琳关注的是团队的进度问题。\r\n比如，在一个软件开发项目中，和客户谈需求时，会问客户：你想实现的主要功能有哪些？\r\n明确客户关心的重点功能模块。\r\n方法总结：\r\n通过这个故事，可以总结为3个步骤：\r\n1、启动观察：“凯瑟琳走神了”，反应她对目前正在讨论的话题不感兴趣；\r\n2、明确焦点：今天我们要讨论的重点是什么\r\n3、进一步探讨：能否再说详细一点吗？预见了什么，发生了什么？\r\n请大家注意，在第2步中，使用了2个不同的问题重复邀请对方来表达自己的关注点。“今天我们讨论的重点是什么”，“接下来我们应该集中讨论什么”。\r\n适用场景：无事先预设的特定主题时，比如和老板沟通、和家人沟通时，可以尝试用这个方法来探询谈话对象的诉求点。\r\n注意事项：1、措词要用“我们”，而不是“你”，是我们双方要共同探讨的一个话题；2、必要时，可以换一个说法，追问一次。如片段中，就连续问了2次。\r\n过程：谈话开始-通常在谈话开始的时间就开始问比较好。谈话过程-在过程中，要随时注意客户的变化，确定讨论的内容重点是否一直是客户关心的话题。","interaction":"拆书家提问设计（逐字稿）：\r\n下面请大家编一个故事，这个故事里需要使用刚刚学习的提问方法。\r\n建议包括：对话的过程，对方会如何表现，你会如何应对；对方会说什么，你会说什么。\r\n请大家把对话要点记录在便签上，时长3分钟。\r\n完成后：请2个伙伴分享下你的故事，分享时长不要超过1分钟\r\n学习者案例记录\r\n伙伴1：一个男生准备带女友出游，询问女友：你觉得什么地方好？\r\n伙伴2：一个上级询问下属要一份报告，这份报告如何，为什么没有交？家里是不是有事？家里的装修进展如何？","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":205,"quote":"P74\r\n提问的心得\r\n我们今天应该讨论的重点是什么？\r\n如果你所谈论的事情不能与谈话对象最关心的诉求相吻合的话，那么他们将会表现得心不在焉。如果你能将谈话的焦点放在对对方最重要的事情上，那对提高你们关系的密切性和影响力具有意想不到的作用。\r\n什么时间问最合适\r\n在和客户或老板讨论进展情况的会议上\r\n在做销售定位时。\r\n当你和爱人或关系密切的人在一起时。\r\n你还可以这样问\r\n你今天最想谈点什么？\r\n你在想什么？\r\n只剩20分钟了，还有什么是我们今天应该讨论却被漏掉的？\r\n有什么事是我们应该强调却没有强调的？\r\n接下来这样问\r\n你能就那件事再多说一点吗？\r\n那件事背后的情况是怎样的？\r\n为什么现在这对你很重要？","explains":"请大家完成自测题\r\n为了解更关注自己的利益，还是更关注客户的利益，我们来做一下自我测试吧。\r\n请仔细阅读下面的5个问题，按照1-6分的标准给自己打分，1代表完全不符合，6代表非常非常符合。请仔细阅读正面表格中的每句话，根据自己的实际情况为自己打分。（1表示很不符合，6表示非常符合）\r\n1、我在与客户沟通时，会注意观察客户的微表情与肢体动作。\r\n1分，2分，3分，4分，5分，6分\r\n2、我会注意到谈话是否偏离主题\r\n1分，2分，3分，4分，5分，6分\r\n3、我对客户想谈话的话题有浓厚的兴趣与好奇心\r\n1分，2分，3分，4分，5分，6分\r\n4、我在沟通过程中，会注意使用提问的方式进行。\r\n1分，2分，3分，4分，5分，6分\r\n5、在谈话过程中，我会更在意自己的主题，还是客户想探讨的主题？\r\nA、我会更在意自己的主题\r\nB、还是客户想探讨的主题\r\n请完成打分的伙伴，把1-4的分数加一下，有没有大于20分的，有没有小于12分的？\r\n这个测试的目的，是了解大家自己的沟通风格和沟通习惯。分数越好，说明你更善长提问，并且更关注客户的利益；分数越低，说明你需要更多的进行提问，更多的关注客户的利益。\r\n问题1，是判断我们的眼睛和观察力，是否有把注意力焦点放在客户身上\r\n问题2，是在谈话过程中的觉察力，是否围绕谈话主题\r\n问题3，是对客户的问题是否有兴趣和好奇心，来帮助我们进行提问的前提\r\n问题4，是判断自己已有的沟通风格和习惯，喜欢“表达自己”，还是喜欢“探询客户”\r\n问题5：是判断自己的关注点，在自己，还是在客户","interaction":"这个片段告诉我们提问的时间点和提问的方式\r\n拆书家提问设计（逐字稿）：\r\n1、明确问题：在人际交往中，我们为什么要关注客户的利益与价值？根本原因或好处有哪些？给我们的启发是什么？\r\n2、2人一组，进行讨论。\r\n3、记录：请大家把讨论记录在A4纸上，5分钟，请2位代表来分享你们的讨论要点，每人分享不要超过1分钟\r\n4、阶段2：除了问“我们今天讨论的重点是什么”，还有什么新方法可以来问“客户的利益与价值”。时间为3分钟。\r\n请2位代表来分享你们的讨论要点，每人分享不要超过1分钟\r\n学习者案例记录\r\n关注客户利益的好处：\r\n1、了解客户信息\r\n2、建立良好关系\r\n3、促进双方合作\r\n4、抓住重点，利于营销\r\n5、给客户留下深刻印象\r\n有什么新方法来提问？\r\n1、你还有什么要求？\r\n2、你现在最大的困惑是什么？\r\n3、你觉得哪个问题最迫切需要解决？\r\n4、关键词+重复技巧：重复客户说的关键词\r\n5、请谈一谈你的想法\r\n6、还有什么需要补充的？\r\n拆书家提问设计（逐字稿）：\r\n1、确定一个你明天要进行的一场对话\r\n2、设计一下你会如何进行这场对话\r\n把你要问的问题写下来，要使用今天所学的方法\r\n请2位代表来分享你们的讨论要点，每人分享不要超过1分钟\r\n学习者案例记录：\r\n伙伴1:明天晚上和老婆对话\r\n如何让我们的生活更快乐，更幸福？\r\n有何看法和建议？\r\n具体一点，我可以做哪些事情？\r\n伙伴2:明天给ma老师讲的课程做反馈\r\n进一步注意哪些问题？\r\n在给你提的反馈中，值得你吸引的有哪些？\r\n你觉得，有哪些问题可以帮到你？\r\n伙伴3:周六和大哥吃饭，大哥希望我可以帮忙\r\n你需要我为你做些什么？\r\n有什么我能为你做的？\r\n伙伴4:明天在家和老婆沟通时\r\n先观察老婆的反应，是否有不开心或不高兴\r\n如果有，我会问，有什么让你不开心的吗？\r\n希望我做什么，可以让你开心？\r\n还有么？\r\n伙伴5:明天和一个合作伙伴沟通时\r\n我们今天需要干什么？\r\n具体要干成什么样？\r\n需要有哪些资源？\r\n我能为你做些什么？\r\n还有呢？\r\n伙伴6:明天和公司客户\r\n最大的困扰是什么？\r\n希望我可以提供什么帮助？\r\n需要哪些具体支持？\r\n伙伴7:明天和客户电话沟通市场行情\r\n对我们公司操作有什么建议？\r\n伙伴8:明天需要给内训师提供一份方案\r\n问内训师\r\n你们更关注文章需要有哪些内容或风格？\r\n这份方案是给客户老板看的，还是给普通员工看的？\r\n还有哪些内容是我没有想到的？","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1457537389000,"updated_at":1457537389000,"ria":true},{"id":82,"topic":"使用提问开始会议","learn_goal":"参加完学习后，学习者能够以提问的形式开始一场会议","remark":"今天与大家分享的图书是一本风靡全美的提问书《提问的艺术》，它向我们提示了生活中真正的力量——一种能让我们在发展深入关系的同时解决问题的力量，并能帮助我们更好地了解自己。","level":"TF3-2","duration":30,"status":0,"type":1,"chaishujia":{"username":"海边渔民","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1453305120000,"updated_at":1453305120000}]};